    { name = 'The Beast of Bastore', group = 'Abyssea', desc = 'Kill Sedna in Abyssea - Vunkerl for a zone key item; begins at the Jugner Forest Cavernous Maw. Source: https://vanadreams.org/wiki/#quest-135', steps = { { title = 'Requirements', note = '• Dawn of Death; 1+ traverser stone' }, { title = 'Start', note = '• Click the Jugner Forest maw; accept.' }, { title = 'Kill NM', note = '• In Abyssea - Vunkerl, kill Sedna (K-6); title: Sedna Tuskbreaker.' }, { title = 'Finish', note = '• Re-enter Jugner Forest for the cutscene and key item.' }, { title = 'Notes', note = '• Key item varies by the zone where you finish.' } } },
    { name = 'The Forbidden Frontier', group = 'Abyssea', desc = 'Clear the first three zone hunts and report to Joachim in Port Jeuno. Source: https://vanadreams.org/wiki/#quest-138', steps = { { title = 'Requirements', note = '• Started one of A Goldstruck Gigas, To Paste a Peiste, Megadrile Menace' }, { title = 'Steps', note = '• Accept from Joachim (H-8), Port Jeuno.\n• Finish A Goldstruck Gigas, To Paste a Peiste and Megadrile Menace.\n• Return to Joachim to complete.' } } },
    { name = 'The Truth Beckons', group = 'Abyssea', desc = 'Visit any Abyssea zone, then see Joachim (Port Jeuno). Source: https://vanadreams.org/wiki/#quest-144', steps = { { title = 'Requirements', note = '• A Journey Begins done' }, { title = 'Steps', note = '• Use a Cavernous Maw to enter any Abyssea zone.\n• Joachim (H-8), Port Jeuno: cutscene.' }, { title = 'Notes', note = '• Leads to Dawn of Death.' } } },
    { name = 'The Wyrm God', group = 'Abyssea', desc = 'Win The Wyrm God battle in Abyssea - Empyreal Paradox and report to Prishe. Source: https://vanadreams.org/wiki/#quest-147', steps = { { title = 'Requirements', note = '• Quest accepted (earlier Abyssea quests done)' }, { title = 'Steps', note = '• Examine the Transcendental Radiance entrance in Abyssea - Empyreal Paradox for a cutscene.\n• Fight The Wyrm God via the Transcendental Radiance (K-12) and win.\n• Speak with Prishe (K-12).' }, { title = 'Notes', note = '• Leads to Meanwhile, Back on Abyssea.' } } },
    { name = 'To Paste a Peiste', group = 'Abyssea', desc = 'Kill Kukulkan in Abyssea - Konschtat for a key item; begins at the Konschtat Highlands Cavernous Maw. Source: https://vanadreams.org/wiki/#quest-149', steps = { { title = 'Requirements', note = '• Dawn of Death; 1+ traverser stone' }, { title = 'Start', note = '• With a traverser stone, examine the Cavernous Maw (I-12) in Konschtat Highlands.' }, { title = 'Kill NM', note = '• In Abyssea - Konschtat, pop Kukulkan (H-5) at its ??? with tattered hippogryph wing, cracked wivre horn and mucid Ahriman eyeball.\n• Kill it; title: Kukulkan Defanger.' }, { title = 'Finish', note = '• Re-enter Konschtat Highlands for the cutscene and key item.' }, { title = 'Notes', note = '• Key item depends on how many of the 9 zone quests you have done.' } } },
    { name = 'Uleguerand - Dominion Op #01', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Mechanical Menaces. Source: https://vanadreams.org/wiki/#quest-150', steps = { { title = 'Op', note = '• Sign on: Zazarg\'s sergeant.\n• Kill 5 Mechanical Menaces. Report back.\n• Kills count only while the op is active.' } } },
    { name = 'Uleguerand - Dominion Op #02', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Spectators. Source: https://vanadreams.org/wiki/#quest-151', steps = { { title = 'Op', note = '• Sign on: any zone sergeant.\n• Kill 5 Spectators. Report back.\n• Rewards: experience, cruor, Dominion Notes.\n• Below level 75 the experience is reduced.\n• Rewards are paid on turn-in.' } } },
    { name = 'Uleguerand - Dominion Op #03', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Sub-zero Gears. Source: https://vanadreams.org/wiki/#quest-152', steps = { { title = 'Op', note = '• Sign on: any zone sergeant.\n• Kill 5 Sub-zero Gears. Report back.\n• Rewards: experience, cruor, Dominion Notes.\n• Below level 75 the experience is reduced.\n• Rewards are paid on turn-in.' } } },
    { name = 'Uleguerand - Dominion Op #04', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Snowflakes. Source: https://vanadreams.org/wiki/#quest-153', steps = { { title = 'Op', note = '• Sign on: any zone sergeant.\n• Kill 5 Snowflakes. Report back.\n• Sergeants: Maat (J-5), Romaa, Zazarg (G-7).\n• Rewards: experience, cruor, Dominion Notes.\n• Below level 75 the experience is reduced.\n• Cancel at a sergeant to switch ops.' } } },
    { name = 'Uleguerand - Dominion Op #05', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Verglas Golems. Source: https://vanadreams.org/wiki/#quest-154', steps = { { title = 'Op', note = '• Sign on: Maat\'s sergeant.\n• Kill 5 Verglas Golems. Report back.\n• Repeatable; kill count shown as you go.' } } },
    { name = 'Uleguerand - Dominion Op #06', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Olyphants. Source: https://vanadreams.org/wiki/#quest-155', steps = { { title = 'Op', note = '• Sign on: any zone sergeant.\n• Kill 5 Olyphants. Report back.\n• Sergeants: Maat (J-5), Romaa, Zazarg (G-7).\n• Kills credit the player who lands them.\n• Cancel by talking to the sergeant again.' } } },
    { name = 'Uleguerand - Dominion Op #07', group = 'Abyssea', desc = 'Abyssea - Uleguerand Dominion Op: kill 5 Svelldrakes. Source: https://vanadreams.org/wiki/#quest-156', steps = { { title = 'Op', note = '• Sign on: Maat\'s sergeant.\n• Kill 5 Svelldrakes. Report back.\n• Kills count only while the op is active.' } } },
    { name = 'Uleguerand - Dominion Op #08', group = 'Abyssea', desc = 'Kill five Adasaurus for the Dominion Sergeant in Abyssea - Uleguerand. Source: https://vanadreams.org/wiki/#quest-157', steps = { { title = 'Walkthrough', note = '• Sign up for Op #08 with the Dominion Sergeant at Maat\'s Camp.\n• Kill 5 Adasaurus.\n• Report back.' }, { title = 'Notes', note = '• One active Op at a time; the Sergeant can cancel it.\n• Pays experience, cruor and dominion notes.' } } },
    { name = 'Uleguerand - Dominion Op #09', group = 'Abyssea', desc = 'Kill Ectozoon for the Dominion Sergeant in Abyssea - Uleguerand. Source: https://vanadreams.org/wiki/#quest-158', steps = { { title = 'Walkthrough', note = '• Take the Op from the Dominion Sergeant at Romaa Mihgo\'s Camp.\n• Kill Ectozoon.' } } },
    { name = 'Uleguerand - Dominion Op #10', group = 'Abyssea', desc = 'Kill five Hoarmites in Abyssea - Uleguerand. Source: https://vanadreams.org/wiki/#quest-159', steps = { { title = 'Walkthrough', note = '• Take Op #10 from the Dominion Sergeant at Romaa Mihgo\'s Camp.\n• Kill 5 Hoarmites.\n• Report back to that Sergeant.' }, { title = 'Reward', note = '• Experience, cruor, Dominion Notes.' } } },
    { name = 'Uleguerand - Dominion Op #11', group = 'Abyssea', desc = 'Kill five Ermit Imps in Abyssea - Uleguerand. Source: https://vanadreams.org/wiki/#quest-160', steps = { { title = 'Walkthrough', note = '• Sign up for Op #11 with the Dominion Sergeant at Zazarg\'s Camp.\n• Kill 5 Ermit Imps.\n• Report to any Dominion Sergeant in the zone.' }, { title = 'Notes', note = '• Repeatable; cancel at a Sergeant.\n• Pays experience, cruor and dominion notes.' } } },
    { name = 'Uleguerand - Dominion Op #12', group = 'Abyssea', desc = 'Kill five Benumbed Vodoriga in Abyssea - Uleguerand for experience, cruor and Dominion notes. Source: https://vanadreams.org/wiki/#quest-161', steps = { { title = 'Walkthrough', note = '• Take the Op from a Dominion Sergeant in the zone.\n• Kill 5 Benumbed Vodoriga.\n• Report to a Sergeant to collect rewards.' }, { title = 'Notes', note = '• Below level 75 the experience is lowered.' } } },
    { name = 'Uleguerand - Dominion Op #13', group = 'Abyssea', desc = 'Kill five Bluffalo in Abyssea - Uleguerand. Source: https://vanadreams.org/wiki/#quest-162', steps = { { title = 'Walkthrough', note = '• Sign on for Op #13 at Romaa Mihgo\'s Camp (Dominion Sergeant).\n• Kill 5 Bluffalo.\n• Report back to that Sergeant.' }, { title = 'Notes', note = '• Repeatable; pays Dominion Notes each time.' } } },
    { name = 'Uleguerand - Dominion Op #14', group = 'Abyssea', desc = 'Kill five Sierra Tigers in Abyssea - Uleguerand. Source: https://vanadreams.org/wiki/#quest-163', steps = { { title = 'Walkthrough', note = '• Sign on with the Romaa Mihgo\'s Camp Dominion Sergeant.\n• Kill 5 Sierra Tigers (only counted while the Op is active).\n• Report to the Sergeant for the reward.' } } },
    { name = 'A Certain Substitute Patrolman', group = 'Adoulin', desc = 'Patrol Western Adoulin by checking in with seven residents in a fixed order. Starts with Rising Solstice. Source: https://vanadreams.org/wiki/#quest-175', steps = { { title = 'Requirements', note = '• Seekers of Adoulin: Life on the Frontier (reached/finished).' }, { title = 'Walkthrough', note = '• Get the Western Adoulin patrol route from Rising Solstice (D-9).\n• Visit in order: Zaoso (E-8), Clemmar (G-8), Kongramm (I-5), Virsaint (H-8), Shipilolo (J-10), Dangueubert (H-11), Nylene (H-10).\n• Report to Rising Solstice (D-9).' }, { title = 'Notes', note = '• Order matters.\n• The route key item is taken at the end.' }, { title = 'Reward', note = '• 1,000 EXP' } } },
    { name = 'A Geothermal Expedition', group = 'Adoulin', desc = 'Collect five hot spring reports in Morimar Basalt Fields at set Vana\'diel hours for Fallion. Source: https://vanadreams.org/wiki/#quest-176', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge; Adoulin fame 1.' }, { title = 'Walkthrough', note = '• Accept from Fallion (I-10), Morimar Basalt Fields.\n• Examine the Hot Springs beyond Bivouac #2 (H-7, H-8, G-8) at varying hours to get reports #1-#5.\n• Hand all five to Fallion (I-10).' }, { title = 'Report hours', note = '• #1: any spring at 0-1, 7-8, 10-11, 17-18, 21-23 (not 21-23 at H-8).\n• #2: any spring at 3-4, 5-6, 13-14, 17-24.\n• #3: H-7 only at 1-3, 11-12, 20-21, 22-23.\n• #4: H-8 only at 10-11, 18-19, 20-21, 22-23.\n• #5: G-8 only at 5-6, 10-11, 17-18.\n• No new info means try a different hour.' }, { title = 'Reward', note = '• 3,000 EXP' } } },
    { name = 'A Good Pair of Crocs (A Good Pair of Crocs)', group = 'Adoulin', desc = 'Fame quest: Felmsy (Eastern Adoulin) wants a Velkk Necklace or Velkk Mask. Source: https://vanadreams.org/wiki/#quest-177', steps = { { title = 'Walkthrough', note = '• Accept from Felmsy (G-5), Eastern Adoulin (needs Seekers of Adoulin progress that opens fame quests).\n• Get a Velkk Necklace or Velkk Mask from Velkk.\n• Trade it to Felmsy.' }, { title = 'Notes', note = '• Cycles with It Sets My Heart Aflutter and A Shot in the Dark after all three are done; each gives fame, bayld and EXP.' }, { title = 'Reward', note = '• 500 EXP; Adoulin fame (6)' } } },
    { name = 'A Shot in the Dark (A Shot in the Dark)', group = 'Adoulin', desc = 'Third quest in the Adoulin fame cycle: give Pudith an Umbril Ooze. Source: https://vanadreams.org/wiki/#quest-178', steps = { { title = 'Walkthrough', note = '• Accept from Pudith (F-6), Eastern Adoulin.\n• Get one Umbril Ooze.\n• Trade only that single Umbril Ooze to Pudith.' }, { title = 'Notes', note = '• Repeats only after It Sets My Heart Aflutter and A Good Pair of Crocs are done.' }, { title = 'Reward', note = '• 500 EXP; Adoulin fame (6)' } } },
    { name = 'A Stone\'s Throw Away', group = 'Adoulin', desc = 'Mine a Marble Nugget for Apolliane in Morimar Basalt Fields to learn "Demolishing". Source: https://vanadreams.org/wiki/#quest-179', steps = { { title = 'Walkthrough', note = '• Accept from Apolliane (K-10), Morimar Basalt Fields.\n• Mine a Marble Nugget at a Morimar mining point.\n• Trade it to Apolliane.' } } },
    { name = 'Boiling Over', group = 'Adoulin', desc = 'Survey the Moh Gates magma vein for Leautiere in Yahse Hunting Grounds. Source: https://vanadreams.org/wiki/#quest-185', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge; Adoulin fame 1+.' }, { title = 'Walkthrough', note = '• Accept from Leautiere (G-7), Yahse Hunting Grounds.\n• In the Moh Gates, examine the Magma Vein (Map 1, J-5) for the survey report.\n• Talk to Leautiere to turn it in.' }, { title = 'Notes', note = '• A reive often blocks the path; enter the Moh Gates from Morimar\'s Frontier Station.\n• Lost the report? Examine the vein again.' }, { title = 'Reward', note = '• 2,000 EXP' } } },
    { name = 'Breaking the Ice', group = 'Adoulin', desc = 'Trade hides and a tusk to Traiffeaux in Kamihr Drifts for fuzzy earmuffs and the "Fragmenting" skill. Source: https://vanadreams.org/wiki/#quest-186', steps = { { title = 'Walkthrough', note = '• Accept from Traiffeaux (K-10), Kamihr Drifts.\n• Trade exactly 3 Rabbit Hides + 1 Raaz Tusk together to him.' }, { title = 'Reward', note = '• Pair of fuzzy earmuffs; learn "Fragmenting".' } } },
    { name = 'Dances with Luopans', group = 'Adoulin', desc = 'Geomancer unlock: get homeland soil, trade a Petrified Log for a luopan, then absorb locus energy. Starts with Sylvie in Western Adoulin. Source: https://vanadreams.org/wiki/#quest-188', steps = { { title = 'Walkthrough', note = '• Accept from Sylvie (I-5), Western Adoulin.\n• Examine the Ergon Locus in your nation\'s zone (La Theine Plateau / Konschtat Highlands / Tahrongi Canyon) to collect homeland soil (fistful).\n• Give Sylvie a Petrified Log; she hands over the luopan.\n• Enter a locus area in Ceizak Battlegrounds or Yahse Hunting Grounds and /heal until a mystical warmth is felt.\n• Return to Sylvie to unlock Geomancer.' }, { title = 'Notes', note = '• The luopan must be held while absorbing; don\'t leave the area.\n• Replacement Matre Bell from Sylvie: 300,000 gil or 150,000 bayld.' }, { title = 'Reward', note = '• Indi-Poison, Matre Bell' } } },
    { name = 'Empty Nest', group = 'Adoulin', desc = 'Kill Belaboring Wasps in Ceizak Battlegrounds for Bataron. Source: https://vanadreams.org/wiki/#quest-195', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge; Adoulin fame 1.' }, { title = 'Walkthrough', note = '• Accept from Bataron (H-7), Ceizak Battlegrounds.\n• Kill 8 Belaboring Wasps (zoning may reset the count).\n• Return to Bataron.' }, { title = 'Reward', note = '• 2,000 EXP' } } },
    { name = 'Flavors of Our Lives (Flavors of Our Lives)', group = 'Adoulin', desc = 'Track down a blightberry for Berghent\'s drink. Starts with Berghent in Western Adoulin. Source: https://vanadreams.org/wiki/#quest-201', steps = { { title = 'Walkthrough', note = '• Accept from Berghent (J-9, by the Big Bridge), Western Adoulin; ask again if you declined.\n• Talk to Masad (G-10) in the Mummers\' Coalition.\n• After one Vana\'diel day, talk to Dewalt (G-7) in the Couriers\' Coalition.\n• Enter Rala Waterways at (I-12) and talk to Chalvava (F-11).\n• Harvest the blightberry at the Yahse Hunting Grounds Harvesting Point with a Sickle.\n• Return to Berghent.' }, { title = 'Reward', note = '• 500 EXP; title Potation Pathfinder' } } },
    { name = 'Geomancerrific', group = 'Adoulin', desc = 'GEO weapon skill quest: awaken the Trial Wand to learn Exudation. Starts with Nhili Uvolep in Eastern Adoulin. Source: https://vanadreams.org/wiki/#quest-205', steps = { { title = 'Requirements', note = '• GEO 99 main; Dances with Luopans done.' }, { title = 'Walkthrough', note = '• Get the Trial Wand from Nhili Uvolep (I-7), Eastern Adoulin.\n• Fight with it equipped and weapon skill until it reaches 300 WS points.\n• Trade it back to Nhili Uvolep.' }, { title = 'Notes', note = '• Early trade shows progress and returns the wand.\n• Lost wand: ask Nhili Uvolep for another.' }, { title = 'Reward', note = '• Trial Wand' } } },
    { name = 'Grind to Sawdust', group = 'Adoulin', desc = 'Join a Colonization Reive in Ceizak Battlegrounds, then report to Elmric for the Logging key item. Source: https://vanadreams.org/wiki/#quest-207', steps = { { title = 'Walkthrough', note = '• Talk to Elmric (J-7), Ceizak Battlegrounds.\n• Participate in a Colonization Reive until the end-of-reive evaluation (winning not required).\n• Return to Elmric.' }, { title = 'Notes', note = '• If you were already evaluated in a reive, Elmric completes it at once.' }, { title = 'Reward', note = '• Key item "Logging"' } } },
    { name = 'Hide and Go Peak', group = 'Adoulin', desc = 'Marjami Ravine quest that teaches Climbing so you can use Scalable Areas. Source: https://vanadreams.org/wiki/#quest-208', steps = { { title = 'Walkthrough', note = '• Examine the Toppled Tree (L-7), Marjami Ravine.\n• Examine the Velkk Cache (K-10) for a large strip of Velkk hide.\n• Examine the Toppled Tree again to hand it over.\n• Examine Scalable Area 2 for Velkk gloves and Climbing.' }, { title = 'Notes', note = '• Scalable Areas unlock in Cirdas Caverns, Dho Gates, Marjami Ravine, Moh Gates, Morimar Basalt Fields, Sih Gates and Woh Gates.' } } },
    { name = 'Hunger Strikes', group = 'Adoulin', desc = 'Give Westerly Breeze in Western Adoulin a Wisdom Soup. Source: https://vanadreams.org/wiki/#quest-210', steps = { { title = 'Walkthrough', note = '• Accept from Westerly Breeze (I-5), Western Adoulin.\n• Get a Wisdom Soup.\n• Trade it to her.' }, { title = 'Notes', note = '• Other food is consumed without credit.\n• Leads to The Starving the next Vana\'diel day.' }, { title = 'Reward', note = '• 1,000 EXP' } } },
    { name = 'I\'m on a Boat', group = 'Adoulin', desc = 'Bring materials to Choubollet in Foret de Hennetiel and ride the castoff points to learn watercrafting. Source: https://vanadreams.org/wiki/#quest-212', steps = { { title = 'Walkthrough', note = '• Talk to Choubollet (J-6), Foret de Hennetiel.\n• Trade 3 Dhalmel Leather, 1 Umbril Ooze, 1 Twitherym Scale for the watercraft key item.\n• Examine Castoff Point 4 and ride.\n• Then examine Castoff Point 5 and ride.\n• Talk to Choubollet to finish.' }, { title = 'Notes', note = '• Points must be used 4 then 5.\n• Afterwards castoff points in Cirdas Caverns, Foret de Hennetiel, Morimar Basalt Fields, Sih Gates and Yahse Hunting Grounds work as boat landings.\n• Toxin Tussler title adds an extra scene option on the river route.' } } },
    { name = 'It Sets My Heart Aflutter (It Sets My Heart Aflutter)', group = 'Adoulin', desc = 'Give two Twitherym Wings to Saldinor in Rala Waterways. Source: https://vanadreams.org/wiki/#quest-215', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways at (I-12) from Western Adoulin; accept from Saldinor (E-10). Needs Pioneer\'s Badge.\n• Get exactly two Twitherym Wings.\n• Trade them to Saldinor.' }, { title = 'Notes', note = '• Repeatable for fame once A Good Pair of Crocs and A Shot in the Dark are also done.' }, { title = 'Reward', note = '• 500 EXP; Adoulin fame (6)' } } },
    { name = 'Lerene\'s Lament', group = 'Adoulin', desc = 'Give Lerene 2 Ancestral Cloth in Outer Ra\'Kaznar. Source: https://vanadreams.org/wiki/#quest-218', steps = { { title = 'Walkthrough', note = '• Accept from Lerene (Map 1, N-7), Outer Ra\'Kaznar.\n• Get 2 Ancestral Cloth.\n• Trade them to Lerene.' }, { title = 'Reward', note = '• Lerene\'s paten; learn Pulverizing.' } } },
    { name = 'Rune Fencing the Night Away', group = 'Adoulin', desc = 'RUN weapon skill quest: power up the Trial Blade for Gaddiux to learn Dimidiation (also pays bayld). Source: https://vanadreams.org/wiki/#quest-233', steps = { { title = 'Requirements', note = '• RUN 99; Children of the Rune done.' }, { title = 'Walkthrough', note = '• Get the Trial Blade from Gaddiux (J-10), Western Adoulin.\n• Weapon skill with it until it has 300 WS points.\n• Trade it back to Gaddiux.' }, { title = 'Notes', note = '• Trade early to check progress; Gaddiux replaces a lost blade.\n• Not repeatable.' }, { title = 'Reward', note = '• Trial Blade' } } },
    { name = 'The Longest Way Round...', group = 'Adoulin', desc = 'Patrol Eastern Adoulin by visiting seven residents in order, then report to Vastran. Source: https://vanadreams.org/wiki/#quest-242', steps = { { title = 'Requirements', note = '• Seekers of Adoulin mission Life on the Frontier reached.' }, { title = 'Walkthrough', note = '• Get the Eastern Adoulin patrol route from Vastran (F-8).\n• Visit in order: Fostaig (G-7), Lamaron (G-5), Irate Destrier (G-9), Nhili Uvolep (I-7), Ploh Trishbahk (K-9), Cunegonde (G-11), Ndah Tolohjin.\n• Return to Vastran.' }, { title = 'Reward', note = '• 1,000 EXP' } } },
    { name = 'The Starving', group = 'Adoulin', desc = 'Give Westerly Breeze in Western Adoulin a Goblin Drink. Source: https://vanadreams.org/wiki/#quest-244', steps = { { title = 'Walkthrough', note = '• Wait a Vana\'diel day after the previous quest, then accept from Westerly Breeze (I-5).\n• Get a Goblin Drink (no other drink works).\n• Trade it to her.' }, { title = 'Notes', note = '• Zone and wait a day to unlock Always More, Quoth the Ravenous.' }, { title = 'Reward', note = '• 1,000 EXP' } } },
    { name = 'The Whole Place Is Abuzz', group = 'Adoulin', desc = 'Catch bees in Yahse Hunting Grounds and deliver the hive to Ndah Tolohjin; rewards toxin resilience and bayld. Source: https://vanadreams.org/wiki/#quest-247', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge; Adoulin fame 1.' }, { title = 'Walkthrough', note = '• Get the Land of Milk and Honey hive from Rumin-Flumin (H-9), Frontier Bivouac #3, Yahse.\n• Check the Pollinating Swarm (G-10), then /heal until 10 bees are caught.\n• Stand and check the swarm again for the full hive.\n• Deliver it to Ndah Tolohjin (G-9) outside the Scouts\' Coalition, Eastern Adoulin.' }, { title = 'Notes', note = '• Zoning wipes the count; stopping rest too long ends the attempt.' }, { title = 'Reward', note = '• Key item: toxin resilience' } } },
    { name = 'To Catch a Predator', group = 'Adoulin', desc = 'Lure the Truculent Mantis with bait at Ceizak Battlegrounds\' Frontier Bivouac #1 and kill it. Source: https://vanadreams.org/wiki/#quest-249', steps = { { title = 'Requirements', note = '• Adoulinian charter permit; Adoulin fame 1.' }, { title = 'Walkthrough', note = '• Talk to Lucretia (H-9), Frontier Bivouac #1.\n• Kill Fernfelling Chapuli to the south for mantid bait.\n• Use the bait on the Claw Mark (north of camp) to spawn the Truculent Mantis.\n• Kill it for the flayed mantid corpse.\n• Bring the corpse to Lucretia.' }, { title = 'Notes', note = '• Bait is consumed on use; if the Mantis despawns you need new bait.\n• Lucretia takes leftover bait.' }, { title = 'Reward', note = '• 2,000 EXP' } } },
    { name = 'Transporting', group = 'Adoulin', desc = 'Deliver a misdelivered parcel via the Rala Waterways for Vaulois. Source: https://vanadreams.org/wiki/#quest-251', steps = { { title = 'Requirements', note = '• Adoulin fame 2.' }, { title = 'Walkthrough', note = '• Get the misdelivered parcel from Vaulois (H-6), Western Adoulin.\n• Talk to Kongramm (I-5).\n• Enter Rala Waterways at (F-5); examine the ??? (C-6) at sluice gate 6 (parcel is taken).\n• Return to Vaulois.' }, { title = 'Reward', note = '• 1,000 EXP' } } },
    { name = 'Twitherym Dust', group = 'Adoulin', desc = 'Fetch dust-laden sap from the Twinkling Tree for Gurren-Murren in Ceizak Battlegrounds. Source: https://vanadreams.org/wiki/#quest-253', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge; Adoulin fame 1+.' }, { title = 'Walkthrough', note = '• Accept from Gurren-Murren (K-7), Ceizak Battlegrounds.\n• Examine the Twinkling Tree to the south for a cupful of dust-laden sap.\n• Talk to Gurren-Murren again.' }, { title = 'Reward', note = '• 1,000 EXP' } } },
    { name = 'A Taste of Honey', group = 'Aht Urhgan', desc = 'Bring Qutiba three White Honey from the Wajaom Woodlands hives. Source: https://vanadreams.org/wiki/#quest-265', steps = { { title = 'Requirements', note = '• Vanishing Act done, then zone and wait.' }, { title = 'Walkthrough', note = '• Accept from Qutiba or Ulamaal (K-12), Aht Urhgan Whitegate.\n• Collect White Honey from Pephredo Hives in Wajaom Woodlands (one per hive per Japanese day).\n• Trade 3 White Honey to Qutiba.' }, { title = 'Notes', note = '• Qutiba gives recipe hints afterwards; Fochacha has extra pre-quest dialogue.' }, { title = 'Reward', note = '• Irmik Helvasi, White Honey' } } },
    { name = 'An Empty Vessel (BLU Unlock)', group = 'Aht Urhgan', desc = 'Blue Mage unlock via Waoud\'s divination, a mystic item and Yasfel in Aydeewa Subterrane. Source: https://vanadreams.org/wiki/#quest-266', steps = { { title = 'Requirements', note = '• Any job at level 30.' }, { title = 'Walkthrough', note = '• Pay Waoud (J-10), Whitegate, for a divination and answer all 10 questions right.\n• Accept; after a Vana\'diel day and a zone, talk to Waoud.\n• After another day and zone, Waoud names the item: Siren\'s Tear, Sunsand or Dangruf Stone.\n• Get it and show it to Waoud (kept).\n• Once more wait a day, zone and see Waoud; then enter the marked area in Aydeewa Subterrane holding the item.\n• Accept Yasfel\'s offer to become a Blue Mage.' }, { title = 'Notes', note = '• Divination: 1000 gil, retry after a day and zone.\n• Refusing Yasfel cancels; restartable.' }, { title = 'Reward', note = '• Title: Bearer of the Mark of Zahak' } } },
    { name = 'Arts and Crafts', group = 'Aht Urhgan', desc = 'Visit seven Whitegate artisans for Hadahda, then trade back the Sutlac. Source: https://vanadreams.org/wiki/#quest-268', steps = { { title = 'Walkthrough', note = '• Accept from Hadahda (F-10), Aht Urhgan Whitegate.\n• Talk (any order) to Mhasbaf (J-8), Mathlouq (F-5), Zabahf (F-8), Ekhu Pesshyadha (H-6), Qutiba, Balakaf (I-5), Matifa (H-9).\n• Return to Hadahda for a Sutlac.\n• Trade the Sutlac to Hadahda.' }, { title = 'Reward', note = '• Imp. Brz. Piece, Sutlac' } } },
    { name = 'Beginnings (BLU AF1)', group = 'Aht Urhgan', desc = 'BLU AF1: gather the five Brands of the Serpents for Waoud. Source: https://vanadreams.org/wiki/#quest-269', steps = { { title = 'Requirements', note = '• BLU main at AF level; Immortal Sentries (ToAU mission) and An Empty Vessel done.' }, { title = 'Walkthrough', note = '• Accept from Waoud (J-10), Whitegate.\n• Springserpent: Meyaada, Arrapago Reef.\n• Skyserpent: Daswil (Map 2, H-10), Bhaflau Thickets.\n• Galeserpent: Nahshib (Map 2, I-9), Caedarva Mire; Stoneserpent: Nareema, Caedarva Mire.\n• Flameserpent: Waudeen (K-6), Mount Zhayolm.\n• Return all five to Waoud.' }, { title = 'Notes', note = '• Waoud divines missing brands for 1,000 gil.\n• Omens unlocks one minute after completion.' }, { title = 'Reward', note = '• Immortal\'s Scimitar; title Branded by the Five Serpents' } } },
    { name = 'Omens (BLU AF2)', group = 'Aht Urhgan', desc = 'BLU AF2: a Navukgo Execution Chamber fight and a trail in Aydeewa Subterrane. Source: https://vanadreams.org/wiki/#quest-270', steps = { { title = 'Requirements', note = '• BLU main at the required level; Beginnings done (and enough wait since it).' }, { title = 'Walkthrough', note = '• Talk to Waoud (J-10), Whitegate.\n• Talk again; buy a 1,000-gil divination.\n• Win the Omens fight in Navukgo Execution Chamber.\n• Get the sealed Immortal envelope from Waoud.\n• Show it to Lathuya (F-8), Whitegate.\n• Examine the ??? in Aydeewa Subterrane.\n• Return to Lathuya.' }, { title = 'Reward', note = '• Magus Charuqs; title Immortal Lion' } } },
    { name = 'Transformations (BLU AF3)', group = 'Aht Urhgan', desc = 'BLU AF3: search Alzadaal Undersea Ruins and kill the Nepionic Soulflayer. Source: https://vanadreams.org/wiki/#quest-271', steps = { { title = 'Requirements', note = '• BLU main at the required level; Omens done (and enough wait since it).' }, { title = 'Walkthrough', note = '• Buy a 1,000-gil divination from Waoud (J-10).\n• Talk to the Imperial Whitegate (L-9).\n• Enter Alzadaal Undersea Ruins from Caedarva Mire (I-10); walk into the first then the second marked area.\n• Examine the ??? and kill the Nepionic Soulflayer.\n• Examine the ??? again.' }, { title = 'Reward', note = '• Magus Keffiyeh; title Paragon of Blue Mage Excellence' } } },
    { name = 'The Beast Within (BLU LB)', group = 'Aht Urhgan', desc = 'BLU limit break: win The Beast Within in the Jade Sepulcher to lift the cap from 70 to 75. Source: https://vanadreams.org/wiki/#quest-272', steps = { { title = 'Requirements', note = '• BLU main 66+; Transformations done; Blue M. Testimony.' }, { title = 'Walkthrough', note = '• Accept from Waoud (J-10), Whitegate.\n• Hand the Blue M. Testimony (trade) to the Imperial Whitegate (L-9).\n• Watch the Jade Sepulcher cutscene.\n• Win The Beast Within.' }, { title = 'Notes', note = '• Waoud divinations: 1,000 gil any time.' }, { title = 'Reward', note = '• Instant Warp scroll; title Master of Ambition' } } },
    { name = 'Equipped for All Occasions', group = 'Aht Urhgan', desc = 'COR AF1: beat a Lost Soul in Maze of Shakhrami for its trigger; Ratihb rewards the Trump Gun. Source: https://vanadreams.org/wiki/#quest-273', steps = { { title = 'Requirements', note = '• COR at AF level; Luck of the Draw done, then talk to Ratihb for the extra scene.' }, { title = 'Walkthrough', note = '• Check the ??? (H-10), Arrapago Reef.\n• Enter Maze of Shakhrami from Attohwa Chasm (G-10); check the Iron Door to spawn a Lost Soul.\n• Kill it, check the door again for the wheel lock trigger.\n• Check the ??? (H-10) in Arrapago Reef again.\n• Talk to Ratihb (J-12), Whitegate.' }, { title = 'Reward', note = '• Trump Gun' } } },
    { name = 'Navigating the Unfriendly Seas', group = 'Aht Urhgan', desc = 'COR AF2: use a Hydrogauge at a Wajaom Woodlands leypoint and report to the ??? in Arrapago Reef. Source: https://vanadreams.org/wiki/#quest-274', steps = { { title = 'Requirements', note = '• COR main at AF2 level; Equipped for All Occasions done; Hydrogauge.' }, { title = 'Walkthrough', note = '• Examine the ??? (H-10), Arrapago Reef.\n• Trade the Hydrogauge to Leleroon (G-7), Nashmau.\n• Trade it to the Leypoint (G-8), Wajaom Woodlands (consumed).\n• After one minute, examine the Leypoint again.\n• Return to the ??? in Arrapago Reef.' }, { title = 'Reward', note = '• Corsair\'s Culottes' } } },
    { name = 'Against All Odds', group = 'Aht Urhgan', desc = 'COR AF3: defeat Gowam and Yazquhl in The Ashu Talif for the Corsair\'s Tricorne. Source: https://vanadreams.org/wiki/#quest-275', steps = { { title = 'Requirements', note = '• COR main 50+; Navigating the Unfriendly Seas done.' }, { title = 'Walkthrough', note = '• Walk into the marked area in Whitegate for the life float.\n• Walk to the marked spot in Arrapago Reef for a cutscene.\n• Enter The Ashu Talif with the float (consumed) and kill Gowam and Yazquhl.\n• Lost the float? Ratihb (J-12) gives another after the next game day.\n• Talk to the Cutter (Map 5, H-8) in Arrapago Reef, or rezone, for the final scene.' }, { title = 'Reward', note = '• Corsair\'s Tricorne; title Paragon of Corsair Excellence' } } },
    { name = 'Breaking the Bonds of Fate', group = 'Aht Urhgan', desc = 'COR limit break: trade the testimony at a ??? in Arrapago Reef and win in Talacca Cove to lift the cap to 75. Source: https://vanadreams.org/wiki/#quest-276', steps = { { title = 'Requirements', note = '• COR main 66+ throughout; Against All Odds done; Cor. Testimony.' }, { title = 'Walkthrough', note = '• Examine the ??? in Arrapago Reef and accept.\n• Trade the Cor. Testimony to it.\n• Win Breaking the Bonds of Fate in Talacca Cove.' }, { title = 'Reward', note = '• Cap 70 to 75; Instant Warp; title Master of Chance' } } },
    { name = 'Cook-a-roon', group = 'Aht Urhgan', desc = 'Repeatable fish turn-in for Ququroon in Nashmau. Source: https://vanadreams.org/wiki/#quest-278', steps = { { title = 'Walkthrough', note = '• Accept from Ququroon (G-6), Nashmau.\n• Trade one each: Ahtapot, Istakoz, Istavrit, Istiridye, Mercanbaligi.' }, { title = 'Reward', note = '• Repeatable; roughly 50% chance of a bonus Nashmau Stew.' } } },
    { name = 'Delivering the Goods', group = 'Aht Urhgan', desc = 'Whitegate errand between Fochacha and Qutiba/Ulamaal. Source: https://vanadreams.org/wiki/#quest-279', steps = { { title = 'Walkthrough', note = '• Accept from Fochacha (I-9), Whitegate.\n• Talk to Qutiba or Ulamaal (K-12).\n• Return to Fochacha.' }, { title = 'Notes', note = '• Zone before starting Vanishing Act.' }, { title = 'Reward', note = '• Imp. Brz. Piece' } } },
    { name = 'Divine Interference', group = 'Aht Urhgan', desc = 'Make a lightning cell and beat Alexander in Nyzul Isle for Naja Salaheem\'s reward. Source: https://vanadreams.org/wiki/#quest-280', steps = { { title = 'Requirements', note = '• ToAU mission Eternal Mercenary active; Waking the Colossus done.' }, { title = 'Walkthrough', note = '• Enter the marked area in Whitegate, then accept at the Imperial Whitegate (L-9).\n• Examine the Acid-eaten Door (I-9), Mount Zhayolm.\n• Trade 3 Plumbago to the door for the lightning cell.\n• Examine the Blank Lamp in Alzadaal Undersea Ruins.\n• Enter Nyzul Isle via the Runic Seal (Map 5, I-9) and kill Alexander.\n• Zone into Alzadaal for the whisper of radiance.\n• Show it to Naja Salaheem (I-10), Whitegate, and pick a reward.' }, { title = 'Reward', note = '• Always Imp. Gold Piece, plus one of Colossus\'s Mantle/Earring/Torque, 10,000 gil or the Alexander spell; title Heir of the Blessed Radiance.\n• Repeatable after the next day change.' } } },
    { name = 'Embers of His Past', group = 'Aht Urhgan', desc = 'Help Fari-Wari recall a lost friend via Wajaom Woodlands and night visits to Mount Zhayolm. Source: https://vanadreams.org/wiki/#quest-282', steps = { { title = 'Requirements', note = '• Soothing Waters done.' }, { title = 'Walkthrough', note = '• Talk to Fari-Wari in Whitegate; you\'re sent to Wajaom Woodlands.\n• Re-enter Wajaom twice more for two scenes.\n• At night (18:00-6:00) examine Sprightly Footsteps (L-7), Mount Zhayolm.\n• At night examine Withered Petals (L-6), Mount Zhayolm.\n• Trade a Hydrangea to Fari-Wari (K-12).\n• Re-enter Wajaom twice more; the Hydrangea comes back.\n• At night trade the Hydrangea to Withered Petals (L-6).\n• Talk to Fari-Wari to finish; zone and talk again for a Mercenary Camp Entry Slip.' }, { title = 'Reward', note = '• Imp. Gold Piece, M. Camp Entry; title Flameserpent Facilitator' } } },
    { name = 'Fear of the Dark 2', group = 'Aht Urhgan', desc = 'Give Suldiran in Al Zahbi two Imp Wings. Source: https://vanadreams.org/wiki/#quest-283', steps = { { title = 'Walkthrough', note = '• Accept from Suldiran (J-10), Al Zahbi.\n• Trade 2 Imp Wings.' }, { title = 'Reward', note = '• 200 gil; title Dark Resistant.\n• Repeat trades of 2 Imp Wings pay 200 gil each.' } } },
    { name = 'Fist of the People', group = 'Aht Urhgan', desc = 'Take a Rusty Medal to a Wajaom Woodlands leypoint for Talhaal. Source: https://vanadreams.org/wiki/#quest-285', steps = { { title = 'Requirements', note = '• Ode to the Serpents accepted; Rusty Medal.' }, { title = 'Walkthrough', note = '• Talk to Talhaal (H-6), Al Zahbi.\n• Talk to Fari-Wari (K-12), Whitegate.\n• Trade the Rusty Medal to the Leypoint (G-8), Wajaom Woodlands.' }, { title = 'Reward', note = '• Imperial Standing; title Stoneserpent Shocktrooper' } } },
    { name = 'Give Peace a Chance', group = 'Aht Urhgan', desc = 'Scout Wajaom Woodlands and Mamook on Mishhar\'s behalf. Source: https://vanadreams.org/wiki/#quest-289', steps = { { title = 'Requirements', note = '• Treasures of Aht Urhgan access' }, { title = 'Walkthrough', note = '• Accept from Mishhar (H-8), Aht Urhgan Whitegate.\n• Check the ??? in Wajaom Woodlands at night for a cutscene.\n• Report to Mishhar.\n• Enter Mamook via Wajaom Woodlands (E-12) and check its ???.\n• Report to Mishhar to finish.' }, { title = 'Notes', note = '• Zone before taking another daily-timed Aht Urhgan quest.' }, { title = 'Reward', note = '• Imp. Slv. Piece' } } },
    { name = 'Got It All', group = 'Aht Urhgan', desc = 'An errand loop among three Whitegate NPCs ending in a Bibiki Seashell. Source: https://vanadreams.org/wiki/#quest-290', steps = { { title = 'Walkthrough', note = '• Start with Tehf Kimasnahya (F-8), Aht Urhgan Whitegate.\n• Speak to Ekhu Pesshyadha (H-6), then Zabahf (F-8).\n• Ekhu Pesshyadha again: get the vial of luminous water.\n• Hand the vial to Tehf Kimasnahya when prompted.\n• Walk to the marked Whitegate spot for a scene.\n• Speak to Tehf Kimasnahya, zone, speak again to finish.' }, { title = 'Notes', note = '• The vial is consumed on hand-in.' }, { title = 'Reward', note = '• Bibiki Seashell' } } },
    { name = 'Keeping Notes', group = 'Aht Urhgan', desc = 'Deliver writing supplies to Ahkk Jharcham in Whitegate. Source: https://vanadreams.org/wiki/#quest-291', steps = { { title = 'Walkthrough', note = '• Accept from Ahkk Jharcham (I-10), Aht Urhgan Whitegate.\n• Trade him a Parchment plus a Black Ink in one trade.' }, { title = 'Notes', note = '• Other trades are rejected.' } } },
    { name = 'Led Astry', group = 'Aht Urhgan', desc = 'Run errands around Whitegate for Mhasbaf, then carry Bernahn\'s letter to Tataroon in Nashmau. Source: https://vanadreams.org/wiki/#quest-292', steps = { { title = 'Walkthrough', note = '• Accept from Mhasbaf (J-8), Aht Urhgan Whitegate.\n• Enter the marked Whitegate area for a scene.\n• Speak to Tohka Telposkha (I-8).\n• Speak to Rubahah (F-9) and Cacaroon (G-11), any order.\n• Enter the second marked area to get Bernahn\'s letter.\n• Deliver it to Tataroon (G-8), Nashmau.' }, { title = 'Reward', note = '• Imp. Slv. Piece' } } },
    { name = 'Luck of the Draw', group = 'Aht Urhgan', desc = 'Corsair unlock: retrieve a hexagun in Talacca Cove. Begins with Ratihb in Whitegate. Source: https://vanadreams.org/wiki/#quest-293', steps = { { title = 'Requirements', note = '• Level 30+' }, { title = 'Walkthrough', note = '• Speak to Ratihb (J-12), then Mafwahb (L-9), Aht Urhgan Whitegate.\n• Check the ??? at H-10, Arrapago Reef, for a scene.\n• Check the ??? (F-7), Talacca Cove: forgotten hexagun.\n• Check the Rock Slab (E-6), Talacca Cove, to unlock Corsair.' }, { title = 'Notes', note = '• The hexagun is removed at the end.' }, { title = 'Reward', note = '• Corsair Die\n• Key item: job gesture: corsair\n• Title: Seagull Phratrie Crew Member' } } },
    { name = 'Moment of Truth: Quest 6 30', group = 'Aht Urhgan', desc = 'Follow-up for Mishhar: scout Mamook, then win the Moment of Truth battlefield in Jade Sepulcher. Source: https://vanadreams.org/wiki/#quest-294', steps = { { title = 'Requirements', note = '• Give Peace a Chance done' }, { title = 'Walkthrough', note = '• Accept from Mishhar (H-8), Aht Urhgan Whitegate.\n• Enter the marked area for a scene; speak to Mishhar again.\n• Enter Mamook via Wajaom Woodlands (D-12); examine the ???.\n• Examine the door (H-8), Jade Sepulcher.\n• Win Moment of Truth.\n• Report to Mishhar.' }, { title = 'Notes', note = '• Reward item varies by main job.' }, { title = 'Reward', note = '• One of: Pro-Ether +1, Vile Elixir +1, Strength/Dexterity/Vitality/Agility/Int./Mind/Charisma Potion, Icarus Wing, Hermes Quencher' } } },
    { name = 'No Strings Attached', group = 'Aht Urhgan', desc = 'Puppetmaster unlock: find an antique automaton in Arrapago Reef and get it repaired. Begins with Shamarhaan in Bastok Markets. Source: https://vanadreams.org/wiki/#quest-295', steps = { { title = 'Requirements', note = '• Treasures of Aht Urhgan access\n• One Vana\'diel day wait mid-quest' }, { title = 'Walkthrough', note = '• Speak to Shamarhaan, Bastok Markets, for a scene.\n• Accept from Iruki-Waraki (K-9), Aht Urhgan Whitegate.\n• Speak to Ghatsad (I-7).\n• Examine the ??? (discarded materials pile), Arrapago Reef: Antique Automaton.\n• Give it to Ghatsad; wait one Vana\'diel day; speak to him again.\n• Name your automaton with Iruki-Waraki to finish.' }, { title = 'Notes', note = '• Lost Animator: trade Iruki-Waraki 10,000 gil for a new one.\n• If Iruki-Waraki won\'t respond, re-talk to Shamarhaan.' }, { title = 'Reward', note = '• Animator\n• Key item: job gesture: puppetmaster\n• Title: Proud Automaton Owner' } } },
    { name = 'Not Meant to Be', group = 'Aht Urhgan', desc = 'Fhe Maksojha in Nashmau sends you to Caedarva Mire to beat Lamia No.27 and Moshdahn. Source: https://vanadreams.org/wiki/#quest-296', steps = { { title = 'Walkthrough', note = '• Accept from Fhe Maksojha (H-6), Nashmau.\n• Examine the ??? in Caedarva Mire for a cutscene.\n• Return to Fhe Maksojha.\n• Examine the ??? again to spawn Lamia No.27 and Moshdahn; kill both.\n• Examine the ??? once more for a cutscene.\n• Report to Fhe Maksojha.' }, { title = 'Notes', note = '• Kill order doesn\'t matter; if another party has them spawned, wait for despawn.' }, { title = 'Reward', note = '• Imp. Gold Piece' } } },
    { name = 'Ode to the Serpents', group = 'Aht Urhgan', desc = 'Fari-Wari gives you Biyaada\'s letter and wants two other quests done first. Source: https://vanadreams.org/wiki/#quest-297', steps = { { title = 'Requirements', note = '• Saga of the Skyserpent done' }, { title = 'Walkthrough', note = '• Accept from Fari-Wari (K-12), Aht Urhgan Whitegate; receive Biyaada\'s letter.\n• Finish \'When the Bow Breaks\' and \'Fist of the People\'.\n• Return to Fari-Wari.' }, { title = 'Reward', note = '• Imp. Gold Piece' } } },
    { name = 'Olduum', group = 'Aht Urhgan', desc = 'Dig up an electric relic in Aydeewa Subterrane for Dkhaaya, then turn the reward into an Olduum Ring. Source: https://vanadreams.org/wiki/#quest-298', steps = { { title = 'Walkthrough', note = '• Speak to Dkhaaya (G-9), Aht Urhgan Whitegate: Dkhaaya\'s research journal.\n• Trade a Pickaxe to the Excavation Site, Aydeewa Subterrane: electrocell, electropot or electrolocomotive on success.\n• Bring it to Dkhaaya: Lightning Band.\n• Trade the band to the Leypoint (G-8), Wajaom Woodlands: Olduum Ring.' }, { title = 'Notes', note = '• Dig success ~50%; Pickaxe always consumed.\n• Lost band/ring: re-ask Dkhaaya and dig again.\n• Need a free inventory slot at the Leypoint.' }, { title = 'Reward', note = '• Lightning Band, Olduum Ring' } } },
    { name = 'Puppetmaster Blues', group = 'Aht Urhgan', desc = 'Third Puppetmaster artifact quest: collect parts for Shamarhaan and win a fight in Talacca Cove. Source: https://vanadreams.org/wiki/#quest-299', steps = { { title = 'Requirements', note = '• Puppetmaster main at required level\n• Operation Teatime done' }, { title = 'Walkthrough', note = '• Speak to Iruki-Waraki (K-9), Aht Urhgan Whitegate.\n• Shamarhaan, Bastok Markets: Valkeng\'s memory chip.\n• Examine the ??? (L-8), Mount Zhayolm: toggle switch.\n• Win Puppetmaster Blues, Talacca Cove.\n• Speak to Shamarhaan, then Iruki-Waraki, then Sajhra (H-9) in Nashmau.\n• Return to Iruki-Waraki to finish.' }, { title = 'Notes', note = '• Chip and switch are consumed in the battle.' }, { title = 'Reward', note = '• Pup. Taj\n• Title: Paragon of Puppetmaster Excellence' } } },
    { name = 'Promotion: Chief Sergeant', group = 'Aht Urhgan', desc = 'Cultivate scourshrooms in Aydeewa Subterrane for Abquhbah to reach Chief Sergeant. Source: https://vanadreams.org/wiki/#quest-301', steps = { { title = 'Requirements', note = '• Promotion: Sergeant Major done\n• Enough Assault promotion points' }, { title = 'Walkthrough', note = '• Accept from Abquhbah (I-10), Aht Urhgan Whitegate; speak to Hagakoff (K-10).\n• Alternate Abquhbah and Hagakoff until it advances.\n• Enter Aydeewa Subterrane via Wajaom Woodlands (I-10); take a scourshroom from a Mushroom Patch.\n• Plant it in a different patch.\n• Wait one Vana\'diel day, zone, then harvest.\n• Repeat if desired; deliver to Abquhbah.' }, { title = 'Notes', note = '• Six patches, one harvest each; max 5 mushrooms.\n• Harvesting 4:00-6:00 may double yield; bonus chance exists.\n• Keep two free slots for the Imp. Gold Piece reward option.' }, { title = 'Reward', note = '• Imp. Mtl. Piece, Imp. Gold Piece\n• Key item: CS Wildcat badge\n• Title: Chief Sergeant' } } },
    { name = 'Promotion: Corporal', group = 'Aht Urhgan', desc = 'Use a quartz transmitter on a warhorse track to become Corporal. Source: https://vanadreams.org/wiki/#quest-302', steps = { { title = 'Requirements', note = '• Promotion: Lance Corporal done\n• 25+ Assault promotion points' }, { title = 'Walkthrough', note = '• Naja Salaheem (I-10), Aht Urhgan Whitegate: quartz transmitter.\n• Examine one Warhorse Hoofprint in Wajaom Woodlands, Bhaflau Thickets, Mount Zhayolm or Caedarva Mire.\n• Return to Naja Salaheem.' }, { title = 'Notes', note = '• Only the first hoofprint counts; transmitter consumed.\n• LC Wildcat badge removed.' }, { title = 'Reward', note = '• Key item: C Wildcat badge\n• Title: Corporal' } } },
    { name = 'Promotion First Lieutenant', group = 'Aht Urhgan', desc = 'Reach First Lieutenant through multi-day talks with Abquhbah. Source: https://vanadreams.org/wiki/#quest-303', steps = { { title = 'Requirements', note = '• Promotion: Second Lieutenant done\n• 25 Assault promotion points\n• 5 Imp. Gold Piece' }, { title = 'Walkthrough', note = '• Enter the trigger area in Aht Urhgan Whitegate.\n• Trade 5 Imp. Gold Piece to Abquhbah (I-10).\n• On each of the next three Vana\'diel days, speak to him and agree.\n• Speak to him between 15:00-17:00, then zone.\n• Return between 15:00-17:00 to finish.' }, { title = 'Notes', note = '• Each stage needs a new day; declining means retry next day.\n• SL Wildcat badge swapped for FL.' }, { title = 'Reward', note = '• Key item: FL Wildcat badge\n• Title: First Lieutenant' } } },
    { name = 'Promotion: Lance Corporal', group = 'Aht Urhgan', desc = 'Gather five mythralline samples and blend them for Nafiwaa to make Lance Corporal. Source: https://vanadreams.org/wiki/#quest-304', steps = { { title = 'Requirements', note = '• Promotion: Superior Private done\n• 25+ Assault promotion points' }, { title = 'Walkthrough', note = '• Begin with Abquhbah (I-10), Aht Urhgan Whitegate.\n• Nafiwaa (G-5): five Empty Test Tubes.\n• Fill tubes 1-4 at Mythralline Wellsprings in Wajaom Woodlands.\n• Fill tube 5 at the Wellspring (Map 1, G-7), Bhaflau Thickets.\n• Mix at Nafiwaa; keep the result or discard and remix.\n• Wait one Vana\'diel day; enter the marked Whitegate area.' }, { title = 'Notes', note = '• All five tubes must be full first; tube densities differ, so pour amounts set quality.\n• Perfect mix = best reward; bad mix = none.\n• Remix is limited by remaining fluid.' }, { title = 'Reward', note = '• Imp. Mtl. Piece, Imp. Gold Piece\n• Key item: LC Wildcat badge\n• Title: Lance Corporal' } } },
    { name = 'Promotion: Private First Class', group = 'Aht Urhgan', desc = 'Bring Naja Salaheem an Imp Wing to rank up to Private First Class. Source: https://vanadreams.org/wiki/#quest-305', steps = { { title = 'Requirements', note = '• 25 Assault promotion points; PSC Wildcat badge' }, { title = 'Walkthrough', note = '• Accept from Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Get an Imp Wing from an imp.\n• Trade it to Naja Salaheem.' }, { title = 'Notes', note = '• PSC badge replaced by PFC badge.' }, { title = 'Reward', note = '• Key item: PFC Wildcat badge\n• Title: Private First Class' } } },
    { name = 'Promotion Second Lieutenant', group = 'Aht Urhgan', desc = 'Pass Abquhbah\'s three games to become Second Lieutenant. Source: https://vanadreams.org/wiki/#quest-306', steps = { { title = 'Requirements', note = '• Promotion: Chief Sergeant done\n• 25+ Assault promotion points' }, { title = 'Walkthrough', note = '• Accept from Abquhbah (I-10), Aht Urhgan Whitegate.\n• Trade 3 Imperial Gold Pieces: Officer Academy manual.\n• Trade 2 Imperial Mythril Pieces; win game one.\n• Trade 2 Imperial Mythril Pieces for game two.\n• Trade one beastmen item (Macuahuitl -1, Mamool Ja Collar, Mamool Ja Helm, Jadagna -1, Januwiyah -1, Tariqah -1, Troll Pauldron, Troll Vambrace, Lamian Armlet, Lamian Kaman -1 or Qutrub Gorget).\n• Trade 2 Imperial Mythril Pieces; win the final game.' }, { title = 'Notes', note = '• CS Wildcat badge removed.\n• Speak to Abquhbah before a game to hear its rules.' }, { title = 'Reward', note = '• Key item: SL Wildcat badge\n• Title: Second Lieutenant' } } },
    { name = 'Promotion: Sergeant', group = 'Aht Urhgan', desc = 'Errands in Nashmau and Caedarva Mire earn the Sergeant rank. Source: https://vanadreams.org/wiki/#quest-307', steps = { { title = 'Requirements', note = '• Promotion: Corporal done\n• 25+ Assault promotion points' }, { title = 'Walkthrough', note = '• Accept from Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Enter the marked Whitegate area for a cutscene.\n• Enter the marked Nashmau area; pick the continue option.\n• Trade a Bowl of Sutlac to Totoroon (G-8), Nashmau.\n• Click the ??? in Caedarva Mire.\n• Report to Naja Salaheem.' }, { title = 'Notes', note = '• Declining in Nashmau: retry after one Vana\'diel day.' }, { title = 'Reward', note = '• Key item: S Wildcat badge\n• Title: Sergeant' } } },
    { name = 'Promotion: Promotion Sergeant Major', group = 'Aht Urhgan', desc = 'Daily conversations with Naja Salaheem earn Sergeant Major. Source: https://vanadreams.org/wiki/#quest-308', steps = { { title = 'Requirements', note = '• Promotion: Sergeant done\n• 25 Assault promotion points' }, { title = 'Walkthrough', note = '• Begin with Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Return once per Vana\'diel day for each stage, picking any dialogue.\n• Speak to him at the last stage to be promoted.' }, { title = 'Notes', note = '• One stage per Vana\'diel day.\n• Some choices cut the number of visits.\n• S badge removed; Assault promotion points reset.' }, { title = 'Reward', note = '• Key item: SM Wildcat badge\n• Title: Sergeant Major' } } },
    { name = 'Promotion: Superior Private', group = 'Aht Urhgan', desc = 'Find a Dark Rider hoofprint to become Superior Private. Source: https://vanadreams.org/wiki/#quest-309', steps = { { title = 'Requirements', note = '• Promotion: Private First Class done\n• 25 Assault promotion points' }, { title = 'Walkthrough', note = '• Accept from Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Zone, then speak to him again for a hint.\n• Examine a Warhorse Hoofprint in Bhaflau Thickets, Caedarva Mire, Mount Zhayolm or Wajaom Woodlands: Dark Rider hoofprint.\n• Return to Naja Salaheem.' }, { title = 'Notes', note = '• Any of the four zones works.\n• PFC badge removed; Assault promotion points reset.' }, { title = 'Reward', note = '• Key item: SP Wildcat badge\n• Title: Superior Private' } } },
    { name = 'Rat Race', group = 'Aht Urhgan', desc = 'Pay Cacaroon and gather fish for Ququroon\'s feast. Begins with Kakkaroon in Nashmau. Source: https://vanadreams.org/wiki/#quest-310', steps = { { title = 'Walkthrough', note = '• Accept from Kakkaroon (H-8), Nashmau.\n• Speak to Nadee Periyaha (H-9), Aht Urhgan Whitegate.\n• Trade an Imp. Brz. Piece to Cacaroon (G-11), Whitegate.\n• Speak to Ququroon (G-6), Nashmau.\n• Trade him Ahtapot, Istakoz, Istavrit, Istiridye and Mercanbaligi in one trade: Nashmau Stew.\n• Trade the stew to Kyokyoroon (H-7), Nashmau.\n• Report to Kakkaroon.' }, { title = 'Reward', note = '• Imp. Gold Piece, Imp. Mtl. Piece, Imp. Slv. Piece, Nashmau Stew' } } },
    { name = 'Rock Bottom', group = 'Aht Urhgan', desc = 'Supply Zurtermor in Mount Zhayolm with two picks. Source: https://vanadreams.org/wiki/#quest-311', steps = { { title = 'Walkthrough', note = '• Accept from Zurtermor at the marked spot, Mount Zhayolm.\n• Trade a Pickaxe.\n• Zone, then trade a Mythril Pick or Mythril Pick +1.' }, { title = 'Notes', note = '• Zoning between trades is required.\n• Already own the Mount Zhayolm map: 2,000 gil instead.' } } },
    { name = 'Saga of the Skyserpent', group = 'Aht Urhgan', desc = 'Recover a lilac ribbon from Halvung for Fari-Wari. Source: https://vanadreams.org/wiki/#quest-313', steps = { { title = 'Requirements', note = '• Treasures of Aht Urhgan access\n• One Vana\'diel day wait before the end' }, { title = 'Walkthrough', note = '• Accept from Fari-Wari (K-12), Aht Urhgan Whitegate.\n• Enter Halvung via Mount Zhayolm (I-9); examine the ??? (Map 1, H-11): Lilac Ribbon.\n• Return to Fari-Wari; scene sends you to Wajaom Woodlands.\n• Watch the Wajaom cutscenes; you return and the ribbon is consumed.\n• After one Vana\'diel day, speak to Fari-Wari.' }, { title = 'Notes', note = '• Biyaada in Al Zahbi has extra lines meanwhile.' }, { title = 'Reward', note = '• Imp. Gold Piece\n• Title: Skyserpent Aggrandizer' } } },
    { name = 'Soothing Waters', group = 'Aht Urhgan', desc = 'Collect clues in Whitegate and Al Zahbi, then offer Colorful Hair in Aydeewa Subterrane. Source: https://vanadreams.org/wiki/#quest-315', steps = { { title = 'Requirements', note = '• Ode to the Serpents done' }, { title = 'Walkthrough', note = '• Accept from Fari-Wari (K-12), Aht Urhgan Whitegate.\n• Speak to Eunheem (G-9) and Nadeey (K-7), Whitegate.\n• Speak to Mihli Aliapoh (H-6), Al Zahbi.\n• Enter Aydeewa Subterrane via Bhaflau Thickets (I-7); trade Colorful Hair to the ??? (Map 1, H-8).\n• Return to Fari-Wari.' }, { title = 'Notes', note = '• Also grants imperial standing.' }, { title = 'Reward', note = '• Imp. Gold Piece\n• Title: Springserpent Sentry' } } },
    { name = 'Striking a Balance', group = 'Aht Urhgan', desc = 'Fetch Munahda\'s package from Al Zahbi for Wazyih and Saliyahf. Source: https://vanadreams.org/wiki/#quest-316', steps = { { title = 'Walkthrough', note = '• Speak to Wazyih (F-11), then accept from Saliyahf (G-7), Aht Urhgan Whitegate.\n• Speak to Wazyih again.\n• Enter the marked Whitegate area for a scene; speak to Wazyih.\n• Find and examine the ??? with Munahda\'s package in Al Zahbi.\n• Zone into Whitegate for a scene.\n• Report to Saliyahf.' }, { title = 'Reward', note = '• Imp. Brz. Piece' } } },
    { name = 'Such Sweet Sorrow', group = 'Aht Urhgan', desc = 'After a Caedarva Mire visit, Dabhuh wants a Merrow Scale. Source: https://vanadreams.org/wiki/#quest-317', steps = { { title = 'Walkthrough', note = '• Speak to Dabhuh (K-11), Aht Urhgan Whitegate; cutscene moves you to Caedarva Mire.\n• Watch the Mire scene; you return to Whitegate.\n• Watch the next scene to accept.\n• Get a Merrow Scale (dropped by Merrows).\n• Trade it to Dabhuh.' }, { title = 'Reward', note = '• M. No.17\'s Locket' } } },
    { name = 'The Die is Cast', group = 'Aht Urhgan', desc = 'Investigate Arrapago Reef for Ratihb and earn a Random Ring. Source: https://vanadreams.org/wiki/#quest-320', steps = { { title = 'Walkthrough', note = '• Accept from Ratihb (J-12), Aht Urhgan Whitegate.\n• Speak to Ekhu Pesshyadha (H-6), Whitegate, then Jijiroon (H-8), Nashmau.\n• Examine the ??? in Arrapago Reef.\n• Examine again to spawn Bukki; kill it.\n• Examine once more: bag of gold pieces.\n• Return to Ratihb.' }, { title = 'Notes', note = '• Bag is removed on completion.' }, { title = 'Reward', note = '• Random Ring' } } },
    { name = 'The Prankster', group = 'Aht Urhgan', desc = 'Hunt Ahaadah\'s prankster in Bhaflau Thickets for a Caedarva Mire map. Source: https://vanadreams.org/wiki/#quest-321', steps = { { title = 'Walkthrough', note = '• Accept from Ahaadah (G-6), Aht Urhgan Whitegate.\n• Pass the first, then second marked Whitegate spot for cutscenes.\n• Examine the ??? (Map 1, I-8), Bhaflau Thickets, to spawn Plague Chigoe; kill it.\n• Examine the ??? again to finish.' }, { title = 'Notes', note = '• If Plague Chigoe is already spawned, wait for kill or despawn.' }, { title = 'Reward', note = '• Key item: map of Caedarva Mire' } } },
    { name = 'The Prince and the Hopper', group = 'Aht Urhgan', desc = 'Track toad footprints in Mamook for Maudaal and beat Poroggo Casanova. Source: https://vanadreams.org/wiki/#quest-322', steps = { { title = 'Requirements', note = '• Access to Wajaom Woodlands and Mamook' }, { title = 'Walkthrough', note = '• Accept from Maudaal (E-9), Aht Urhgan Whitegate.\n• Zone into Wajaom Woodlands (via the entrance near Mamook) for a cutscene.\n• Enter Mamook via Wajaom (D-12); examine the second Toad\'s Footprint; you are sent to Wajaom.\n• Zone into Wajaom, then Mamook, for further scenes.\n• Examine the first Toad\'s Footprint for a scene, then again to spawn Poroggo Casanova with Mikilulu, Mikiruru, Nikilulu, Mikiluru and Mikirulu.\n• Defeat Poroggo Casanova.\n• Examine the first footprint again; report to Maudaal.' }, { title = 'Reward', note = '• Chanoix\'s Gorget' } } },
    { name = 'Three Men and a Closet', group = 'Aht Urhgan', desc = 'Track down the closet\'s owner for Kubhe Ijyuhla. Source: https://vanadreams.org/wiki/#quest-324', steps = { { title = 'Requirements', note = '• Got It All done' }, { title = 'Walkthrough', note = '• Accept from Kubhe Ijyuhla (I-8), Aht Urhgan Whitegate.\n• Zone from Whitegate into Wajaom Woodlands for a cutscene.\n• Return to Kubhe Ijyuhla.\n• Speak to Ratihb (J-12), then Tehf Kimasnahya (F-8) and agree.\n• Report to Kubhe Ijyuhla.' }, { title = 'Notes', note = '• Wajaom scene triggers only when entering from Whitegate.' }, { title = 'Reward', note = '• Imp. Brz. Piece' } } },
    { name = 'Two Horn the Savage', group = 'Aht Urhgan', desc = 'Hire help and defeat a Mamool Ja in Mamook for Milazahn. Source: https://vanadreams.org/wiki/#quest-326', steps = { { title = 'Walkthrough', note = '• Accept from Milazahn (G-8), Aht Urhgan Whitegate.\n• Trade 1,000 gil to Cacaroon (G-11).\n• Enter Mamook via Wajaom Woodlands (E-12); examine the Viscous Liquid for a scene.\n• Examine again to spawn the Mamool Ja; kill it.\n• Examine once more for a scene.\n• Report to Milazahn.' }, { title = 'Notes', note = '• Zoning after the kill keeps progress.' }, { title = 'Reward', note = '• Imp. Mtl. Piece' } } },
    { name = 'Vanishing Act', group = 'Aht Urhgan', desc = 'Harvest a rainbow berry in Wajaom Woodlands for Qutiba and Ulamaal. Source: https://vanadreams.org/wiki/#quest-330', steps = { { title = 'Requirements', note = '• Delivering the Goods done\n• A Sickle' }, { title = 'Walkthrough', note = '• Accept from Qutiba or Ulamaal (K-12), Aht Urhgan Whitegate.\n• Speak to Fochacha (I-9).\n• Enter the trigger area for a cutscene.\n• Trade a Sickle to a Harvesting Point in Wajaom Woodlands: rainbow berry.\n• Give it to Qutiba or Ulamaal.' }, { title = 'Notes', note = '• If refused, zone and retry soon.\n• Ulamaal gives a recipe if spoken to afterwards.' }, { title = 'Reward', note = '• Imp. Slv. Piece' } } },
    { name = 'Waking the Colossus', group = 'Aht Urhgan', desc = 'Collect nation approvals, power up the colossus and defeat Alexander on Nyzul Isle. Source: https://vanadreams.org/wiki/#quest-331', steps = { { title = 'Requirements', note = '• At ToAU mission Eternal Mercenary' }, { title = 'Walkthrough', note = '• Pass the Whitegate gate area for a scene; accept the Imperial missive at the Imperial Whitegate (L-9).\n• Check the audience chamber door, Ru\'Lude Gardens.\n• Get approval letters from Halver (I-9) Chateau d\'Oraguille, Iron Eater (J-8) Metalworks, Kupipi (Map 2, H-6) Heavens Tower.\n• Back at the Ru\'Lude door: Jeunoan approval letter.\n• Hand letters in at the Imperial Whitegate: present for Megomak.\n• Check the Acid-eaten Door (I-9), Mount Zhayolm: Megomak\'s shopping list.\n• Trade 3 Plumbago to that door: lightning cell.\n• Check the blank lamp, Alzadaal Undersea Ruins.\n• Use the Runic Seal (Map 5, I-9) to enter Nyzul Isle; defeat Alexander.\n• Zone into Alzadaal: whisper of radiance.\n• Speak to the Imperial Whitegate, then Naja Salaheem (I-10); pick a reward.' }, { title = 'Notes', note = '• Choices: Colossus\'s Mantle, Earring or Torque, 10,000 gil, or the Alexander spell.\n• Divine Interference unlocks after the next Japan midnight.' }, { title = 'Reward', note = '• Imp. Gold Piece; Colossus\'s Mantle/Torque/Earring option\n• Title: Heir of the Blessed Radiance' } } },
    { name = 'What Friends Are For', group = 'Aht Urhgan', desc = 'Carry Tsetseroon\'s stew to his friend in Aydeewa Subterrane. Source: https://vanadreams.org/wiki/#quest-332', steps = { { title = 'Walkthrough', note = '• Enter Aydeewa Subterrane via Wajaom Woodlands (E-10); step into the marked area for a scene.\n• Accept from Tsetseroon (G-6), Nashmau.\n• Trade him Tin Ore and Cobalt Jellyfish: pot of Tsetseroon\'s stew.\n• Deliver to the ??? (Map 3, G-10), Aydeewa Subterrane.\n• Report to Tsetseroon.' }, { title = 'Notes', note = '• Already own the Aydeewa map: Imperial Bronze Piece instead.' }, { title = 'Reward', note = '• Imp. Brz. Piece' } } },
    { name = 'When the Bow Breaks', group = 'Aht Urhgan', desc = 'Deliver a Frayed Arrow to the Giwahb Watchtower for Gaweesh of Al Zahbi. Source: https://vanadreams.org/wiki/#quest-333', steps = { { title = 'Requirements', note = '• Ode to the Serpents active' }, { title = 'Walkthrough', note = '• Accept from Gaweesh (G-8), Al Zahbi.\n• Get a Frayed Arrow.\n• Trade exactly one to the Giwahb Watchtower (F-5), Wajaom Woodlands.' }, { title = 'Reward', note = '• Title: Galeserpent Guardian' } } },
    { name = 'A Flash in the Pan', group = 'Bastok', desc = 'Repeatable: give Aquillina four Flint Stones. Source: https://vanadreams.org/wiki/#quest-335', steps = { { title = 'Walkthrough', note = '• Accept from Aquillina (K-8), Bastok Markets.\n• Trade her 4 Flint Stones.' }, { title = 'Notes', note = '• ~15-minute cooldown between turn-ins.' }, { title = 'Reward', note = '• 100 gil\n• Bastok fame 10' } } },
    { name = 'A Foreman\'s Best Friend', group = 'Bastok', desc = 'Return a Dog Collar to Gudav in Port Bastok. Source: https://vanadreams.org/wiki/#quest-336', steps = { { title = 'Walkthrough', note = '• Accept from Gudav (H-5), Port Bastok.\n• Trade him a Dog Collar.' }, { title = 'Notes', note = '• Dehlner (Port Bastok) comments while active.\n• Already own the Gusgen Mines map: EXP instead.' }, { title = 'Reward', note = '• Bastok fame 20' } } },
    { name = 'A Lady\'s Heart', group = 'Bastok', desc = 'Give Valah Molkot an Amaryllis to unlock a Mog House feature. Source: https://vanadreams.org/wiki/#quest-337', steps = { { title = 'Walkthrough', note = '• Find Valah Molkot (J-12), Port Bastok.\n• Trade any flower to start; trade an Amaryllis to finish.' }, { title = 'Notes', note = '• Wrong valid flowers are consumed.\n• After completion flowers are no longer consumed.' }, { title = 'Reward', note = '• Bastok fame 0' } } },
    { name = 'A Question of Faith', group = 'Bastok', desc = 'Take a Dawn talisman to Oldton Movalpolos and defeat Bugallug for Virnage. Source: https://vanadreams.org/wiki/#quest-338', steps = { { title = 'Requirements', note = '• Bastok fame 4\n• Out of the Depths done' }, { title = 'Walkthrough', note = '• Begin with Ayame (K-7), Metalworks.\n• Virnage (I-5), Bastok Mines: Dawn talisman.\n• Enter Oldton Movalpolos via North Gustaberg (K-6); speak to Rakorok (K-10) to spawn Bugallug.\n• Defeat Bugallug; speak to Rakorok (talisman taken).\n• Report to Virnage.' }, { title = 'Reward', note = '• 3,000 gil\n• Bastok fame 40' } } },
    { name = 'A Test of True Love', group = 'Bastok', desc = 'Recover three story pages from treasure chests for Carmelo. Source: https://vanadreams.org/wiki/#quest-339', steps = { { title = 'Requirements', note = '• Bastok fame 6\n• Love and Ice done' }, { title = 'Walkthrough', note = '• Speak to Carmelo (E-6), Port Bastok.\n• "Un Moment": Treasure Chest in Castle Zvahl Baileys or Keep.\n• "L\'Ephemere": Treasure Chest in Sea Serpent Grotto.\n• "L\'Ancienne": Treasure Chest in Labyrinth of Onzozo.\n• Show all three to Carmelo; zone; speak to him again.' }, { title = 'Notes', note = '• Open chests with the zone key or thief\'s tools.\n• Pages removed on completion.' }, { title = 'Reward', note = '• 10,000 gil\n• Bastok fame 70' } } },
    { name = 'Altana\'s Sorrow', group = 'Bastok', desc = 'Fetch divine paint from Garlaige Citadel and carry Virnage\'s letter to San d\'Oria. Source: https://vanadreams.org/wiki/#quest-340', steps = { { title = 'Requirements', note = '• Level 10+\n• Bastok fame 4' }, { title = 'Walkthrough', note = '• Speak to Virnage (I-5), Bastok Mines.\n• Enter Garlaige Citadel via Sauromugue Champaign (H-11); examine the ??? (Map 1, H-8): bucket of divine paint.\n• Return to Virnage: letter from Virnage.\n• Deliver to Eperdur (M-7), Northern San d\'Oria.' }, { title = 'Reward', note = '• Teleport-Dem\n• Title: Pilgrim to Dem\n• Bastok fame 40' } } },
    { name = 'Ayame and Kaede', group = 'Bastok', desc = 'Ninja unlock quest involving Kaede, Kagetora and Ensetsu of Port Bastok. Source: https://vanadreams.org/wiki/#quest-341', steps = { { title = 'Requirements', note = '• Main job level 30+' }, { title = 'Walkthrough', note = '• Accept from Kaede (J-5), Port Bastok.\n• Speak to Kagetora (F-6), then Ensetsu (I-5).\n• Enter Korroloka Tunnel via Western Altepa Desert (M-8); examine the ??? (Map 5, L-8) to spawn three Korroloka Leeches; kill all.\n• Examine the ??? again: strangely shaped coral.\n• Speak to Ensetsu; take the coral to Ryoma (H-8), Norg: sealed dagger.\n• Return to Ensetsu.' }, { title = 'Notes', note = '• Coral and dagger are consumed.' }, { title = 'Reward', note = '• Ninja job unlocked\n• Key item: job gesture: ninja\n• Title: Shadow Walker\n• Norg fame 20' } } },
    { name = 'Beadeaux Smog', group = 'Bastok', desc = 'Gather corrupted dirt in Beadeaux for High Bear. Source: https://vanadreams.org/wiki/#quest-343', steps = { { title = 'Requirements', note = '• Bastok fame 4+' }, { title = 'Walkthrough', note = '• Accept from High Bear (I-8), Metalworks.\n• Enter Beadeaux via Pashhow Marshlands (L-11); examine the ??? (Map 1, G-10): corrupted dirt.\n• Hand it to High Bear (free inventory slot needed).' }, { title = 'Reward', note = '• Chakram\n• Title: Beadeaux Surveyor\n• Bastok fame 40' } } },
    { name = 'Beauty and the Galka', group = 'Bastok', desc = 'Zinc Ore errand from Talib in Port Bastok, ending with a log delivery to Parraggoh. Source: https://vanadreams.org/wiki/#quest-344', steps = { { title = 'Walkthrough', note = '• Accept from Talib (Port Bastok F-6); if you refused him, Parraggoh (Bastok Mines H-5) offers it instead.\n• Hand Talib one Zinc Ore; he gives you the Palborough Mines logs.\n• Deliver the logs to Parraggoh (H-5).' }, { title = 'Reward', note = '• Bronze Knife\n• Norg fame 30' } } },
    { name = 'Bite the Dust', group = 'Bastok', desc = 'Repeatable fetch: Yazan in Port Bastok needs a Sand Bat Fang. Source: https://vanadreams.org/wiki/#quest-345', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2+.\n• Accept from Yazan (Port Bastok H-6), then trade him a Sand Bat Fang.' }, { title = 'Reward', note = '• 350 gil, title Sand Blaster, Bastok fame 10' } } },
    { name = 'Blade of Darkness', group = 'Bastok', desc = 'Dark Knight unlock: score 100 kills with the Chaosbringer. Source: https://vanadreams.org/wiki/#quest-346', steps = { { title = 'Walkthrough', note = '• Level 30+ required.\n• Accept from Gumbah (Bastok Mines J-7).\n• Get the Chaosbringer by zoning from Palborough Mines into Zeruhn Mines.\n• Kill 100 monsters with it equipped.\n• Zone from Pashhow Marshlands into Beadeaux for the closing scene.' }, { title = 'Notes', note = '• Kills count only while the Chaosbringer is wielded; dropping it resets the count.\n• Lost it? Repeat the Palborough-to-Zeruhn zone.' }, { title = 'Reward', note = '• Chaosbringer, key item job gesture: dark knight\n• Title Dark Sider, Bastok fame 20' } } },
    { name = 'Blade of Death', group = 'Bastok', desc = 'Follow-up to Blade of Darkness: 200 Chaosbringer kills, then a trade in Gusgen Mines. Source: https://vanadreams.org/wiki/#quest-347', steps = { { title = 'Walkthrough', note = '• Needs Blade of Darkness done and Bastok fame 3+.\n• Get Zeid\'s letter from Gumbah (Bastok Mines J-7).\n• Zone Palborough Mines into Zeruhn Mines for a Chaosbringer if you lack one.\n• Kill 200 monsters wielding it.\n• Trade it to the ??? in Gusgen Mines (Map 1, J-7).' }, { title = 'Notes', note = '• Only kills with the Chaosbringer equipped count; re-zone into Zeruhn Mines to replace a lost one.' }, { title = 'Reward', note = '• Deathbringer, Chaosbringer\n• Title Black Death, Bastok fame 30' } } },
    { name = 'Breaking Stones', group = 'Bastok', desc = 'Horatius in Bastok Markets wants a Dangruf Stone. Source: https://vanadreams.org/wiki/#quest-348', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2.\n• Accept from Horatius (Bastok Markets I-9).\n• Dig a Dangruf Stone in Dangruf Wadi and trade it to him.' }, { title = 'Reward', note = '• 400 gil, Bastok fame 30' } } },
    { name = 'Brygid the Stylist', group = 'Bastok', desc = 'Wear the outfit Brygid in Bastok Markets asks for. Source: https://vanadreams.org/wiki/#quest-349', steps = { { title = 'Walkthrough', note = '• Speak to Brygid (Bastok Markets K-9).\n• Equip a Robe (body) and Bronze Subligar (legs), then speak to her again.' }, { title = 'Reward', note = '• Gloves, title Brygid Approved, Bastok fame 20' } } },
    { name = 'Brygid the Stylist Returns', group = 'Bastok', desc = 'Repeatable sequel: dress as Brygid asks, pick a prize, then pay with the matching zodiac Subligar. Source: https://vanadreams.org/wiki/#quest-350', steps = { { title = 'Walkthrough', note = '• Needs Brygid the Stylist done.\n• Talk to Brygid (Bastok Markets K-9) with at least one artifact armor piece on; she names a body and a leg piece.\n• Equip both, talk again and choose one of 13 prizes.\n• Trade her the Subligar that matches that prize.' }, { title = 'Prize / Subligar pairs', note = '• Duende Cotehardie - Aries; Nokizaru Gi - Taurus; Rapparee Harness - Gemini; Shinimusha Hara-Ate - Cancer\n• Wyvern Mail - Leo; Shikaree Aketon - Virgo; Cerise Doublet - Libra; Glamor Jupon - Scorpius\n• Gloom Breastplate - Sagittarius; Nimbus Doublet - Capricornus; Aikido Gi - Aquarius; Parade Cuirass - Pisces; Gaudy Harness - Ophiuchus\n• Requested gear is always something your job can wear.' }, { title = 'Reward', note = '• Chosen prize (one of 26 items listed)\n• Title Bastoks Second Best Dressed, Bastok fame 10' } } },
    { name = 'Buckets of Gold', group = 'Bastok', desc = 'Foss in Bastok Markets takes five Rusty Buckets. Source: https://vanadreams.org/wiki/#quest-351', steps = { { title = 'Walkthrough', note = '• Accept from Foss (Bastok Markets F-7), then trade him 5 Rusty Buckets.\n• Rusty Buckets can be fished up.' }, { title = 'Reward', note = '• 300 gil, title Bucket Fisher, Bastok fame 10' } } },
    { name = 'Chips', group = 'Bastok', desc = 'Repeatable trade of three colored chips to Cid for CCB Polymer. Source: https://vanadreams.org/wiki/#quest-352', steps = { { title = 'Walkthrough', note = '• Requires Chains of Promathia mission One to Be Feared reached or done.\n• Accept from Ghebi Damomohe (Lower Jeuno I-7).\n• Trade one Carmine Chip, one Cyan Chip and one Gray Chip together to Cid (Metalworks H-8).' }, { title = 'Notes', note = '• Need a free slot and no CCB Polymer already held.\n• Repeat with another chip set; raises Bastok and San d\'Oria fame.' }, { title = 'Reward', note = '• CCB Polymer' } } },
    { name = 'Cid\'s Secret', group = 'Bastok', desc = 'Retrieve an unfinished letter from Hilda for Cid. Source: https://vanadreams.org/wiki/#quest-353', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 4.\n• Talk to Cid (Metalworks H-8), then Hilda (Port Bastok E-6).\n• Trade Hilda a Rolanberry 874 for the unfinished letter (taken at the end).\n• Report back to Cid.' }, { title = 'Reward', note = '• Ram Mantle, Bastok fame 40' } } },
    { name = 'Dark Legacy', group = 'Bastok', desc = 'First Dark Knight artifact quest: beat Vaa Huja the Erudite in Giddeus for the Darksteel Formula. Source: https://vanadreams.org/wiki/#quest-354', steps = { { title = 'Walkthrough', note = '• Needs DRK main 40+ and Blade of Darkness done.\n• Accept from Raibaht (Metalworks G-8).\n• Get the letter from the Darksteel Forge from Mighty Fist (Metalworks G-9).\n• Take it to Cochal-Monchal in Windurst Waters for a cutscene.\n• In Giddeus, optionally give Quu Bokye (Map 2, F-6) a Yagudo Cherry for a hint, then trade a Yagudo Cherry to the ??? to pop Vaa Huja the Erudite.\n• Kill it, check the ??? again for the Darksteel Formula, and return to Raibaht.' }, { title = 'Notes', note = '• Bring two Yagudo Cherries if you want the hint.\n• The NM won\'t spawn while another copy is up.' }, { title = 'Reward', note = '• Raven Scythe, Bastok fame 20' } } },
    { name = 'Dark Puppet', group = 'Bastok', desc = 'Dark Knight artifact quest with three chained fights in Ordelles Caves. Source: https://vanadreams.org/wiki/#quest-355', steps = { { title = 'Walkthrough', note = '• Needs DRK main at AF2 level and Dark Legacy done; bring a party.\n• Accept from Cid (Metalworks H-8), then enter Ordelles Caves for a scene.\n• Trade a Darksteel Ingot to the ??? (Axe, H-8); kill the Dark Puppet for Gerwitz\'s Axe.\n• Trade the Axe to the ??? (Sword, G-6); kill the Dark Puppet for Gerwitz\'s Sword.\n• Trade the Sword to the ??? (Soul, G-6) and defeat Gerwitz\'s Soul.\n• Zone into La Theine Plateau for the last scene.' }, { title = 'Notes', note = '• Losing a weapon may force you back to the previous ???.' }, { title = 'Reward', note = '• Chaos Sollerets, Bastok fame 20' } } },
    { name = 'Blade of Evil', group = 'Bastok', desc = 'Final Dark Knight armor quest, fought in Middle Delkfutt\'s Tower for the Chaos Burgeonet. Source: https://vanadreams.org/wiki/#quest-356', steps = { { title = 'Walkthrough', note = '• Needs DRK main 50+ and Dark Puppet done.\n• Start by zoning from Pashhow Marshlands into Beadeaux.\n• Get a Vial of Quadav Mage Blood.\n• Trade it to the ??? in Middle Delkfutt\'s Tower (Map 3, J-7); kill all three Gerwitz\'s Scythes.\n• Step into the marked area for the finishing cutscene.' }, { title = 'Notes', note = '• The ??? ignores you while any Scythe lives.\n• Accept the item when offered in the final scene.' }, { title = 'Reward', note = '• Chaos Burgeonet\n• Title Paragon of Dark Knight Excellence, Bastok fame 20' } } },
    { name = 'Drachenfall', group = 'Bastok', desc = 'Fill Black Mud\'s canteen at the North Gustaberg waterfall. Source: https://vanadreams.org/wiki/#quest-357', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2.\n• Get a Brass Canteen from Black Mud (Bastok Mines J-7); ask again if lost.\n• Trade it to the Waterfall Base (North Gustaberg F-7) for Drachenfall Water.\n• Trade the water to Black Mud.' }, { title = 'Reward', note = '• 2,000 gil, Drachenfall Water, Brass Canteen\n• Title Drachenfall Ascetic, Bastok fame 20' } } },
    { name = 'Eco-Warrior (Bastok)', group = 'Bastok', desc = 'Bastok\'s Eco-Warrior: level-capped fight with two Puddings in Gusgen Mines for an indigested ore. Source: https://vanadreams.org/wiki/#quest-358', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 1+ and no other nation\'s Eco-Warrior active.\n• Accept from Raifa (Port Bastok D-6).\n• Enter Gusgen Mines from Konschtat Highlands (L-7); let Degga (Map 1, H-9) apply the ointment (level restriction).\n• Check the ???, kill both Puddings, check it again for the indigested ore.\n• See Degga if needed, then return to Raifa.' }, { title = 'Notes', note = '• Zoning removes the restriction; Degga can also remove it.\n• After finishing in one nation, others are locked until the next conquest tally.' }, { title = 'Reward', note = '• 5,000 gil, Dragon Chronicles\n• Title Cerulean Soldier, Bastok fame 20' } } },
    { name = 'Faded Promises', group = 'Bastok', desc = 'Ninja quest: recover the Diary of Mukunda from Palborough Mines. Source: https://vanadreams.org/wiki/#quest-360', steps = { { title = 'Walkthrough', note = '• Needs NIN main 20+ and Bastok fame 4.\n• Talk to Romualdo (Metalworks K-9), then Ayame (Metalworks K-7).\n• Open a Treasure Chest in Palborough Mines (key or thief\'s tools) for the Diary of Mukunda.\n• Show it to Kagetora (Port Bastok F-6), revisit Ayame, then finish with Alois (Metalworks K-8).' }, { title = 'Reward', note = '• Fukuro, title Assassin Reject, Norg fame 20' } } },
    { name = 'Fallen Comrades', group = 'Bastok', desc = 'Repeatable: return a Silver Name Tag to Pavvke in Bastok Mines. Source: https://vanadreams.org/wiki/#quest-361', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2+.\n• Accept from Pavvke (Bastok Mines I-7) and trade him a Silver Name Tag.\n• Repeats also grant fame.' }, { title = 'Reward', note = '• 550 gil, Bastok fame 10' } } },
    { name = 'Father Figure', group = 'Bastok', desc = 'Trade Michea a Silver Ingot. Source: https://vanadreams.org/wiki/#quest-362', steps = { { title = 'Walkthrough', note = '• Needs The Elvaan Goldsmith done and Bastok fame 2.\n• Talk to Michea (Bastok Markets F-10), then trade her a Silver Ingot.' }, { title = 'Reward', note = '• 2,200 gil, Bastok fame 20' } } },
    { name = 'Fear of Flying', group = 'Bastok', desc = 'Kurando in Port Bastok wants a Silkworm Egg. Source: https://vanadreams.org/wiki/#quest-363', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 3+.\n• Accept from Kurando (Port Bastok H-6) and trade him a Silkworm Egg.\n• Speak to him once more afterward for an extra scene.' }, { title = 'Reward', note = '• Black Neckerchief, title Airship Denouncer, Bastok fame 30' } } },
    { name = 'Forever to Hold', group = 'Bastok', desc = 'Give a Brass Hairpin to Romilda for Qiji. Source: https://vanadreams.org/wiki/#quest-364', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2.\n• Accept from Qiji (Port Bastok I-7).\n• Trade the Brass Hairpin to Romilda (I-7), not Qiji, then report to Qiji.' }, { title = 'Reward', note = '• 300 gil, title Qijis Friend, Bastok fame 20' } } },
    { name = 'Gourmet', group = 'Bastok', desc = 'Repeatable: give Salimah in Bastok Markets the ingredient matching the game hour. Source: https://vanadreams.org/wiki/#quest-365', steps = { { title = 'Walkthrough', note = '• Accept from Salimah (Bastok Markets L-8).\n• 18:00-06:00: Sleepshroom; 06:00-12:00: Treant Bulb; 12:00-18:00: Wild Onion.' }, { title = 'Notes', note = '• Correct-time pay: Wild Onion 350 gil, Sleepshroom/Treant Bulb 200 gil; wrong time still completes for 100 gil.\n• Once per game day; zone before repeating.' }, { title = 'Reward', note = '• Gil as above, title Mommys Helper' } } },
    { name = 'Groceries', group = 'Bastok', desc = 'Carry Tami\'s Note to Zelman in Zeruhn Mines and return with Meat Jerky. Source: https://vanadreams.org/wiki/#quest-366', steps = { { title = 'Walkthrough', note = '• Get Tami\'s Note from Tami (Bastok Mines J-8).\n• Read it from the key item list before delivering.\n• Give it to Zelman (Zeruhn Mines I-8).\n• Trade a Strip of Meat Jerky to Tami.' }, { title = 'Notes', note = '• Delivering unread sends you back to restart for a small consolation; Tami reissues the note.' }, { title = 'Reward', note = '• Rabbit Mantle, Bastok fame 10' } } },
    { name = 'Welcome to Bastok', group = 'Bastok', desc = 'Fetch Domien\'s letter for Powhatan while holding a Maul. Source: https://vanadreams.org/wiki/#quest-367', steps = { { title = 'Walkthrough', note = '• Listed requirements: Bastok fame 3, level 31+, Welcome to Bastok done.\n• Talk to Powhatan (Port Bastok E-6).\n• With a Maul or Replica Maul equipped as main weapon, talk to Steel Bones (D-8) for the letter from Domien.\n• Deliver it to Powhatan.' }, { title = 'Reward', note = '• Targe, Bastok fame 30' } } },
    { name = 'Hearts of Mythril', group = 'Bastok', desc = 'Place Elki\'s bouquet at the North Gustaberg Monument. Source: https://vanadreams.org/wiki/#quest-368', steps = { { title = 'Walkthrough', note = '• Get the bouquet for the pioneers from Elki (Bastok Mines H-5).\n• Examine the Monument (North Gustaberg J-7) to leave it.\n• Return to Elki.\n• Zone afterward before The Eleventh\'s Hour can start.' }, { title = 'Reward', note = '• Sitabaki, title Pursuer of the Past, Bastok fame 20' } } },
    { name = 'Inheritance', group = 'Bastok', desc = 'Great Sword weapon skill quest for Ground Strike, ending with a Maharaja fight. Source: https://vanadreams.org/wiki/#quest-369', steps = { { title = 'Walkthrough', note = '• Needs Great Sword skill 250+, able to equip the Sword of Trials, no other weapon training guide held.\n• Get the Sword of Trials and a guide from Gumbah (Bastok Mines J-7).\n• Fight with it to 300 weapon skill points, then trade it to Gumbah for the map to the Annals of Truth.\n• Check the ??? (Western Altepa Desert E-9), kill Maharaja, check again for the Annals of Truth.\n• Talk to Gumbah to learn Ground Strike.' }, { title = 'Notes', note = '• Gumbah replaces a lost sword or cancels the quest.' }, { title = 'Reward', note = '• Sword of Trials, Bastok fame 20' } } },
    { name = 'Love and Ice', group = 'Bastok', desc = 'Take Carmelo\'s song sheet to the Mirror Pond in Beaucedine Glacier. Source: https://vanadreams.org/wiki/#quest-370', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 5, The Siren\'s Tear done, and the carrier pigeon letter seen (The Stars of Ifrit).\n• Get the song sheet from Carmelo (Port Bastok E-6).\n• Examine the Mirror Pond in Beaucedine Glacier (sheet consumed).\n• Talk to Carmelo again.\n• Zone once to unlock A Test of True Love.' }, { title = 'Reward', note = '• Lamia Harp, title Sorrow Drowner, Bastok fame 50' } } },
    { name = 'Lovers in the Dusk', group = 'Bastok', desc = 'Deliver Carmelo\'s song to Zi\'Tah at dusk. Source: https://vanadreams.org/wiki/#quest-371', steps = { { title = 'Walkthrough', note = '• Needs A Test of True Love done, Bastok fame 6, and one zone since the last turn-in.\n• Get "Chanson de Liberte" from Carmelo (Port Bastok E-6).\n• Check the ??? (The Sanctuary of Zi\'Tah H-8) at Vana\'diel dusk.' }, { title = 'Reward', note = '• Siren Flute, Bastok fame 70' } } },
    { name = 'Lure of the Wildcat (Bastok)', group = 'Bastok', desc = 'Talk to 20 Bastok NPCs for Alib-Mufalib to earn the blue invitation card. Source: https://vanadreams.org/wiki/#quest-372', steps = { { title = 'Walkthrough', note = '• Needs Treasures of Aht Urhgan.\n• Get the blue Sentinel badge from Alib-Mufalib (Port Bastok K-7).\n• Port Bastok: Hilda (E-6), Kaede (J-5), Patient Wheel (F-5), Paujean (F-6), Tilian (F-8).\n• Metalworks: Ayame (K-7), Invincible Shield, Kaela (I-8), Manilam (G-7), Raibaht (G-8).\n• Bastok Markets: Arawn (J-10), Harmodios (K-10), Horatius (I-9), Ken (E-10), Pavel (E-11).\n• Bastok Mines: Deidogg (H-6), Echo Hawk (H-7), Goraow (I-6), Griselda (H-5), Vaghron (H-9).\n• Any order; then return to Alib-Mufalib (badge is taken).' }, { title = 'Reward', note = '• Key item blue invitation card' } } },
    { name = 'Ghosts of the Past', group = 'Bastok', desc = 'Monk AF1: take a Miner\'s Pendant from a ghost in Gusgen Mines. Source: https://vanadreams.org/wiki/#quest-373', steps = { { title = 'Walkthrough', note = '• Needs MNK main 40.\n• Accept from Oggbi (Port Bastok D-6).\n• Enter Gusgen Mines from Konschtat Highlands (L-7); trade a Pickaxe to the ??? (Map 4, G-7).\n• Kill the Wandering Ghost for the Miner\'s Pendant (won\'t spawn if you hold one).\n• Trade the pendant to Oggbi.' }, { title = 'Reward', note = '• Beat Cesti, Bastok fame 20' } } },
    { name = 'The First Meeting', group = 'Bastok', desc = 'Monk armor quest: get a martial arts scroll from Davoi for Oggbi. Source: https://vanadreams.org/wiki/#quest-374', steps = { { title = 'Walkthrough', note = '• Needs MNK main 50, Ghosts of the Past done, one zone since.\n• Accept from Oggbi (Port Bastok D-6).\n• Zone from Qu\'Bia Arena into Fei\'Yin for the letter from Dalzakk.\n• Enter Davoi from Jugner Forest (G-12); stand right by the second Hide Flap and examine it to pop Bilopdop (F-7) and Deloknok.\n• Kill both, examine the Hide Flap (F-6) for the San d\'Orian martial arts scroll.\n• Show both key items to Oggbi.' }, { title = 'Notes', note = '• Without the letter the Hide Flap gives nothing.' }, { title = 'Reward', note = '• Temple Gaiters, Bastok fame 20' } } },
    { name = 'True Strength', group = 'Bastok', desc = 'Monk armor quest: Xalmo Feather from Castle Oztroja for Ayame. Source: https://vanadreams.org/wiki/#quest-375', steps = { { title = 'Walkthrough', note = '• Needs The First Meeting done and MNK main 50.\n• Accept from Ayame (Metalworks K-7).\n• Enter Castle Oztroja from Meriphataud Mountains (L-8); trade a Yagudo Drink to the ??? (Map 4, H-8).\n• Kill Huu Xalmo the Savage for a Xalmo Feather (won\'t spawn if you hold one).\n• Trade the feather to Ayame.' }, { title = 'Reward', note = '• Temple Hose, title Paragon of Monk Excellence, Bastok fame 20' } } },
    { name = 'Mean Machine', group = 'Bastok', desc = 'Slime Oil for the Unlucky Rat. Source: https://vanadreams.org/wiki/#quest-376', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2.\n• Accept from the Unlucky Rat (Metalworks G-7) and trade a Slime Oil.' }, { title = 'Reward', note = '• Warp, Bastok fame 20' } } },
    { name = 'Minesweeper', group = 'Bastok', desc = 'Repeatable: Zeruhn Soot for Gerbaum. Source: https://vanadreams.org/wiki/#quest-377', steps = { { title = 'Walkthrough', note = '• Accept from Gerbaum (Bastok Mines F-8) and trade 3 Pinches of Zeruhn Soot.' }, { title = 'Reward', note = '• 150 gil, title Zeruhn Sweeper, Bastok fame 10' } } },
    { name = 'Mom, the Adventurer?', group = 'Bastok', desc = 'Copper Ring for a letter, between Bastok Markets and Bastok Mines. Source: https://vanadreams.org/wiki/#quest-378', steps = { { title = 'Walkthrough', note = '• Talk to Nbu Latteh (Bastok Markets J-9); she gives a Fire Crystal.\n• Trade a Copper Ring to Roh Latteh (Bastok Mines H-7) for her letter.\n• Bring it to Nbu Latteh (letter is taken).\n• Repeatable at low fame after zoning.' }, { title = 'Reward', note = '• Fire Crystal, title Ringbearer, Bastok fame 10' } } },
    { name = 'Out of One\'s Shell', group = 'Bastok', desc = 'Three Shell Bugs for Ronan in Port Bastok. Source: https://vanadreams.org/wiki/#quest-379', steps = { { title = 'Walkthrough', note = '• Needs The Quadav\'s Curse done and Bastok fame 2.\n• Accept from Ronan (Port Bastok K-6) and trade 3 Shell Bugs.\n• Zone, then talk to Ronan to finish.\n• Hints: Mine Konte and Panana (Port Bastok).' }, { title = 'Reward', note = '• Monk\'s Headgear, title Shell Outer, Bastok fame 20' } } },
    { name = 'Out of the Depths', group = 'Bastok', desc = 'Trade Hoary Bomb Ash for trinkets in Oldton Movalpolos and deliver them to Ravorara. Source: https://vanadreams.org/wiki/#quest-380', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 3+.\n• Accept from Ayame (Metalworks K-7), then talk to Ravorara (Port Bastok E-7).\n• Enter Oldton Movalpolos from North Gustaberg (K-6); agree to help Brakobrik (K-11).\n• Collect Hoary Bomb Ash from bombs there.\n• Trade Brakobrik 1, 2, 3 and 4 ash in separate trades: dusty tome, pointed jug, cracked club, peeling hairpin.\n• Give each to Ravorara (100/200/300/400 gil).\n• Trade 1 more ash for the old nametag and give it to Ravorara.\n• Talk to Pavvke (Bastok Mines I-7).' }, { title = 'Notes', note = '• Brakobrik won\'t duplicate an item you hold.' }, { title = 'Reward', note = '• 1,200 gil, title Trash Collector, Bastok fame 80' } } },
    { name = 'Achieving True Power', group = 'Bastok', desc = 'Puppetmaster limit break to level cap 75 via a Navukgo Execution Chamber battle. Source: https://vanadreams.org/wiki/#quest-381', steps = { { title = 'Walkthrough', note = '• Needs PUP main 66+, Puppetmaster Blues done, Puppetmaster\'s Testimony.\n• Accept from Shamarhaan (Bastok Markets).\n• Trade him the testimony to be sent to Navukgo Execution Chamber.\n• Win the Achieving True Power fight; cap becomes 75 if not already.' }, { title = 'Reward', note = '• Instant Warp, title Master of Manipulation' } } },
    { name = 'Past Perfect', group = 'Bastok', desc = 'Repeatable: recover tattered mission orders in Konschtat Highlands for Evi. Source: https://vanadreams.org/wiki/#quest-382', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2+.\n• Talk to Evi (Port Bastok H-6) twice to accept.\n• Examine the ??? (Konschtat Highlands G-8) for the orders.\n• Return them to Evi.' }, { title = 'Reward', note = '• Scale Mail, Bastok fame 20' } } },
    { name = 'Return to the Depths', group = 'Bastok', desc = 'Build the Pungent Providence Pot via Jeuno and Kazham, then win a fight in Mine Shaft #2716. Source: https://vanadreams.org/wiki/#quest-383', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 5, A Question of Faith done, 10,000 gil, a Misareaux Garlic.\n• Accept from Ayame (Metalworks K-7).\n• Enter Oldton Movalpolos from North Gustaberg (K-6) for a cutscene.\n• Trade the garlic to Muckvix (Lower Jeuno H-10) for the Letter from Muckvix.\n• Talk to Magriffon (Kazham), then pay him 10,000 gil for the Providence Pot and Letter from Magriffon.\n• Bring both to Muckvix for the Pungent Providence Pot.\n• Re-enter Oldton Movalpolos for a cutscene and talk to Tarnotik (K-10).\n• Trade a Bottle of Ahriman Tears to Tarnotik (E-8) to reach Mine Shaft #2716.\n• Click the door and win the Return to the Depths fight.\n• Report to Ayame.' }, { title = 'Notes', note = '• Afterward Ravorara (Port Bastok) buys the Pungent Providence Pot; more Ahriman Tears to Tarnotik re-enter the fight.' }, { title = 'Reward', note = '• Bowyer Ring, title Goblin in Disguise, Bastok fame 50' } } },
    { name = 'Rivals', group = 'Bastok', desc = 'Mythril Sallet for Detzo in Bastok Mines. Source: https://vanadreams.org/wiki/#quest-384', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 3.\n• Accept from Detzo (Bastok Mines I-6) and trade a Mythril Sallet.' }, { title = 'Reward', note = '• Wolf Gorget, title Contest Rigger, Bastok fame 30' } } },
    { name = 'Shady Business', group = 'Bastok', desc = 'Repeatable: four Zinc Ore for Talib. Source: https://vanadreams.org/wiki/#quest-385', steps = { { title = 'Walkthrough', note = '• Needs Beauty and the Galka done.\n• Talk to Talib (Port Bastok F-6), then trade 4 Chunks of Zinc Ore.\n• Also raises Norg fame.' }, { title = 'Reward', note = '• 350 gil' } } },
    { name = 'Shoot First, Ask Questions Later', group = 'Bastok', desc = 'Marksmanship weapon skill quest for Detonator, with a Boyahda Tree NM. Source: https://vanadreams.org/wiki/#quest-386', steps = { { title = 'Walkthrough', note = '• Needs Marksmanship 250+ and ability to equip the Gun of Trials.\n• Get the Gun of Trials and a guide from Cid (Metalworks H-8).\n• Earn 300 weapon skill points with it, then trade it to Cid for the map to the Annals of Truth.\n• Enter The Boyahda Tree from Zi\'Tah (J-12); check the ??? and kill Beet Leafhopper.\n• Check the ??? again for the Annals of Truth and show them to Cid to learn Detonator.' }, { title = 'Notes', note = '• Cid replaces a lost gun or cancels the quest.' }, { title = 'Reward', note = '• Gun of Trials, Bastok fame 20' } } },
    { name = 'Silence of the Rams', group = 'Bastok', desc = 'Two ram horns for Paujean in Port Bastok. Source: https://vanadreams.org/wiki/#quest-387', steps = { { title = 'Walkthrough', note = '• Needs Norg fame 2+.\n• Accept from Paujean (Port Bastok F-6).\n• Trade a Lumbering Horn and a Rampaging Horn together.' }, { title = 'Reward', note = '• Purple Belt (item and title), Norg fame 20' } } },
    { name = 'Smoke on the Mountain', group = 'Bastok', desc = 'Galkan Sausage for the Hungry Wolf. Source: https://vanadreams.org/wiki/#quest-388', steps = { { title = 'Walkthrough', note = '• Accept from the Hungry Wolf (Metalworks G-9) and trade a Galkan Sausage.\n• Hints: Offa (Bastok Markets).' }, { title = 'Reward', note = '• 300 gil, title Hot Dog, Bastok fame 10' } } },
    { name = 'Stamp Hunt', group = 'Bastok', desc = 'Collect seven stamps around Bastok for Arawn. Source: https://vanadreams.org/wiki/#quest-389', steps = { { title = 'Walkthrough', note = '• Get the stamp sheet from Arawn (Bastok Markets J-10).\n• Markets: Pavel (E-11). Mines: Deadly Spider (G-8), Tall Mountain (J-7).\n• Metalworks: Elayne (G-8), Romualdo (K-9). Port Bastok: Ehrhard (G-5), Latifah (J-8).\n• Any order; return to Arawn.' }, { title = 'Reward', note = '• Leather Gorget, title Stampeder, Bastok fame 20' } } },
    { name = 'Stardust', group = 'Bastok', desc = 'Repeatable: Valkurm Sunsand for Baldric. Source: https://vanadreams.org/wiki/#quest-390', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 2+.\n• Accept from Baldric (Metalworks G-9) and trade 1 Pinch of Valkurm Sunsand.\n• To repeat: zone, talk to him, trade again.' }, { title = 'Reward', note = '• 300 gil, Bastok fame 10' } } },
    { name = 'Teak Me to the Stars', group = 'Bastok', desc = 'Garhada Teak Lumber for Raibaht. Source: https://vanadreams.org/wiki/#quest-391', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 3.\n• Accept from Raibaht (Metalworks G-8) and trade a Garhada Teak Lumber.\n• Zone once to unlock Hyper-active.' }, { title = 'Reward', note = '• 2,100 gil, Bastok fame 30' } } },
    { name = 'The Bare Bones', group = 'Bastok', desc = 'Bone Chip for Degenhard in Bastok Markets. Source: https://vanadreams.org/wiki/#quest-392', steps = { { title = 'Walkthrough', note = '• Accept from Degenhard (Bastok Markets I-10) and trade a Bone Chip.\n• Hints: Biggorf (H-10).' }, { title = 'Reward', note = '• 2,000 EXP, key item map of the Dangruf Wadi, Bastok fame 20' } } },
    { name = 'The Cold Light of Day', group = 'Bastok', desc = 'Steam Clock for Malene in Bastok Markets. Source: https://vanadreams.org/wiki/#quest-393', steps = { { title = 'Walkthrough', note = '• Accept from Malene (Bastok Markets I-5) and trade a Steam Clock.\n• Hints: Gwill (Bastok Markets).' }, { title = 'Reward', note = '• 500 gil, title Crab Crusher, Bastok fame 10' } } },
    { name = 'The Curse Collector', group = 'Bastok', desc = 'Gather curses in Beadeaux on Zon-Fobun\'s cursepaper. Source: https://vanadreams.org/wiki/#quest-394', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 4.\n• Get the cursepaper from Zon-Fobun (Bastok Markets G-5).\n• In Beadeaux, talk to The Mute.\n• Walk through the cursed spots, upper levels included, until the paper is full.\n• Return it to Zon-Fobun (it is taken).' }, { title = 'Reward', note = '• Poison Cesti, Bastok fame 40' } } },
    { name = 'The Darksmith', group = 'Bastok', desc = 'Darksteel Ore for Mighty Fist in Metalworks. Source: https://vanadreams.org/wiki/#quest-395', steps = { { title = 'Walkthrough', note = '• Needs Bastok fame 3.\n• Accept from Mighty Fist (Metalworks G-9) and trade 2 Chunks of Darksteel Ore.\n• He gives one hint per zone.' }, { title = 'Reward', note = '• 8,000 gil, Bastok fame 16' } } },
    { name = 'The Eleventh\'s Hour', group = 'Bastok', desc = 'Bastok Mines quest to recover an old toolbox from Palborough Mines for Elki and Babenn. Source: https://vanadreams.org/wiki/#quest-396', steps = { { title = 'Requirements', note = '• Hearts of Mythril finished\n• Bastok fame 3\n• If prompted, zone once after your last Bastok quest' }, { title = 'Walkthrough', note = '• Accept from Elki (H-5), Bastok Mines.\n• In Palborough Mines, take the Old Toolbox (Map 3, H-8).\n• Show the toolbox to Elki (H-5).\n• Finish by talking to Babenn (J-6), Bastok Mines.' }, { title = 'Notes', note = '• The toolbox is removed on completion.' }, { title = 'Reward', note = '• Small Sword\n• Title: Pursuer of the Truth\n• Bastok fame 30' } } },
    { name = 'The Elvaan Goldsmith', group = 'Bastok', desc = 'Hand Michea a Copper Ingot for gil and fame. Source: https://vanadreams.org/wiki/#quest-397', steps = { { title = 'Walkthrough', note = '• No requirements.\n• Talk to Michea (F-10), Bastok Markets.\n• Trade him a Copper Ingot.' }, { title = 'Notes', note = '• Repeatable while Bastok fame is level 1; zone between turn-ins.' }, { title = 'Reward', note = '• 180 gil\n• Bastok fame 10' } } },
    { name = 'The Gustaberg Tour', group = 'Bastok', desc = 'Escort a low-level party to the Hunting Bear in North Gustaberg. Source: https://vanadreams.org/wiki/#quest-398', steps = { { title = 'Walkthrough', note = '• No requirements.\n• Accept from Izabele (G-8), Metalworks.\n• Party of 2+, everyone level 15 or under, standing together.\n• Examine the Hunting Bear (F-8), North Gustaberg.' }, { title = 'Notes', note = '• Fails to progress if any member is over 15 or out of range.' }, { title = 'Reward', note = '• 500 gil\n• Title: Gustaberg Tourist\n• Bastok fame 20' } } },
    { name = 'The Quadav\'s Curse', group = 'Bastok', desc = 'Give Corann in Port Bastok a Quadav Backplate. Source: https://vanadreams.org/wiki/#quest-399', steps = { { title = 'Walkthrough', note = '• No requirements.\n• Accept from Corann (K-6), Port Bastok.\n• Trade him a Quadav Backplate (dropped by quadav near Bastok).' }, { title = 'Reward', note = '• Bronze Subligar\n• Bastok fame 20' } } },
    { name = 'The Return of the Adventurer', group = 'Bastok', desc = 'Deliver Cinnamon to Gwill in Bastok Markets. Source: https://vanadreams.org/wiki/#quest-400', steps = { { title = 'Requirements', note = '• Bastok fame 3\n• Father Figure finished' }, { title = 'Walkthrough', note = '• Accept from Gwill (E-11), Bastok Markets.\n• Get a Cinnamon and trade it to Gwill.' }, { title = 'Reward', note = '• Cotton Headband\n• Title: Kulatz Bridge Companion\n• Bastok fame 30' } } },
    { name = 'The Signpost Marks the Spot', group = 'Bastok', desc = 'Retrieve a windmill painting from a Konschtat Highlands signpost for the Latteh siblings. Source: https://vanadreams.org/wiki/#quest-401', steps = { { title = 'Requirements', note = '• Bastok fame 2\n• Mom, the Adventurer finished (zone afterwards if not offered)' }, { title = 'Walkthrough', note = '• Accept from Nbu Latteh (J-9), Bastok Markets.\n• Check the marked signpost in Konschtat Highlands to get the painting.\n• Deliver it to Roh Latteh (H-7), Bastok Mines.' }, { title = 'Reward', note = '• Linen Robe\n• Title: Treasure Scavenger\n• Bastok fame 20' } } },
    { name = 'The Siren\'s Tear', group = 'Bastok', desc = 'Find the Siren\'s Tear in North Gustaberg for Wahid. Source: https://vanadreams.org/wiki/#quest-402', steps = { { title = 'Walkthrough', note = '• Accept from Wahid (I-8), Bastok Mines.\n• Speak to Otto (E-6), then Carmelo (E-6), both in Port Bastok.\n• Examine the ??? in North Gustaberg for the Siren\'s Tear.\n• Trade it to Wahid.' }, { title = 'Notes', note = '• Lost it after finishing? Carmelo will direct you again.' }, { title = 'Reward', note = '• 150 gil\n• Title: Tearjerker\n• Bastok fame 10' } } },
    { name = 'The Stars of Ifrit', group = 'Bastok', desc = 'Pick up a carrier pigeon letter on the San d\'Oria-Jeuno airship for Agapito. Source: https://vanadreams.org/wiki/#quest-403', steps = { { title = 'Requirements', note = '• Bastok fame 3\n• Airship pass' }, { title = 'Walkthrough', note = '• Accept from Agapito (G-6), Port Bastok.\n• On the San d\'Oria-Jeuno airship, examine the ??? (F-11) at night or on a full moon.\n• Report back to Agapito.' }, { title = 'Notes', note = '• The ??? only shows at night or full moon.\n• The letter is a permanent key item.' }, { title = 'Reward', note = '• 2,100 gil\n• Title: Star of Ifrit\n• Bastok fame 30' } } },
    { name = 'The Usual', group = 'Bastok', desc = 'Trade Hilda a King Truffle to earn a Steaming Sheep invitation. Source: https://vanadreams.org/wiki/#quest-404', steps = { { title = 'Requirements', note = '• Cid\'s Secret finished\n• Bastok fame 5+' }, { title = 'Walkthrough', note = '• Accept from Hilda (E-6), Port Bastok.\n• Trade her a King Truffle for the invitation.\n• Show it to Raibaht (G-8), Metalworks.\n• Go back to Hilda to finish.' }, { title = 'Reward', note = '• Speed Bow\n• Title: Steaming Sheep Regular\n• Bastok fame 50' } } },
    { name = 'The Walls of Your Mind', group = 'Bastok', desc = 'Hand-to-Hand weapon skill quest for Asuran Fists via the Knuckles of Trials and Bodach. Source: https://vanadreams.org/wiki/#quest-405', steps = { { title = 'Requirements', note = '• Hand-to-Hand skill 250+\n• Can equip Knuckles of Trials; no weapon training guide held' }, { title = 'Walkthrough', note = '• Get the Knuckles of Trials and training guide from Oggbi (D-6), Port Bastok.\n• Earn 300 weapon skill points with them.\n• Trade the knuckles to Oggbi for the map to the Annals of Truth.\n• Enter Bostaunieux Oubliette from West Ronfaure (E-8); examine the ??? (Map 3, I-8) and kill Bodach.\n• Examine the ??? again for the Annals of Truth.\n• Talk to Oggbi to learn Asuran Fists.' }, { title = 'Notes', note = '• Oggbi replaces lost knuckles or cancels the quest on request.' }, { title = 'Reward', note = '• Knuckles of Trials\n• Bastok fame 20' } } },
    { name = 'The Weight of Your Limits', group = 'Bastok', desc = 'Great Axe weapon skill quest for Steel Cyclone via the Axe of Trials and Greenman. Source: https://vanadreams.org/wiki/#quest-406', steps = { { title = 'Requirements', note = '• Great Axe skill 240+\n• Job that can equip the Axe of Trials; no training guide held' }, { title = 'Walkthrough', note = '• Get the Axe of Trials and training guide from Iron Eater (J-8), Metalworks.\n• Earn 300 weapon skill points with it.\n• Trade the axe to Iron Eater for the map to the Annals of Truth.\n• Sanctuary of Zi\'Tah: examine the ??? (F-6), defeat Greenman while holding the map.\n• Examine the ??? again for the Annals of Truth.\n• Bring them to Iron Eater to learn Steel Cyclone.' }, { title = 'Notes', note = '• Iron Eater replaces a lost axe or lets you abandon.' }, { title = 'Reward', note = '• Axe of Trials\n• Bastok fame 20' } } },
    { name = 'The Wisdom of Elders', group = 'Bastok', desc = 'Bring Benita in Port Bastok a Bomb Ash. Source: https://vanadreams.org/wiki/#quest-407', steps = { { title = 'Walkthrough', note = '• Accept from Benita (J-6), Port Bastok.\n• Speak to Tete (I-5), Port Bastok.\n• Get a Bomb Ash and trade it to Benita.' }, { title = 'Reward', note = '• Traveler\'s Hat\n• Bastok fame 20' } } },
    { name = 'Till Death Do Us Part', group = 'Bastok', desc = 'Give Romilda in Port Bastok a pair of Cotton Gloves. Source: https://vanadreams.org/wiki/#quest-408', steps = { { title = 'Requirements', note = '• Forever to Hold finished\n• Bastok fame 3' }, { title = 'Walkthrough', note = '• Talk to Romilda (I-7), Port Bastok.\n• Trade her Cotton Gloves.' }, { title = 'Reward', note = '• 2,000 gil\n• Title: Qijis Rival\n• Bastok fame 30' } } },
    { name = 'Trial-Size Trial by Earth', group = 'Bastok', desc = 'Summoner quest: win the Trial-size Trial by Earth in the Cloister of Tremors to gain Titan. Source: https://vanadreams.org/wiki/#quest-409', steps = { { title = 'Requirements', note = '• Summoner main, level 20+\n• Bastok fame 2' }, { title = 'Walkthrough', note = '• Get the Mini Fork of Earth from Ferrol (I-7), Port Bastok.\n• Trade the fork back to Ferrol to warp to the Cloister of Tremors.\n• Win the battle.' }, { title = 'Notes', note = '• Ferrol hands out a new fork if lost.' }, { title = 'Reward', note = '• Titan spell\n• Instant Warp scroll, Mini Fork of Earth\n• Bastok fame 20' } } },
    { name = 'Trial by Earth', group = 'Bastok', desc = 'Beat Titan in the Cloister of Tremors and pick an Earth reward from Juroro. Source: https://vanadreams.org/wiki/#quest-410', steps = { { title = 'Requirements', note = '• Bastok fame 6+' }, { title = 'Walkthrough', note = '• Get a tuning fork of earth from Juroro (I-8), Port Bastok.\n• Defeat the avatar in the Trial by Earth fight, Cloister of Tremors.\n• Bring the whisper of tremors to Juroro and pick a reward.' }, { title = 'Notes', note = '• Choices: Titan\'s Cudgel, Earth Belt, Earth Ring, Desert Light, 10,000 gil, or Titan spell.\n• Lost the fight? Juroro gives a new fork.\n• Repeatable after one Japanese day.' }, { title = 'Reward', note = '• One of the choices above\n• Bastok fame 60' } } },
    { name = 'Trust: Bastok', group = 'Bastok', desc = 'Bastok Trust tutorial: learn Trust: Naji and get the Bastok Trust permit. Source: https://vanadreams.org/wiki/#quest-411', steps = { { title = 'Requirements', note = '• Level 5+\n• Trust quests enabled\n• No other nation\'s Trust quest in progress' }, { title = 'Walkthrough', note = '• Accept from Clarion Star (K-7), Port Bastok; receive the blue institute card.\n• Learn Trust: Naji from Naji (J-8), Metalworks.\n• Cast it to summon Naji.\n• Speak to Naji again to finish.' }, { title = 'Notes', note = '• If another nation\'s Trust quest is done, Naji gives the spell immediately.\n• Afterwards, Ayame, Volker and Iron Eater unlock in Metalworks via Naji, Lucius and Iron Eater once their conditions are met.' }, { title = 'Reward', note = '• Key item: Bastok Trust permit' } } },
    { name = 'Vengeful Wrath', group = 'Bastok', desc = 'Bring Goraow a Quadav Helm. Source: https://vanadreams.org/wiki/#quest-412', steps = { { title = 'Requirements', note = '• Bastok fame 3' }, { title = 'Walkthrough', note = '• Talk to Goraow (I-6), Bastok Mines.\n• Get a Quadav Helm from Quadav and trade it to him.' }, { title = 'Reward', note = '• 900 gil\n• Title: Avenger\n• Bastok fame 16' } } },
    { name = 'The Doorman', group = 'Bastok', desc = 'First Warrior artifact quest: win grip material in Davoi and deliver Yasin\'s sword to Naji. Source: https://vanadreams.org/wiki/#quest-413', steps = { { title = 'Requirements', note = '• Warrior main at artifact-quest level' }, { title = 'Walkthrough', note = '• Start with Phara (J-9), Bastok Mines.\n• Enter Davoi from Jugner Forest (G-12); check the Hide Flap on the orc tent to spawn Gavotvut (K-9) and Barakbok.\n• Kill both.\n• Check the Hide Flap (K-10) again for the sword grip material.\n• Give it to Phara.\n• After one Vana\'diel day, get Yasin\'s sword from Phara.\n• Deliver the sword to Naji (J-8), Metalworks.' }, { title = 'Notes', note = '• Stand right at the Hide Flap when checking.\n• Only whoever claimed both NMs gets the key item.' }, { title = 'Reward', note = '• Razor Axe\n• Bastok fame 20' } } },
    { name = 'The Talekeeper\'s Truth', group = 'Bastok', desc = 'Second Warrior artifact quest: get a Mottled Quadav Egg and a Parasite Skin for Deidogg. Source: https://vanadreams.org/wiki/#quest-414', steps = { { title = 'Requirements', note = '• Warrior main at artifact-quest level\n• The Doorman finished' }, { title = 'Walkthrough', note = '• Talk to Phara (J-9), then Deidogg (H-6) twice, Bastok Mines.\n• Palborough Mines: click the ??? (Map 3, G-10), defeat Ni\'Ghu Nestfender for the Mottled Quadav Egg.\n• Trade the egg to Deidogg.\n• Enter Castle Oztroja from Meriphataud Mountains (L-8); kill a Yagudo Parasite (Map 3, H-9) for a Parasite Skin.\n• Trade the skin to Deidogg.\n• After one Vana\'diel day, talk to Deidogg to finish.' }, { title = 'Notes', note = '• Both items can be obtained again if lost.' }, { title = 'Reward', note = '• Fighter\'s Calligae\n• Bastok fame 20' } } },
    { name = 'The Talekeeper\'s Gift', group = 'Bastok', desc = 'Warrior artifact quest: defeat three goblins in Behemoth\'s Dominion for the Fighter\'s Lorica. Source: https://vanadreams.org/wiki/#quest-415', steps = { { title = 'Requirements', note = '• Warrior main, level 50+\n• The Talekeeper\'s Truth finished, then one Vana\'diel day and a zone' }, { title = 'Walkthrough', note = '• Talk to Deidogg (H-6), then Detzo (I-6), Bastok Mines.\n• Trade Deidogg a Ginger Cookie to begin.\n• Behemoth\'s Dominion: check the ??? (K-9) and kill Picklix Longindex, Moxnix Nightgoggle and Doglix Muttsnout.\n• Zone into Qufim Island for the final scene.' }, { title = 'Notes', note = '• All three goblins must die before you leave the zone.' }, { title = 'Reward', note = '• Fighter\'s Lorica\n• Title: Paragon of Warrior Excellence\n• Bastok fame 20' } } },
    { name = 'Welcome to Bastok', group = 'Bastok', desc = 'Starter quest: show Bartolomeo your equipped Shell Shield. Source: https://vanadreams.org/wiki/#quest-416', steps = { { title = 'Requirements', note = '• Shell Shield' }, { title = 'Walkthrough', note = '• Accept from Powhatan (E-6), Port Bastok.\n• With the Shell Shield equipped in the sub slot, talk to Bartolomeo (F-7), Port Bastok.\n• Return to Powhatan.' }, { title = 'Reward', note = '• Spatha\n• Title: Bastok Welcoming Committee\n• Bastok fame 20' } } },
    { name = 'Wish Upon a Star', group = 'Bastok', desc = 'Log a Fallen Star in the jungle and hand it to Enu on a clear night. Source: https://vanadreams.org/wiki/#quest-417', steps = { { title = 'Requirements', note = '• Bastok fame 5\n• Hatchet' }, { title = 'Walkthrough', note = '• In Bastok Markets talk to Zacc (G-9), Malene (I-5), then accept from Enu (G-9).\n• Trade a Hatchet to a Logging Point in Yuhtunga or Yhoator Jungle for a Fallen Star.\n• Trade it to Enu at night with no weather.' }, { title = 'Notes', note = '• Enu refuses outside night/clear weather (midnight counts).\n• Only one Fallen Star can be held at a time.' }, { title = 'Reward', note = '• Cactus Stems, Fallen Star\n• Bastok fame 50' } } },
    { name = 'Clear: Ceizak Battlegrounds', group = 'Coalition', desc = 'Pioneers\' Coalition assignment: finish a Colonization Reive in Ceizak or Yahse and report back. Source: https://vanadreams.org/wiki/#quest-418', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• Imprimaturs to sign up' }, { title = 'Walkthrough', note = '• Pick Clear: Ceizak Battlegrounds at the Task Delegator, Western Adoulin.\n• Complete a Colonization Reive in Ceizak Battlegrounds or Yahse Hunting Grounds.\n• Report to the Task Delegator.' }, { title = 'Notes', note = '• Joining mid-reive counts if you are there for the final evaluation.\n• Cancel at the Task Delegator.' } } },
    { name = 'Gather: Ceizak Battlegrounds', group = 'Coalition', desc = 'Inventors\' Coalition assignment: turn in 5 Chapuli Wings. Source: https://vanadreams.org/wiki/#quest-419', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• 1+ imprimatur' }, { title = 'Walkthrough', note = '• Sign up at the Inventors\' Coalition Task Delegator, Western Adoulin, choosing imprimaturs.\n• Get 5 Chapuli Wings from Ceizak Battlegrounds monsters.\n• Trade them to the Task Delegator, then talk to collect.' }, { title = 'Notes', note = '• More imprimaturs = 100% / 180% / 240% reward.\n• Cancelling refunds imprimaturs.' } } },
    { name = 'Gather: Rala Waterways', group = 'Coalition', desc = 'Inventors\' Coalition assignment: turn in 3 Spools of Bloodthread for experience and bayld. Source: https://vanadreams.org/wiki/#quest-420', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• Imprimaturs to sign up' }, { title = 'Walkthrough', note = '• Sign up at the Inventors\' Coalition Task Delegator, Western Adoulin.\n• Get 3 Spools of Bloodthread (Pewter Diremites, NW Rala Waterways, or buy).\n• Trade them in, then talk to collect.' }, { title = 'Notes', note = '• Rewards scale with imprimaturs spent; cancellable at the desk.' } } },
    { name = 'Gather: Yahse Hunting Grounds', group = 'Coalition', desc = 'Inventors\' Coalition assignment: turn in 5 Twitherym Wings. Source: https://vanadreams.org/wiki/#quest-421', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• Imprimaturs to sign up' }, { title = 'Walkthrough', note = '• Sign up at the Inventors\' Coalition Task Delegator, Western Adoulin.\n• Get 5 Twitherym Wings (Yahse Hunting Grounds monsters or other sources).\n• Trade them in, then talk to collect.' }, { title = 'Notes', note = '• Cancellable before turn-in.\n• Experience and Bayld scale with imprimaturs.' } } },
    { name = 'Recover: Ceizak Battlegrounds', group = 'Coalition', desc = 'Mummers\' Coalition assignment: find a lost article in Ceizak or Yahse and return it. Source: https://vanadreams.org/wiki/#quest-423', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• 1+ imprimatur' }, { title = 'Walkthrough', note = '• Sign up at the Mummers\' Coalition Task Delegator, Western Adoulin.\n• Examine the Lost Article in Ceizak Battlegrounds or Yahse Hunting Grounds for the key item.\n• Hand it in at the Task Delegator.' }, { title = 'Notes', note = '• The Lost Article relocates after each pickup.\n• More imprimaturs = bigger reward; cancelling refunds them.' } } },
    { name = 'Research: Rala Waterways', group = 'Coalition', desc = 'Mummers\' Coalition assignment: take a slug\'s Fuscous Ooze in Rala Waterways and report. Source: https://vanadreams.org/wiki/#quest-424', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• 1+ imprimatur' }, { title = 'Walkthrough', note = '• Sign up at the Mummers\' Coalition Task Delegator, Western Adoulin, spending the imprimaturs you choose.\n• In Rala Waterways, get hit by a slug\'s Fuscous Ooze.\n• Report to the Task Delegator in Western Adoulin.' }, { title = 'Notes', note = '• You must be hit, not your pet; no need to kill the slug.\n• Reward scales with 1, 2 or 3 imprimaturs; cancelling refunds them.' }, { title = 'Reward', note = '• Key item: Pioneer\'s Badge' } } },
    { name = 'Support: Ceizak Battlegrounds', group = 'Coalition', desc = 'Pioneers\' Coalition assignment: deliver a materials container to a Bivouac Administrator. Source: https://vanadreams.org/wiki/#quest-425', steps = { { title = 'Requirements', note = '• Pioneer\'s Badge\n• Imprimaturs to sign up' }, { title = 'Walkthrough', note = '• Pick Support: Ceizak Battlegrounds at the Task Delegator, Western Adoulin, for the Cei. FB op. materials container.\n• Hand it to any Bivouac Administrator in Ceizak Battlegrounds or Yahse Hunting Grounds.\n• Report to the Task Delegator.' }, { title = 'Notes', note = '• Cancel at the Task Delegator.' } } },
    { name = 'A Little Knowledge', group = 'Crystal War', desc = 'Scholar unlock: collect Vellum and show Erlene a mage two-hour ability. Source: https://vanadreams.org/wiki/#quest-429', steps = { { title = 'Requirements', note = '• Access to Eldieme Necropolis [S]' }, { title = 'Walkthrough', note = '• Accept from Erlene, Eldieme Necropolis [S].\n• Talk to Tucker (Map 1, K-8), Crawler\'s Nest [S].\n• Trade him Rolanberries in 12s (max 4 stacks per trade) for Vellum until he stops.\n• Trade 12 Vellum to Erlene.\n• Talk to her with Manafont, Chainspell, Astral Flow or Azure Lore active.' }, { title = 'Notes', note = '• Those abilities need BLM, RDM, SMN or BLU.\n• Afterwards a level 5 Scholar can learn Embrava and Kaustra from Erlene.' }, { title = 'Reward', note = '• Vellum\n• Key items: grimoire, job gesture: scholar\n• Title: Schultz Scholar' } } },
    { name = 'Hammering Hearts', group = 'Crystal War', desc = 'Swap a Heavy Quadav Chestplate and Backplate for a Trainee Hammer. Source: https://vanadreams.org/wiki/#quest-432', steps = { { title = 'Walkthrough', note = '• Accept from Scarred Shark (G-5), Bastok Markets [S].\n• Trade him a Heavy Quadav Chestplate and a Heavy Quadav Backplate.\n• Zone, then talk to him again.' }, { title = 'Reward', note = '• Trainee Hammer' } } },
    { name = 'Her Memories: Azure Footfalls', group = 'Crystal War', desc = 'Bastok-allegiance Her Memories errand in North Gustaberg (S). Source: https://vanadreams.org/wiki/#quest-434', steps = { { title = 'Requirements', note = '• Current WotG mission: Her Memories\n• Campaign allegiance: Bastok' }, { title = 'Walkthrough', note = '• Zone North Gustaberg (S) to Bastok Markets (S) for a scene.\n• Accept from Adelbrecht (E-8), Bastok Markets (S).\n• North Gustaberg (S): talk to Gebhardt (I-6), then Roderich (E-11), then examine the Barricade (E-7).\n• Return to Adelbrecht.' }, { title = 'Reward', note = '• Key item: large memory fragment' } } },
    { name = 'Her Memories: Carnelian Footfalls', group = 'Crystal War', desc = 'San d\'Oria-allegiance Her Memories errand: visit three spots in East Ronfaure [S]. Source: https://vanadreams.org/wiki/#quest-435', steps = { { title = 'Requirements', note = '• Current WotG mission: Her Memories\n• Campaign allegiance: San d\'Oria' }, { title = 'Walkthrough', note = '• Zone East Ronfaure [S] to Southern San d\'Oria [S] for a scene.\n• Accept from Mainchelite (I-9), Southern San d\'Oria [S].\n• Zone into East Ronfaure [S] for a scene.\n• Examine all three ??? (H-8, J-7, I-8).\n• Report to Mainchelite.' }, { title = 'Notes', note = '• He only gives hints until all three are done.' }, { title = 'Reward', note = '• Key item: large memory fragment' } } },
    { name = 'Her Memories: Homecoming Queen', group = 'Crystal War', desc = 'Her Memories errand: three small San d\'Oria tasks, each giving a tiny memory fragment. Source: https://vanadreams.org/wiki/#quest-436', steps = { { title = 'Requirements', note = '• Current WotG mission: Her Memories' }, { title = 'Walkthrough', note = '• Start: zone East Ronfaure to Southern San d\'Oria.\n• Old Bean: Thierride (G-7, Port San d\'Oria) gives his bean creation; take it to Amaura (G-6, Southern San d\'Oria); return to Thierride.\n• The Faux Pas: Abioleget (M-7), then Bertenont (E-4), Northern San d\'Oria.\n• The Grave Resolve: Halver (I-9, Chateau d\'Oraguille); examine the Weathered Gravestone (I-10, Batallia Downs), then trade it a Lilac.' }, { title = 'Notes', note = '• Errands in any order; the third merges the fragments.' }, { title = 'Reward', note = '• Key item: large memory fragment' } } },
    { name = 'Her Memories: Of Malign Maladies', group = 'Crystal War', desc = 'Her Memories errand: prepare a fey stone in Grauberg [S]. Source: https://vanadreams.org/wiki/#quest-437', steps = { { title = 'Requirements', note = '• Current WotG mission: Her Memories' }, { title = 'Walkthrough', note = '• Talk to Amaura (G-6), Southern San d\'Oria.\n• Talk to Monberaux (G-10), Upper Jeuno.\n• Examine the library book, Windurst Waters.\n• Trade a Philosopher\'s Stone to the Fey Blossoms (F-5), Grauberg [S].\n• One Vana\'diel day later, examine them for the fey stone.\n• Show it to Raustigne (I-7), Southern San d\'Oria [S].' }, { title = 'Reward', note = '• Key item: large memory fragment' } } },
    { name = 'Her Memories: Operation Cupid', group = 'Crystal War', desc = 'Her Memories errand: make martial relish and deliver it to the Bulwark Gate. Source: https://vanadreams.org/wiki/#quest-438', steps = { { title = 'Requirements', note = '• Current WotG mission: Her Memories' }, { title = 'Walkthrough', note = '• Zone Jugner Forest (S) to Batallia Downs (S) for the opening scene.\n• Examine the Bulwark Gate (E-6), Sauromugue Champaign (S).\n• Get a Bottle of Rice Vinegar, a Jar of Ground Wasabi and a Sprig of Holy Basil.\n• Trade all three at once to Leadavox (J-6), Vunkerl Inlet (S), for martial relish.\n• Bring the relish to the Bulwark Gate.\n• Zone Rolanberry Fields (S) to Batallia Downs (S) to finish.' }, { title = 'Reward', note = '• Key item: large memory fragment' } } },
    { name = 'Lost in Translocation', group = 'Crystal War', desc = 'Gather three map pieces in The Eldieme Necropolis [S] for Thorben. Source: https://vanadreams.org/wiki/#quest-440', steps = { { title = 'Walkthrough', note = '• Accept from Thorben (J-10), Batallia Downs [S].\n• Enter The Eldieme Necropolis [S] at (J-10).\n• Left piece: Erik (Map 1, H-7). Middle: the Gravestone. Right: the Sarcophagus. Any order.\n• Return to Thorben.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP\n• Key item: map of Grauberg' } } },
    { name = 'Message on the Wind', group = 'Crystal War', desc = 'Relay Romualdo\'s message to the Grauberg [S] front. Source: https://vanadreams.org/wiki/#quest-441', steps = { { title = 'Requirements', note = '• Level 20+' }, { title = 'Walkthrough', note = '• Talk to Romualdo (K-9), Metalworks.\n• Talk to Romualdo (I-7), Batallia Downs [S].\n• Grauberg [S]: talk to Childerich (E-12), examine the ??? (J-8), talk to Childerich again.\n• Return to Romualdo in Batallia Downs [S].\n• Closing scenes: Romualdo in Metalworks, then Childerich in Grauberg [S] (title Windtalker).' }, { title = 'Reward', note = '• Smart Grenade\n• Title: Windtalker\n• Bastok fame 20' } } },
    { name = 'On Sabbatical', group = 'Crystal War', desc = 'First Scholar artifact quest: shuttle sealed letters for Erlene. Source: https://vanadreams.org/wiki/#quest-442', steps = { { title = 'Requirements', note = '• Scholar main at first artifact-quest level\n• A Little Knowledge finished' }, { title = 'Walkthrough', note = '• Enter Eldieme Necropolis [S] from Batallia Downs [S] (J-10); get Ulbrecht\'s sealed letter from Erlene.\n• Talk to Gentle Tiger (H-6), Bastok Markets [S].\n• Pashhow Marshlands [S]: check Indescript Markings until one gives Schultz\'s sealed letter.\n• Bring both letters to Erlene.' }, { title = 'Notes', note = '• Wait a Vana\'diel day and zone before the next job quest.' }, { title = 'Reward', note = '• Klimaform' } } },
    { name = 'Downward Helix', group = 'Crystal War', desc = 'Second Scholar artifact quest: recover Ulbrecht\'s mortarboard. Source: https://vanadreams.org/wiki/#quest-443', steps = { { title = 'Requirements', note = '• Scholar main at artifact-quest level\n• On Sabbatical finished, 1+ Vana\'diel day ago' }, { title = 'Walkthrough', note = '• Accept from Erlene, Eldieme Necropolis [S] (enter from Batallia Downs [S], J-10).\n• Zone East Ronfaure [S] to Southern San d\'Oria [S] for a scene.\n• Return to Erlene for a scene.\n• Zone Rolanberry Fields [S] to Sauromugue Champaign [S] for a scene.\n• Click Indescript Markings (J-7), Sauromugue Champaign [S], for the mortarboard.\n• Bring it to Erlene.' }, { title = 'Notes', note = '• Zone and wait one Vana\'diel day before the next job quest.' }, { title = 'Reward', note = '• Scholar\'s Bracers' } } },
    { name = 'Seeing Spots', group = 'Crystal War', desc = 'Hand Wyatt four Ladybug Wings; repeatable. Source: https://vanadreams.org/wiki/#quest-445', steps = { { title = 'Walkthrough', note = '• Accept from Wyatt (L-6), Southern San d\'Oria [S].\n• Get 4 Ladybug Wings from ladybugs and trade them to him.' }, { title = 'Notes', note = '• Repeatable with another 4 wings.' }, { title = 'Reward', note = '• 3,000 gil\n• Title: Lady Killer' } } },
    { name = 'The Dawn of Delectability', group = 'Crystal War', desc = 'Cook-off errand for Ranpi-Monpi across past and present Windurst Waters. Source: https://vanadreams.org/wiki/#quest-449', steps = { { title = 'Requirements', note = '• Pepperoni, Walnut, Dragon Fruit, Bastore Sweeper' }, { title = 'Walkthrough', note = '• Accept from Ranpi-Monpi, Windurst Waters [S].\n• Talk to Ranpi-Monpi in present Windurst Waters.\n• Trade him all four ingredients in one trade.\n• After one Vana\'diel day, get the Ranpi-Monpi Specialty from him.\n• Give it to Ranpi-Monpi in Windurst Waters [S] for the culinary knife.\n• Bring the knife to Ranpi-Monpi in Windurst Waters.' }, { title = 'Reward', note = '• Trainee Knife' } } },
    { name = 'The Flipside of Things', group = 'Crystal War', desc = 'Retrieve a firepower case in Garlaige Citadel [S] for Rarcasmeault. Source: https://vanadreams.org/wiki/#quest-450', steps = { { title = 'Walkthrough', note = '• Enter Garlaige Citadel [S] from Sauromugue Champaign [S] (J-10); accept from Rarcasmeault.\n• Examine the ??? for the firepower case.\n• Give it to Rarcasmeault.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP\n• Key item: map of Vunkerl Inlet' } } },
    { name = 'The Fumbling Friar', group = 'Crystal War', desc = 'Recover an ornate package from Grauberg (S) for Fondactiont. Source: https://vanadreams.org/wiki/#quest-451', steps = { { title = 'Requirements', note = '• Brass Ribbon of Service or higher medal\n• Level 30+' }, { title = 'Walkthrough', note = '• Accept from Fondactiont, Garlaige Citadel (S).\n• Examine the ??? in Grauberg (S) for the ornate package.\n• Return it to Fondactiont.' }, { title = 'Reward', note = '• Recall-Pashh' } } },
    { name = 'The Lost Book', group = 'Crystal War', desc = 'Recover a lost book via Windurst Waters [S], Giddeus and Castle Oztroja [S]. Source: https://vanadreams.org/wiki/#quest-452', steps = { { title = 'Requirements', note = '• Level 30+\n• Bronze Ribbon of Service' }, { title = 'Walkthrough', note = '• Examine Door: Rhinostery, Windurst Waters [S].\n• Trade a Mythril Beastcoin to Quu Bokye (Map 2, F-6), Giddeus, for the Leather-bound Book.\n• Examine Door: Rhinostery again, then Door: Optistery.\n• Check the ??? (G-8), Castle Oztroja [S], for a Lynx Pelt.\n• Trade a Vellum to Door: Optistery.\n• After one Vana\'diel day, examine Door: Optistery to finish.' }, { title = 'Reward', note = '• Retrace' } } },
    { name = 'The Weekly Adventurer', group = 'Crystal War', desc = 'Pass Rakula-Motakula\'s quiz for journalist Naiko-Paneiko. Source: https://vanadreams.org/wiki/#quest-454', steps = { { title = 'Walkthrough', note = '• Get the Scoop-Dedicated Linkpearl from Naiko-Paneiko (Map 1, L-8), Crawlers\' Nest (S).\n• Talk to Rakula-Motakula (G-9), Rolanberry Fields (S); answer 4, 4, 5.\n• Report to Naiko-Paneiko.' }, { title = 'Notes', note = '• Wrong answers: talk to Naiko-Paneiko and retry.\n• The linkpearl is removed on completion.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP\n• Key item: map of Fort Karugo-Narugo' } } },
    { name = 'The Fighting Fourth (WOTG Nation Quests - Bastok 0)', group = 'Crystal War', desc = 'Bastok\'s opening Campaign quest: carry rations for the Fourth Division and inspect a barricade. Begins with Turbulent Storm in The Eldieme Necropolis [S]. Source: https://vanadreams.org/wiki/#quest-475', steps = { { title = 'Requirements', note = '• Wings of the Goddess access.\n• No Campaign allegiance to another nation.' }, { title = 'Walkthrough', note = '• Get the Blue Recommendation Letter from Turbulent Storm, Eldieme Necropolis [S].\n• Give it to Adelbrecht (E-8), Bastok Markets [S]; enlist and take the Battle Rations.\n• Hand the rations to Gebhardt (I-6), North Gustaberg [S].\n• Speak with Roderich (E-11), North Gustaberg [S].\n• Examine the Barricade (E-7), North Gustaberg [S] for a scene.\n• Report to Adelbrecht (E-8) to finish.' }, { title = 'Notes', note = '• Adelbrecht offers a way out before the final step and hands the letter back.\n• Completion sets your Campaign allegiance to Bastok.' }, { title = 'Reward', note = '• Sprinter\'s Shoes\n• Title: Fourth Division Soldier' } } },
    { name = 'What Price Loyalty (WOTG Nation Quests - Bastok 10)', group = 'Crystal War', desc = 'Deliver supplies for Gentle Tiger, then beat Klara in Everbloom Hollow for the Fourth Staff. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-476', steps = { { title = 'Requirements', note = '• Beneath the Mask done.\n• WotG missions at Fate in Haze or beyond.' }, { title = 'Walkthrough', note = '• Get the sack of victuals from Gentle Tiger (H-6), Bastok Markets [S].\n• Bring it to Roderich (E-11), North Gustaberg [S].\n• Go back to Gentle Tiger for new orders.\n• Enter Xarcabard [S]; a scene grants the commander\'s endorsement.\n• Examine the Forbidding Portal (I-7), Xarcabard [S] for a scene.\n• Examine the portal again with the endorsement to enter Everbloom Hollow; defeat Klara.\n• Watch the scene back in Xarcabard [S], then report to Gentle Tiger.' }, { title = 'Notes', note = '• Lost endorsement: Gentle Tiger reissues it.\n• Solo foe Klara; 30-minute limit.' }, { title = 'Reward', note = '• Fourth Staff' } } },
    { name = 'The Truth Lies Hid (WOTG Nation Quests - Bastok 11)', group = 'Crystal War', desc = 'Identify the truthful imp in Castle Zvahl Keep [S] and examine the Displaced Block. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-477', steps = { { title = 'Requirements', note = '• What Price Loyalty done.\n• WotG missions through \'Adieu, Lilisette\'.' }, { title = 'Walkthrough', note = '• Accept from Gentle Tiger (H-6), Bastok Markets [S].\n• Enter Castle Zvahl Baileys [S] for a cutscene.\n• In Castle Zvahl Keep [S], hear Rikke (Map 1, G-7), Rakke (Map 1, G-10) and Rokke (Map 1, H-10).\n• Trade an Elixir to the imp telling the truth.\n• Examine the ??? (Map 3, G-9).\n• Examine the Displaced Block (Map 3, H-7) to finish.' }, { title = 'Notes', note = '• The truthful imp varies by Vana\'diel day.\n• One Elixir trade per Vana\'diel day; a wrong pick means retrying tomorrow.' }, { title = 'Reward', note = '• Sanctus Rosary' } } },
    { name = 'Bonds of Mythril (WOTG Nation Quests - Bastok 12)', group = 'Crystal War', desc = 'Earn the Zvahl passkey in Castle Zvahl Keep [S], win the Throne Room [S] battle and return to Bastok. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-478', steps = { { title = 'Requirements', note = '• The Truth Lies Hid done.\n• WotG missions through Adieu, Lilisette.' }, { title = 'Walkthrough', note = '• Zone from Castle Zvahl Keep [S] into Castle Zvahl Baileys [S]; the cutscene starts the quest.\n• Back in the Keep, click the ??? (Map 3, G-9) for a cutscene.\n• Kill four Keep Imps, click the ??? to spawn the Gargouille Warden, and defeat it.\n• Click the ??? once more for the Zvahl passkey.\n• Click the Throne Room door in the Throne Room [S] and win Bonds of Mythril.\n• Speak to Gentle Tiger (H-6), Bastok Markets [S]; you are moved to Metalworks.\n• After the Metalworks scene you go to North Gustaberg [S]; its final cutscene completes the quest.' }, { title = 'Notes', note = '• The passkey is removed at completion.' }, { title = 'Reward', note = '• Excelsis Ring\n• Title: Temperer of Mythril' } } },
    { name = 'Better Part of Valor (WOTG Nation Quests - Bastok 1)', group = 'Crystal War', desc = 'Take animal hair to a ??? in North Gustaberg (S) and get a Gnole Claw traded by Leadavox in Vunkerl Inlet (S). Begins with Wolfram in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-479', steps = { { title = 'Requirements', note = '• Any one first-tier WotG nation quest done: Steamed Rams, Snake on the Plains or The Fighting Fourth.' }, { title = 'Walkthrough', note = '• Zone Bastok Markets (S) to North Gustaberg (S); you get the clump of animal hair.\n• Speak to Engelhart (K-10), Bastok Markets (S).\n• Examine the ??? (J-9), North Gustaberg (S).\n• Speak to Leadavox (J-6), Vunkerl Inlet (S).\n• Trade him a Gnole Claw for the xhifhut.\n• Bring the xhifhut to Engelhart (K-10).' }, { title = 'Notes', note = '• Zone once after finishing before starting another Crystal War quest.' }, { title = 'Reward', note = '• 10,000 gil\n• Key item: warning letter' } } },
    { name = 'Fires of Discontent (WOTG Nation Quests - Bastok 2)', group = 'Crystal War', desc = 'Bastok errand chain across Bastok Markets [S], Metalworks and Grauberg [S]. Begins with Engelhart in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-480', steps = { { title = 'Requirements', note = '• The Better Part of Valor done.' }, { title = 'Walkthrough', note = '• Engelhart (K-10), Bastok Markets [S].\n• Pagdako (H-9), Bastok Markets [S].\n• Iron Eater (J-8), Metalworks.\n• Engelhart (K-10) again.\n• Check the ??? (I-6) in Grauberg [S] for a scene.\n• Engelhart (K-10), then Gentle Tiger (H-6).\n• Engelhart (K-10) a final time to finish.' }, { title = 'Reward', note = '• 10,000 gil' } } },
    { name = 'Light in the Darkness (WOTG Nation Quests - Bastok 3)', group = 'Crystal War', desc = 'Buy a mine shaft key, then beat Quadav in a Ruhotz Silvermines battlefield for an Adaman Ingot. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-481', steps = { { title = 'Requirements', note = '• Fires of Discontent done.\n• WotG mission Back to the Beginning done, plus one Vana\'diel day elapsed.' }, { title = 'Walkthrough', note = '• Speak to Gentle Tiger (H-6), Bastok Markets [S].\n• Speak to Pagdako (H-9), then Blatherix (F-8).\n• Trade Blatherix 30 Gob. Chocolates or 5,000 gil for the mine shaft key.\n• Go from Grauberg [S] into Pashhow Marshlands [S] for a scene.\n• Check the Corroded Door (F-5), Pashhow Marshlands [S], to enter.\n• Kill 7 or more of the 10 Quadav in Ruhotz Silvermines inside 30 minutes.\n• After the scene, report to Gentle Tiger.' }, { title = 'Notes', note = '• On failure, a replacement key costs 10 Gob. Chocolates or 1,000 gil from Blatherix.\n• Next Bastok quest waits until the next Vana\'diel day.' }, { title = 'Reward', note = '• Adaman Ingot' } } },
    { name = 'Burden of Suspicion (WOTG Nation Quests - Bastok 4)', group = 'Crystal War', desc = 'Look into a suspicious matter for Gentle Tiger, including a Sarcophagus in The Eldieme Necropolis [S]. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-482', steps = { { title = 'Requirements', note = '• Light in the Darkness done.' }, { title = 'Walkthrough', note = '• Accept from Gentle Tiger (H-6), Bastok Markets [S].\n• Speak to Engelhart (K-10).\n• Enter The Eldieme Necropolis [S] via Batallia Downs [S] (J-10) and examine the Sarcophagus.\n• Report to Gentle Tiger to finish.' }, { title = 'Notes', note = '• No response from Gentle Tiger: zone or wait a Vana\'diel day.' }, { title = 'Reward', note = '• Title: Assistant Detective' } } },
    { name = 'Storm on the Horizon (WOTG Nation Quests - Bastok 5)', group = 'Crystal War', desc = 'Visit North Gustaberg [S] and Grauberg [S] for Bastok. Begins with Blatherix in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-483', steps = { { title = 'Requirements', note = '• Burden of Suspicion done.' }, { title = 'Walkthrough', note = '• Get an Elixir from Blatherix (F-8), Bastok Markets [S].\n• After one Vana\'diel day, zone from North Gustaberg [S] into Bastok Markets [S] to start.\n• Speak to Gentle Tiger (H-6).\n• Examine the Monument (J-7), North Gustaberg [S].\n• Examine the ??? (I-6), Grauberg [S] to finish.' }, { title = 'Notes', note = '• A zone plus one game day after Blatherix are needed before it triggers.' }, { title = 'Reward', note = '• Icarus Wing, Elixir' } } },
    { name = 'Fire in the Hole (WOTG Nation Quests - Bastok 6)', group = 'Crystal War', desc = 'Escort Adelheid through Ruhotz Silvermines with the silvermine key. Begins with Stonehoused Adit in North Gustaberg [S]. Source: https://vanadreams.org/wiki/#quest-484', steps = { { title = 'Requirements', note = '• Storm on the Horizon done.\n• WotG missions through \'In the Name of the Father\'.' }, { title = 'Walkthrough', note = '• Zone North Gustaberg [S] to Bastok Markets [S]; scenes give the silvermine key.\n• Examine the Stonehoused Adit (E-8), North Gustaberg [S], to enter Ruhotz Silvermines.\n• Protect Adelheid through every Quadav wave; she must live.\n• Exit to North Gustaberg [S] for a cutscene.\n• Zone into Bastok Markets [S] for another.\n• Speak to Gentle Tiger (H-6) twice to finish.' }, { title = 'Notes', note = '• Roughly 30-minute limit.\n• Lost key: Solitary Ant, North Gustaberg [S].' }, { title = 'Reward', note = '• Rep. Silver Medal\n• Title: Mythril Musketeer No 6' } } },
    { name = 'Quelling the Storm (WOTG Nation Quests - Bastok 7)', group = 'Crystal War', desc = 'Collect goblin goods for Blatherix and check a spot in Vunkerl Inlet [S]. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-485', steps = { { title = 'Requirements', note = '• Fire in the Hole done.\n• WotG missions through \'Crossroads of Time\'.' }, { title = 'Walkthrough', note = '• Zone North Gustaberg [S] to Bastok Markets [S] for a cutscene.\n• Speak to Gentle Tiger (H-6).\n• Speak to Paul (H-5), Biggorf (H-10) and Wilhelmina (I-10), any order.\n• Speak to Gentle Tiger, then Blatherix (F-8).\n• Trade Blatherix a Goblin Mess Tin, Goblin Mushpot and Twinkle Powder.\n• Speak to Gentle Tiger.\n• Examine the ??? (F-6), Vunkerl Inlet [S].\n• Speak to Blatherix to finish.' }, { title = 'Reward', note = '• Goblin Belt' } } },
    { name = 'Honor Under Fire (WOTG Nation Quests - Bastok 8)', group = 'Crystal War', desc = 'Use a flare grenade to reach Everbloom Hollow and beat Arch Ahriman. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-486', steps = { { title = 'Requirements', note = '• Quelling the Storm done.\n• WotG mission \'Crossroads of Time\' reached.' }, { title = 'Walkthrough', note = '• Accept from Gentle Tiger (H-6), Bastok Markets (S).\n• Examine the ??? (F-6), Vunkerl Inlet (S).\n• Speak to the Beastman Ensign (J-7), Vunkerl Inlet (S).\n• Get the flare grenade from Gentle Tiger.\n• Speak to the Beastman Ensign again for a cutscene.\n• With the grenade, speak to him once more to enter Everbloom Hollow; kill Arch Ahriman and its reinforcements.\n• Zone into Vunkerl Inlet (S) for a cutscene.\n• Report to Gentle Tiger.' }, { title = 'Notes', note = '• Lost grenade: Gentle Tiger gives another.' }, { title = 'Reward', note = '• Elixir Tank' } } },
    { name = 'Beneath the Mask (WOTG Nation Quests - Bastok 9)', group = 'Crystal War', desc = 'Make a wax seal for Red Axe and carry word to Hoarfang. Begins with Gentle Tiger in Bastok Markets [S]. Source: https://vanadreams.org/wiki/#quest-487', steps = { { title = 'Requirements', note = '• Honor Under Fire done.\n• WotG missions through \'Fate in Haze\'.' }, { title = 'Walkthrough', note = '• Accept from Gentle Tiger (H-6), Bastok Markets [S].\n• Zone into Beadeaux [S] for a cutscene.\n• Return to Gentle Tiger.\n• Enter The Eldieme Necropolis [S] via Batallia Downs [S] (J-10) and speak to Red Axe.\n• Trade Beeswax + Red Textile Dye to Leadavox (J-6), Vunkerl Inlet [S], for a wax seal.\n• Give the seal to Red Axe.\n• Speak to Gentle Tiger.\n• Speak to Hoarfang (F-10), Beaucedine Glacier [S] to finish.' }, { title = 'Reward', note = '• Super Reraiser' } } },
    { name = 'Steamed Rams (WOTG Nation Quests - San d\'Oria 0)', group = 'Crystal War', desc = 'San d\'Oria\'s opening Campaign quest: salvage three pieces of airship wreck in East Ronfaure [S] for the Iron Rams. Begins with Randecque in Garlaige Citadel [S]. Source: https://vanadreams.org/wiki/#quest-488', steps = { { title = 'Requirements', note = '• Wings of the Goddess access.\n• No other nation\'s Campaign allegiance, unless switching.' }, { title = 'Walkthrough', note = '• Enter Garlaige Citadel [S] via Sauromugue Champaign [S] (J-10); Randecque (Map 2, I-6) gives the Red Recommendation Letter.\n• Bring it to Mainchelite (I-9), Southern San d\'Oria [S], and accept.\n• Check the three ??? in East Ronfaure [S] for the Charred Propeller, Piece of Shattered Lumber and Oxidized Plate.\n• Return all three to Mainchelite.' }, { title = 'Notes', note = '• Mainchelite lets you quit and returns the letter.\n• Completion sets your Campaign allegiance to San d\'Oria.' }, { title = 'Reward', note = '• Sprinter\'s Shoes\n• Title: Knight of the Iron Ram' } } },
    { name = 'Blood of Heroes (WOTG Nation Quests - San d\'Oria 10)', group = 'Crystal War', desc = 'Use military prism powder to enter Ghoyu\'s Reverie and beat Kingslayer Doggvdegg. Begins with Animal Spoor in Xarcabard [S]. Source: https://vanadreams.org/wiki/#quest-489', steps = { { title = 'Requirements', note = '• Songbirds in a Snowstorm done.' }, { title = 'Walkthrough', note = '• Start at Animal Spoor (J-9), Xarcabard (S); Rholont (E-7), Southern San d\'Oria (S), offers background.\n• Examine the Wheel Rut (I-9).\n• Return to Animal Spoor for the vial of military prism powder.\n• Examine the Forbidding Portal (I-7).\n• Examine Animal Spoor again; wait if asked and re-collect the vial if needed.\n• With the vial, use the Forbidding Portal to enter Ghoyu\'s Reverie; kill Kingslayer Doggvdegg (Map 4, K-6) and the Bloodwing orcs while keeping Excenmille alive.\n• Watch the scene in Xarcabard (S), then examine the Wheel Rut to finish.' }, { title = 'Notes', note = '• Loss or Excenmille\'s death: retry next Vana\'diel day.' }, { title = 'Reward', note = '• Ram Staff\n• Title: House Aurchiat Retainer' } } },
    { name = 'Chasing Shadows (WOTG Nation Quests - San d\'Oria 11)', group = 'Crystal War', desc = 'Track footprints in Xarcabard [S] and fight Menechme in Batallia Downs [S] for a Darksteel Sheet. Begins with Rongelouts in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-490', steps = { { title = 'Requirements', note = '• Blood of Heroes done.' }, { title = 'Walkthrough', note = '• Speak to Rongelouts N Distaud (I-9), Southern San d\'Oria [S].\n• Zone Beaucedine Glacier [S] to Xarcabard [S] for a scene.\n• Check, in order: Backfilled Pit (F-8), Compact Footprint (H-8), Sunken Footprint (H-6), Compact Footprint again.\n• Zone Beaucedine Glacier [S] to Batallia Downs [S] for a scene.\n• Check the Fresh Snowmelt (H-5) twice to spawn Menechme.\n• Defeat Menechme and check the Fresh Snowmelt again to finish.' }, { title = 'Notes', note = '• Unlocks Face of the Future.' }, { title = 'Reward', note = '• Darksteel Sheet' } } },
    { name = 'Face of the Future (WOTG Nation Quests - San d\'Oria 12)', group = 'Crystal War', desc = 'Infiltrate Yughott Grotto disguised and win the Everbloom Hollow battle. Begins with Metallic Hodgepodge in Jugner Forest. Source: https://vanadreams.org/wiki/#quest-491', steps = { { title = 'Requirements', note = '• Follows Chasing Shadows.\n• Cavernous Maw in Batallia Downs unlocked.' }, { title = 'Walkthrough', note = '• Zone Batallia Downs to Jugner Forest for a cutscene.\n• Click the Metallic Hodgepodge (F-9), Jugner Forest.\n• Enter Ghelsba Outpost from West Ronfaure (E-4) for a cutscene.\n• In Ghelsba Outpost, click the Clandestine Marking (I-10) for the Orcish infiltration kit.\n• Enter Yughott Grotto from Fort Ghelsba (H-9); click the Scrape Mark (Map 1, G-9) for a scene, then again to fight.\n• Win the battle and re-enter Yughott Grotto for a cutscene.\n• Click the Cavernous Maw (H-5), Batallia Downs, for the next cutscene.\n• Zone into Batallia Downs for a scene, then view the scene in Xarcabard [S].\n• Re-enter Batallia Downs for the last cutscene to finish.' }, { title = 'Notes', note = '• The Orcish infiltration kit is required at the Scrape Mark.' }, { title = 'Reward', note = '• Griffon Ring\n• Title: Fangmonger Forestaller' } } },
    { name = 'Gifts of the Griffon (WOTG Nation Quests - San d\'Oria 1)', group = 'Crystal War', desc = 'Distribute seven Plumes d\'Or to residents of Southern San d\'Oria [S]. Begins with Louxiard in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-492', steps = { { title = 'Requirements', note = '• One opening WotG nation quest done.' }, { title = 'Walkthrough', note = '• Speak to Louxiard (G-7), Southern San d\'Oria [S], zone, and speak again.\n• Accept from Rholont (E-7) and take seven Plumes d\'Or.\n• Trade one plume each to Elnonde (K-8), Illeuse (H-9), Loillie (K-9), Louxiard (G-7), Machionage (C-6), Rongelouts N Distaud (I-9), Sabiliont (I-11).\n• Report to Rholont to finish.' }, { title = 'Notes', note = '• One plume per person.\n• Lost plumes are replaced by Rholont after the next conquest tally.' }, { title = 'Reward', note = '• Deathstone, Plume d\'Or' } } },
    { name = 'Claws of the Griffon (WOTG Nation Quests - San d\'Oria 2)', group = 'Crystal War', desc = 'Hunt a thief in Jugner Forest (S) for Rholont. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-493', steps = { { title = 'Requirements', note = '• Gifts of the Griffon done.\n• One Vana\'diel day since your previous Crystal War quest.' }, { title = 'Walkthrough', note = '• Speak to Rholont (E-7), Southern San d\'Oria (S), zone, then speak again.\n• Zone East Ronfaure (S) to Jugner Forest (S) for a cutscene.\n• Examine the ??? (I-6).\n• Examine it again to spawn Fingerfilcher Dradzad and kill it.\n• Examine it once more to finish.' }, { title = 'Reward', note = '• Angelstone' } } },
    { name = 'Boy and the Beast (WOTG Nation Quests - San d\'Oria 3)', group = 'Crystal War', desc = 'Find the right Vunkerl herb at the Leafy Patch in Vunkerl Inlet (S). Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-494', steps = { { title = 'Requirements', note = '• WotG mission Back to the Beginning done.\n• Claws of the Griffon done.' }, { title = 'Walkthrough', note = '• Speak to Raustigne (I-7), then Rholont (E-7), Southern San d\'Oria (S).\n• Examine the ??? in Vunkerl Inlet (S) for the Vunkerl herb memo.\n• Examine the Leafy Patch (F-5) for a Vunkerl herb; the herb depends on time of day.\n• Examine the ??? again to hand it in.' }, { title = 'Notes', note = '• Wrong herb: try the Leafy Patch at another time of day.\n• Herb and memo are removed at completion.' }, { title = 'Reward', note = '• Carbon Fish. Rod' } } },
    { name = 'Wrath of the Griffon (WOTG Nation Quests - San d\'Oria 4)', group = 'Crystal War', desc = 'Kill Cobraclaw Buchzvotch in Jugner Forest [S] to earn a military scrip. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-495', steps = { { title = 'Requirements', note = '• The Boy and the Beast done.' }, { title = 'Walkthrough', note = '• Accept from Rholont (E-7), Southern San d\'Oria [S].\n• Examine the ??? (H-10), Jugner Forest [S], for a cutscene.\n• Examine again to spawn Cobraclaw Buchzvotch; kill it.\n• Examine once more for a cutscene.\n• Report to Rholont.' }, { title = 'Notes', note = '• Wyatt, Southern San d\'Oria [S], swaps the scrip for gil.\n• Perils of the Griffon opens one Vana\'diel day later.' }, { title = 'Reward', note = '• Key item: military scrip' } } },
    { name = 'Perils of the Griffon (WOTG Nation Quests - San d\'Oria 5)', group = 'Crystal War', desc = 'Retrieve an orcish warmachine body in Jugner Forest [S]. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-496', steps = { { title = 'Requirements', note = '• Wrath of the Griffon done.\n• WotG mission Purple, the New Black done.' }, { title = 'Walkthrough', note = '• Speak to Rholont (E-7), Southern San d\'Oria [S].\n• After a Vana\'diel day and a zone, speak to him again.\n• Speak to Daigraffeaux (I-11).\n• Accept from Rholont.\n• Check the ??? (I-6), Jugner Forest [S], for the orcish warmachine body.\n• Deliver it to Rholont.' }, { title = 'Reward', note = '• Elixir\n• Title: Knight of the Swiftwing Griffin' } } },
    { name = 'In a Haze of Glory (WOTG Nation Quests - San d\'Oria 6)', group = 'Crystal War', desc = 'Unseal a shelter in Garlaige Citadel (S) for Diordinne. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-497', steps = { { title = 'Requirements', note = '• Perils of the Griffon done.' }, { title = 'Walkthrough', note = '• Get the number eight shelter key from Diordinne, Garlaige Citadel (S).\n• Examine the Wooden Crates for a cutscene.\n• Examine them again with the key and win the battle.\n• Re-enter Garlaige Citadel (S) for a cutscene.\n• Speak to Rholont (E-7), Southern San d\'Oria (S), at or after 18:00 Vana\'diel time.' }, { title = 'Notes', note = '• Lost key: wait a day, ask Diordinne.' }, { title = 'Reward', note = '• Fullmetal Bullet' } } },
    { name = 'The Price of Valor (WOTG Nation Quests - San d\'Oria 7)', group = 'Crystal War', desc = 'Assemble provisions for Rholont, then fight through Vunkerl Inlet [S] to Pashhow Marshlands [S]. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-498', steps = { { title = 'Requirements', note = '• In a Haze of Glory done.\n• If Rholont refuses, zone and wait a Vana\'diel day.' }, { title = 'Walkthrough', note = '• Speak to Rholont (E-7), Southern San d\'Oria [S].\n• Tree Hollow (E-7): long-life biscuits.\n• Well (E-7): flask of Kingdom water.\n• Log in East Ronfaure [S] until Ronfaure maple syrup drops.\n• Rholont gives the biscuit a la Rholont.\n• Examine the Felled Trees (G-7), Jugner Forest [S], to start.\n• Vunkerl Inlet [S]: first Toppled Cresset, second Toppled Cresset, then Underbrush (F-13).\n• Examine the Underbrush again; kill Madthrasher Zradbodd.\n• Examine the Underbrush once more, then the Shimmering Pondweed (G-6), Pashhow Marshlands [S].' }, { title = 'Notes', note = '• Syrup appears on about half of logging attempts.\n• If the Madthrasher is already spawned, wait until it is killed.' }, { title = 'Reward', note = '• Peiste Skin' } } },
    { name = 'Bonds That Never Die (WOTG Nation Quests - San d\'Oria 8)', group = 'Crystal War', desc = 'Log Jugner ivy, then kill the Young Behemoth in Everbloom Hollow. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-499', steps = { { title = 'Requirements', note = '• The Price of Valor done.' }, { title = 'Walkthrough', note = '• Get the Letter to Count Aurchiat from Rholont (E-7), Southern San d\'Oria [S].\n• Examine the Shimmering Pondweed (G-6), Pashhow Marshlands [S], to accept.\n• Take the Hatchet from Overgrown Mushrooms (F-10), Jugner Forest [S].\n• Log in Jugner Forest [S] until you get a Length of Jugner Ivy.\n• Return to Overgrown Mushrooms for a scene, then examine the Mossy Stump (F-7).\n• Examine the stump again to enter Everbloom Hollow; kill the Young Behemoth.\n• Zone into Jugner Forest [S] for a scene, then speak to Rongelouts N Distaud (I-9), Southern San d\'Oria [S].' }, { title = 'Notes', note = '• A loss means gathering ivy again.\n• Cap: 6 players, 30 minutes.' }, { title = 'Reward', note = '• Behemoth Horn, Hatchet' } } },
    { name = 'Songbirds in a Snowstorm (WOTG Nation Quests - San d\'Oria 9)', group = 'Crystal War', desc = 'In Beaucedine Glacier [S], fish three key items, light a fire and kill an Orcish Bloodletter. Begins with Rholont in Southern San d\'Oria [S]. Source: https://vanadreams.org/wiki/#quest-500', steps = { { title = 'Requirements', note = '• Bonds That Never Die done.\n• WotG mission \'The Will of the World\' done.' }, { title = 'Walkthrough', note = '• Speak to Rholont (E-7), then Daigraffeaux (I-11), Southern San d\'Oria [S].\n• Zone into Beaucedine Glacier [S] for a scene.\n• Examine the Colossal Footprint (I-7).\n• Examine the Rocky Perch (G-10) for a Goliath Worm (the bait).\n• Fish the glacier ponds for the Lance Fish, Paladin Lobster and Scutum Crab key items.\n• Examine the Colossal Footprint again with all three.\n• Trade a Flint Stone to the Charred Firewood (I-7).\n• Examine the Compressed Snow (H-10) twice; kill the Orcish Bloodletter.\n• Examine the Compressed Snow again to finish.' }, { title = 'Notes', note = '• Rholont needs a Vana\'diel day between talks.' }, { title = 'Reward', note = '• Icarus Wing, Goliath Worm' } } },
    { name = 'Snake on the Plains (WOTG Nation Quests - Windurst 0)', group = 'Crystal War', desc = 'Windurst\'s opening Campaign quest: plug three entrances in West Sarutabaruta (S) with putty. Begins with Miah Riyuh in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-501', steps = { { title = 'Requirements', note = '• A green recommendation letter or an existing Campaign allegiance.\n• Not mid-way through San d\'Oria\'s or Bastok\'s first Campaign quest.' }, { title = 'Walkthrough', note = '• Accept from Miah Riyuh, Windurst Waters (S); get Zonpa-Zippa\'s All-Purpose Putty.\n• Examine Sealed Entrances 1, 2 and 3 in West Sarutabaruta (S).\n• Return to Miah Riyuh for the reward.' }, { title = 'Notes', note = '• With no prior allegiance you also get a Bronze Ribbon of Service and join Windurst.\n• Talk to Miah Riyuh again to abandon and restart.' }, { title = 'Reward', note = '• Sprinter\'s Shoes\n• Title: Cobra Unit Mercenary' } } },
    { name = 'Howl from the Heavens (WOTG Nation Quests - Windurst 10)', group = 'Crystal War', desc = 'Collect three magicite shards, then protect Romaa Mihgo at the Windurstian Bulwark. Begins with Velda-Galda in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-502', steps = { { title = 'Requirements', note = '• Sins of the Mothers done.' }, { title = 'Walkthrough', note = '• Accept from Robel-Akbel, Windurst Waters [S].\n• Magicite (E-6), Monastic Cavern: shard of optistone.\n• Magicite (F-9), Qulun Dome: shard of aurastone.\n• Magicite (G-8), Altar Room: shard of orastone.\n• Give all three to Velda-Galda.\n• Enter the battle at the Windurstian Bulwark (J-8), West Sarutabaruta [S]; keep Romaa Mihgo alive through four Yagudo and Gigas waves.\n• Speak to Robel-Akbel to finish.' }, { title = 'Notes', note = '• Shards are removed at completion.' }, { title = 'Reward', note = '• Title: The Moons Companion' } } },
    { name = 'Manifest Destiny (WOTG Nation Quests - Windurst 11)', group = 'Crystal War', desc = 'Free prisoners in Castle Oztroja [S] using Dorter Keys and beat Tzee Xicu the Manifest. Begins with Dhea Prandoleh in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-503', steps = { { title = 'Requirements', note = '• Howl from the Heavens done.\n• Three Dorter Keys.' }, { title = 'Walkthrough', note = '• Accept from Dhea Prandoleh, Windurst Waters [S].\n• Click the Mithran Bivouac (I-8), Meriphataud Mountains [S].\n• Farm Dorter Keys from Yagudo in Meriphataud Mountains [S].\n• Trade one key to each of three different Iron Grilles in Castle Oztroja [S]; you get the poet god\'s key.\n• Click the Collapsing Floor (Map 4, H-7) for a scene, then again to fight.\n• Kill Tzee Xicu the Manifest and its two elementals.' }, { title = 'Reward', note = '• Hi-Reraiser' } } },
    { name = 'At Journey\'s End (WOTG Nation Quests - Windurst 12)', group = 'Crystal War', desc = 'Beat Fenrir in Ghoyu\'s Reverie alongside Lehko Habhoka to close Windurst\'s Campaign story. Begins with Mithran Bivouac in Meriphataud Mountains [S]. Source: https://vanadreams.org/wiki/#quest-504', steps = { { title = 'Requirements', note = '• Manifest Destiny done.' }, { title = 'Walkthrough', note = '• Examine the Mithran Bivouac (I-8), Meriphataud Mountains (S), for the poet god\'s key.\n• Examine the Collapsing Floor (Map 4, H-7), Castle Oztroja (S), for a scene.\n• Examine it again to enter Ghoyu\'s Reverie; kill Fenrir (Karaha-Baruha and Robel-Akbel join as it weakens).\n• Return to the Mithran Bivouac for a scene.\n• Speak to Dhea Prandoleh, Windurst Waters (S).\n• Examine any Sealed Entrance, West Sarutabaruta (S).\n• Report to Dhea Prandoleh.' }, { title = 'Notes', note = '• Lehko Habhoka must live.\n• Lost key: re-examine the Mithran Bivouac.' }, { title = 'Reward', note = '• Title: Star in the Azure Sky' } } },
    { name = 'The Tigress Stirs (WOTG Nation Quests - Windurst 1)', group = 'Crystal War', desc = 'Fetch a small starfruit from West Sarutabaruta (S) for the Acolyte Hostel. Begins with Dhea Prandoleh in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-505', steps = { { title = 'Requirements', note = '• Any one first-tier WotG nation quest done: Steamed Rams, Snake on the Plains or The Fighting Fourth.' }, { title = 'Walkthrough', note = '• Accept from Dhea Prandoleh, Windurst Waters (S).\n• Examine the ??? in West Sarutabaruta (S) for a small starfruit.\n• Examine the lower Acolyte Hostel door, Windurst Waters (S), to finish.' }, { title = 'Reward', note = '• Hi-Elixir' } } },
    { name = 'The Tigress Strikes (WOTG Nation Quests - Windurst 2)', group = 'Crystal War', desc = 'Assist Rotih Moalghett at Fort Karugo-Narugo [S] by killing a War Lynx. Begins with Dhea Prandoleh in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-506', steps = { { title = 'Requirements', note = '• The Tigress Stirs done.' }, { title = 'Walkthrough', note = '• Accept from Dhea Prandoleh, Windurst Waters [S].\n• Enter Fort Karugo-Narugo [S] from West Sarutabaruta [S] (I-4); speak to Rotih Moalghett (Map 2, I-8).\n• Check the ??? for a cutscene.\n• Check again to spawn a War Lynx; kill it.\n• Check once more for a cutscene.\n• Report to Dhea Prandoleh.' }, { title = 'Notes', note = '• Zone after finishing before the next quest proceeds.' }, { title = 'Reward', note = '• Star Globe\n• Title: Ajido Marujidos Minder' } } },
    { name = 'Knot Quite There (WOTG Nation Quests - Windurst 3)', group = 'Crystal War', desc = 'Bring a 108-Knot Quipu to the Bulwark Gate in Sauromugue Champaign (S). Begins with Bulwark Gate in Rolanberry Fields [S]. Source: https://vanadreams.org/wiki/#quest-507', steps = { { title = 'Requirements', note = '• The Tigress Strikes done.\n• WotG mission Back to the Beginning done.' }, { title = 'Walkthrough', note = '• Examine the downstairs Acolyte Hostel door, Windurst Waters (S), to start.\n• Examine the Bulwark Gate (E-6), Sauromugue Champaign (S).\n• Acquire a 108-Knot Quipu and trade it to the Bulwark Gate.\n• Zone East Ronfaure (S) to Southern San d\'Oria (S) for a cutscene.\n• Examine the marked door in Southern San d\'Oria (S) to finish.' }, { title = 'Notes', note = '• After starting, the hostel door only repeats a reminder.' }, { title = 'Reward', note = '• Plt. Beastcoin' } } },
    { name = 'A Manifest Problem (WOTG Nation Quests - Windurst 4)', group = 'Crystal War', desc = 'Help Rotih Moalghett push the Yagudo out of Fort Karugo-Narugo (S). Begins with Rotih Moalghett in Fort Karugo-Narugo [S]. Source: https://vanadreams.org/wiki/#quest-508', steps = { { title = 'Requirements', note = '• Knot Quite There done.' }, { title = 'Walkthrough', note = '• Speak to Rotih Moalghett (Map 2, I-8), Fort Karugo-Narugo (S).\n• Zone into Castle Oztroja (S) for a cutscene.\n• Return to Rotih Moalghett for the fort key.\n• Use it on the Colorful Door (Map 2, H-5) and win the battle.\n• Report to Dhea Prandoleh, Windurst Waters (S).' }, { title = 'Notes', note = '• Lost key: ask Rotih Moalghett again.\n• Key is removed at completion.' }, { title = 'Reward', note = '• Title: Friend of Lehko Habhoka' } } },
    { name = 'When One Man Is Not Enough (WOTG Nation Quests - Windurst 5)', group = 'Crystal War', desc = 'Trade fish to a Sealed Entrance in West Sarutabaruta (S) to recruit help. Begins with Dhea Prandoleh in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-509', steps = { { title = 'Requirements', note = '• A Manifest Problem done.\n• WotG mission Purple, the New Black done.' }, { title = 'Walkthrough', note = '• Speak to Dhea Prandoleh, Windurst Waters (S).\n• Get either a Blackened Muddy Siredon, or a Pipira plus a Greedie.\n• Trade it to any of the three Sealed Entrances, West Sarutabaruta (S).\n• Report to Dhea Prandoleh.' }, { title = 'Reward', note = '• Pipira, Greedie' } } },
    { name = 'A Feast for Gnats (WOTG Nation Quests - Windurst 6)', group = 'Crystal War', desc = 'Destroy a Confederate belfry beneath Sauromugue Champaign [S] with the Cobra Unit. Begins with Dhea Prandoleh in Windurst Waters [S]. Source: https://vanadreams.org/wiki/#quest-510', steps = { { title = 'Requirements', note = '• When One Man Is Not Enough done.\n• WotG mission In the Name of the Father reached.' }, { title = 'Walkthrough', note = '• Accept from Dhea Prandoleh, Windurst Waters [S].\n• Speak to Mham Lahrih (K-9), Sauromugue Champaign [S].\n• Examine the Abandoned Mineshaft (K-9) for the signal firecracker.\n• Examine it again to enter and destroy the Confederate belfry.\n• Report to Dhea Prandoleh.' }, { title = 'Notes', note = '• Lost firecracker: re-examine the mineshaft.\n• The battle can be retried until won.' }, { title = 'Reward', note = '• Ruby\n• Title: Jewel of the Cobra Unit' } } },
    { name = 'The Long March North (WOTG Nation Quests - Windurst 7)', group = 'Crystal War', desc = 'Windurst WotG quest: craft Beastbane bullets, then beat Count Furfur\'s party in Fort Karugo-Narugo [S]. Source: https://vanadreams.org/wiki/#quest-511', steps = { { title = 'Requirement', note = '• A Feast for Gnats done.' }, { title = 'Walkthrough', note = '• Accept from Robel-Akbel, Windurst Waters [S].\n• Southern San d\'Oria [S]: speak to Raustigne (I-7), then Hauberliond (H-9).\n• Check a New-turned Earth (East Ronfaure [S], Jugner Forest [S] or La Vaule [S]) for the darkfire cinder.\n• Speak to Striking Snake (H-8), Metalworks.\n• North Gustaberg [S] Mining Point: get liquid quicksilver and gelid sulfur.\n• Give all three to Striking Snake; after one game day collect the Beastbane bullets.\n• Enter Fort Karugo-Narugo [S] via West Sarutabaruta [S] (I-4); speak to Rotih Moalghett (Map 2, I-8).\n• Warding Door (Map 2, E-7): kill Count Furfur (E-8), 2 Count Murmurs, 2 Tartalos.\n• Check the Warding Door again to finish.' }, { title = 'Notes', note = '• Abandoned fights can be restarted at the door.\n• Bullets are removed on completion.' } } },
    { name = 'The Forbidden Path (WOTG Nation Quests - Windurst 8)', group = 'Crystal War', desc = 'Windurst Crystal War quest: collect three strands for Velda-Galda for a job-based stat potion. Source: https://vanadreams.org/wiki/#quest-512', steps = { { title = 'Requirements', note = '• The Long March North done.\n• Bottled Pixie; any job Testimony.' }, { title = 'Walkthrough', note = '• Accept from Lehko Habhoka, Windurst Waters [S].\n• Inner Horutoto Ruins: enter via Lily Tower (East Sarutabaruta J-7), go west via Beetle\'s Burrow (Map 2) and Rose Tower (Map 3), through the Magic Gate (H-9).\n• Rose Tower 2F (Map 4) Gate of Darkness (I-7): Irradiant Strand.\n• Grauberg [S] Fey Blossoms (F-5): view, then trade Bottled Pixie 18:00–06:00 for the Scintillant Strand.\n• Castle Oztroja [S] Writhing Flame: view, then trade a Testimony for the Refulgent Strand.\n• Hand strands to Velda-Galda (Windurst Waters [S]); after one game day talk again for the reward.' }, { title = 'Notes', note = '• Strands: any order, can be turned in singly.\n• Potion type follows main job at pickup.' }, { title = 'Reward', note = '• Title: Karaha Baruhas Research Assistant' } } },
    { name = 'Sins of the Mothers (WOTG Nation Quests - Windurst 9)', group = 'Crystal War', desc = 'Windurst Crystal War quest: rescue Nhev Befrathi and Syu near Fort Karugo-Narugo [S] for a Kitty Rod. Source: https://vanadreams.org/wiki/#quest-513', steps = { { title = 'Requirement', note = '• The Forbidden Path done.' }, { title = 'Walkthrough', note = '• Windurst Waters [S]: Lehko Habhoka, then Dhea Prandoleh, then Velda-Galda.\n• Enter Fort Karugo-Narugo [S] from Meriphataud Mountains [S] (C-7); check the Stone Monument (Map 1, E-7).\n• Succulent Cactus (Map 1, F-5): get a succulent dragon fruit; bring it to the Monument.\n• Sunken Hollow (Map 1, G-7): enter the escort fight in Ghoyu\'s Reverie.\n• Report to Dhea Prandoleh.' }, { title = 'Notes', note = '• No fruit left: retry the next game day.' }, { title = 'Reward', note = '• Kitty Rod' } } },
    { name = 'Chocobo Whistle', group = 'Hidden', desc = 'Chocobo-raising side quest: find a handkerchief while walking your bird and trade it to Hantileon for a Chocobo Whistle. Source: https://vanadreams.org/wiki/#quest-514', steps = { { title = 'Requirement', note = '• A chocobo being raised.' }, { title = 'Walkthrough', note = '• Hear Hantileon\'s request (I-11, Southern San d\'Oria).\n• Walk your chocobo until a handkerchief turns up.\n• Return to Hantileon and pick the whistle.' }, { title = 'Notes', note = '• Handkerchief lies on one of 3 routes; may take several walks.\n• Have inventory space.' } } },
    { name = 'Crafted Corsair Artifact (COR AF)', group = 'Hidden', desc = 'Leleroon in Nashmau arranges Corsair AF pieces from three craftsmen, one order at a time. Source: https://vanadreams.org/wiki/#quest-515', steps = { { title = 'Requirement', note = '• Against All Odds started or done.' }, { title = 'Walkthrough', note = '• Pick a piece with Leleroon (G-7, Nashmau); take his letter.\n• Gants: door in Windurst Waters. Bottes: door in Bastok Mines. Frac: Raqtibahl (G-8), Port San d\'Oria.\n• Trade the 4 materials, then the fee: 4 Imperial Mythril Pieces (Gants/Bottes) or 1 Imperial Gold Piece (Frac).\n• Wait one game day, zone, and collect.' }, { title = 'Materials', note = '• Gants: Gold Thread, Karakul Leather, Red Grass Cloth, Wamoura Silk.\n• Bottes: Mythril Sheet, Karakul Leather, Lm. Buffalo Leather, Wolf Felt.\n• Frac: Gold Chain, Velvet Cloth, Red Grass Cloth, Sailcloth.\n• Each piece once, one at a time.' }, { title = 'Reward', note = '• Corsair\'s Frac, Corsair\'s Gants, Corsair\'s Bottes' } } },
    { name = 'Crafted Dancer Artifact', group = 'Hidden', desc = 'Matthias in Bastok Markets makes Dancer AF pieces from delivered materials. Source: https://vanadreams.org/wiki/#quest-516', steps = { { title = 'Requirements', note = '• The Road to Divadom done.\n• Main job DNC.' }, { title = 'Walkthrough', note = '• Speak to Olgald (G-7), Upper Jeuno.\n• Pick tiara, bangles or toe shoes with Matthias (J-9), Bastok Markets.\n• Trade materials; return after one game day.' }, { title = 'Materials', note = '• Tiara: Imp. Silk Cloth, Wolf Felt, Silver Brocade.\n• Bangles: Karakul Cloth, Rainbow Cloth, Rainbow Velvet.\n• Toe Shoes: Wamoura Cloth, Moblinweave, Gold Brocade.\n• Repeat per piece; gender-matched; Matthias tracks what\'s left.' }, { title = 'Reward', note = '• Dancer\'s Bangles, Dancer\'s Toe Shoes, Dancer\'s Tiara' } } },
    { name = 'Crafted Magus Artifact (BLU AF)', group = 'Hidden', desc = 'Lathuya in Aht Urhgan Whitegate makes the three Blue Mage AF pieces from your materials and a fee. Source: https://vanadreams.org/wiki/#quest-517', steps = { { title = 'Requirement', note = '• Transformations accepted or done.' }, { title = 'Walkthrough', note = '• Choose a piece with Lathuya (F-8).\n• Trade materials, then Imp. Mtl. Piece fee (2 Bazubands/Shalwar, 4 Jubbah) for the magus order slip.\n• Wait a game day, zone, collect.\n• Wait a day before ordering the next piece.' }, { title = 'Materials', note = '• Bazubands: Platinum Sheet, Velvet Cloth, Karakul Leather, Venom Potion.\n• Shalwar: Gold Chain, Velvet Cloth, Flan Meat, Imp. Silk Cloth.\n• Jubbah: Velvet Cloth, Chimera Blood, Karakul Cloth, Imp. Silk Cloth.' }, { title = 'Reward', note = '• Magus Jubbah, Magus Bazubands, Magus Shalwar' } } },
    { name = 'Crafted Puppetry Artifact (PUP AF)', group = 'Hidden', desc = 'Dhima Polevhia in Aht Urhgan Whitegate makes Puppetmaster AF from delivered materials. Source: https://vanadreams.org/wiki/#quest-518', steps = { { title = 'Requirement', note = '• Puppetmaster Blues started.' }, { title = 'Walkthrough', note = '• Order Pup. Tobe, Dastanas or Babouches from Dhima Polevhia (J-8).\n• Trade materials; collect after the next game day.\n• Next order allowed right after pickup; nothing more after all three.' }, { title = 'Materials', note = '• Tobe: Ruby, Moblinweave, Scarlet Linen, Wamoura Cloth, Imp. Gold Piece.\n• Dastanas: Platinum Sheet, Rainbow Thread, Marid Leather, Wamoura Cloth, Imp. Mtl. Piece.\n• Babouches: Platinum Sheet, Ruby, Marid Leather, Wamoura Cloth, 2 Imp. Mtl. Pieces.' } } },
    { name = 'Crimson Orb', group = 'Hidden', desc = 'Davoi side quest: take a white orb to four ponds to turn it into a crimson orb for Sedal-Godjal. Source: https://vanadreams.org/wiki/#quest-519', steps = { { title = 'Requirement', note = '• Davoi access.' }, { title = 'Walkthrough', note = '• Enter Davoi from Jugner Forest (G-12); examine the Wall of Banishing (J-9).\n• Accept from Sedal-Godjal (J-8); get a white orb.\n• Examine Groaning, Howling, Wailing and Screaming Pond (E-8) once each.\n• Now cursed, give the orb to Sedal-Godjal for the crimson orb.' }, { title = 'Notes', note = '• Any pond order; each counts once per orb.' }, { title = 'Reward', note = '• Key item: crimson orb' } } },
    { name = 'Lure of the Wildcat Invitation Cards', group = 'Hidden', desc = 'Trade red, blue, green and white invitation cards to Naja Salaheem for Imperial coins. Source: https://vanadreams.org/wiki/#quest-522', steps = { { title = 'Walkthrough', note = '• Get any of the red, blue, green, white invitation cards.\n• Turn them in to Naja Salaheem (I-10), Aht Urhgan Whitegate; return with the rest later.' }, { title = 'Payout', note = '• All 4 at once: Imp. Mythril Piece.\n• 1–3 cards: that many Imp. Bronze Pieces.\n• Earlier turn-ins count toward the four.' }, { title = 'Reward', note = '• Imp. Brz. Piece, Imp. Mtl. Piece' } } },
    { name = 'Lost Chick', group = 'Hidden', desc = 'Chocobo-raising event: your chick finds a lost chick and you identify its owner in that nation\'s city. Source: https://vanadreams.org/wiki/#quest-523', steps = { { title = 'Requirement', note = '• Raising enabled, active chick walked in San d\'Oria, Bastok or Windurst.' }, { title = 'Walkthrough', note = '• Walk until a lost chick appears.\n• Gather owner clues from trainers on later walks.\n• Question residents (Southern San d\'Oria, Bastok Mines or Windurst Woods); pick the owner for Story of a Diligent Chocobo.\n• Report to Hantileon (I-11, S. San d\'Oria), Zopago (J-9, Bastok Mines) or Pulonono (K-12, Windurst Woods).' }, { title = 'Notes', note = '• Any guess ends it; only the right one gives the story.\n• Candidates: Coderiant, Cahaurme, Victoire, Corua (S. San d\'Oria); Drangord, Deegis, Gray Wolf, Gerbaum (Bastok Mines); Kapeh Myohrye, Kororo, Gioh Ajihri (Windurst Woods).' } } },
    { name = 'Mimeo Stone', group = 'Hidden', desc = 'Attohwa Chasm task: run a fading Mimeo Stone to the Cradle of Rebirth for a feather. Source: https://vanadreams.org/wiki/#quest-524', steps = { { title = 'Walkthrough', note = '• Check a Luminant for the Mimeo Stone.\n• Hurry to the Cradle of Rebirth (J-9) and check it.' }, { title = 'Notes', note = '• Lost if fully faded or you zone.\n• Brightness sets the feather: Regain, Rebirth, Revive, Blaze or Fire.\n• Repeatable.' }, { title = 'Reward', note = '• Fire, Blaze, Revive, Rebirth or Regain Feather' } } },
    { name = 'Moghouse Exposition', group = 'Hidden', desc = 'Moogle cutscenes introducing Mog Houses at home and abroad. Source: https://vanadreams.org/wiki/#quest-525', steps = { { title = 'Walkthrough', note = '• Enter your home-nation Mog House the first time for a scene.\n• Talk to the Moogle in another nation\'s Mog House for the second scene.\n• Completes once each scene is viewed.' } } },
    { name = 'Monstrosity: Suibhne Bee Guessing Game', group = 'Hidden', desc = 'Solve Suibhne\'s puzzle in the Feretory to unlock the Bee in Monstrosity. Source: https://vanadreams.org/wiki/#quest-526', steps = { { title = 'Requirements', note = '• Monstrosity on; Bee not yet unlocked.' }, { title = 'Walkthrough', note = '• In the Feretory, accept Suibhne\'s game.\n• Set the right mix of Aengus, Maccus, Suibhne and Terynon across the 3 positions.' }, { title = 'Notes', note = '• Wrong answer: retry next game day.\n• The puzzle doesn\'t change until solved.' } } },
    { name = 'New Character Cutscenes', group = 'Hidden', desc = 'Intro scene for a new character\'s first entry into a starting city; awards an Adventurer Coupon. Source: https://vanadreams.org/wiki/#quest-527', steps = { { title = 'Walkthrough', note = '• Zone a new character into the nation start area.\n• Watch the scene and map-marker tutorial; take the coupon.' }, { title = 'Notes', note = '• Full inventory forfeits the coupon.' }, { title = 'Reward', note = '• Adventurer Cpn.' } } },
    { name = 'Portal Charm', group = 'Hidden', desc = 'Give Kupipi a Rolanberry for the Portal Charm. Source: https://vanadreams.org/wiki/#quest-528', steps = { { title = 'Requirement', note = '• Windurst citizen, rank 3+.' }, { title = 'Walkthrough', note = '• Trade a Rolanberry to Kupipi (Map 2, H-6), Heaven\'s Tower.\n• With Written in the Stars done, the charm comes at once; otherwise finish that mission and talk to her again.' }, { title = 'Notes', note = '• One charm only.' }, { title = 'Reward', note = '• Key item: portal charm' } } },
    { name = 'Trust: Abquhbah', group = 'Hidden', desc = 'Abquhbah in Aht Urhgan Whitegate hands over his Trust cipher. Source: https://vanadreams.org/wiki/#quest-532', steps = { { title = 'Requirements', note = '• A nation Trust permit; Immortal Sentries done.\n• RoV mission Ever Forward or later.\n• Trust/cipher not already owned.' }, { title = 'Walkthrough', note = '• Talk to Abquhbah (I-10), view the scene, take Cipher: Abquhbah (free a slot).' }, { title = 'Reward', note = '• Cipher: Abquhbah' } } },
    { name = 'Trust: Cherukiki', group = 'Hidden', desc = 'Taillegeas in Ru\'Lude Gardens grants the Cherukiki Trust. Source: https://vanadreams.org/wiki/#quest-533', steps = { { title = 'Requirements', note = '• Trust permit.\n• CoP past Chains and Bonds (or deep into Dawn).' }, { title = 'Walkthrough', note = '• Talk to Taillegeas (I-7) and accept to learn it.' } } },
    { name = 'Trust: Halver', group = 'Hidden', desc = 'Halver in Chateau d\'Oraguille gives Cipher: Halver. Source: https://vanadreams.org/wiki/#quest-537', steps = { { title = 'Requirements', note = '• Trust permit; RoV The Path Untraveled done.\n• Trust/cipher not owned.' }, { title = 'Walkthrough', note = '• Talk to Halver (I-9); use the cipher from the Trust menu.' }, { title = 'Reward', note = '• Cipher: Halver' } } },
    { name = 'Trust: Ingrid', group = 'Hidden', desc = 'Rigobertine in Eastern Adoulin grants Ingrid\'s Trust. Source: https://vanadreams.org/wiki/#quest-538', steps = { { title = 'Requirements', note = '• Nation Trust permit; SoA The Merciless One done; Ingrid not known.' }, { title = 'Walkthrough', note = '• Talk to Rigobertine (J-7) and accept.' } } },
    { name = 'Trust: Maat', group = 'Hidden', desc = 'Maat grants his Trust once you\'ve beaten him on enough jobs. Source: https://vanadreams.org/wiki/#quest-542', steps = { { title = 'Requirements', note = '• Trust permit; Maat not known.\n• Maat defeated in Maat\'s Cap with 6+ jobs.' }, { title = 'Walkthrough', note = '• Talk to Maat (H-5), Ru\'Lude Gardens, and accept.' }, { title = 'Notes', note = '• Under 6 jobs: no offer.' } } },
    { name = 'Trust: Nashmeira', group = 'Hidden', desc = 'The Imperial Whitegate in Aht Urhgan Whitegate grants Nashmeira\'s Trust. Source: https://vanadreams.org/wiki/#quest-543', steps = { { title = 'Requirements', note = '• Trust permit; ToAU The Empress Crowned done; Nashmeira not known.' }, { title = 'Walkthrough', note = '• Talk to the Imperial Whitegate (L-9) and pick the learn option.' } } },
    { name = 'Trust: Prishe', group = 'Hidden', desc = 'The Walnut Door in Tavnazian Safehold grants Prishe\'s Trust. Source: https://vanadreams.org/wiki/#quest-544', steps = { { title = 'Requirements', note = '• Trust permit; CoP Dawn done; Prishe not known.' }, { title = 'Walkthrough', note = '• Examine the Walnut Door, watch the scene, pick the learn option.' }, { title = 'Notes', note = '• Dialogue references In the Mood for Love, A Chocobo\'s Tale, Hook, Line and Sinker, Apocalypse Nigh if done.' } } },
    { name = 'Trust: Semih', group = 'Hidden', desc = 'Kupipi in Heaven\'s Tower gives Cipher: Semih. Source: https://vanadreams.org/wiki/#quest-546', steps = { { title = 'Requirements', note = '• Trust permit; RoV The Path Untraveled done.' }, { title = 'Walkthrough', note = '• Talk to Kupipi (Map 2, H-6); use the cipher.' }, { title = 'Reward', note = '• Cipher: Semih' } } },
    { name = 'Trust: Shantotto', group = 'Hidden', desc = 'Shantotto in Windurst Walls teaches her Trust once you own nine specific Trusts. Source: https://vanadreams.org/wiki/#quest-547', steps = { { title = 'Requirements', note = '• Windurst Trust permit; Curses, Foiled A-Golem? done.\n• Trusts: Kupipi, Nanaa Mihgo, Ajido-Marujido, Excenmille, Curilla, Trion, Ayame, Naji, Volker.' }, { title = 'Walkthrough', note = '• Talk to Shantotto (K-7), watch the scene, accept.' }, { title = 'Notes', note = '• Missing requirements: she just repeats lines.' } } },
    { name = 'Trust: Shikaree Z', group = 'Hidden', desc = 'Perih Vashai in Windurst Woods grants the Shikaree Z Trust. Source: https://vanadreams.org/wiki/#quest-548', steps = { { title = 'Requirements', note = '• Trust permit plus Windurst Trust permit KI; CoP Three Paths done.\n• Not between Flames in the Darkness and Fire in the Eyes of Men, nor on A Fate Decided.' }, { title = 'Walkthrough', note = '• Talk to Perih Vashai (K-7) and watch the scene.' } } },
    { name = 'Trust: Ulmia', group = 'Hidden', desc = 'Ulmia\'s Trust is learned at the Dilapidated Gate, Misareaux Coast. Source: https://vanadreams.org/wiki/#quest-549', steps = { { title = 'Requirements', note = '• Trust permit; past Dawn\'s main fight (CoP); Ulmia not known.' }, { title = 'Walkthrough', note = '• Examine the Dilapidated Gate; accept her aid in the scene.' }, { title = 'Notes', note = '• Apocalypse Nigh completion alters the dialogue.' } } },
    { name = 'Trust: Zeid II', group = 'Hidden', desc = 'The Oaken Door in Norg gives Cipher: Zeid II after the RoV story. Source: https://vanadreams.org/wiki/#quest-550', steps = { { title = 'Requirements', note = '• RoV Volto Oscuro done; Zeid II not learned.' }, { title = 'Walkthrough', note = '• In Norg, examine the Oaken Door (K-8); free a slot first.' }, { title = 'Reward', note = '• Cipher: Zeid II' } } },
    { name = 'Tutorial Mini-Quest', group = 'Hidden', desc = 'New-player tutorial chain from Gulldago, Alaune or Selele with small rewards per stage. Source: https://vanadreams.org/wiki/#quest-551', steps = { { title = 'NPCs', note = '• Gulldago (D-11) Bastok Markets; Alaune (G-10) Southern San d\'Oria; Selele (K-10) Windurst Woods.' }, { title = 'Walkthrough', note = '• Talk to your NPC twice.\n• Get Signet from a conquest guard: 6 Meat Jerky.\n• Eat food, then report.\n• Learn a weapon skill: 100 gil.\n• Activate Records of Eminence for a memorandoll: starter items + crystal.\n• Use an Auction House counter: Conquest promotion voucher.\n• Reach level 5: Raising Earring.\n• Get nation Trust permit: Warp Ring.\n• Check two Survival Guides: 12 Saltena.\n• Reach level 18: Copper Voucher.\n• Set a subjob: 12 Chocopass + Echad Ring.' }, { title = 'Notes', note = '• Survival Guides: Bastok Mines + North Gustaberg; Northern San d\'Oria + West Ronfaure; Port Windurst + West Sarutabaruta.\n• Memorandoll items vary by nation.' }, { title = 'Reward', note = '• 14 possible items incl. Lizard Tail, Rock Salt, Chocopass, Fire/Water Crystal, Hare Meat, Honey, Meat Jerky, Bird Egg, Saltena, Copper Voucher, Raising Earring' } } },
    { name = 'A Candlelight Vigil', group = 'Jeuno', desc = 'Deliver the holy candle from Candle Making to Ilumida, Upper Jeuno. Source: https://vanadreams.org/wiki/#quest-554', steps = { { title = 'Requirements', note = '• Jeuno fame 4; holy candle (Candle Making).' }, { title = 'Walkthrough', note = '• Accept from Ilumida (G-8); re-talk if declined.\n• Finish Candle Making, then give her the candle.' }, { title = 'Notes', note = '• Zone before Searching for the Right Words unlocks.' }, { title = 'Reward', note = '• Flower Necklace\n• Title: Activist for Kindness' } } },
    { name = 'A Chocobo\'s Tale', group = 'Jeuno', desc = 'Help Nevela\'s chocobo: warding oil plus a Badshah fight in Batallia Downs. Source: https://vanadreams.org/wiki/#quest-555', steps = { { title = 'Requirement', note = '• CoP A Vessel Without a Captain done.' }, { title = 'Walkthrough', note = '• Nevela (G-8, Upper Jeuno), then Wobke (I-9, Bastok Mines).\n• Pashhow Marshlands Outpost Gate (K-6): view scene, trade 3 Warding Oil.\n• Back to Wobke.\n• Batallia Downs ??? (H-6): defeat the Badshah, check again for Silver Comet\'s collar.\n• Give the collar to Nevela.' }, { title = 'Reward', note = '• 5,200 gil\n• Title: Chocobo Love Guru' } } },
    { name = 'A Clock Most Delicate', group = 'Jeuno', desc = 'Bring Clock Tower Oil to the clockkeeper\'s Door: House in Upper Jeuno. Source: https://vanadreams.org/wiki/#quest-556', steps = { { title = 'Requirements', note = '• Jeuno fame 2; Clock Tower Oil (from Deal with Tenshodo).' }, { title = 'Walkthrough', note = '• Cutscene with Collet (G-7).\n• Accept at the Door: House.\n• Get the oil, return to the Door: House (F-7).' }, { title = 'Notes', note = '• Also raises San d\'Oria, Bastok, Windurst fame.' }, { title = 'Reward', note = '• 1,200 gil\n• Engineer\'s Gloves\n• Title: Professional Loafer' } } },
    { name = 'A Minstrel in Despair', group = 'Jeuno', desc = 'Copy the Song Runes\' tune onto parchment for Mertaire in Lower Jeuno. Source: https://vanadreams.org/wiki/#quest-557', steps = { { title = 'Requirements', note = '• The Old Monument done; 1 Parchment.' }, { title = 'Walkthrough', note = '• Trade Parchment to the Song Runes (F-9), Buburimu Peninsula: Poetic Parchment.\n• Trade it to Mertaire (I-8).' }, { title = 'Notes', note = '• Raises fame in all three nations.' }, { title = 'Reward', note = '• 2,100 gil\n• Poetic Parchment' } } },
    { name = 'A Reputation in Ruins', group = 'Jeuno', desc = 'Get two bracelets in Pso\'Xja and view the Avatar Gate for Migliorozz. Source: https://vanadreams.org/wiki/#quest-558', steps = { { title = 'Requirement', note = '• CoP The Road Forks done.' }, { title = 'Walkthrough', note = '• Accept from Migliorozz (H-9, Upper Jeuno); receive Phoenix Armlet or Phoenix Pearl.\n• Enter Pso\'Xja from Beaucedine Glacier (G-9); in the tower nearest Ranguemont Pass, 2F ???: kill Gargoyle-Iota (Map 4, I-8) and Gargoyle-Kappa, recheck for the Blue Bracelet.\n• Past the blue door, basement ???: kill Gargoyle-Lambda and Gargoyle-Mu, recheck for the Green Bracelet.\n• Behind the green door, examine the Avatar Gate.\n• Report to Migliorozz.' }, { title = 'Notes', note = '• Bracelets are kept.' }, { title = 'Reward', note = '• 3,500 gil' } } },
    { name = 'All in the Cards', group = 'Jeuno', desc = 'Gather four specific Tarut cards for Chululu, Lower Jeuno. Source: https://vanadreams.org/wiki/#quest-559', steps = { { title = 'Requirement', note = '• Collect Tarut Cards done.' }, { title = 'Walkthrough', note = '• Accept from Chululu (I-8); get 5 of a random Tarut card.\n• Collect Tarut: The Fool, Death, The Hermit, The King.\n• Trade all four to Chululu.' }, { title = 'Notes', note = '• New batch of 5 per Earth day.\n• Repeatable once re-offered next Japanese day.\n• Raises all three nations\' fame.' }, { title = 'Reward', note = '• 600 gil\n• Tarut:The Fool, Tarut:Death, Tarut:The King, Tarut:The Hermit\n• Title: Card Collector' } } },
    { name = 'Apocalypse Nigh', group = 'Jeuno', desc = 'Post-Shadows of the Departed quest: battle at Empyreal Paradox, then pick an earring from Gilgamesh in Norg. Source: https://vanadreams.org/wiki/#quest-560', steps = { { title = 'Requirements', note = '• Shadows of the Departed done; nation rank 5+.' }, { title = 'Walkthrough', note = '• Enter the marked spot in Ru\'Lude Gardens for the opening scene.\n• Zone into Sealion\'s Den for a scene.\n• Enter Grand Palace of Hu\'Xzoi from Al\'Taieu (H-11); examine the door.\n• Empyreal Paradox entrance: scene, then win Apocalypse Nigh.\n• Re-zone into Empyreal Paradox for a scene.\n• Talk to Aldo (J-8), Lower Jeuno.\n• Norg Oaken Door scene; zone and wait a game day.\n• Choose from Gilgamesh (L-8): Static, Magnetic, Hollow or Ethereal Earring.' }, { title = 'Notes', note = '• One game day between battle and Aldo/Gilgamesh.\n• You may defer the earring choice.\n• Afterwards, with no earring owned, the Empyreal Paradox ??? can reset CoP/Zilart to Dawn/Awakening.' }, { title = 'Reward', note = '• Static, Magnetic, Hollow or Ethereal Earring' } } },
    { name = 'Axe the Competition', group = 'Jeuno', desc = 'Unlocks axe WS Decimation: train the Pick of Trials, then defeat Yallery Brown in Temple of Uggalepih. Source: https://vanadreams.org/wiki/#quest-561', steps = { { title = 'Requirements', note = '• Axe skill 240+; can equip Pick of Trials.' }, { title = 'Walkthrough', note = '• Accept from Brutus (G-7, Upper Jeuno); get Pick of Trials + training guide.\n• Earn 300+ WS points with the Pick.\n• Trade it to Brutus for the map to the Annals of Truth.\n• Temple of Uggalepih ??? (Map 2, G-9): kill Yallery Brown, recheck for Annals of Truth.\n• Return to Brutus for Decimation.' }, { title = 'Notes', note = '• Lost Pick: Brutus replaces it; he also lets you abandon.' }, { title = 'Reward', note = '• Pick of Trials' } } },
    { name = 'Borghertz\'s Calling Hands', group = 'Jeuno', desc = 'SMN AF hands: old gauntlets plus Shadow Flames for the Evoker\'s Bracers. Source: https://vanadreams.org/wiki/#quest-564', steps = { { title = 'Requirements', note = '• SMN 50+; Class Reunion done; no other Borghertz quest active.' }, { title = 'Walkthrough', note = '• Talk to Guslam (H-8, Upper Jeuno) twice.\n• First Borghertz quest only: Deadly Minnow (H-9, Upper Jeuno), then pay Yin Pocanakhu (J-8, Lower Jeuno) 1,000 gil.\n• Sea Serpent Grotto Treasure Coffer: old gauntlets.\n• Port Jeuno ??? Borghertz: agree to get Shadow Flames.\n• Castle Zvahl Baileys via Xarcabard (D-7): Torch (Map 1, F-8), kill Dark Spark, recheck for the Flames.\n• Return to the ??? Borghertz.' }, { title = 'Notes', note = '• Temple of Uggalepih and Toraimarai Canal coffers may hold other AF.' } } },
    { name = 'Borghertz\'s Chasing Hands', group = 'Jeuno', desc = 'RNG AF hands: old gauntlets plus shadow flames for Hunter\'s Bracers. Source: https://vanadreams.org/wiki/#quest-565', steps = { { title = 'Requirements', note = '• RNG main 50+; Fire and Brimstone accepted or done; no other Borghertz quest active.' }, { title = 'Walkthrough', note = '• Accept from Guslam (H-8, Upper Jeuno).\n• Garlaige Citadel Treasure Coffer: old gauntlets; show them to Guslam.\n• First Borghertz quest only: Deadly Minnow (H-9), then 1,000 gil to Yin Pocanakhu (J-8, Lower Jeuno).\n• Port Jeuno ??? Borghertz: agree to find shadow flames.\n• Castle Zvahl Baileys via Xarcabard (D-7): Torch (Map 1, F-8), kill Dark Spark, recheck.\n• Return to Borghertz for Hunter\'s Bracers.' }, { title = 'Notes', note = '• Crawlers\' Nest and Monastic Cavern coffers may hold Hunter\'s Braccae / Jerkin.\n• One Borghertz quest at a time; repeats skip Deadly Minnow and Yin Pocanakhu.' } } },
    { name = 'Borghertz\'s Dragon Hands', group = 'Jeuno', desc = 'DRG artifact hands quest: bring old gauntlets and Shadow Flames to earn the Drachen Fng. Gnt. Source: https://vanadreams.org/wiki/#quest-566', steps = { { title = 'Requirements', note = '• DRG main job, level 50+.\n• Chasing Quotas (San d\'Oria) started or finished.\n• No other Borghertz Hands quest active.' }, { title = 'Walkthrough', note = '• Accept the quest from Guslam (H-8) in Upper Jeuno.\n• Get the old gauntlets from the Treasure Coffer in The Boyahda Tree.\n• First Borghertz quest only: speak to Deadly Minnow (H-9) in Upper Jeuno, then give Yin Pocanakhu (J-8) in Lower Jeuno 1,000 gil.\n• Check the ??? in Port Jeuno and agree to find the Shadow Flames.\n• Go to Castle Zvahl Baileys through Xarcabard (D-7), examine the Torch (Map 1, F-8) and kill the Dark Spark it summons.\n• Examine the Torch again for the shadow flames.\n• Hand the old gauntlets and shadow flames to the Port Jeuno ???.' }, { title = 'Notes', note = '• Ifrit\'s Cauldron and Quicksand Caves coffers can hold other Drachen artifact pieces.\n• Later Borghertz quests let you skip the intermediaries.' } } },
    { name = 'Borghertz\'s Harmonious Hands', group = 'Jeuno', desc = 'BRD AF hands: old gauntlets plus shadow flames for Choral Cuffs. Source: https://vanadreams.org/wiki/#quest-567', steps = { { title = 'Requirements', note = '• BRD main 50+; The Requiem done; no other Borghertz quest active.' }, { title = 'Walkthrough', note = '• Accept from Guslam (H-8, Upper Jeuno).\n• Castle Zvahl Baileys Treasure Coffer (key or lockpick): old gauntlets; speak to Guslam again.\n• First Borghertz quest only: Deadly Minnow (H-9), then 1,000 gil to Yin Pocanakhu (J-8, Lower Jeuno).\n• Meet Borghertz at the Port Jeuno ???.\n• Castle Zvahl Baileys via Xarcabard (D-7): Torch (Map 1, F-8), kill Dark Spark, recheck.\n• Bring the flames to the Port Jeuno ???.' }, { title = 'Notes', note = '• Castle Oztroja and Crawlers\' Nest coffers may hold Choral Cannions / Roundlet.\n• One Borghertz quest at a time; repeats skip Deadly Minnow and Yin Pocanakhu.' } } },
    { name = 'Borghertz\'s Healing Hands', group = 'Jeuno', desc = 'WHM AF hands: old gauntlets plus Shadow Flames for Healer\'s Mitts. Source: https://vanadreams.org/wiki/#quest-568', steps = { { title = 'Requirements', note = '• WHM 50+; Prelude of Black and White done; no other Borghertz quest active.' }, { title = 'Walkthrough', note = '• Talk to Guslam (H-8, Upper Jeuno) twice.\n• First Borghertz quest only: Deadly Minnow (H-9), then 1,000 gil to Yin Pocanakhu (J-8, Lower Jeuno).\n• Beadeaux Treasure Coffer: old gauntlets.\n• Port Jeuno ??? Borghertz: agree to get Shadow Flames.\n• Castle Zvahl Baileys via Xarcabard (D-7): Torch (Map 1, F-8), kill Dark Spark, recheck.\n• Return to the ??? Borghertz.' }, { title = 'Notes', note = '• Crawlers\' Nest and Garlaige Citadel coffers may hold other AF.' } } },
    { name = 'Borghertz\'s Loyal Hands', group = 'Jeuno', desc = 'Samurai artifact hands quest: bring Borghertz the old gauntlets and shadow flames to get Myochin Kote. Source: https://vanadreams.org/wiki/#quest-569', steps = { { title = 'Before you start', note = '• Main job SAM, Lv50+\n• Yomi Okuri done\n• No other Borghertz\'s Hands quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the old gauntlets from a Treasure Coffer in Kuftal Tunnel (key or thief\'s tools).' }, { title = 'Step 3', note = '• Report back to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno to meet Borghertz.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill the Dark Spark that appears, then check the Torch again for the shadow flames.' }, { title = 'Step 7', note = '• Bring the flames and gauntlets to the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• After starting, coffers in Quicksand Caves and Temple of Uggalepih hold the other SAM artifact pieces.\n• Gauntlets and flames are removed at the end.\n• Small fame gain in all three nations.' } } },
    { name = 'Borghertz\'s Lurking Hands', group = 'Jeuno', desc = 'Ninja artifact hands quest: bring Borghertz the old gauntlets and shadow flames to get Ninja Tekko. Source: https://vanadreams.org/wiki/#quest-570', steps = { { title = 'Before you start', note = '• Main job NIN, Lv50+\n• I\'ll Take the Big Box done\n• No other Borghertz hands quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the old gauntlets from a Treasure Coffer in Ifrit\'s Cauldron (key or lockpick).' }, { title = 'Step 3', note = '• Report back to Guslam.' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno to meet Borghertz.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill the Dark Spark, then check the Torch again for the shadow flames.' }, { title = 'Step 7', note = '• Hand the shadow flames over at the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• Coffers in Sea Serpent Grotto and The Boyahda Tree may hold Ninja Kyahan and Ninja Hatsuburi.\n• Only one Borghertz quest at a time.' } } },
    { name = 'Borghertz\'s Shadowy Hands', group = 'Jeuno', desc = 'Dark Knight artifact gauntlets quest: find the Old Gauntlets and fetch shadow flames from Castle Zvahl Baileys for Borghertz. Source: https://vanadreams.org/wiki/#quest-571', steps = { { title = 'Before you start', note = '• Main job DRK, Lv50+\n• Dark Puppet done\n• No other Borghertz quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the Old Gauntlets from a Treasure Coffer in The Eldieme Necropolis.' }, { title = 'Step 3', note = '• Report back to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno; Borghertz requests shadow flames.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill the Dark Spark, then check it again for the Shadow Flames.' }, { title = 'Step 7', note = '• Give the Shadow Flames at the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• Coffers in Castle Oztroja and Monastic Cavern may hold your other artifact pieces.' } } },
    { name = 'Borghertz\'s Sneaky Hands', group = 'Jeuno', desc = 'Thief artifact hands quest: bring Borghertz the old gauntlets and shadow flames to get Rogue\'s Armlets. Source: https://vanadreams.org/wiki/#quest-572', steps = { { title = 'Before you start', note = '• Main job THF, Lv50+\n• As Thick As Thieves done\n• No other Borghertz quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the Old Gauntlets from the Treasure Coffer in Monastic Cavern.' }, { title = 'Step 3', note = '• Report to Guslam (H-8); on your first Borghertz quest also see Deadly Minnow (H-9), Upper Jeuno, and give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 4', note = '• Check the ??? in Port Jeuno to meet Borghertz.' }, { title = 'Step 5', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check a Torch (Map 1, F-8), kill the Dark Spark, then check it again for the Shadow Flames.' }, { title = 'Step 6', note = '• Give gauntlets and flames to Borghertz at the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• Skip Deadly Minnow and Yin Pocanakhu if you finished another Borghertz quest before.\n• Coffers in Castle Oztroja and Castle Zvahl Baileys can hold other artifact pieces.' } } },
    { name = 'Borghertz\'s Sorcerous Hands', group = 'Jeuno', desc = 'Black Mage artifact gloves quest: bring Borghertz the old gauntlets and shadow flames to get Wizard\'s Gloves. Source: https://vanadreams.org/wiki/#quest-573', steps = { { title = 'Before you start', note = '• Main job BLM, Lv50+\n• Recollections done or previously accepted\n• No other Borghertz\'s Hands quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the old gauntlets from the Treasure Coffer in Garlaige Citadel.' }, { title = 'Step 3', note = '• Show them to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then pay Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Speak to Borghertz at the ??? in Port Jeuno and agree to get shadow flames.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill Dark Spark, then check it again for the shadow flames.' }, { title = 'Step 7', note = '• Return to Borghertz at the ??? in Port Jeuno to receive Wizard\'s Gloves.' }, { title = 'Good to know', note = '• Coffers in Monastic Cavern and The Eldieme Necropolis may hold Wizard\'s Coat and Wizard\'s Tonban.\n• One Borghertz quest at a time; later ones skip Deadly Minnow and Yin Pocanakhu.' } } },
    { name = 'Borghertz\'s Stalwart Hands', group = 'Jeuno', desc = 'Paladin artifact hands quest: bring Borghertz the old gauntlets and shadow flames to get Gallant Gauntlets. Source: https://vanadreams.org/wiki/#quest-574', steps = { { title = 'Before you start', note = '• Main job PLD, Lv50+\n• A Boy\'s Dream done\n• No other Borghertz\'s Hands quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the old gauntlets from a Treasure Coffer in The Eldieme Necropolis (key or thief\'s tools).' }, { title = 'Step 3', note = '• Report back to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno to meet Borghertz.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill Dark Spark, then check it again for the shadow flames.' }, { title = 'Step 7', note = '• Bring flames and gauntlets to the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• After starting, coffers in Beadeaux and Garlaige Citadel hold the other PLD artifact pieces.\n• Gauntlets and flames are removed at the end.\n• Small fame gain in all three nations.' } } },
    { name = 'Borghertz\'s Striking Hands', group = 'Jeuno', desc = 'Monk artifact hands quest: bring Borghertz the old gauntlets and shadow flames to get Temple Gloves. Source: https://vanadreams.org/wiki/#quest-575', steps = { { title = 'Before you start', note = '• Main job MNK, Lv50+\n• The First Meeting done\n• No other Borghertz\'s Hands quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the old gauntlets from a Treasure Coffer in Crawlers\' Nest (key or thief\'s tools).' }, { title = 'Step 3', note = '• Report back to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno to meet Borghertz.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill Dark Spark, then check it again for the shadow flames.' }, { title = 'Step 7', note = '• Bring flames and gauntlets to the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• After starting, coffers in Beadeaux and Garlaige Citadel hold the other MNK artifact pieces.\n• Gauntlets and flames are removed at the end.\n• Small fame gain in all three nations.' } } },
    { name = 'Borghertz\'s Vermillion Hands', group = 'Jeuno', desc = 'Red Mage artifact gloves quest: find the Old Gauntlets and fetch shadow flames from Castle Zvahl Baileys for Borghertz. Source: https://vanadreams.org/wiki/#quest-576', steps = { { title = 'Before you start', note = '• Main job RDM, Lv50+\n• Enveloped in Darkness done\n• No other Borghertz quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the Old Gauntlets from a Treasure Coffer in The Eldieme Necropolis.' }, { title = 'Step 3', note = '• Report back to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno; Borghertz requests shadow flames.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill the Dark Spark, then check it again for the Shadow Flames.' }, { title = 'Step 7', note = '• Give the Shadow Flames at the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• Coffers in Castle Oztroja and Garlaige Citadel may hold your other artifact pieces.' } } },
    { name = 'Borghertz\'s Warring Hands', group = 'Jeuno', desc = 'Warrior artifact hands quest: get shadow flames for Borghertz to earn Fighter\'s Mufflers. Source: https://vanadreams.org/wiki/#quest-577', steps = { { title = 'Before you start', note = '• Warrior Lv50+\n• Bastok quest The Talekeeper\'s Truth done\n• No other Borghertz\'s Hands quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the old gauntlets from the Treasure Coffer in The Eldieme Necropolis (needs a key).' }, { title = 'Step 3', note = '• Report to Guslam (H-8), then see Deadly Minnow (H-9), Upper Jeuno.' }, { title = 'Step 4', note = '• Pay Yin Pocanakhu (J-8), Lower Jeuno, 1000 gil.' }, { title = 'Step 5', note = '• Check the ??? (H-8) in Port Jeuno and agree to bring Borghertz shadow flames.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill Dark Spark, then check it again for the shadow flames.' }, { title = 'Step 7', note = '• Hand the flames over at the ??? (H-8) in Port Jeuno.' }, { title = 'Good to know', note = '• Later Borghertz\'s Hands quests skip Deadly Minnow and Yin Pocanakhu.\n• Fighter\'s Cuisses and Fighter\'s Mask can come from coffers in Castle Zvahl Baileys and Crawlers\' Nest.' } } },
    { name = 'Borghertz\'s Wild Hands', group = 'Jeuno', desc = 'Beastmaster artifact gloves quest: find the Old Gauntlets and fetch shadow flames from Castle Zvahl Baileys for Borghertz. Source: https://vanadreams.org/wiki/#quest-578', steps = { { title = 'Before you start', note = '• Main job BST, Lv50+\n• Scattered into Shadow done\n• No other Borghertz quest active' }, { title = 'Step 1', note = '• Accept from Guslam (H-8), Upper Jeuno.' }, { title = 'Step 2', note = '• Get the Old Gauntlets from a Treasure Coffer in Crawlers\' Nest.' }, { title = 'Step 3', note = '• Report back to Guslam (H-8).' }, { title = 'Step 4', note = '• First Borghertz quest only: see Deadly Minnow (H-9), Upper Jeuno, then give Yin Pocanakhu (J-8), Lower Jeuno, 1,000 gil.' }, { title = 'Step 5', note = '• Check the ??? in Port Jeuno; Borghertz requests shadow flames.' }, { title = 'Step 6', note = '• Go into Castle Zvahl Baileys via Xarcabard (D-7); check the Torch (Map 1, F-8), kill the Dark Spark, then check it again for the Shadow Flames.' }, { title = 'Step 7', note = '• Give the Shadow Flames at the ??? in Port Jeuno.' }, { title = 'Good to know', note = '• Coffers in Beadeaux and Garlaige Citadel may hold your other artifact pieces.' } } },
    { name = 'Candle Making', group = 'Jeuno', desc = 'Part of A Candlelight Vigil: give Rouliette in Upper Jeuno a Lanolin. Source: https://vanadreams.org/wiki/#quest-579', steps = { { title = 'Before you start', note = '• A Candlelight Vigil accepted' }, { title = 'Steps', note = '• Accept from Rouliette (H-9), Upper Jeuno.\n• Trade her a Lanolin.' }, { title = 'Reward', note = '• Key item: holy candle\n• Title: Believer of Altana\n• Fame in all three nations' } } },
    { name = 'Child\'s Play', group = 'Jeuno', desc = 'Continue The Wonder Magic Set by giving Karl in Port Jeuno a White Rock. Source: https://vanadreams.org/wiki/#quest-580', steps = { { title = 'Before you start', note = '• The Wonder Magic Set accepted' }, { title = 'Steps', note = '• Accept from Karl (H-8), Port Jeuno.\n• Get a White Rock and trade it to Karl.' }, { title = 'Reward', note = '• Key item: Wonder Magic Set\n• Title: Trader of Mysteries\n• Fame in San d\'Oria, Bastok, Windurst' } } },
    { name = 'Chocobo on the Loose', group = 'Jeuno', desc = 'Help Brutus in Upper Jeuno find an escaped chocobo. Source: https://vanadreams.org/wiki/#quest-581', steps = { { title = 'Before you start', note = '• Lv20+' }, { title = 'Steps', note = '• Accept from Brutus (G-7), Upper Jeuno.\n• Check the Chocobo Tracks (E-4) in La Theine Plateau.\n• Report to Brutus.\n• Speak to Hantileon (I-11), Southern San d\'Oria, twice.\n• Report to Brutus again.\n• After one Vana\'diel day and a zone, talk to Brutus to finish.' }, { title = 'Reward', note = '• Chocobo Egg\n• Fame in San d\'Oria, Bastok, Windurst' } } },
    { name = 'Chocobo\'s Wounds', group = 'Jeuno', desc = 'Feed an injured chocobo in Upper Jeuno until it recovers to earn a chocobo license. Source: https://vanadreams.org/wiki/#quest-582', steps = { { title = 'Before you start', note = '• Lv20+' }, { title = 'Steps', note = '• Agree to help Brutus (G-7), Upper Jeuno.\n• Trade one Clump of Gausebit Grass to the Chocobo (G-7).\n• Keep feeding one at a time roughly every 45 seconds, six feedings total.\n• The final scene grants the chocobo license.' }, { title = 'Good to know', note = '• Gysahl Greens don\'t count.\n• Osker hints at the chocobo\'s condition.' }, { title = 'Reward', note = '• Key item: chocobo license\n• Title: Chocobo Trainer' } } },
    { name = 'Collect Tarut Cards', group = 'Jeuno', desc = 'Assemble four different Tarut cards for Chululu in Lower Jeuno. Source: https://vanadreams.org/wiki/#quest-584', steps = { { title = 'Before you start', note = '• Jeuno fame 3' }, { title = 'Steps', note = '• Accept from Chululu (I-8), Lower Jeuno; you get five random Tarut cards.\n• Collect Tarut: The Fool, Tarut: Death, Tarut: The Hermit and Tarut: The King.\n• Trade all four to Chululu.' }, { title = 'Good to know', note = '• He gives five new random cards per real-world day.\n• Spare duplicates can go to other players.' }, { title = 'Reward', note = '• Tarut:The Fool, Tarut:Death, Tarut:The King, Tarut:The Hermit\n• Title: Card Collector' } } },
    { name = 'Community Service', group = 'Jeuno', desc = 'Light Lower Jeuno\'s twelve streetlamps in a single night for Zauko. Source: https://vanadreams.org/wiki/#quest-585', steps = { { title = 'Steps', note = '• No requirements.\n• Accept from Zauko (I-6), Lower Jeuno, between 18:00 and 23:00 Vana\'diel time.\n• Check and light all 12 streetlamps in Lower Jeuno.\n• Report to Zauko before 01:00.' }, { title = 'Good to know', note = '• One player per night.\n• Too slow: talk to Zauko to reset and retry another night.\n• Repeats may let you keep a Lamp Lighters membership card.' }, { title = 'Reward', note = '• Title: Torchbearer' } } },
    { name = 'Crest of Davoi', group = 'Jeuno', desc = 'Give Baudin in Upper Jeuno Coeurl Meat to receive the crest of Davoi. Source: https://vanadreams.org/wiki/#quest-586', steps = { { title = 'Before you start', note = '• Key item: silver bell' }, { title = 'Steps', note = '• Accept from Baudin (G-8), Upper Jeuno.\n• Get Coeurl Meat and trade it to Baudin.' }, { title = 'Reward', note = '• Key item: crest of Davoi\n• Fame in Bastok, San d\'Oria, Windurst' } } },
    { name = 'The Unfinished Waltz', group = 'Jeuno', desc = 'First Dancer artifact quest: obtain The Essence of Dance in Grauberg [S] for Laila. Source: https://vanadreams.org/wiki/#quest-587', steps = { { title = 'Before you start', note = '• Main job DNC at first-artifact-quest level\n• Lakeside Minuet done' }, { title = 'Steps', note = '• Accept from Laila (G-7), Upper Jeuno.\n• Speak to Rhea Myuliah (G-7), Upper Jeuno.\n• As DNC, check the ??? in Grauberg [S] and view the cutscene.\n• Check it again and defeat the Migratory Hippogryph.\n• Check it once more for the key item The Essence of Dance.\n• Show it to Laila.' }, { title = 'Good to know', note = '• Without the key item Laila only repeats old lines.' }, { title = 'Reward', note = '• War Hoop\n• Title: Promising Dancer' } } },
    { name = 'The Road to Divadom', group = 'Jeuno', desc = 'Dancer artifact quest: deliver a Block of Yagudo Glue at Jugner Forest [S] for Laila to get Dancer\'s Tights. Source: https://vanadreams.org/wiki/#quest-588', steps = { { title = 'Before you start', note = '• Main job DNC, Lv50+\n• The Unfinished Waltz done\n• One Vana\'diel day and a zone since that quest' }, { title = 'Steps', note = '• Accept from Laila (G-7), Upper Jeuno, and speak to her again.\n• Enter Jugner Forest [S] for a cutscene.\n• Check the Glowing Pebbles (I-5).\n• Trade them a Block of Yagudo Glue.\n• Return to Laila for the scenes and Dancer\'s Tights.' }, { title = 'Good to know', note = '• Keep an inventory slot free.\n• Rhea Myuliah has optional dialogue.' }, { title = 'Reward', note = '• Dancer\'s Tights\n• Title: Stardust Dancer' } } },
    { name = 'Comeback Queen', group = 'Jeuno', desc = 'Third Dancer artifact quest: a series of errands and cutscenes for Laila ending in Dancer\'s Casaque. Source: https://vanadreams.org/wiki/#quest-589', steps = { { title = 'Before you start', note = '• Main job DNC, Lv50+\n• The Road to Divadom done' }, { title = 'Steps', note = '• Accept from Laila (G-7), Upper Jeuno; receive Wyatt\'s proposal.\n• Take it to Harmodios (K-10), Bastok Markets.\n• Return to Laila for a cutscene.\n• After a Vana\'diel day, talk to Laila for another cutscene.\n• After another day, talk to her and choose to continue.\n• Keep zoning into Upper Jeuno to trigger the cutscenes.\n• The last one awards Dancer\'s Casaque.' }, { title = 'Good to know', note = '• Laila, Olgald and Rhea Myuliah repeat hints.\n• Have inventory space; if delivery failed, talk to Laila again.' }, { title = 'Reward', note = '• Dancer\'s Casaque\n• Title: Elegant Dancer' } } },
    { name = 'Deal with Tenshodo', group = 'Jeuno', desc = 'Give Garnev in Lower Jeuno a Gold Orcmask to earn Tenshodo favor and clock tower oil. Source: https://vanadreams.org/wiki/#quest-591', steps = { { title = 'Before you start', note = '• A Clock Most Delicate active\n• Norg fame 2 (Garnev won\'t offer it otherwise)' }, { title = 'Steps', note = '• Accept from Garnev (J-7), Lower Jeuno.\n• Get a Gold Orcmask and trade it to him.' }, { title = 'Reward', note = '• Key item: clock tower oil\n• Title: Trader of Renown\n• Norg fame (50)' } } },
    { name = 'Ducal Hospitality', group = 'Jeuno', desc = 'Repeatable Ru\'Lude Gardens quest: trade Taillegeas one of five requested item sets. Source: https://vanadreams.org/wiki/#quest-592', steps = { { title = 'Before you start', note = '• Jeuno fame 4\n• A Vessel Without a Captain done' }, { title = 'Steps', note = '• Accept from Taillegeas (I-7), Ru\'Lude Gardens; he names one set.\n• Set options: Counterfeit Gil, Goblin Bread, Goblin Doll, Goblin Mushpot, Goblin Pie / Chocobo Bedding, Kaiserin Cosme., My First Magic Kit / Eastern Paper, Shuriken, Silver Obi, Tonosama R.Ball / Dart, Kongou Inaho, Nyumomo Doll, Snoll Gelato / Fernan\'s Diaries, Naphille Pochette, Sphene Earring, Turquoise Ring.\n• Trade him exactly the requested set.' }, { title = 'Good to know', note = '• Repeat after zoning and waiting one Vana\'diel day.\n• Decline and ask again to get a different set.' }, { title = 'Reward', note = '• 4,000 gil\n• Title: Ducal Dupe' } } },
    { name = 'Empty Memories', group = 'Jeuno', desc = 'Repeatable: exchange Promathia Recollection items with Harith in Ru\'Lude Gardens. Source: https://vanadreams.org/wiki/#quest-593', steps = { { title = 'Before you start', note = '• Promathia mission The Mothercrystals reached' }, { title = 'Steps', note = '• Agree to help Harith (H-5), Ru\'Lude Gardens.\n• Recollection of Pain, Fear or Guilt + 2,000 gil → Hysteroanima, Psychoanima or Terroanima.\n• Recollection of Suffering → Hamayumi; Recollection of Anxiety → Stone Gorget; Recollection of Animosity → Dia Wand.' }, { title = 'Reward', note = '• 2,000 gil\n• Hysteroanima, Psychoanima, Terroanima, Hamayumi, Stone Gorget, Dia Wand (per item traded)' } } },
    { name = 'Hook, Line, and Sinker', group = 'Jeuno', desc = 'Give Omer in Lower Jeuno an Egret Fishing Rod. Source: https://vanadreams.org/wiki/#quest-595', steps = { { title = 'Before you start', note = '• CoP mission A Vessel Without a Captain done' }, { title = 'Steps', note = '• Accept from Omer (G-9), Lower Jeuno.\n• Get an Egret Fishing Rod and trade it to him.' }, { title = 'Reward', note = '• 3,000 gil\n• Title: Rod Retriever\n• Fame in San d\'Oria, Bastok, Windurst' } } },
    { name = 'In the Mood for Love', group = 'Jeuno', desc = 'Give Odasel in Lower Jeuno a Chameleon Diamond. Source: https://vanadreams.org/wiki/#quest-596', steps = { { title = 'Before you start', note = '• CoP progress past A Vessel Without a Captain\n• A Chameleon Diamond' }, { title = 'Steps', note = '• Accept from Odasel (H-9), Lower Jeuno, and trade him the Chameleon Diamond.' }, { title = 'Good to know', note = '• Afterwards Matoaka in Lower Jeuno has an extra scene.' }, { title = 'Reward', note = '• 4,800 gil\n• Title: Pick Up Artist' } } },
    { name = 'In Defiant Challenge', group = 'Jeuno', desc = 'Limit break 1: raises the level cap from 50 to 55. Source: https://vanadreams.org/wiki/#quest-597', steps = { { title = 'Before you start', note = '• Main job Lv50, cap still 50' }, { title = 'Steps', note = '• Accept from Maat (H-5), Ru\'Lude Gardens.\n• Crawlers\' Nest (enter from Rolanberry Fields D-11): search the ??? for Exoray Mold pieces and combine them.\n• Garlaige Citadel: search the ??? for Bomb Coal pieces and combine them.\n• The Eldieme Necropolis (enter from Batallia Downs H-8): search the ??? for Ancient Papyrus pieces and combine them.\n• Trade Exoray Mold, Bomb Coal and Ancient Papyrus to Maat.' }, { title = 'Good to know', note = '• The three items may also come from normal drops or treasure.\n• Need inventory room for each combined item.' }, { title = 'Reward', note = '• Title: Horizon Breaker' } } },
    { name = 'Atop the Highest Mountains', group = 'Jeuno', desc = 'Limit break 2: collect three frigicite in Xarcabard to raise the cap from 55 to 60. Source: https://vanadreams.org/wiki/#quest-598', steps = { { title = 'Before you start', note = '• Cap 55, Lv51+' }, { title = 'Steps', note = '• Accept from Maat (H-5), Ru\'Lude Gardens.\n• Xarcabard ??? for Boreal Tiger (I-5): Round Frigicite.\n• Xarcabard ??? for Boreal Coeurl (J-6): Square Frigicite.\n• Xarcabard ??? for Boreal Hound (G-10): Triangular Frigicite.\n• Defeat each NM first if needed, then return all three to Maat.' }, { title = 'Reward', note = '• Title: Summit Breaker' } } },
    { name = 'Whence Blows the Wind', group = 'Jeuno', desc = 'Limit break 3: collect three beastman crests for Maat to raise the cap from 60 to 65. Source: https://vanadreams.org/wiki/#quest-599', steps = { { title = 'Before you start', note = '• Cap 60\n• Main job Lv56+' }, { title = 'Steps', note = '• Accept from Maat (H-5), Ru\'Lude Gardens.\n• Monastic Cavern (enter from Davoi J-9): ??? (J-6) gives the Orcish crest.\n• Qulun Dome: ??? (I-7) gives the Quadav crest.\n• Castle Oztroja (enter from Meriphataud Mountains L-8): ??? gives the Yagudo crest.\n• Bring all three to Maat.' }, { title = 'Good to know', note = '• Crests are removed on completion.' }, { title = 'Reward', note = '• Title: Sky Breaker' } } },
    { name = 'Riding on the Clouds', group = 'Jeuno', desc = 'Limit break 4 (cap 65 to 70): trade Kindred\'s Seals to four people Maat picks. Source: https://vanadreams.org/wiki/#quest-600', steps = { { title = 'Before you start', note = '• Lv61+, cap 65\n• Four Kindred\'s Seals' }, { title = 'Steps', note = '• Accept from Maat (H-5), Ru\'Lude Gardens; he names one person per region.\n• San d\'Oria target + Kindred\'s Seal → Scowling Stone.\n• Bastok target + seal → Smiling Stone.\n• Windurst target + seal → Spirited Stone.\n• Selbina or Mhaura target + seal → Somber Stone.\n• Bring all four stones to Maat.' }, { title = 'Possible targets', note = '• San d\'Oria: Raminel, Sobane, Taurette, Maloquedil, Sheridan, Fontoumant, Brifalien, Rugiette\n• Bastok: Babenn, Gwill, Brygid, Kaede, Hilda, Naji, Raibaht, Lucius\n• Windurst: Koko Lihzeh, Naiko-Paneiko, Kerutoto, Koru-Moru, Shanruru, Boizo-Naizo, Sola Jaab, Kupipi (Heaven\'s Tower)\n• Selbina: Mathilde, Vobo, Melyon, Gabwaleid; Mhaura: Celestina, Ekokoko, Bihoro-Guhoro, Jikka-Abukka\n• Targets are random; ask Maat again anytime for a reminder.' }, { title = 'Reward', note = '• Title: Cloud Breaker' } } },
    { name = 'Shattering Stars', group = 'Jeuno', desc = 'Beat Maat one-on-one on your job to push past the level 80 cap. Source: https://vanadreams.org/wiki/#quest-601', steps = { { title = 'Before you start', note = '• Lv80 with cap 80\n• Main job one of the original fifteen (Warrior through Summoner)' }, { title = 'Steps', note = '• Accept from Maat (H-5), Ru\'Lude Gardens.\n• Trade him your job\'s Testimony (e.g. Warrior\'s Testimony) and agree to go to the fight.\n• Win the battle at your job\'s arena.\n• Talk to Maat to finish.' }, { title = 'Arenas', note = '• Balga\'s Dais: MNK, WHM, SMN\n• Horlais Peak: WAR, BLM, RNG\n• Qu\'Bia Arena: PLD, DRK, BRD\n• Waughroon Shrine: RDM, THF, BST\n• Chamber of Oracles: SAM, NIN, DRG' }, { title = 'Good to know', note = '• An Instant Warp scroll is given after the fight.\n• Each job won counts for Beyond the Sun.' }, { title = 'Reward', note = '• Instant Warp\n• Title: Star Breaker' } } },
    { name = 'Beyond the Sun', group = 'Jeuno', desc = 'Beat Maat on all fifteen original jobs to earn Maat\'s Cap. Source: https://vanadreams.org/wiki/#quest-602', steps = { { title = 'Before you start', note = '• Shattering Stars done' }, { title = 'Steps', note = '• Win Maat\'s fight on each of the fifteen original jobs (Shattering Stars arenas).\n• Then talk to Maat (H-5), Ru\'Lude Gardens.' }, { title = 'Good to know', note = '• Maat explains the rematch on any job.' }, { title = 'Reward', note = '• Maat\'s Cap\n• Title: Ultimate Champion of the World' } } },
    { name = 'New Worlds Await', group = 'Jeuno', desc = 'Limit break 6: get the limit breaker key item from the Nomad Moogle in Ru\'Lude Gardens. Source: https://vanadreams.org/wiki/#quest-603', steps = { { title = 'Steps', note = '• Requires Lv75+.\n• At the Nomad Moogle (H-5), Ru\'Lude Gardens, pick the limit breaker option.' }, { title = 'Good to know', note = '• The Kindred\'s Seal part is currently not offered.' } } },
    { name = 'Expanding Horizons', group = 'Jeuno', desc = 'Limit break: give the Nomad Moogle five Kindred\'s Crests to raise the cap from 80 to 85. Source: https://vanadreams.org/wiki/#quest-604', steps = { { title = 'Before you start', note = '• New Worlds Await done\n• Cap 80\n• 4+ merit points' }, { title = 'Steps', note = '• Accept from the Nomad Moogle (H-5), Ru\'Lude Gardens.\n• Get five Kindred\'s Crests and trade them to the moogle.' }, { title = 'Good to know', note = '• Costs 4 merit points; cap becomes 85.' } } },
    { name = 'Beyond the Stars', group = 'Jeuno', desc = 'Limit break 8: win a Maat vs. Degenhard color contest via the Nomad Moogle to reach cap 90. Source: https://vanadreams.org/wiki/#quest-605', steps = { { title = 'Before you start', note = '• Expanding Horizons done\n• Cap 85' }, { title = 'Steps', note = '• Accept from the Nomad Moogle (H-5), Ru\'Lude Gardens.\n• Trade 10 Kindred\'s Crests (5 merit points are also spent).\n• Talk again and pick Red, Blue or Green each round until Maat wins.' }, { title = 'Good to know', note = '• Red beats Blue, Blue beats Green, Green beats Red.' } } },
    { name = 'Dormant Powers Dislodged', group = 'Jeuno', desc = 'Limit break to cap 95: give the Nomad Moogle a Kindred\'s Crest plus a named item, then pass a timing test. Source: https://vanadreams.org/wiki/#quest-606', steps = { { title = 'Before you start', note = '• Beyond the Stars done\n• Cap 90' }, { title = 'Steps', note = '• Accept from the Nomad Moogle (H-5), Ru\'Lude Gardens; it names one item.\n• Have a Kindred\'s Crest, that item and 10+ merit points.\n• Trade the crest and item (10 merits spent).\n• Talk again for the timing test and stop around 9-11 seconds.' }, { title = 'Good to know', note = '• Possible items: Sunsand, Faded Crystal, Orc. Armor Plate, Magicked Skull, Dhalmel Saliva, Yagudo Caulk, Siren\'s Tear, Dangruf Stone, Orcish Axe, Quadav Backscale.\n• Missing the timing lets you retry.' }, { title = 'Reward', note = '• Key item: soul gem' } } },
    { name = 'Prelude to Puissance', group = 'Jeuno', desc = 'Give the Nomad Moogle a Seasoning Stone on the way to the next cap. Source: https://vanadreams.org/wiki/#quest-607', steps = { { title = 'Before you start', note = '• Dormant Powers Dislodged done\n• Cap 95; level above 90' }, { title = 'Steps', note = '• Accept from the Nomad Moogle (H-5), Ru\'Lude Gardens.\n• Trade it a Seasoning Stone.\n• Talk again and make a choice to finish.' }, { title = 'Good to know', note = '• Some choices start Beyond Infinity at once and may warp you to a battlefield.' }, { title = 'Reward', note = '• Key item: soul gem clasp' } } },
    { name = 'Beyond Infinity', group = 'Jeuno', desc = 'Win the Beyond Infinity fight using a Soul Gem Clasp to raise the cap from 98 to 99. Source: https://vanadreams.org/wiki/#quest-608', steps = { { title = 'Before you start', note = '• Cap 98\n• Lv91+ recommended' }, { title = 'Steps', note = '• Accept from the Nomad Moogle (H-5), Ru\'Lude Gardens; receive the Soul Gem Clasp.\n• Use its menu to go to a battlefield (Horlais Peak, Waughroon Shrine, Balga\'s Dais or Qu\'Bia Arena), enter with the clasp and win.\n• Report back to the Nomad Moogle.' }, { title = 'Good to know', note = '• Entering consumes the clasp; after a loss, trade five H. Kindred Crests or spend a merit point for a new one.\n• Afterwards, at Lv99 the moogle gives the Job Breaker.' }, { title = 'Reward', note = '• Instant Warp\n• Title: Bushin Aspirant' } } },
    { name = 'Lakeside Minuet', group = 'Jeuno', desc = 'Dancer unlock quest: fetch a stardust pebble for Laila and Rhea Myuliah in Upper Jeuno. Source: https://vanadreams.org/wiki/#quest-609', steps = { { title = 'Before you start', note = '• Lv30+\n• Wings of the Goddess enabled' }, { title = 'Steps', note = '• Accept from Laila (G-7), Upper Jeuno.\n• Speak to Rhea Myuliah (G-7), Upper Jeuno.\n• Speak to Valderotaux (L-6), Southern San d\'Oria.\n• Return to Rhea Myuliah.\n• Check the Glowing Pebbles (I-5) in Jugner Forest [S] for the stardust pebble.\n• Give it to Laila.' }, { title = 'Reward', note = '• Title: Troupe Brilioth Dancer' } } },
    { name = 'Lure of the Wildcat (Jeuno)', group = 'Jeuno', desc = 'Ajithaam has you greet twenty Jeuno residents for the Wildcats. Source: https://vanadreams.org/wiki/#quest-610', steps = { { title = 'Before you start', note = '• Aht Urhgan enabled' }, { title = 'Steps', note = '• Accept from Ajithaam (F-6), Upper Jeuno; receive the white sentinel badge.\n• Ru\'Lude Gardens: Albiona (H-9), Crooked Arrow, Muhoho (H-7), Adolie (G-7), Yavoraile (I-6).\n• Upper Jeuno: Sibila-Mobla (G-6), Shiroro (G-8), Luto Mewrilah, Renik, Hinda (H-9).\n• Lower Jeuno: Sutarara (J-7), Saprut (I-7), Bluffnix (H-9), Naruru (H-10), Gurdern (G-10).\n• Port Jeuno: Red Ghost (G-8), Karl (H-8), Shami, Rinzei (I-8), Sagheera.\n• Report to Ajithaam after all twenty.' }, { title = 'Good to know', note = '• Any order works.\n• The badge is taken and replaced by the white invitation card.' }, { title = 'Reward', note = '• Key item: white invitation card' } } },
    { name = 'Martial Mastery', group = 'Jeuno', desc = 'Spend 15 merit points with the Nomad Moogle to learn the Bushin technique. Source: https://vanadreams.org/wiki/#quest-611', steps = { { title = 'Before you start', note = '• Lv96+\n• A combat weapon skill at 357+\n• 15 merit points' }, { title = 'Steps', note = '• Accept from the Nomad Moogle (H-5), Ru\'Lude Gardens.\n• Return with 15 merits to spend and finish.' }, { title = 'Reward', note = '• Key item: heart of the bushin\n• Title: Bushin Ryu Inheritor' } } },
    { name = 'Mysteries of Beadeaux I', group = 'Jeuno', desc = 'Sattal-Mansal in Lower Jeuno asks for a Quadav Charm; accepting also opens Mysteries of Beadeaux II. Source: https://vanadreams.org/wiki/#quest-615', steps = { { title = 'Requirements', note = '• Key item: silver bell.' }, { title = 'Steps', note = '• Accept from Sattal-Mansal (J-8), Lower Jeuno.\n• Get a Quadav Charm.\n• Trade it to Sattal-Mansal for the coruscant rosary.' }, { title = 'Notes', note = '• Fame up in San d\'Oria, Bastok and Windurst.\n• Mysteries of Beadeaux II starts on acceptance.' } } },
    { name = 'Mysteries of Beadeaux II', group = 'Jeuno', desc = 'Hand Sattal-Mansal in Lower Jeuno a Qdv. Augury Shell to earn the black matinee necklace. Source: https://vanadreams.org/wiki/#quest-616', steps = { { title = 'Requirements', note = '• Mysteries of Beadeaux (I) done.\n• One Qdv. Augury Shell.' }, { title = 'Steps', note = '• Get a Qdv. Augury Shell.\n• Trade it to Sattal-Mansal (J-8), Lower Jeuno.' }, { title = 'Notes', note = '• Fame up in Bastok, San d\'Oria and Windurst.' } } },
    { name = 'Never to Return', group = 'Jeuno', desc = 'Get three fortune readings from Kurou-Morou in Lower Jeuno on separate days, then give him a Horn Hairpin. Source: https://vanadreams.org/wiki/#quest-617', steps = { { title = 'Requirements', note = '• Your Crystal Ball done.\n• Jeuno fame 5.' }, { title = 'Steps', note = '• Get a reading from Kurou-Morou (I-7), Lower Jeuno, on three different Vana\'diel days.\n• Speak to him after the third to accept.\n• Trade him a Horn Hairpin.' }, { title = 'Notes', note = '• One reading counts per Vana\'diel day.\n• Readings remain available afterward.' }, { title = 'Reward', note = '• 1,200 gil, Garnet Ring.' } } },
    { name = 'Northward', group = 'Jeuno', desc = 'Radeivepart in Ru\'Lude Gardens wants a Flame Degen. Source: https://vanadreams.org/wiki/#quest-618', steps = { { title = 'Requirements', note = '• Jeuno fame 4+.' }, { title = 'Steps', note = '• Accept from Radeivepart (H-9), Ru\'Lude Gardens.\n• Get a Flame Degen and trade it to him.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP.\n• Key item: map of Castle Zvahl.\n• Title: Envoy to the North.' } } },
    { name = 'Painful Memory', group = 'Jeuno', desc = 'Bard AF1: Mertaire in Lower Jeuno sends you to the Waters of Oblivion in Ranguemont Pass to beat Tros. Source: https://vanadreams.org/wiki/#quest-619', steps = { { title = 'Requirements', note = '• Bard main, level 40+.\n• Path of the Bard done.' }, { title = 'Steps', note = '• Accept from Mertaire (I-8), Lower Jeuno; you get Mertaire\'s bracelet.\n• Examine the Waters of Oblivion (D-5), Ranguemont Pass, to spawn Tros.\n• Defeat Tros.\n• Examine the Waters again for the cutscene.' }, { title = 'Notes', note = '• Declined? Speak to Mertaire again.' }, { title = 'Reward', note = '• Paper Knife.' } } },
    { name = 'Path of the Bard', group = 'Jeuno', desc = 'Bard job unlock at the Song Runes in Valkurm Dunes. Source: https://vanadreams.org/wiki/#quest-621', steps = { { title = 'Requirements', note = '• A Minstrel in Despair done.' }, { title = 'Steps', note = '• Examine the Song Runes (B-7), Valkurm Dunes, and watch the cutscene.' }, { title = 'Notes', note = '• Bki Tbujhja, Mataligeat and Mertaire (Lower Jeuno) have optional lines.' }, { title = 'Reward', note = '• 3,000 gil.\n• Key item: job gesture: bard.\n• Title: Wandering Minstrel.' } } },
    { name = 'Path of the Beastmaster', group = 'Jeuno', desc = 'Beastmaster job unlock: one talk with Brutus in Upper Jeuno. Source: https://vanadreams.org/wiki/#quest-622', steps = { { title = 'Requirements', note = '• Save My Son done.\n• Level 30+.' }, { title = 'Steps', note = '• Speak to Brutus (G-7), Upper Jeuno, and watch the scene.' }, { title = 'Reward', note = '• Key item: job gesture: beastmaster.\n• Title: Animal Trainer.' } } },
    { name = 'Pretty Little Things', group = 'Jeuno', desc = 'Give Zona Shodhun in Port Jeuno the correct rock. Source: https://vanadreams.org/wiki/#quest-623', steps = { { title = 'Requirements', note = '• A Yellow Rock.' }, { title = 'Steps', note = '• Talk to or trade with Zona Shodhun (E-8), Port Jeuno, to start.\n• Trade her a Yellow Rock and agree to her request.' }, { title = 'Notes', note = '• Other rocks and flowers are rejected with a hint.\n• Unlocks a Mog House feature.' } } },
    { name = 'Rubbish Day', group = 'Jeuno', desc = 'Chululu in Lower Jeuno has you carry magic trash to Mashira in Garlaige Citadel. Source: https://vanadreams.org/wiki/#quest-625', steps = { { title = 'Requirements', note = '• Collect Tarut Cards done.' }, { title = 'Steps', note = '• Ask Chululu (I-8), Lower Jeuno, for a compatibility reading naming a partner in the same zone.\n• Repeat on three Vana\'diel days; accept to get the magic trash.\n• Enter Garlaige Citadel from Sauromugue Champaign (J-10) and bring the trash to Mashira.\n• Report back to Chululu.' }, { title = 'Notes', note = '• Only the day\'s first reading counts.\n• Naming Chululu or Kurou-Morou does not count.' }, { title = 'Reward', note = '• 6,000 gil, Chain Choker.' } } },
    { name = 'Save My Sister', group = 'Jeuno', desc = 'Use the Ducal Guard\'s lantern on four braziers in The Eldieme Necropolis to help Baudin\'s sister. Source: https://vanadreams.org/wiki/#quest-626', steps = { { title = 'Requirements', note = '• Crest of Davoi done.\n• Jeuno fame 4.' }, { title = 'Steps', note = '• Speak to Baudin (G-8) and Mailloquetat (H-9), Upper Jeuno.\n• Speak to Baudin again, then Neraf-Najiruf (G-7), Ru\'Lude Gardens, for the Ducal Guard\'s lantern.\n• Enter The Eldieme Necropolis from Batallia Downs (H-8); light braziers in order F-9, H-7, F-7, H-9.\n• Return to Baudin.' }, { title = 'Notes', note = '• Wrong order puts the lantern out; restart from the first.\n• Not shown in the quest log until finished.\n• Neraf-Najiruf reclaims the lantern afterward.' }, { title = 'Reward', note = '• 3,000 gil, Holy Mace.\n• Title: Exorcist in Training.' } } },
    { name = 'Save My Son', group = 'Jeuno', desc = 'Fetch a night-blooming flower on Qufim Island for a sick boy in Lower Jeuno. Source: https://vanadreams.org/wiki/#quest-627', steps = { { title = 'Requirements', note = '• Chocobo\'s Wounds done.\n• Level 30+.' }, { title = 'Steps', note = '• Check the Merchant\'s House door (G-10), Lower Jeuno, and accept.\n• Optional hints: Shalott (G-7), Upper Jeuno.\n• At night (about 21:30-05:40) check the Nightflowers (F-8), Qufim Island.\n• Return to the Merchant\'s House door.' }, { title = 'Reward', note = '• 2,100 gil, Beast Whistle.\n• Title: Life Saver.' } } },
    { name = 'Save the Clock Tower', group = 'Jeuno', desc = 'Gather ten Jeuno signatures on Derrick\'s petition. Source: https://vanadreams.org/wiki/#quest-628', steps = { { title = 'Requirements', note = '• A Clock Most Delicate done.\n• Jeuno fame 5.' }, { title = 'Steps', note = '• Accept from Derrick (H-7), Lower Jeuno; get a Tower Petition.\n• Trade it to: Pitantimand (Port Jeuno); Teigero-Bangero (H-10), Zauko (Lower Jeuno); Baudin (G-8), Collet (G-7), Constance, Monberaux, Souren (G-9), Zuber (Upper Jeuno); Radeivepart (Ru\'Lude Gardens).\n• Trade the signed petition to Derrick.' }, { title = 'Notes', note = '• You get the petition back after each signature.\n• A replacement from Derrick wipes signatures.' }, { title = 'Reward', note = '• Tower Petition.\n• Title: Clock Tower Preservationist.' } } },
    { name = 'Scattered into the Shadow', group = 'Jeuno', desc = 'Beastmaster AF2: plant aquaflora in Feiyin, then bring a Beast Collar to Tebhi in Castle Oztroja. Source: https://vanadreams.org/wiki/#quest-629', steps = { { title = 'Requirements', note = '• Beastmaster main, level 50+.\n• Wings of Gold done.' }, { title = 'Steps', note = '• Accept from Brutus (G-7), Upper Jeuno; get three aquaflora.\n• Plant one at each of the three Underground Pools in Feiyin; defeat Dabotz\'s Ghost at the one that spawns it.\n• Examine that pool again for the scene.\n• Speak to Brutus.\n• Enter Castle Oztroja from Meriphataud Mountains (L-8); open the Treasure Chest for a Beast Collar.\n• Trade it to Tebhi (roams Castle Oztroja).\n• Return to Brutus.' }, { title = 'Notes', note = '• Chest gives the collar only after the pools.\n• Tebhi respawns a few minutes after vanishing.' }, { title = 'Reward', note = '• Beast Gaiters.' } } },
    { name = 'Searching for the Right Words', group = 'Jeuno', desc = 'Defeat Agas in The Boyahda Tree at night for a Moondrop for Ilumida. Source: https://vanadreams.org/wiki/#quest-630', steps = { { title = 'Requirements', note = '• A Candlelight Vigil, Rubbish Day, Never to Return done.\n• Jeuno fame 6.' }, { title = 'Steps', note = '• Hear Kurou-Morou (I-7), Lower Jeuno.\n• Agree to help Ilumida (G-8), Upper Jeuno.\n• Enter The Boyahda Tree from The Sanctuary of Zi\'Tah (J-12), 19:00-04:00 Vana\'diel time, not on a new moon.\n• Click the ??? to spawn Agas; defeat it.\n• Click the ??? again for the Moondrop.\n• Bring it to Ilumida.' }, { title = 'Notes', note = '• Declined? Speak to Ilumida again.\n• Extra scene with Kurou-Morou afterward.' }, { title = 'Reward', note = '• 3,000 gil, Sleepga II.' } } },
    { name = 'Shadows of the Departed', group = 'Jeuno', desc = 'Zilart-linked quest: collect slivers from Promyvion - Dem, Holla and Mea. Source: https://vanadreams.org/wiki/#quest-631', steps = { { title = 'Requirements', note = '• Storms of Fate done.\n• Rise of the Zilart mission Awakening at the right stage.\n• One Vana\'diel day since the previous step.' }, { title = 'Steps', note = '• Enter the marked area in Ru\'Lude Gardens; get the note written by Esha\'ntarl.\n• Examine the marked object in Promyvion - Dem, Promyvion - Holla and Promyvion - Mea for each sliver.\n• Return to the Ru\'Lude Gardens spot with all three.' }, { title = 'Notes', note = '• One-day wait follows before Apocalypse Nigh.' }, { title = 'Reward', note = '• Key items: note written by Esha\'ntarl; Promyvion - Dem, Holla and Mea slivers.' } } },
    { name = 'Storms of Fate', group = 'Jeuno', desc = 'Chains of Promathia (Dawn) quest tracing the Wyrmking through Misareaux Coast and Riverne - Site B01. Source: https://vanadreams.org/wiki/#quest-632', steps = { { title = 'Requirements', note = '• Chains of Promathia mission Dawn at the right stage.\n• Zone once if you just declined or finished another Jeuno quest.' }, { title = 'Steps', note = '• Enter the marked area in Ru\'Lude Gardens and accept.\n• Examine the ??? (F-7), Misareaux Coast.\n• Examine the Unstable Displacement in Riverne - Site B01; win the Storms of Fate battlefield.\n• Return to the Ru\'Lude Gardens spot for the final scene.' }, { title = 'Notes', note = '• Finishing starts the wait for Shadows of the Departed.' }, { title = 'Reward', note = '• Key item: whisper of the Wyrmking.' } } },
    { name = 'Tenshodo Membership', group = 'Jeuno', desc = 'Fetch a Tenshodo application from Port Bastok and give it to Ghebi Damomohe in Lower Jeuno. Source: https://vanadreams.org/wiki/#quest-633', steps = { { title = 'Requirements', note = '• Jeuno fame 3+.' }, { title = 'Steps', note = '• Ask Ghebi Damomohe (I-7), Lower Jeuno, about the Tenshodo.\n• Get the application form from Jabbar or Silver Owl (F-6), Port Bastok.\n• Hand it to Ghebi Damomohe.' }, { title = 'Notes', note = '• A Tenshodo Invite can be traded to Ghebi directly.' }, { title = 'Reward', note = '• Tenshodo Invite.\n• Key item: Tenshodo Member\'s Card.' } } },
    { name = 'The Antique Collector', group = 'Jeuno', desc = 'Trade a Kaiser Sword to Imasuke in Port Jeuno. Source: https://vanadreams.org/wiki/#quest-634', steps = { { title = 'Requirements', note = '• Jeuno fame 2.' }, { title = 'Steps', note = '• Accept from Imasuke (E-6), Port Jeuno.\n• Get a Kaiser Sword and trade it to him.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP.\n• Key item: map of Delkfutt\'s Tower.\n• Title: Trader of Antiquities.' } } },
    { name = 'The Circle of Time (BRD AF3)', group = 'Jeuno', desc = 'Bard AF3: bury the star ring in Xarcabard, then defeat a Bugaboo in Monastic Cavern. Source: https://vanadreams.org/wiki/#quest-635', steps = { { title = 'Requirements', note = '• Bard main at the required level.\n• The Requiem done.' }, { title = 'Steps', note = '• Speak to Mertaire (I-8), Lower Jeuno.\n• Agree to Imasuke\'s task (E-6), Port Jeuno.\n• Examine the Perennial Snow (I-10), Xarcabard, to bury the star ring; wait briefly and examine again.\n• Return to Imasuke.\n• Take the ring to Chalvatot (F-7), Chateau d\'Oraguille; accept the moon ring.\n• Enter Monastic Cavern from Davoi (I-8); examine the Altar (I-8) and defeat the Bugaboo.\n• Examine the Altar again to place the rings.\n• Return to Chalvatot.' }, { title = 'Notes', note = '• Declined Imasuke? Ask again.\n• Both rings are consumed at the altar.' }, { title = 'Reward', note = '• Choral Jstcorps.\n• Title: Paragon of Bard Excellence.' } } },
    { name = 'The Clockmaster', group = 'Jeuno', desc = 'Meet the clockmaster via the Clock Tower door in Upper Jeuno. Source: https://vanadreams.org/wiki/#quest-636', steps = { { title = 'Requirements', note = '• Save the Clock Tower done.\n• Jeuno fame 5.' }, { title = 'Steps', note = '• Examine the Clock Tower door (F-7), Upper Jeuno, and watch the scene.' }, { title = 'Notes', note = '• Collet has new lines afterward.' }, { title = 'Reward', note = '• 1,200 gil, Time Hammer.\n• Title: Timekeeper.' } } },
    { name = 'The Gobbiebag Part I', group = 'Jeuno', desc = 'Bluffnix in Lower Jeuno adds inventory space for crafting materials. Source: https://vanadreams.org/wiki/#quest-637', steps = { { title = 'Requirements', note = '• Jeuno fame 1+.\n• Inventory exactly 30.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade him Dhalmel Leather, Steel Ingot, Linen Cloth and Peridot, or one Goblin Stew 880.' }, { title = 'Notes', note = '• +5 inventory (and Mog Satchel, if owned).' } } },
    { name = 'The Gobbiebag Part II', group = 'Jeuno', desc = 'Next Bluffnix trade for +5 inventory slots. Source: https://vanadreams.org/wiki/#quest-638', steps = { { title = 'Requirements', note = '• The Gobbiebag Part I done.\n• Jeuno fame 1.\n• Inventory exactly 35.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Ram Leather, Mythril Ingot, Wool Cloth and Turquoise, or one Goblin Stew 880.' }, { title = 'Notes', note = '• Mog Satchel also grows.' } } },
    { name = 'The Gobbiebag Part III', group = 'Jeuno', desc = 'Bluffnix raises inventory from 40 to 45. Source: https://vanadreams.org/wiki/#quest-639', steps = { { title = 'Requirements', note = '• Jeuno fame 1.\n• The Gobbiebag Part II done.\n• Inventory exactly 40.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Tiger Leather, Gold Ingot, Velvet Cloth and Painite, or one Goblin Stew 880.' } } },
    { name = 'The Gobbiebag Part IV', group = 'Jeuno', desc = 'Fourth Bluffnix inventory expansion, +5 slots. Source: https://vanadreams.org/wiki/#quest-640', steps = { { title = 'Requirements', note = '• Jeuno fame 1.\n• The Gobbiebag Part III done.\n• Inventory 45.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Cermet Chunk, Darksteel Ingot, Silk Cloth and Goshenite, or one Goblin Stew 880.' } } },
    { name = 'The Gobbiebag Part IX', group = 'Jeuno', desc = 'Ninth Bluffnix trade for +5 inventory slots. Source: https://vanadreams.org/wiki/#quest-641', steps = { { title = 'Requirements', note = '• The Gobbiebag Part VIII done.\n• Jeuno fame 5.\n• Inventory exactly 70.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Ocl. Ingot, Peiste Leather, Oil-Soaked Clth. and Oxblood Orb, or one Goblin Stew 880.' } } },
    { name = 'The Gobbiebag Part V', group = 'Jeuno', desc = 'Fifth Bluffnix inventory expansion; grants the title Greedalox. Source: https://vanadreams.org/wiki/#quest-642', steps = { { title = 'Requirements', note = '• The Gobbiebag Part IV done.\n• Jeuno fame 3.\n• Inventory exactly 50.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Rhodonite, Paktong Ingot, Moblinweave and Bugard Leather, or a Goblin Stew.' } } },
    { name = 'The Gobbiebag Part VI', group = 'Jeuno', desc = 'Bluffnix raises inventory from 55 to 60. Source: https://vanadreams.org/wiki/#quest-643', steps = { { title = 'Requirements', note = '• The Gobbiebag Part V done.\n• Jeuno fame 3.\n• Inventory 55.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Shakudo Ingot, Balloon Cloth, Iolite and H.Q. Eft Skin, or one Goblin Stew 880.' } } },
    { name = 'The Gobbiebag Part VII', group = 'Jeuno', desc = 'Seventh Bluffnix trade for +5 inventory slots. Source: https://vanadreams.org/wiki/#quest-644', steps = { { title = 'Requirements', note = '• The Gobbiebag Part VI done.\n• Jeuno fame 4.\n• Inventory 60.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Lynx Leather, Adaman Ingot, Rainbow Cloth and Deathstone together, or one Goblin Stew.' }, { title = 'Notes', note = '• Mog Satchel also +5 if owned.' } } },
    { name = 'The Gobbiebag Part VIII', group = 'Jeuno', desc = 'Eighth Bluffnix trade for +5 inventory slots. Source: https://vanadreams.org/wiki/#quest-645', steps = { { title = 'Requirements', note = '• The Gobbiebag Part VII done.\n• Jeuno fame 4.\n• Inventory exactly 65.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Smilodon Leather, Electrum Ingot, Cilice and Angelstone, or one Goblin Stew 880.' } } },
    { name = 'The Gobbiebag Part X', group = 'Jeuno', desc = 'Bluffnix raises inventory from 75 to 80. Source: https://vanadreams.org/wiki/#quest-646', steps = { { title = 'Requirements', note = '• Jeuno fame 5.\n• The Gobbiebag Part IX done.\n• Inventory exactly 75.' }, { title = 'Steps', note = '• Accept from Bluffnix (H-9), Lower Jeuno.\n• Trade Molybden. Ingot, Griffon Leather, Foulard and Angel Skin Orb, or one Goblin Stew 880.' }, { title = 'Notes', note = '• Items are consumed.\n• Mog Satchel also +5 if owned.' } } },
    { name = 'The Goblin Tailor', group = 'Jeuno', desc = 'Find a magical pattern in the dungeon chest Guttrix names, then pick a race-specific Rare Skill Equipment piece. Source: https://vanadreams.org/wiki/#quest-647', steps = { { title = 'Requirements', note = '• Level 10+.\n• Jeuno fame 3.' }, { title = 'Steps', note = '• Accept from Guttrix (H-10), Lower Jeuno; note the day\'s dungeon and race.\n• If you match that race, open the Treasure Chest there (Ordelle\'s Caves, Gusgen Mines or Maze of Shakhrami) with a suitable key for the magical pattern.\n• Return to Guttrix and choose body, hands, legs or feet.' }, { title = 'Notes', note = '• Dungeon and race rotate by Vana\'diel day.\n• Each slot can be claimed once; repeat for the others.\n• Guttrix says when you own all four.' }, { title = 'Reward', note = '• One of 28 items, e.g. Custom Tunic, Custom Vest, Magna Jerkin, Magna Bodice, Wonder Kaftan, Savage Separates, Elder\'s Surcoat, Custom M Gloves, Custom F Gloves, Magna Gauntlets, Magna Gloves, Wonder Mitts.\n• Title: Goblins Exclusive Fashion Mannequin.' } } },
    { name = 'The Old Monument', group = 'Jeuno', desc = 'Copy the Song Runes in Buburimu Peninsula onto a Parchment for Mertaire. Source: https://vanadreams.org/wiki/#quest-648', steps = { { title = 'Requirements', note = '• Level 30+.\n• A Parchment.' }, { title = 'Steps', note = '• Speak to Mertaire (I-8), Lower Jeuno.\n• Trade a Parchment to the Song Runes (F-9), Buburimu Peninsula.' }, { title = 'Notes', note = '• Mataligeat has extra lines.' }, { title = 'Reward', note = '• Poetic Parchment.\n• Title: Researcher of Classics.' } } },
    { name = 'The Requiem', group = 'Jeuno', desc = 'Bard AF2: use blessed Holy Water in The Eldieme Necropolis and defeat three Yum Kimil for a star ring. Source: https://vanadreams.org/wiki/#quest-649', steps = { { title = 'Requirements', note = '• Painful Memory done.\n• Bard main, level 50.' }, { title = 'Steps', note = '• Accept from Bki Tbujhja (H-8), Lower Jeuno.\n• Trade him a Holy Water to bless it.\n• Enter The Eldieme Necropolis from Batallia Downs (F-5); trade the Holy Water to the fourth sarcophagus.\n• Defeat the three Yum Kimil.\n• Examine the sarcophagus for a star ring.\n• Show it to Bki Tbujhja.' }, { title = 'Notes', note = '• Other sarcophagi do nothing.\n• Mataligeat has optional lines.' }, { title = 'Reward', note = '• Choral Slippers.' } } },
    { name = 'The Road to Aht Urhgan', group = 'Jeuno', desc = 'Faursel in Lower Jeuno gets you an Aht Urhgan boarding permit for gil or goods. Source: https://vanadreams.org/wiki/#quest-650', steps = { { title = 'Requirements', note = '• Treasures of Aht Urhgan enabled.' }, { title = 'Steps', note = '• Hear Faursel\'s offer (J-8), Lower Jeuno.\n• Pay 500,000 gil, or trade one set: Damselfly Worm, Magicked Skull, Crab Apron, Bloody Robe, Dhalmel Saliva, Wild Rabbit Tail; or Jade Cryptex, Silver Engraving, 13-Knot Quipu; or Carmine, Cyan and Gray Chip; or one coffer key or job testimony.\n• Zone and return after a Vana\'diel day for the permit.\n• If you paid gil, take his teleport to Wajaom Woodlands for the permit and map, then report to Faursel.' }, { title = 'Notes', note = '• The 500,000 gil is non-refundable.\n• On Rhapsodies mission Inescapable Binds, the mission option completes this at once and advances the mission.' } } },
    { name = 'Unlisted Qualities', group = 'Jeuno', desc = 'Build a character description from several NPCs\' choices and confirm it with Bheem and Luto Mewrilah. Source: https://vanadreams.org/wiki/#quest-651', steps = { { title = 'Steps', note = '• Choose name and race with Luto Mewrilah (G-8), Upper Jeuno.\n• Choose size with Akta (H-10), Ru\'Lude Gardens.\n• Choose face with Kuah Dakonsa (H-8), Lower Jeuno.\n• Choose personality with Red Ghost (G-8), Port Jeuno.\n• Confirm with Bheem (F-5), Upper Jeuno.\n• Finish with Luto Mewrilah.' }, { title = 'Notes', note = '• Personality options follow the chosen race\'s gender.\n• Size, face and personality: any order.' }, { title = 'Reward', note = '• Silver Ingot.' } } },
    { name = 'Unlocking a Myth: Black Mage', group = 'Jeuno', desc = 'Zalsuhm in Lower Jeuno teaches Vidohunir once your Mage\'s Staff has 250 weapon skill points. Source: https://vanadreams.org/wiki/#quest-652', steps = { { title = 'Requirements', note = '• Black Mage main.\n• Mage\'s Staff equipped to start; 250 WS points.' }, { title = 'Steps', note = '• With the staff equipped, accept from Zalsuhm (H-9), Lower Jeuno.\n• Fight with it until charged.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Early trade shows progress.\n• Talking without the staff equipped sulks him until you zone.' } } },
    { name = 'Unlocking a Myth: Blue Mage', group = 'Jeuno', desc = 'Zalsuhm teaches Blue Mages Expiacion for a charged Wightslayer. Source: https://vanadreams.org/wiki/#quest-653', steps = { { title = 'Requirements', note = '• Blue Mage main.\n• Wightslayer.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with it.\n• Trade it to Zalsuhm to learn Expiacion.' }, { title = 'Notes', note = '• Early trade shows progress; weapon is kept.\n• Declining requires a zone before he talks again.' } } },
    { name = 'Unlocking a Myth: Bard', group = 'Jeuno', desc = 'Zalsuhm teaches Bards Mordant Rime for a charged Dancing Dagger. Source: https://vanadreams.org/wiki/#quest-654', steps = { { title = 'Requirements', note = '• Bard main.\n• Dancing Dagger.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with it.\n• Trade it to Zalsuhm to learn Mordant Rime.' }, { title = 'Notes', note = '• Early trade shows progress; weapon is kept.\n• Declining requires a zone before he talks again.' } } },
    { name = 'Unlocking a Myth: Beastmaster', group = 'Jeuno', desc = 'Charge a Double Axe to 250 WS points and show Zalsuhm to learn Primal Rend. Source: https://vanadreams.org/wiki/#quest-655', steps = { { title = 'Requirements', note = '• Beastmaster main.\n• Double Axe (Vigil weapon).' }, { title = 'Steps', note = '• Equip it; begin the trial with Zalsuhm (H-9), Lower Jeuno.\n• Use weapon skills with it to reach 250 points.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Early trade shows progress.\n• Saying you\'re not ready upsets him until you zone.' } } },
    { name = 'Unlocking a Myth: Corsair', group = 'Jeuno', desc = 'Zalsuhm teaches Leaden Salute once your Quicksilver has 250 WS points. Source: https://vanadreams.org/wiki/#quest-656', steps = { { title = 'Requirements', note = '• Corsair main.\n• Quicksilver equipped to start; 250 WS points.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Fight with it until charged.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Early trade shows progress.\n• Talking without it equipped sulks him until you zone.' } } },
    { name = 'Unlocking a Myth: Dancer', group = 'Jeuno', desc = 'Charge a Main Gauche for Zalsuhm to learn Pyrrhic Kleos. Source: https://vanadreams.org/wiki/#quest-657', steps = { { title = 'Requirements', note = '• Dancer main.\n• Main Gauche.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Use weapon skills with it to 250 points.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Must be wielded to start.\n• Early trade shows progress and the weapon comes back.' } } },
    { name = 'Unlocking a Myth: Dragoon', group = 'Jeuno', desc = 'Charge a Radiant Lance for Zalsuhm to learn Drakesbane. Source: https://vanadreams.org/wiki/#quest-658', steps = { { title = 'Requirements', note = '• Dragoon main.\n• Radiant Lance, 250 WS points.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with it.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Lance is kept.\n• If declined, zone and ask again.' } } },
    { name = 'Unlocking a Myth: Dark Knight', group = 'Jeuno', desc = 'Charge a Death Sickle for Zalsuhm to learn Insurgency. Source: https://vanadreams.org/wiki/#quest-659', steps = { { title = 'Requirements', note = '• Dark Knight main.\n• Death Sickle in main hand to start.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with it.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Weapon is kept; early trade shows progress.' } } },
    { name = 'Unlocking a Myth: Monk', group = 'Jeuno', desc = 'Charge Burning Fists for Zalsuhm to learn Ascetic\'s Fury. Source: https://vanadreams.org/wiki/#quest-660', steps = { { title = 'Requirements', note = '• Monk main.\n• Burning Fists in main hand to start.' }, { title = 'Steps', note = '• Equip them; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with them.\n• Trade them to Zalsuhm.' }, { title = 'Notes', note = '• Weapon is kept; early trade shows progress.' } } },
    { name = 'Unlocking a Myth: Ninja', group = 'Jeuno', desc = 'Trade a fully charged Sasuke Katana to Zalsuhm to learn Blade: Kamu. Source: https://vanadreams.org/wiki/#quest-661', steps = { { title = 'Requirements', note = '• Ninja main.\n• Sasuke Katana equipped when talking to Zalsuhm.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Use it until it has the required WS points.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Early trade shows progress; katana is kept.' } } },
    { name = 'Unlocking a Myth: Paladin', group = 'Jeuno', desc = 'Charge a Brave Blade for Zalsuhm to learn Atonement. Source: https://vanadreams.org/wiki/#quest-662', steps = { { title = 'Requirements', note = '• Paladin main.\n• Brave Blade wielded when asking.' }, { title = 'Steps', note = '• Equip it as main weapon; accept from Zalsuhm (H-9), Lower Jeuno.\n• Fight with it to build WS points.\n• Trade it to Zalsuhm when charged.' }, { title = 'Notes', note = '• Early trade shows progress; blade is kept.' } } },
    { name = 'Unlocking a Myth: Puppetmaster', group = 'Jeuno', desc = 'Zalsuhm teaches Stringing Pummel for charged Inferno Claws. Source: https://vanadreams.org/wiki/#quest-663', steps = { { title = 'Requirements', note = '• Puppetmaster main.\n• Inferno Claws.' }, { title = 'Steps', note = '• Equip them; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with them.\n• Trade them to Zalsuhm.' }, { title = 'Notes', note = '• Early trade shows progress; claws are kept.\n• Declining requires a zone before he talks again.' } } },
    { name = 'Unlocking a Myth: Red Mage', group = 'Jeuno', desc = 'Charge a Vorpal Sword to 250 WS points and show Zalsuhm to learn Death Blossom. Source: https://vanadreams.org/wiki/#quest-664', steps = { { title = 'Requirements', note = '• Red Mage main.\n• Vorpal Sword (Vigil weapon).' }, { title = 'Steps', note = '• Equip it; begin the trial with Zalsuhm (H-9), Lower Jeuno.\n• Use weapon skills with it to reach 250 points.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Early trade shows progress.\n• Saying you\'re not ready upsets him until you zone.' } } },
    { name = 'Unlocking a Myth: Ranger', group = 'Jeuno', desc = 'Charge a Killer Bow and trade it to Zalsuhm to learn Trueflight. Source: https://vanadreams.org/wiki/#quest-665', steps = { { title = 'Requirements', note = '• Ranger main.\n• Killer Bow in main or ranged slot when talking to Zalsuhm.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Fight with it to build WS points.\n• Trade it to Zalsuhm when charged.' }, { title = 'Notes', note = '• Bow is kept; early trade only gives a hint.\n• Zone if he is upset by a refusal.' } } },
    { name = 'Unlocking a Myth: Samurai', group = 'Jeuno', desc = 'Charge a Windslicer for Zalsuhm to learn Tachi: Rana. Source: https://vanadreams.org/wiki/#quest-666', steps = { { title = 'Requirements', note = '• Samurai main.' }, { title = 'Steps', note = '• Wield a Windslicer; accept from Zalsuhm (H-9), Lower Jeuno.\n• Fight with it until charged.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Weapon is kept; early trade shows progress.' } } },
    { name = 'Unlocking a Myth: Scholar', group = 'Jeuno', desc = 'Charge the Elder Staff and trade it to Zalsuhm to learn Omniscience. Source: https://vanadreams.org/wiki/#quest-667', steps = { { title = 'Requirements', note = '• Scholar main.\n• Elder Staff.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Fight with it to earn the needed WS points.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Staff is kept.\n• Declining requires a zone before he talks again.' } } },
    { name = 'Unlocking a Myth: Summoner', group = 'Jeuno', desc = 'Charge a Scepter Staff for Zalsuhm to learn Garland of Bliss. Source: https://vanadreams.org/wiki/#quest-668', steps = { { title = 'Requirements', note = '• Summoner main.\n• Scepter Staff in main hand to start.' }, { title = 'Steps', note = '• Equip it; accept from Zalsuhm (H-9), Lower Jeuno.\n• Earn 250 WS points with it.\n• Trade it to Zalsuhm.' }, { title = 'Notes', note = '• Staff is kept.' } } },
    { name = 'Unlocking a Myth: Thief', group = 'Jeuno', desc = 'Thief mythic weapon skill quest: get 250 weapon skill points on a Swordbreaker and hand it to Zalsuhm to learn Mandalic Stab. Source: https://vanadreams.org/wiki/#quest-669', steps = { { title = 'Requirements', note = '• Main job Thief.\n• Swordbreaker (Vigil weapon).' }, { title = 'Walkthrough', note = '• With the Swordbreaker equipped, speak to Zalsuhm (H-9), Lower Jeuno, and start the trial.\n• Build 250 weapon skill points on it via weapon skills.\n• Trade it to Zalsuhm to learn Mandalic Stab.' }, { title = 'Notes', note = '• An early trade shows your rough progress.\n• Saying you are not ready blocks him until you zone.' } } },
    { name = 'Unlocking a Myth: Warrior', group = 'Jeuno', desc = 'Warrior weapon skill quest: raise weapon skill points on a Sturdy Axe for Zalsuhm to learn King\'s Justice. Source: https://vanadreams.org/wiki/#quest-670', steps = { { title = 'Requirements', note = '• Main job Warrior.\n• Sturdy Axe.' }, { title = 'Walkthrough', note = '• Main-hand the Sturdy Axe, speak to Zalsuhm (H-9), Lower Jeuno, and accept.\n• Use weapon skills with it to build points.\n• Trade the axe to Zalsuhm when complete.' }, { title = 'Notes', note = '• Early trades report progress.\n• The axe is returned to you.' } } },
    { name = 'Unlocking a Myth: White Mage', group = 'Jeuno', desc = 'White Mage weapon skill quest: bring Zalsuhm a Werebuster with 250 weapon skill points to learn Mystic Boon. Source: https://vanadreams.org/wiki/#quest-671', steps = { { title = 'Requirements', note = '• Main job White Mage.\n• Werebuster.' }, { title = 'Walkthrough', note = '• Equip the Werebuster, speak to Zalsuhm (H-9), Lower Jeuno, and accept.\n• Earn 250 weapon skill points with it.\n• Trade it to Zalsuhm to learn Mystic Boon.' }, { title = 'Notes', note = '• The weapon is kept.\n• Declining his offer means zoning before he will talk again.' } } },
    { name = 'Wings of Gold', group = 'Jeuno', desc = 'Beastmaster quest from Brutus in Upper Jeuno: get a guiding bell from a Delkfutt\'s Tower chest. Source: https://vanadreams.org/wiki/#quest-672', steps = { { title = 'Requirements', note = '• \'Path of the Beastmaster\' done.\n• Main job Beastmaster, level 40.' }, { title = 'Walkthrough', note = '• Accept from Brutus (G-7), Upper Jeuno.\n• Use a Delkfutt Chest Key on a Treasure Chest in Middle or Upper Delkfutt\'s Tower to get the guiding bell.\n• Return the bell to Brutus.' }, { title = 'Notes', note = '• The chest always gives the bell if you lack it.\n• The bell is removed on completion.' }, { title = 'Reward', note = '• Barbaroi Axe' } } },
    { name = 'Your Crystal Ball', group = 'Jeuno', desc = 'Kurou-Morou in Lower Jeuno sends you to Rockwell in the Maze of Shakhrami with an Ahriman Lens for a Divination Sphere. Source: https://vanadreams.org/wiki/#quest-673', steps = { { title = 'Requirements', note = '• Jeuno fame 2.' }, { title = 'Walkthrough', note = '• Accept from Kurou-Morou (I-7), Lower Jeuno.\n• Get an Ahriman Lens.\n• Enter Maze of Shakhrami via Attohwa Chasm (G-10) and trade the lens to Rockwell.\n• After about a minute, speak to Rockwell for the Divination Sphere.\n• Trade the sphere to Kurou-Morou.' }, { title = 'Notes', note = '• Keep one inventory slot free.\n• Raises San d\'Oria, Bastok and Windurst fame.' }, { title = 'Reward', note = '• Divination Sphere\n• Title: Fortune Teller in Training' } } },
    { name = 'Helpers for Jeuno quests', group = 'Jeuno', desc = 'Not a standalone quest; a helper entry for the Gobbiebag, Unlocking a Myth and Borghertz hand-armor quests. Source: https://vanadreams.org/wiki/#quest-674', steps = {  } },
    { name = 'A Bitter Past', group = 'Other Areas', desc = 'Frescheque in Tavnazian Safehold wants a tiny wristlet taken from two orc NMs in Lufaise Meadows. Source: https://vanadreams.org/wiki/#quest-675', steps = { { title = 'Requirements', note = '• Tavnazian Safehold access.' }, { title = 'Walkthrough', note = '• Accept from Frescheque, Tavnazian Safehold.\n• Speak to Raminey (Map 1, J-7), then Equette.\n• In Lufaise Meadows, check the ??? (I-8) to spawn Blackbone Frazdiz and Rainbringer Yjatvot.\n• Kill both, then check the ??? again for the tiny wristlet.\n• Bring it to Frescheque.' }, { title = 'Reward', note = '• Yinyang Lorgnette' } } },
    { name = 'A Hard Day\'s Knight', group = 'Other Areas', desc = 'Quelveuiat in Tavnazian Safehold asks you to kill Splinterspine Grukjuk in Lufaise Meadows. Source: https://vanadreams.org/wiki/#quest-676', steps = { { title = 'Walkthrough', note = '• Accept from Quelveuiat, Tavnazian Safehold.\n• In Lufaise Meadows, check the ??? (H-10) to spawn Splinterspine Grukjuk and defeat it.\n• Report to Quelveuiat.' }, { title = 'Notes', note = '• Afterward, trade him a Sealion Crest Key plus a Coral Crest Key for the Temple Knight key.' }, { title = 'Reward', note = '• 2,100 gil\n• Title: Tavnazian Squire' } } },
    { name = 'An Explorer\'s Footsteps', group = 'Other Areas', desc = 'Abelard in Selbina has you collect clay tablet rubbings from seventeen Stone Monuments. Source: https://vanadreams.org/wiki/#quest-677', steps = { { title = 'Requirements', note = '• Level 10+.' }, { title = 'Walkthrough', note = '• Accept from Abelard (G-9), Selbina, to get a Lump of Selbina Clay.\n• Trade the clay to the Stone Monument in the named zone for a Clay Tablet.\n• Turn the tablet in to Abelard for gil and new clay.\n• Repeat for all seventeen monuments in any order.' }, { title = 'Monuments', note = '• West/East Ronfaure, La Theine Plateau, Valkurm Dunes, Jugner Forest, Batallia Downs, North/South Gustaberg, Konschtat Highlands, Pashhow Marshlands, Rolanberry Fields, West/East Sarutabaruta, Tahrongi Canyon, Buburimu Peninsula, Meriphataud Mountains, Sauromugue Champaign.\n• Wings of the Goddess versions count.\n• Duplicates give new clay only.' }, { title = 'Reward', note = '• Clay Tablet, Selbina Clay\n• All seventeen: map of the Crawlers\' Nest' } } },
    { name = 'Behind the Smile', group = 'Other Areas', desc = 'Enaremand in Tavnazian Safehold needs red oil from Carpenters\' Landing. Source: https://vanadreams.org/wiki/#quest-678', steps = { { title = 'Requirements', note = '• It\'s Raining Mannequins done.' }, { title = 'Walkthrough', note = '• Speak to Enaremand (Map 1, J-7), Tavnazian Safehold.\n• Speak to Fyi Chalmwoh (G-8), Mhaura.\n• In Carpenters\' Landing, check the ??? (Map 1, I-10) to spawn Bullheaded Grosvez and kill it.\n• Check the ??? again for the red oil.\n• Return to Enaremand.' }, { title = 'Notes', note = '• Red oil is removed on completion.' }, { title = 'Reward', note = '• Mannequin Pumps' } } },
    { name = 'Better The Demon You Know', group = 'Other Areas', desc = 'Koblakiq in Oldton Movalpolos needs a Demon Pen and Zeelozok\'s earplug from Castle Zvahl Baileys. Source: https://vanadreams.org/wiki/#quest-679', steps = { { title = 'Requirements', note = '• For the Birds done, then zone.' }, { title = 'Walkthrough', note = '• Enter Oldton Movalpolos via North Gustaberg (K-6); accept from Koblakiq (H-11).\n• Trade him a Demon Pen; wait about a minute and speak again.\n• Enter Castle Zvahl Baileys via Xarcabard (D-7); check the ??? (Map 2, I-8) to spawn Marquis Andrealphus (Map 2, H-8) and group, and defeat them.\n• Check the ??? again for Zeelozok\'s earplug.\n• Speak to Koblakiq to finish.' }, { title = 'Notes', note = '• Zoning before taking the earplug means refighting.' }, { title = 'Reward', note = '• Goblin Grenade\n• Title: Apostate for Hire' } } },
    { name = 'Bombs Away!', group = 'Other Areas', desc = 'Repeatable: give Buffalostalker Dodzbraz in Uleguerand Range two Cluster Cores. Source: https://vanadreams.org/wiki/#quest-680', steps = { { title = 'Walkthrough', note = '• Accept from Buffalostalker Dodzbraz (F-9), Uleguerand Range.\n• Get 2 Cluster Cores from bombs.\n• Trade both to him.' }, { title = 'Reward', note = '• Shu\'Meyo Salt' } } },
    { name = 'Confessions of a Bellmaker', group = 'Other Areas', desc = 'Carry the ornamented scroll from Riverne - Site #A01 to Bastok and San d\'Oria, then defeat an Arcane Phantasm. Source: https://vanadreams.org/wiki/#quest-681', steps = { { title = 'Walkthrough', note = '• Check the Stone Monument (Map 2, D-7) in Riverne - Site #A01 to get the ornamented scroll.\n• Speak to Reinberta (H-8), Bastok Markets.\n• Speak to Mevreauche (E-6), Northern San d\'Oria.\n• Back at the monument, watch the scene.\n• Check it again to spawn the Arcane Phantasm and defeat it.\n• Check it once more for the last scene.' }, { title = 'Notes', note = '• Scroll is removed at the end.' }, { title = 'Reward', note = '• Minstrel\'s Dagger' } } },
    { name = 'Elder Memories', group = 'Other Areas', desc = 'Subjob unlock from Isacio in Selbina using three trade items. Source: https://vanadreams.org/wiki/#quest-682', steps = { { title = 'Requirements', note = '• Level 18+.\n• The Old Lady not started.\n• Magicked Skull, Damselfly Worm, Crab Apron.' }, { title = 'Walkthrough', note = '• Accept from Isacio (G-10), Selbina.\n• Trade the Magicked Skull.\n• Trade the Damselfly Worm.\n• Trade the Crab Apron to unlock subjobs.' }, { title = 'Notes', note = '• Vera in Mhaura has only extra lines.\n• Talk to Isacio between trades for a reminder.' }, { title = 'Reward', note = '• Copper Voucher' } } },
    { name = 'Elderly Pursuits', group = 'Other Areas', desc = 'Take Despachiaire\'s antique amulet to San d\'Oria and back, with a fight in Carpenters\' Landing. Source: https://vanadreams.org/wiki/#quest-683', steps = { { title = 'Requirements', note = '• Secrets of Ovens Lost done.' }, { title = 'Walkthrough', note = '• Get the antique amulet from Despachiaire (Map 1, K-10), Tavnazian Safehold.\n• Show it to Rouva (I-8), Southern San d\'Oria.\n• In Carpenters\' Landing, check the ??? (Map 1, F-9) to spawn Para and kill it.\n• Check the ??? again; the amulet becomes the cathedral medallion.\n• Show the medallion to Rouva.\n• Return to Despachiaire.' }, { title = 'Notes', note = '• Zoning out after the fight resets that step.\n• Medallion is removed at the end.' }, { title = 'Reward', note = '• Elegant Ribbon' } } },
    { name = 'For the Birds', group = 'Other Areas', desc = 'Koblakiq in Oldton Movalpolos wants intelligence from Castle Oztroja and Beadeaux. Source: https://vanadreams.org/wiki/#quest-684', steps = { { title = 'Requirements', note = '• Missionary Moblin done, then zone.' }, { title = 'Walkthrough', note = '• Enter Oldton Movalpolos via North Gustaberg (K-6); accept from Koblakiq (H-11).\n• Enter Castle Oztroja via Meriphataud Mountains (L-8); trade an Arnica Root to Daa Bola the Seer.\n• Zone, then get the glittering fragment from Koblakiq.\n• Enter Beadeaux via Pashhow Marshlands (L-11); speak to GeFhu Yagudoeye to spawn 2 Magnes Quadav and 2 Nickel Quadav; kill all four.\n• Speak to GeFhu Yagudoeye again for the scene.\n• Report to Koblakiq.' }, { title = 'Notes', note = '• Fragment is taken when the Quadav spawn.\n• Leaving Beadeaux mid-fight resets kills.' }, { title = 'Reward', note = '• Jaguar Mantle' } } },
    { name = 'Give a Moogle a Break', group = 'Other Areas', desc = 'Mog House quest: give your Moogle a Power Bow and Beetle Ring to enlarge the Mog Safe. Source: https://vanadreams.org/wiki/#quest-685', steps = { { title = 'Requirements', note = '• Home nation fame 3.\n• Bronze Bed placed in your home-nation Mog House.' }, { title = 'Walkthrough', note = '• With the Bronze Bed placed, wait a minute and talk to your Moogle; agree to help.\n• Get a Power Bow and a Beetle Ring and trade both.\n• Wait a minute, then talk to the Moogle again.' }, { title = 'Reward', note = '• Larger Mog Safe\n• Title: Mogs Kind Master' } } },
    { name = 'Go! Go! Gobmuffin!', group = 'Other Areas', desc = 'Epinolle in Tavnazian Safehold asks you to kill three goblin NMs in Riverne - Site #B01. Source: https://vanadreams.org/wiki/#quest-686', steps = { { title = 'Requirements', note = '• CoP mission \'Sheltering Doubt\' done.' }, { title = 'Walkthrough', note = '• Accept from Epinolle (Map 2, F-7), Tavnazian Safehold.\n• In Riverne - Site #B01, check the Spatial Displacement to spawn the goblins.\n• Kill Book Browser Bokabraq, Chemical Cook Chemachiq and Spell Spitter Spilospok.\n• Return to Epinolle.' }, { title = 'Notes', note = '• All three in one visit; zoning resets.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP\n• Key item: map of Cape Riverne' } } },
    { name = 'In Search of the Truth', group = 'Other Areas', desc = 'For Tressia in Tavnazian Safehold, question four residents and follow a water trail with the Shaded Cruse. Source: https://vanadreams.org/wiki/#quest-687', steps = { { title = 'Requirements', note = '• CoP progress past Darkness Named.' }, { title = 'Walkthrough', note = '• Start with Tressia, Tavnazian Safehold.\n• Speak to Raminey (Map 1, J-7), Zadant, Fouagine and Noam (Map 2, G-9).\n• Report to Tressia, then talk to her again.\n• Check the first marked spot for the Shaded Cruse; follow the water trail through the next three spots in order.\n• At the final spot, pour out the Shaded Cruse.\n• Talk to Tressia, then Ondieulix, to finish.' }, { title = 'Reward', note = '• Gramary Cape' } } },
    { name = 'Inside the Belly', group = 'Other Areas', desc = 'Fishing quest: trade listed fish to Zaldon in Selbina for gil and possible bonus items; keeps working after completion. Source: https://vanadreams.org/wiki/#quest-688', steps = { { title = 'Requirements', note = '• The Real Gift done.\n• Fishing skill 30+.' }, { title = 'Walkthrough', note = '• Accept from Zaldon (H-9), Selbina.\n• Catch a fish on his list (list depends on your skill).\n• Trade it to Zaldon.' }, { title = 'Notes', note = '• Further trades keep paying gil plus a chance at a bonus.\n• Pay scales with fish rarity; some fish give titles like Ace Angler.' }, { title = 'Reward', note = '• 350 gil\n• One of 115 items, e.g. Grimmonite, Gold Ring, Mythril Ring, Silver Ring, Ryugu Titan, Mercurial Sword, Giant Donko, Bkn. Halcyon Rod, Jungle Catfish, Bkn. Hume Rod, Giant Chirai, Twinthread\n• Title: Ace Angler' } } },
    { name = 'It\'s Raining Mannequins!', group = 'Other Areas', desc = 'Gather five mannequin parts for Fyi Chalmwoh in Mhaura to get a mannequin of your race. Source: https://vanadreams.org/wiki/#quest-689', steps = { { title = 'Walkthrough', note = '• Speak to Fyi Chalmwoh (G-8), Mhaura.\n• Get Ye Olde Mannequin Catalogue from Ramona (H-9), Selbina.\n• Get the mannequin joint diagrams from Cheupirudaux (F-3), Northern San d\'Oria.\n• Obtain Mannequin Head, Body, Hands, Legs and Feet; trade all five to Fyi Chalmwoh.\n• Wait about a minute, then collect your mannequin.' }, { title = 'Notes', note = '• Need one free inventory slot.' }, { title = 'Reward', note = '• H♂ Mannequin' } } },
    { name = 'Knocking on Forbidden Doors', group = 'Other Areas', desc = 'Find the mire incense in Misareaux Coast, kill Alsha, and take Better Humes and Mannequins to Mhaura. Source: https://vanadreams.org/wiki/#quest-690', steps = { { title = 'Requirements', note = '• Behind the Smile done.' }, { title = 'Walkthrough', note = '• Accept from Enaremand (Map 1, J-7), Tavnazian Safehold; then speak to Chemioue.\n• Climb the marked Wooden Ladder in Phomiuna Aqueducts for a scene.\n• In Misareaux Coast, check the ??? at the river\'s end for the mire incense.\n• Check the other ???, watch the scene, check again to spawn Alsha, and kill it.\n• Check that ??? once more for Better Humes and Mannequins.\n• Bring it to Fyi Chalmwoh (G-8), Mhaura.' }, { title = 'Notes', note = '• Unlocks buying, trading and re-posing mannequins for gil.' }, { title = 'Reward', note = '• H♂ Mannequin' } } },
    { name = 'Missionery Moblin', group = 'Other Areas', desc = 'Give Koblakiq in Oldton Movalpolos a Soiled Letter. Source: https://vanadreams.org/wiki/#quest-691', steps = { { title = 'Walkthrough', note = '• Enter Oldton Movalpolos via North Gustaberg (K-6); accept from Koblakiq (H-11).\n• Obtain a Soiled Letter and trade it to him.' }, { title = 'Notes', note = '• Zone before he will talk again.' }, { title = 'Reward', note = '• 4,000 gil' } } },
    { name = 'Monstrosity', group = 'Other Areas', desc = 'Unlocks Monstrosity: trade a starter item to a Suspicious NPC in a home city, then enter the Feretory. Source: https://vanadreams.org/wiki/#quest-692', steps = { { title = 'Requirements', note = '• Monstrosity enabled on the server.' }, { title = 'Walkthrough', note = '• Accept from the Suspicious Hume (E-12), Pashhow Marshlands.\n• Get a Lizard Tail, Rabbit Hide or 2Leaf Mandra Bud.\n• Trade it to the Suspicious Elvaan (L-8) Northern San d\'Oria, Suspicious Galka (K-12) Port Bastok, or Suspicious Tarutaru (M-4) Port Windurst for the ring of supernal disjunction.\n• Take the Odyssean Passage into the Feretory and watch the scene.' }, { title = 'Notes', note = '• Starting species: Lizard Tail = lizard, Rabbit Hide = rabbit, 2Leaf Mandra Bud = mandragora.' } } },
    { name = 'Moogles in the Wild', group = 'Other Areas', desc = 'Give your Moogle a Raptor Mantle and Wool Hat for 10 more slots in each Mog Safe. Source: https://vanadreams.org/wiki/#quest-693', steps = { { title = 'Requirements', note = '• The Moogle Picnic done.\n• Home nation fame 7.\n• Bed placed in your home-nation Mog House.' }, { title = 'Walkthrough', note = '• After placing the bed and waiting briefly, accept the Moogle\'s request.\n• Trade a Raptor Mantle and a Wool Hat together.\n• Wait briefly and talk to the Moogle again.' }, { title = 'Reward', note = '• +10 slots in both Mog Safes\n• Title: Mogs Loving Master' } } },
    { name = 'Paradise Salvation and Maps', group = 'Other Areas', desc = 'Find a Piece of Ripped Floorplans in a Sacrarium chest and tell Nivorajean where it was. Source: https://vanadreams.org/wiki/#quest-694', steps = { { title = 'Requirements', note = '• CoP mission The Savage done.' }, { title = 'Walkthrough', note = '• Accept from Nivorajean, Tavnazian Safehold.\n• Open a Sacrarium Treasure Chest for a Piece of Ripped Floorplans.\n• Tell Nivorajean the chest location.\n• Wait one Vana\'diel day and speak to him again.' }, { title = 'Notes', note = '• Wrong location means searching again.\n• Eight chest spots; only the one you opened counts.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP\n• Key item: map of the Sacrarium' } } },
    { name = 'Petals for Parelbriaux', group = 'Other Areas', desc = 'Fetch a particularly poignant petal from Lufaise Meadows for Ondieulix. Source: https://vanadreams.org/wiki/#quest-695', steps = { { title = 'Requirements', note = '• CoP mission Darkness Named done.' }, { title = 'Walkthrough', note = '• In Tavnazian Safehold, speak to Chemioue, Parelbriaux, then Ondieulix to accept.\n• In fog, check the ??? (G-6) in Lufaise Meadows to spawn Baumesel and kill it.\n• Check the ??? again for the petal.\n• Give it to Ondieulix.' }, { title = 'Notes', note = '• Baumesel needs foggy weather.\n• Zoning before taking the petal may require another kill.' }, { title = 'Reward', note = '• Powerful Rope\n• Title: Putrid Purveyor of Pungent Petals' } } },
    { name = 'Rycharde the Chef', group = 'Other Areas', desc = 'Bring Rycharde in Mhaura two Dhalmel Meat. Source: https://vanadreams.org/wiki/#quest-697', steps = { { title = 'Walkthrough', note = '• Ask Rycharde (H-8), Mhaura, for work.\n• Speak to Take (I-8), then accept from Rycharde.\n• Trade him 2 Dhalmel Meat.' }, { title = 'Notes', note = '• One meat is not enough.\n• If you declined, talk to him again.' }, { title = 'Reward', note = '• 1,500 gil\n• Title: Purveyor in Training\n• Windurst fame +20' } } },
    { name = 'Way of the Cook', group = 'Other Areas', desc = 'Deliver a Beehive Chip and Dhalmel Meat to Rycharde in Mhaura within three Vana\'diel days. Source: https://vanadreams.org/wiki/#quest-698', steps = { { title = 'Requirements', note = '• Rycharde the Chef done, 8+ Vana\'diel days ago.\n• Windurst fame 3.' }, { title = 'Walkthrough', note = '• Accept from Rycharde (H-8), Mhaura.\n• Trade a Beehive Chip and a Dhalmel Meat within three Vana\'diel days.' }, { title = 'Notes', note = '• Late delivery still completes, for less pay.' }, { title = 'Reward', note = '• Title: One Star Purveyor\n• Windurst fame +20' } } },
    { name = 'Unending Chase', group = 'Other Areas', desc = 'Bring Rycharde in Mhaura a Puffball. Source: https://vanadreams.org/wiki/#quest-699', steps = { { title = 'Requirements', note = '• Way of the Cook done.\n• Windurst fame 3.\n• 7+ Vana\'diel days after Rycharde the Chef.' }, { title = 'Walkthrough', note = '• Accept from Rycharde (H-8), Mhaura.\n• Trade him a Puffball.' }, { title = 'Reward', note = '• 2,100 gil\n• Title: Two Star Purveyor\n• Windurst fame +30' } } },
    { name = 'His Name is Valgeir', group = 'Other Areas', desc = 'Deliver Rycharde\'s Aragoneu pizza from Mhaura to Valgeir in Selbina. Source: https://vanadreams.org/wiki/#quest-700', steps = { { title = 'Requirements', note = '• Unending Chase done.\n• Windurst fame 3+.\n• 2+ Vana\'diel days since last completion.' }, { title = 'Walkthrough', note = '• Accept from Rycharde (H-8), Mhaura, to get the Aragoneu pizza.\n• Optionally take the one-time free ferry from Felisa (I-9).\n• Give the pizza to Valgeir (I-8), Selbina.\n• Return to Rycharde.' }, { title = 'Reward', note = '• 2,000 gil\n• Key item: map of the Toraimarai Canal\n• Windurst fame +40' } } },
    { name = 'Expertise', group = 'Other Areas', desc = 'For Take in Mhaura, have Valgeir in Selbina cook land crab bisque. Source: https://vanadreams.org/wiki/#quest-701', steps = { { title = 'Requirements', note = '• His Name is Valgeir done.\n• Windurst fame 3.\n• 8+ Vana\'diel days since last completion.' }, { title = 'Walkthrough', note = '• Accept from Take (I-8), Mhaura.\n• Speak to Valgeir (I-8), Selbina, and trade a Scream Fungus and Land Crab Meat.\n• Wait one Vana\'diel day (about an hour real time), then get the land crab bisque from Valgeir.\n• Deliver it to Take.' }, { title = 'Notes', note = '• Repeatable after a short wait.' }, { title = 'Reward', note = '• Tableware Set\n• Title: Three Star Purveyor' } } },
    { name = 'The Clue', group = 'Other Areas', desc = 'Bring Rycharde in Mhaura four Crawler Eggs. Source: https://vanadreams.org/wiki/#quest-702', steps = { { title = 'Requirements', note = '• Expertise done.\n• Windurst fame 5.\n• 7+ Vana\'diel days after Rycharde the Chef.' }, { title = 'Walkthrough', note = '• Accept from Rycharde (H-8), Mhaura.\n• Trade him 4 Crawler Eggs.' }, { title = 'Reward', note = '• 3,000 gil\n• Title: Four Star Purveyor\n• Windurst fame +50' } } },
    { name = 'The Basics', group = 'Other Areas', desc = 'Carry Mhauran couscous to Valgeir in Selbina and return a Baked Popoto to Rycharde. Source: https://vanadreams.org/wiki/#quest-703', steps = { { title = 'Requirements', note = '• The Clue done, at least a week ago.\n• Windurst fame 5.' }, { title = 'Walkthrough', note = '• Accept from Rycharde (H-8), Mhaura, to get Mhauran couscous.\n• Give it to Valgeir (I-8), Selbina, for a Baked Popoto.\n• Trade the Baked Popoto to Rycharde.' }, { title = 'Reward', note = '• Tea Set, Baked Popoto\n• Title: Five Star Purveyor\n• Windurst fame +60' } } },
    { name = 'Recycling Rods', group = 'Other Areas', desc = 'Give Keshab-Menjab in Mhaura a Clean Snap Rod. Source: https://vanadreams.org/wiki/#quest-704', steps = { { title = 'Walkthrough', note = '• Accept from Keshab-Menjab (H-9), Mhaura.\n• Trade him a Clean Snap Rod.' }, { title = 'Reward', note = '• 1,500 gil' } } },
    { name = 'Requiem of Sin', group = 'Other Areas', desc = 'Use a letter from Shikaree Y to win the Requiem of Sin battlefield in Boneyard Gully. Source: https://vanadreams.org/wiki/#quest-705', steps = { { title = 'Requirements', note = '• Tango with a Tracker done.' }, { title = 'Walkthrough', note = '• Get the letter from Shikaree Y from Despachiaire (Map 1, K-10), Tavnazian Safehold.\n• Enter Requiem of Sin in Boneyard Gully and win.' }, { title = 'Notes', note = '• Replacement letter once per conquest tally.\n• After completion, a Letter from the Mithran Trackers is available once per tally.' }, { title = 'Reward', note = '• Title: Disciple of Justice' } } },
    { name = 'Spice Gals', group = 'Other Areas', desc = 'Retrieve the Tavnazian cookbook for Jonette in Tavnazian Safehold; repeatable each conquest tally. Source: https://vanadreams.org/wiki/#quest-707', steps = { { title = 'Requirements', note = '• San d\'Oria quest Spice Gals done.\n• Not completed since the last tally.' }, { title = 'Walkthrough', note = '• Speak to Despachiaire (Map 1, K-10), Tavnazian Safehold.\n• Accept from Jonette (Map 2, G-9).\n• Check the ??? in the Sacrarium or Phomiuna Aqueducts for the Tavnazian cookbook.\n• Bring it to Jonette.' }, { title = 'Reward', note = '• Miratete\'s Mem.' } } },
    { name = 'Tango With a Tracker', group = 'Other Areas', desc = 'Use a letter from Shikaree X to win the Tango with a Tracker battlefield in Boneyard Gully. Source: https://vanadreams.org/wiki/#quest-708', steps = { { title = 'Requirements', note = '• CoP mission \'A Fate Decided\' done.' }, { title = 'Walkthrough', note = '• Get the letter from Shikaree X from Despachiaire (Map 1, K-10), Tavnazian Safehold.\n• Enter Tango with a Tracker in Boneyard Gully (this accepts the quest) and win.' }, { title = 'Notes', note = '• On a loss, get a new letter after the next conquest tally.' }, { title = 'Reward', note = '• 10,000 gil\n• Title: Sin Hunter Hunter' } } },
    { name = 'Test My Mettle', group = 'Other Areas', desc = 'Repeatable bet with Devean in Selbina: fetch Power Sandals from a Davoi jar before time runs out. Source: https://vanadreams.org/wiki/#quest-709', steps = { { title = 'Requirements', note = '• Level 10+, nation rank 2+.\n• Selbina/Rabao fame 2.\n• Once per Japanese day.' }, { title = 'Walkthrough', note = '• Speak to Devean (I-8), Selbina; pick a bet (100, 250, 500 or 1,000 gil) and time limit.\n• Enter Davoi via Jugner Forest (G-12); check the Jar (F-7) for Power Sandals.\n• Trade the sandals to Devean before time expires.' }, { title = 'Notes', note = '• Shorter limits give a bigger multiplier.\n• Late = bet lost; repeat after Japanese midnight.\n• The Jar relocates after use.' }, { title = 'Reward', note = '• Power Sandals' } } },
    { name = 'The Call of the Sea', group = 'Other Areas', desc = 'Kill the Bloody Coffin on Misareaux Coast for a whispering conch. Source: https://vanadreams.org/wiki/#quest-710', steps = { { title = 'Walkthrough', note = '• In Tavnazian Safehold speak to Equette, Leporaitceau (Map 1, J-8), then Anteurephiaux (Map 1, J-8) to accept.\n• In Misareaux Coast, check the ??? (K-12) to spawn the Bloody Coffin and kill it.\n• Check the ??? again for the whispering conch.\n• Give it to Anteurephiaux, then speak to Equette.' }, { title = 'Notes', note = '• If the Bloody Coffin is already up, wait for despawn.' }, { title = 'Reward', note = '• Memento Muffler' } } },
    { name = 'The Gift', group = 'Other Areas', desc = 'Bring Oswald in Selbina a Danceshroom. Source: https://vanadreams.org/wiki/#quest-711', steps = { { title = 'Requirements', note = '• Under the Sea done.\n• The Sand Charm accepted or done.\n• Fishing enabled.' }, { title = 'Walkthrough', note = '• Accept from Oswald (I-9), Selbina.\n• Trade him a Danceshroom.' }, { title = 'Reward', note = '• Sleep Dagger\n• Title: Savior of Love' } } },
    { name = 'The Moogle\'s Picnic!', group = 'Other Areas', desc = 'Give your Moogle a Shrimp Lure and Selbina Butter for 10 more slots in each Mog Safe. Source: https://vanadreams.org/wiki/#quest-712', steps = { { title = 'Requirements', note = '• \'Give a Moogle a Break\' done.\n• Home nation fame 5+.\n• Bed placed in home-nation Mog House for 1+ minute.' }, { title = 'Walkthrough', note = '• Accept the picnic request from your Moogle.\n• Trade a Shrimp Lure and a Selbina Butter.\n• Wait about a minute and talk again.' }, { title = 'Notes', note = '• No offer menu: zone and retry.' }, { title = 'Reward', note = '• +10 slots per Mog Safe\n• Title: Mogs Exceptionally Kind Master' } } },
    { name = 'The Old Lady', group = 'Other Areas', desc = 'Subjob unlock from Vera in Mhaura using three trade items. Source: https://vanadreams.org/wiki/#quest-713', steps = { { title = 'Requirements', note = '• Subjob quest level (18 on most servers).\n• Elder Memories not started or done.' }, { title = 'Walkthrough', note = '• Accept from Vera (G-10), Mhaura.\n• Trade a Wild Rabbit Tail.\n• Trade a Dhalmel Saliva.\n• Trade a Bloody Robe.' }, { title = 'Notes', note = '• Showing Gilgamesh\'s introductory letter skips the items.' }, { title = 'Reward', note = '• Copper Voucher' } } },
    { name = 'The Real Gift', group = 'Other Areas', desc = 'Bring Oswald in Selbina a Shall Shell for a fishing rod. Source: https://vanadreams.org/wiki/#quest-714', steps = { { title = 'Requirements', note = '• Under the Sea and The Sand Charm done.' }, { title = 'Walkthrough', note = '• Accept from Oswald (I-9), Selbina.\n• Trade him a Shall Shell.' }, { title = 'Reward', note = '• Glass Fiber F. Rod\n• Title: The Love Doctor' } } },
    { name = 'The Rescue', group = 'Other Areas', desc = 'Free a captive trader in Beadeaux for Thunder Hawk in Selbina. Source: https://vanadreams.org/wiki/#quest-715', steps = { { title = 'Requirements', note = '• Selbina/Rabao fame 1.' }, { title = 'Walkthrough', note = '• Accept from Thunder Hawk (F-9), Selbina.\n• Enter Beadeaux via Pashhow Marshlands (L-11); trade a Quadav Charm to the Jail Door (Map 1, I-8) for the Trader\'s Sack.\n• Return to Thunder Hawk.' }, { title = 'Reward', note = '• 5,000 gil, 2,000 EXP\n• Key item: map of the Ranguemont Pass\n• Title: Honorary Citizen of Selbina' } } },
    { name = 'The Sand Charm', group = 'Other Areas', desc = 'Hear a lost sailor\'s story in Mhaura and give Celestina a Sand Charm. Source: https://vanadreams.org/wiki/#quest-716', steps = { { title = 'Requirements', note = '• Windurst fame 2.' }, { title = 'Walkthrough', note = '• Speak to Blandine on the town side of Mhaura\'s docks.\n• Speak to Zexu (I-9), then Blandine again.\n• Accept from Celestina.\n• Trade her a Sand Charm.' }, { title = 'Reward', note = '• 2,000 gil, 2,000 EXP\n• Key item: map of Bostaunieux Oubliette\n• Windurst fame +40' } } },
    { name = 'Under the Sea', group = 'Other Areas', desc = 'Recover Oswald\'s etched ring from a Fat Greedie via Zaldon in Selbina. Source: https://vanadreams.org/wiki/#quest-717', steps = { { title = 'Requirements', note = '• Selbina/Rabao fame 2+.\n• Fishing available.' }, { title = 'Walkthrough', note = '• In Selbina speak to Yaya (H-9), Oswald (I-9), Jimaida (H-9), then Zaldon (H-9).\n• Catch a Fat Greedie and trade it to Zaldon; repeat until he finds the etched ring (20% per try).\n• Bring the ring to Oswald.' }, { title = 'Notes', note = '• Each Fat Greedie is consumed regardless.' }, { title = 'Reward', note = '• Amber Earring\n• Title: Lil Cupid' } } },
    { name = 'Unforgiven', group = 'Other Areas', desc = 'Find the alabaster hairpin for Elysia in Tavnazian Safehold. Source: https://vanadreams.org/wiki/#quest-718', steps = { { title = 'Requirements', note = '• CoP mission An Invitation West or later.' }, { title = 'Walkthrough', note = '• Speak to Elysia (Map 2, G-10), Tavnazian Safehold.\n• Check the ??? (Map 1, K-9) for the alabaster hairpin.\n• Return it to Elysia, then speak to Pradiulot.\n• Afterward, speak to Elysia and Pradiulot for closing scenes.' }, { title = 'Reward', note = '• 2,000 EXP\n• Key item: map of Tavnazia' } } },
    { name = 'Uninvited Guests', group = 'Other Areas', desc = 'Repeatable: win the Uninvited Guests battlefield in Monarch Linn for Justinius in Tavnazian Safehold. Source: https://vanadreams.org/wiki/#quest-719', steps = { { title = 'Requirements', note = '• CoP mission The Savage done.' }, { title = 'Walkthrough', note = '• Accept from Justinius, Tavnazian Safehold, to get the Monarch Linn patrol permit.\n• Enter Uninvited Guests in Monarch Linn and win.\n• Return to Justinius.' }, { title = 'Notes', note = '• Failure or repeat requires waiting for the next conquest tally.\n• Reward is random; first clear also gives 10,000 gil.' }, { title = 'Reward', note = '• One of 36 items, e.g. Armoire, Adaman Ore, Aluminum Ore, Elm Log, Orichalcum Ore, Behemoth Hide, Adamantoise Shell, Raxa, Angel Skin, Siren\'s Hair, Mannequin Head, Mannequin Body\n• Title: Monarch Linn Patrol Guard' } } },
    { name = 'Waking the Beast', group = 'Other Areas', desc = 'Summoner quest to wake Carbuncle: beat the avatars in all six Cloisters, then fight at Full Moon Fountain. Source: https://vanadreams.org/wiki/#quest-720', steps = { { title = 'Walkthrough', note = '• Examine the ??? at La Theine Plateau (G-6); the cutscene gives the rainbow resonator.\n• Clear the Waking the Beast fight in the Cloisters of Flames, Frost, Gales, Storms, Tides and Tremors; each grants an Eye.\n• Holding the six Eyes plus the resonator, win Waking the Beast at Full Moon Fountain for the faded ruby.\n• Examine the La Theine ??? (G-6) with the faded ruby to finish.' }, { title = 'Notes', note = '• Avatars: Ifrit, Garuda, Shiva, Ramuh, Leviathan, Titan.\n• The Eyes and resonator are consumed by the final fight.\n• Repeatable for extra titles, max once per conquest week.\n• Your pick in the final fight sets the title.' }, { title = 'Reward', note = '• Carbuncle\'s Pole' } } },
    { name = 'X Marks the Spot', group = 'Other Areas', desc = 'Tavnazian Safehold errand: bring Odeya a Tavnazian Liver and inspect a gate in Phomiuna Aqueducts. Source: https://vanadreams.org/wiki/#quest-721', steps = { { title = 'Needs', note = '• Chains of Promathia progress up to \'Ancient Vows\'' }, { title = 'Walkthrough', note = '• Accept from Despachiaire (Map 1, K-10), Tavnazian Safehold.\n• Speak with Parelbriaux, then Odeya (Map 1, J-10).\n• Hand Odeya a Tavnazian Liver.\n• In Phomiuna Aqueducts, examine the second Hidden Hallway gate.\n• Report to Odeya to finish.' }, { title = 'Reward', note = '• 4,000 gil' } } },
    { name = 'Helpers for otherAreas quests', group = 'Other Areas', desc = 'Support entry for the Test My Mettle quest in Davoi, not a standalone quest. Source: https://vanadreams.org/wiki/#quest-722', steps = {  } },
    { name = 'A Question of Taste', group = 'Outlands', desc = 'Courier letters between Kazham and Windurst Waters, then beat Trompe L\'Oeil in the Temple of Uggalepih for a torn painting. Source: https://vanadreams.org/wiki/#quest-723', steps = { { title = 'Needs', note = '• Windurst fame 6\n• A Pose by Any Other Name done (to talk to Angelica)' }, { title = 'Walkthrough', note = '• Get the letter to Angelica from Etteh Sulaej (J-9), Kazham.\n• Give it to Angelica in Windurst Waters; receive "Final Fantasy" and Angelica\'s letter.\n• Report to Etteh Sulaej.\n• In the Temple of Uggalepih, examine the Stone Picture Frame and defeat Trompe L\'Oeil.\n• Examine the frame (Map 1, G-9) again for the ripped "Final Fantasy" painting.\n• Return to Etteh Sulaej.' }, { title = 'Notes', note = '• Failed attempt: frame locked for ~15 minutes.\n• Repeatable; repeats give "Final Fantasy Part II".' }, { title = 'Reward', note = '• 3,000 gil' } } },
    { name = 'Bugi Soden', group = 'Outlands', desc = 'Katana weapon skill quest from Ryoma in Norg that teaches Blade: Ku. Source: https://vanadreams.org/wiki/#quest-724', steps = { { title = 'Needs', note = '• Katana skill 250+\n• Job able to equip the Kodachi of Trials' }, { title = 'Walkthrough', note = '• Accept from Ryoma (H-8), Norg; get the Kodachi of Trials and weapon training guide.\n• Fight with the kodachi until it reaches 300 weapon skill points.\n• Trade it to Ryoma for the map to the Annals of Truth.\n• In Labyrinth of Onzozo, check the ??? (I-5), kill Megapod Megalops, then check it again for the Annals of Truth.\n• Bring the Annals to Ryoma.' }, { title = 'Notes', note = '• Talk to Ryoma to abandon and restart.' }, { title = 'Reward', note = '• Kodachi of Trials\n• Norg fame 20' } } },
    { name = 'Chasing Dreams', group = 'Outlands', desc = 'Errand chain across Rabao, Norg, Korroloka Tunnel, Port Bastok and Selbina ending in the Venerer Ring. Source: https://vanadreams.org/wiki/#quest-725', steps = { { title = 'Walkthrough', note = '• In Rabao, talk to Rudolfo (J-7), then Zoriboh (F-7).\n• In Norg, talk to Sohyon, then Washu (J-8) for Washu\'s flask.\n• Fill it at all four clams in Korroloka Tunnel.\n• Get the storeroom key from Sohyon (J-8) and give it to Gimb (H-9).\n• Talk to Kagetora (F-6) in Port Bastok, then trade 5 Eastern Gems to the Patient Wheel (F-5).\n• Talk to Abelard (G-9) in Selbina.\n• Zone into Lufaise Meadows for a cutscene.\n• Return to Zoriboh (F-7) in Rabao.' }, { title = 'Notes', note = '• Each clam works once.\n• Clam water flask and storeroom key are removed as you advance.' }, { title = 'Reward', note = '• 4,000 gil\n• Venerer Ring' } } },
    { name = 'Cloak and Dagger', group = 'Outlands', desc = 'Dagger weapon skill quest from Jakoh Wahcondalo in Kazham that teaches Evisceration. Source: https://vanadreams.org/wiki/#quest-726', steps = { { title = 'Needs', note = '• Dagger skill 230+\n• Job able to equip the Dagger of Trials\n• No weapon training guide already held' }, { title = 'Walkthrough', note = '• Get the Dagger of Trials and training guide from Jakoh Wahcondalo (J-10), Kazham.\n• Earn 300 weapon skill points with it equipped.\n• Trade it back for the map to the Annals of Truth.\n• Enter Gustav Tunnel from Cape Teriggan (J-5); at the ??? (Map 2, I-9) pop and kill Baronial Bat.\n• Check the ??? again for the Annals of Truth.\n• Give the Annals to Jakoh to learn Evisceration.' }, { title = 'Notes', note = '• Lost dagger: Jakoh replaces it or lets you quit.\n• Baronial Bat must die while you hold the map.' }, { title = 'Reward', note = '• Dagger of Trials\n• Windurst fame 20' } } },
    { name = 'Divine Might', group = 'Outlands', desc = 'Rise of the Zilart quest: craft an Ark Pentasphere, win at Laloff Amphitheater, pick one earring at the Shrine of Ru\'Avitau. Starts with Qu\'Hau Spring in Ro\'Maeve. Source: https://vanadreams.org/wiki/#quest-727', steps = { { title = 'Needs', note = '• ZM \'Ark Angels\' reached or passed\n• Parchment and Illuminink' }, { title = 'Walkthrough', note = '• Accept at the ??? in The Shrine of Ru\'Avitau.\n• Full moon, 18:00-06:00: trade Parchment + Illuminink to Qu\'Hau Spring (H-6), Ro\'Maeve, for the Ark Pentasphere.\n• Win the Divine Might battle at Laloff Amphitheater.\n• At the Shrine ???, pick one: Suppanomimi, Knight\'s Earring, Abyssal Earring, Beastly Earring or Bushinomimi.' }, { title = 'Reward', note = '• One earring of your choice (plus Ark Pentasphere)\n• Title: Pentacide Perpetrator' } } },
    { name = 'Divine Might (Repeat)', group = 'Outlands', desc = 'Repeat version: make moonlight ore and a new Ark Pentasphere, beat the Ark Angels again, choose another earring. Starts with Qu\'Hau Spring in Ro\'Maeve. Source: https://vanadreams.org/wiki/#quest-728', steps = { { title = 'Needs', note = '• Divine Might done\n• Owning fewer Divine Might earrings than the server cap (default 1)' }, { title = 'Walkthrough', note = '• Restart at the ??? in The Shrine of Ru\'Avitau.\n• Full moon night (18:00-06:00): trade Light Ore to Qu\'Hau Spring (H-6), Ro\'Maeve, for moonlight ore.\n• Same conditions: trade 1 Parchment + 1 Illuminink there for an Ark Pentasphere.\n• Win Divine Might at La\'Loff Amphitheater.\n• At the Shrine ???, choose Suppanomimi, Knight\'s Earring, Abyssal Earring, Beastly Earring or Bushinomimi.' }, { title = 'Notes', note = '• Spring trades only work on full-moon nights.\n• Picking an earring again restarts the cycle.' }, { title = 'Reward', note = '• One earring (plus Ark Pentasphere)\n• Title: Pentacide Perpetrator' } } },
    { name = 'Everyone\'s Grudging', group = 'Outlands', desc = 'Kazham quest to break the Rancor Flame curse by killing the Rancor Torch in Den of Rancor. Source: https://vanadreams.org/wiki/#quest-729', steps = { { title = 'Needs', note = '• Windurst fame 7\n• A Question of Taste done\n• Cursed by the Rancor Flame (Den of Rancor)' }, { title = 'Walkthrough', note = '• Talk to Jakoh Wahcondalo (J-10), Kazham.\n• Kill the Rancor Torch in Den of Rancor.\n• Report back to Jakoh.' }, { title = 'Reward', note = '• 11,000 gil\n• Windurst fame 60' } } },
    { name = 'Forge Your Destiny', group = 'Outlands', desc = 'Samurai unlock: bring Jaucribaix a Sacred Branch and Lump of Bomb Steel, then wait for the blade. Starts with Jaucribaix in Norg. Source: https://vanadreams.org/wiki/#quest-730', steps = { { title = 'Needs', note = '• Level 30+' }, { title = 'Walkthrough', note = '• Accept from Jaucribaix (K-8), Norg.\n• Get a Lump of Oriental Steel from Aeka (I-8).\n• Trade it to the ??? (D-8) in Konschtat Highlands, standing right beside it; kill the Forger for Bomb Steel.\n• Get a Sacred Sprig from Ranemaud (I-7).\n• Carrying the sprig, trade a Hatchet to the ??? in The Sanctuary of Zitah and kill the Guardian Treant.\n• Trade the Sacred Sprig to that ??? for the Sacred Branch.\n• Give Bomb Steel + Sacred Branch to Jaucribaix.\n• Wait ~3 Vana\'diel days and talk to him again.' }, { title = 'Notes', note = '• Replacement steel: 1 Darksteel Ore to Aeka.\n• Replacement sprig: 2 Gold Ore + 1 Platinum Ore to Ranemaud in one trade.' }, { title = 'Reward', note = '• Samurai job unlocked; Mumeito\n• Key item: job gesture: samurai\n• Title: Bushido Blade\n• Norg fame 20' } } },
    { name = 'I\'ll Take the Big Box (NIN AF2)', group = 'Outlands', desc = 'Ninja AF quest: obtain the seance staff and kill Enagakure on the night ferry to Selbina. Starts with Ryoma in Norg. Source: https://vanadreams.org/wiki/#quest-731', steps = { { title = 'Needs', note = '• Ninja main, level 50+\n• Twenty in Pirate Years done' }, { title = 'Walkthrough', note = '• Talk to Ryoma (H-8), Norg.\n• Talk to Ensetsu (I-5), Port Bastok.\n• Talk to Leodarion (F-8), Rabao, and trade him an Oak Pole.\n• After one Vana\'diel day, collect the seance staff from him.\n• Ride the Selbina-bound ship at night and kill Enagakure.\n• Zone into Selbina for the closing cutscene.' }, { title = 'Notes', note = '• Enagakure spawns at night only.' }, { title = 'Reward', note = '• Ninja Hakama\n• Norg fame 20' } } },
    { name = 'Like Shining Leggings', group = 'Outlands', desc = 'Hand ten Rusty Leggings to Heizo. Starts with Heizo in Norg. Source: https://vanadreams.org/wiki/#quest-732', steps = { { title = 'Needs', note = '• Norg fame 3' }, { title = 'Walkthrough', note = '• Accept from Heizo (H-7), Norg.\n• Trade him Rusty Leggings until ten total are delivered.' }, { title = 'Notes', note = '• Partial batches count.\n• Each trade must contain only Rusty Leggings.' }, { title = 'Reward', note = '• Dokumori: Ichi\n• Title: Looks Good in Leggings\n• Norg fame 30' } } },
    { name = 'Like Shining Subligars', group = 'Outlands', desc = 'Hand ten Rusty Subligars to Heiji. Starts with Heiji in Norg. Source: https://vanadreams.org/wiki/#quest-733', steps = { { title = 'Needs', note = '• Norg fame 3+\n• 10 Rusty Subligars' }, { title = 'Walkthrough', note = '• Accept from Heiji (I-7), Norg.\n• Trade Rusty Subligars in any batch size; quest ends at ten.' }, { title = 'Notes', note = '• Talk to Heiji to check your count.\n• Mixed-item trades are rejected.' }, { title = 'Reward', note = '• Kurayami: Ichi\n• Title: Looks Sublime in a Subligar\n• Norg fame 30' } } },
    { name = 'Open Sesame', group = 'Outlands', desc = 'Trade Lokpix a Tremorstone plus one extra item for the loadstone. Starts with Lokpix in Eastern Altepa Desert. Source: https://vanadreams.org/wiki/#quest-734', steps = { { title = 'Walkthrough', note = '• Accept from Lokpix (G-7), Eastern Altepa Desert.\n• Trade a Tremorstone with one of: 1 Meteorite, 1 Soil Gem, or 12 Soil Geodes.' }, { title = 'Reward', note = '• Key item: loadstone' } } },
    { name = 'The Sacred Katana (SAM AF1)', group = 'Outlands', desc = 'Samurai AF1: buy a Mumeito and fetch crystal scales from Isonade for Jaucribaix. Starts with Jaucribaix in Norg. Source: https://vanadreams.org/wiki/#quest-735', steps = { { title = 'Needs', note = '• Samurai main, level 40+\n• Forge Your Destiny done\n• 30,000 gil; 1 Sack of Fish Bait' }, { title = 'Walkthrough', note = '• Accept from Jaucribaix (K-8), Norg.\n• Pay Ranemaud (I-7) 30,000 gil for a Mumeito.\n• Trade the Sack of Fish Bait to the ??? (E-8) in The Sanctuary of Zi\'Tah and kill Isonade.\n• Check the ??? again for the handful of crystal scales.\n• Trade the Mumeito to Jaucribaix.' }, { title = 'Notes', note = '• Ranemaud won\'t sell if you already own a Mumeito.\n• Scales are removed at completion.' }, { title = 'Reward', note = '• Magoroku, Mumeito\n• Norg fame 20' } } },
    { name = 'Yomi Okuri (SAM AF2)', group = 'Outlands', desc = 'Samurai AF2: lay spirits to rest in Labyrinth of Onzozo and Valkurm Dunes for Myochin Sune-Ate. Starts with Jaucribaix in Norg. Source: https://vanadreams.org/wiki/#quest-736', steps = { { title = 'Needs', note = '• Samurai at AF level\n• The Sacred Katana done' }, { title = 'Walkthrough', note = '• Accept from Jaucribaix (K-8), Norg; then speak to Washu (J-8).\n• Trade Washu a Hecteyes Eye, Bastore Sardine, G. Sheep Meat and Frost Turnip for Washu\'s tasty wurst.\n• At the ??? (F-8) in Labyrinth of Onzozo, offer the wurst and kill Ubume; check again for the yomotsu feather.\n• Give the feather to Jaucribaix, zone, and talk again for the Yomotsu Hirasaka.\n• In Valkurm Dunes, 18:00-05:00, use the Hirasaka beside the ??? (B-7); kill Doman or Onryo.\n• Check the ??? to get the faded Yomotsu Hirasaka.\n• Return to Jaucribaix.' }, { title = 'Notes', note = '• The Valkurm fight won\'t start if Doman or Onryo is already up.' }, { title = 'Reward', note = '• Myochin Sune-Ate\n• Norg fame 20' } } },
    { name = 'A Thief in Norg!? (SAM AF3)', group = 'Outlands', desc = 'Samurai AF3: chase the helm thief, beat him in Waughroon Shrine, and have the helm repaired with gold thread. Starts with Jaucribaix in Norg. Source: https://vanadreams.org/wiki/#quest-737', steps = { { title = 'Needs', note = '• Samurai main at AF level\n• Yomi Okuri done' }, { title = 'Walkthrough', note = '• Accept from Jaucribaix (K-8), Norg.\n• Talk to Sanosuke (H-8), Port Jeuno, then Phoochuchu (H-8), Mhaura.\n• Examine the Door in Bastok Mines.\n• Enter Waughroon Shrine for a scene.\n• Get the Banishing Charm from Jaucribaix.\n• Use it in the Waughroon Shrine battle and kill the thief; receive the charred helm.\n• Talk to Jaucribaix and trade him a Spool of Gold Thread.\n• Wait briefly, zone, and talk to him for the Myochin Kabuto.' }, { title = 'Notes', note = '• Jaucribaix replaces a lost Banishing Charm.' }, { title = 'Reward', note = '• Myochin Kabuto, Banishing Charm\n• Title: Paragon of Samurai Excellence\n• Norg fame 20' } } },
    { name = 'Secret of the Damp Scroll', group = 'Outlands', desc = 'Take a Damp Scroll to the Horlais Peak hot springs to uncover Jubaku: Ichi. Starts with Shivivi in Norg. Source: https://vanadreams.org/wiki/#quest-738', steps = { { title = 'Needs', note = '• Norg fame 3; level 10+\n• Damp Scroll' }, { title = 'Walkthrough', note = '• Talk to Shivivi (J-8), Norg, holding the Damp Scroll.\n• Trade the scroll to the Hot Springs (K-8) at Horlais Peak.' }, { title = 'Reward', note = '• Jubaku: Ichi\n• Title: Cracker of the Secret Code\n• Norg fame 30' } } },
    { name = 'Soul Searching', group = 'Outlands', desc = 'Zilart headstone quest: bring the prismatic fragment to the Cermet Headstone. Starts with Cermet Headstone in The Sanctuary of Zi\'Tah. Source: https://vanadreams.org/wiki/#quest-739', steps = { { title = 'Needs', note = '• ZM \'Headstone Pilgrimage\' reached' }, { title = 'Walkthrough', note = '• Get the prismatic fragment key item in the Chamber of Oracles.\n• Examine the Cermet Headstone (I-7) in The Sanctuary of Zi\'Tah.' }, { title = 'Notes', note = '• Without the fragment you only get a stagnant-air message.' }, { title = 'Reward', note = '• Bat Earring\n• Title: Guider of Souls to the Sanctuary' } } },
    { name = 'Stop Your Whining', group = 'Outlands', desc = 'Fill Washu\'s barrel with opo-opo brew from a Yhoator Jungle tree. Starts with Washu in Norg. Source: https://vanadreams.org/wiki/#quest-740', steps = { { title = 'Needs', note = '• Norg fame 4; level 10+' }, { title = 'Walkthrough', note = '• Get the empty barrel from Washu (J-8), Norg.\n• Check the tree ??? (F-8) in Yhoator Jungle to fill it.\n• Return to Washu.' }, { title = 'Notes', note = '• The ??? gives nothing while you hold a full barrel.' }, { title = 'Reward', note = '• Hojo: Ichi\n• Title: Apprentice Sommelier\n• Norg fame 40' } } },
    { name = 'The Firebloom Tree', group = 'Outlands', desc = 'Repeatable Kazham quest: cut four Firebloom vines, burn three in Ifrit\'s Cauldron, and collect wood from the root of the last one. Starts with Firebloom Tree Root in Yuhtunga Jungle. Source: https://vanadreams.org/wiki/#quest-741', steps = { { title = 'Needs', note = '• Windurst fame 6' }, { title = 'Walkthrough', note = '• Accept from Soun Abralah (H-9), Kazham.\n• In Yuhtunga Jungle, cut a vine at each of the four roots (N, S, E, W).\n• Enter Ifrit\'s Cauldron via Yuhtunga (K-5) and use three different Flame Spouts, one vine each.\n• Back in Yuhtunga, examine the root matching the remaining vine for Firebloom Tree wood.\n• Deliver the wood to Soun Abralah.' }, { title = 'Notes', note = '• Cut all four vines before the first Flame Spout.\n• One use per Flame Spout per attempt.\n• Repeatable for gil.' }, { title = 'Reward', note = '• 5,000 gil' } } },
    { name = 'The Kuftal Tour', group = 'Outlands', desc = 'Lead a low-level party to a spot in Kuftal Tunnel for Datta. Starts with Datta in Rabao. Source: https://vanadreams.org/wiki/#quest-742', steps = { { title = 'Needs', note = '• The Gustaberg Tour done\n• Selbina/Rabao fame 3+\n• Party of 2+, everyone level 40 or under' }, { title = 'Walkthrough', note = '• Accept from Datta (F-7), Rabao.\n• Enter Kuftal Tunnel from Western Altepa Desert (I-5) with the party, all within 15 yalms.\n• Examine the ??? (Map 1, H-8) for a cutscene.\n• Report to Datta.' }, { title = 'Notes', note = '• Solo is impossible; any member over 40 blocks the scene.' }, { title = 'Reward', note = '• 8,000 gil\n• Title: Kuftal Tourist' } } },
    { name = 'The Missing Piece', group = 'Outlands', desc = 'Fetch a tablet fragment in Quicksand Caves for Alfesar, then deliver tablet and letter to Northern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-743', steps = { { title = 'Needs', note = '• Selbina/Rabao fame 4+; level 10+' }, { title = 'Walkthrough', note = '• Accept from Alfesar (H-8), Rabao.\n• Examine the ??? in Quicksand Caves for the ancient tablet fragment (it then relocates).\n• Get the tablet of ancient magic and Alfesar\'s letter from him.\n• Bring both to Charlaimagnat (M-7), Northern San d\'Oria.\n• Wait a little and talk to him again.' }, { title = 'Notes', note = '• Raises San d\'Oria and Bastok fame.' }, { title = 'Reward', note = '• Teleport-Altep' } } },
    { name = 'The Potential Within', group = 'Outlands', desc = 'Great Katana weapon skill quest: level the Tachi of Trials and kill Kettenkaefer to learn Tachi: Kasha. Source: https://vanadreams.org/wiki/#quest-744', steps = { { title = 'Needs', note = '• Great Katana skill 250+\n• Can equip the Tachi of Trials' }, { title = 'Walkthrough', note = '• Get the Tachi of Trials and training guide from Jaucribaix (K-8), Norg.\n• Earn 300+ weapon skill points with it.\n• Trade it to Jaucribaix for the map to the Annals of Truth.\n• Enter Kuftal Tunnel from Cape Teriggan (G-10); pop Kettenkaefer at the ??? and kill it.\n• Check the ??? again for the Annals of Truth.\n• Talk to Jaucribaix.' }, { title = 'Notes', note = '• Trading early just gets a \'not ready\' reply.\n• Jaucribaix replaces a lost Tachi.' }, { title = 'Reward', note = '• Tachi of Trials\n• Norg fame 20' } } },
    { name = 'The Sahagin\'s Stash', group = 'Outlands', desc = 'Grab the Sea Serpent Statue from Sea Serpent Grotto for Laisrean. Starts with Laisrean in Norg. Source: https://vanadreams.org/wiki/#quest-745', steps = { { title = 'Needs', note = '• Norg fame 4; level 5+' }, { title = 'Walkthrough', note = '• Accept from Laisrean (H-8), Norg.\n• Click the ??? in Sea Serpent Grotto for the statue.\n• Deliver it to Laisrean.' }, { title = 'Reward', note = '• Utsusemi: Ichi\n• Title: Treasure House Ransacker\n• Norg fame 40' } } },
    { name = 'Trial by Fire', group = 'Outlands', desc = 'Defeat the fire trial in the Cloister of Flames and return the whisper of flames. Starts with Ronta-Onta in Kazham. Source: https://vanadreams.org/wiki/#quest-746', steps = { { title = 'Needs', note = '• Windurst fame 6+' }, { title = 'Walkthrough', note = '• Get the tuning fork of fire from Ronta-Onta (J-9), Kazham.\n• Win Trial by Fire in the Cloister of Flames for the whisper of flames.\n• Return and pick a reward.' }, { title = 'Notes', note = '• Choices: Ifrit\'s Blade, Fire Belt, Fire Ring, Egil\'s Torch, 10,000 gil, or the Ifrit spell (Summoner).\n• Ronta-Onta replaces a lost fork.\n• Repeatable after one Japanese-time day.' }, { title = 'Reward', note = '• One chosen item\n• Windurst fame 60' } } },
    { name = 'Wandering Souls', group = 'Outlands', desc = 'Offer a Rain Lily at the headstone. Starts with Cermet Headstone in Cape Teriggan. Source: https://vanadreams.org/wiki/#quest-747', steps = { { title = 'Walkthrough', note = '• With the quest active, get a Rain Lily.\n• Trade it to the Cermet Headstone (G-5), Cape Teriggan.' }, { title = 'Notes', note = '• Examining without the lily gives only a hint.' }, { title = 'Reward', note = '• Flagellant\'s Rope\n• Title: Bearer of Bonds Beyond Time' } } },
    { name = 'Wrath of the Opo-Opos', group = 'Outlands', desc = 'Zilart headstone quest: offer a Garnet. Starts with Cermet Headstone in Yuhtunga Jungle. Source: https://vanadreams.org/wiki/#quest-748', steps = { { title = 'Walkthrough', note = '• During ZM \'Headstone Pilgrimage\', get a Garnet.\n• Trade it to the Cermet Headstone (L-7), Yuhtunga Jungle.' }, { title = 'Reward', note = '• Opo-opo Necklace\n• Title: Friend of the Opo Opos' } } },
    { name = 'You Call That a Knife', group = 'Outlands', desc = 'Retrieve Chef Nonberry\'s knife from the Temple of Uggalepih. Starts with Mhebi Juhbily in Kazham. Source: https://vanadreams.org/wiki/#quest-749', steps = { { title = 'Needs', note = '• Windurst fame 6\n• 1 Sandfish' }, { title = 'Walkthrough', note = '• Trade the Sandfish to Mhebi Juhbily (I-11), Kazham.\n• Examine the Shed (I-11) and accept.\n• Talk to Vah Keshura (H-9).\n• Trade a Tonberry Board to Chef Nonberry (Map 3, G-10), Temple of Uggalepih, for Nonberry\'s knife.\n• Bring it to Mhebi Juhbily.' }, { title = 'Notes', note = '• Any other item given to Nonberry is lost and calls his Tonberry cooks (10-minute cooldown).\n• Zone before talking to Mhebi again afterward.' }, { title = 'Reward', note = '• 7,200 gil\n• Title: Ya Done Good\n• Windurst fame 60' } } },
    { name = 'A Job for the Consortium', group = 'San d\'Oria', desc = 'Tenshodo smuggling run: carry Brugaire goods to Lower Jeuno past customs. Starts with Portaure in Port San d\'Oria. Source: https://vanadreams.org/wiki/#quest-750', steps = { { title = 'Needs', note = '• Tenshodo Member\'s Card\n• San d\'Oria fame 5; Norg fame 1' }, { title = 'Walkthrough', note = '• Get the Brugaire Goods from Portaure (H-9), Port San d\'Oria.\n• Get through Port Jeuno customs (Arrivals Entrance or Haubijoux, H-7) undetected.\n• Hand the goods to Yin Pocanakhu (J-8), Lower Jeuno.\n• Report to Portaure.' }, { title = 'Notes', note = '• Daytime customs can seize the goods and ban airships until the next Japanese midnight.\n• Damaged goods pay less; only an intact delivery gives the gil and Norg fame.' } } },
    { name = 'A Knight\'s Test', group = 'San d\'Oria', desc = 'Paladin unlock: collect two books from San d\'Oria knights and the Knight\'s Soul in Davoi. Starts with Balasiel in Southern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-751', steps = { { title = 'Needs', note = '• A Squire\'s Test II done; level 30+' }, { title = 'Walkthrough', note = '• Accept from Balasiel (Southern San d\'Oria) for the Book of Tasks.\n• Get the Book of the West from Baunise (H-9) and the Book of the East from Cahaurme (J-9).\n• Examine the Disused Well (E-10) in Davoi for the Knight\'s Soul.\n• Return to Balasiel.' }, { title = 'Notes', note = '• The well yields the Soul only with both books.' }, { title = 'Reward', note = '• Paladin unlocked; Kite Shield\n• Key item: job gesture: paladin\n• Title: Tried and Tested Knight\n• San d\'Oria fame 20' } } },
    { name = 'A Purchase of Arms', group = 'San d\'Oria', desc = 'Courier a weapons order to Jugner Forest for Helbort. Starts with Helbort in Southern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-752', steps = { { title = 'Needs', note = '• Father and Son done; San d\'Oria fame 2' }, { title = 'Walkthrough', note = '• Take the weapons order from Helbort (K-7).\n• Give it to Alexius (I-6), Jugner Forest, for the receipt.\n• Return to Helbort.' }, { title = 'Reward', note = '• Elm Staff\n• Title: Arms Trader\n• San d\'Oria fame 20' } } },
    { name = 'A Sentry\'s Peril', group = 'San d\'Oria', desc = 'Bring ointment to Glenne\'s husband on patrol in West Ronfaure and return his case. Source: https://vanadreams.org/wiki/#quest-753', steps = { { title = 'Walkthrough', note = '• Get a Dose of Ointment from Glenne (F-8), Southern San d\'Oria.\n• Trade it to Aaveleon (G-6), West Ronfaure, on the Ghelsba Outpost road, for an Ointment Case.\n• Trade the case to Glenne.' }, { title = 'Notes', note = '• No prerequisites.\n• Have a free inventory slot for Aaveleon\'s trade.\n• Lost ointment: ask Glenne; lost case: ask Aaveleon.' }, { title = 'Reward', note = '• Items listed: Bronze Subligar, Ointment, Ointment Case\n• Title: Ronfaurian Rescuer\n• San d\'Oria fame 20' } } },
    { name = 'A Squire\'s Test', group = 'San d\'Oria', desc = 'Starter quest: bring Balasiel a Revival Root from King Ranperre\'s Tomb. Starts with Balasiel in Southern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-754', steps = { { title = 'Walkthrough', note = '• Accept from Balasiel.\n• Get a Revival Root in King Ranperre\'s Tomb.\n• Trade it to Balasiel.' }, { title = 'Reward', note = '• Spatha\n• Title: Knight in Training\n• San d\'Oria fame 20' } } },
    { name = 'A Squire\'s Test II', group = 'San d\'Oria', desc = 'Collect stalactite dew in Ordelle\'s Caves for Balasiel. Starts with Balasiel in Southern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-755', steps = { { title = 'Needs', note = '• A Squire\'s Test done; level 10+' }, { title = 'Walkthrough', note = '• Accept from Balasiel.\n• Optional hints: Chanpau (E-7), Southern San d\'Oria; Morjean (L-7), Northern San d\'Oria.\n• Enter Ordelle\'s Caves from La Theine Plateau (H-7) and examine the first ???.\n• Examine the second ??? within 30 seconds for the dew.\n• Return to Balasiel.' }, { title = 'Notes', note = '• Too slow: restart at the first ???.' }, { title = 'Reward', note = '• Key item: squire certificate\n• Title: Spelunker\n• San d\'Oria fame 20' } } },
    { name = 'A Taste for Meat', group = 'San d\'Oria', desc = 'Supply Thierride with five Hare Meat. Starts with Antreneau in Port San d\'Oria. Source: https://vanadreams.org/wiki/#quest-756', steps = { { title = 'Walkthrough', note = '• Talk to Antreneau (G-8), then Thierride (G-7), Port San d\'Oria.\n• Get 5 Hare Meat from rabbits.\n• Trade all 5 to Thierride.' }, { title = 'Notes', note = '• Antreneau adds a Slice of Grilled Hare afterward.' }, { title = 'Reward', note = '• 150 gil; Grilled Hare\n• Title: Rabbiter\n• San d\'Oria fame 20' } } },
    { name = 'A Timely Visit', group = 'San d\'Oria', desc = 'Errand chain between San d\'Oria and La Theine ending in a night fight in Jugner Forest. Source: https://vanadreams.org/wiki/#quest-757', steps = { { title = 'Needs', note = '• San d\'Oria fame 4' }, { title = 'Walkthrough', note = '• Accept from Deraquien (G-8), Southern San d\'Oria.\n• Talk to Narvecaint (F-7), La Theine Plateau; back to Deraquien.\n• Talk to Halver (I-9), Chateau d\'Oraguille.\n• Talk to Deraquien, then Phillone (D-7); then Deraquien again.\n• At night, check the ??? (F-5) in Jugner Forest; kill Giollemitte B Feroun or the Skeleton Esquire.\n• Check the ??? again, then see Phillone.\n• Visit Narvecaint, then return to Phillone.' }, { title = 'Notes', note = '• The ??? is inactive 06:00-17:59.' }, { title = 'Reward', note = '• Medieval Collar\n• Title: Obsidian Storm\n• San d\'Oria fame 40' } } },
    { name = 'Advanced Teamwork', group = 'San d\'Oria', desc = 'Bring Vilatroire a party where two members share a main job. Starts with Vilatroire in West Ronfaure. Source: https://vanadreams.org/wiki/#quest-758', steps = { { title = 'Needs', note = '• Intermediate Teamwork done\n• San d\'Oria fame 4+; main job 10+' }, { title = 'Walkthrough', note = '• Accept from Vilatroire (H-5), West Ronfaure.\n• Form a party where exactly two members (you included) have the same main job.\n• Talk to Vilatroire with everyone in the zone and within 15 yalms.' }, { title = 'Reward', note = '• Horn Ring\n• Title: First Rate Organizer\n• San d\'Oria fame 40' } } },
    { name = 'Atelloune\'s Lament', group = 'San d\'Oria', desc = 'Give Atelloune a Ladybug Wing. Starts with Atelloune in Southern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-759', steps = { { title = 'Needs', note = '• San d\'Oria fame 2+; Seeing Spots done' }, { title = 'Walkthrough', note = '• Accept from Atelloune (L-6).\n• Get a Ladybug Wing and trade it to her.' }, { title = 'Reward', note = '• Trainee Gloves\n• San d\'Oria fame 20' } } },
    { name = 'Black Tiger Skins', group = 'San d\'Oria', desc = 'Deliver three Tiger Hides. Starts with Hanaa Punaa in Southern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-760', steps = { { title = 'Needs', note = '• San d\'Oria fame 3+; Lizard Skins done' }, { title = 'Walkthrough', note = '• Accept from Hanaa Punaa (E-8).\n• Trade her three Tiger Hides.' }, { title = 'Reward', note = '• Tiger Stole\n• Title: Cat Skinner\n• San d\'Oria fame 30' } } },
    { name = 'Blackmail', group = 'San d\'Oria', desc = 'Deliver an envelope to the castle and fetch Castle Floor Plans. Starts with Dauperiat in Northern San d\'Oria. Source: https://vanadreams.org/wiki/#quest-761', steps = { { title = 'Needs', note = '• San d\'Oria fame 3; home nation rank 3' }, { title = 'Walkthrough', note = '• Get the suspicious envelope from Dauperiat (I-10).\n• Deliver it to Halver (I-9), Chateau d\'Oraguille.\n• Talk to Dauperiat and agree to find the plans.\n• Trade him the Castle Floor Plans.' }, { title = 'Notes', note = '• Plans are a rare drop in Yughott Grotto, Fort Ghelsba and Davoi.\n• Repeat the last step for more gil and fame.' }, { title = 'Reward', note = '• 900 gil\n• San d\'Oria fame 16' } } },
    { name = 'Chasing Quotas (DRG AF2)', group = 'San d\'Oria', desc = 'Dragoon AF2: recover Ranchuriome\'s Legacy from Sturmtiger in Batallia Downs. Starts with Ceraulian in Port San d\'Oria. Source: https://vanadreams.org/wiki/#quest-762', steps = { { title = 'Needs', note = '• Dragoon main, level 50+\n• A Craftsman\'s Work done' }, { title = 'Walkthrough', note = '• Accept from Ceraulian (H-10), Port San d\'Oria, and trade him a Gold Hairpin.\n• Wait ~1 minute and talk to him again.\n• Get the Shiny Earring from Miaux (E-6), Northern San d\'Oria.\n• Show it to Ardea (H-8), Bastok Markets, then Esca (F-6), West Ronfaure.\n• Check the ??? (I-11) in Batallia Downs and kill Sturmtiger; check again for Ranchuriome\'s Legacy.\n• Return to Ceraulian.' }, { title = 'Reward', note = '• Drachen Brais\n• San d\'Oria fame 20' } } },
    { name = 'Distant Loyalties', group = 'San d\'Oria', desc = 'Take Femitte\'s goldsmithing order to Bastok Markets and bring back the mythril hearts. Source: https://vanadreams.org/wiki/#quest-763', steps = { { title = 'Needs', note = '• San d\'Oria fame 4' }, { title = 'Walkthrough', note = '• Get the goldsmithing order from Femitte (I-8), Southern San d\'Oria.\n• Give it to Michea (F-10), Bastok Markets, then trade her a Mythril Ingot.\n• Zone and talk to Michea for the mythril hearts.\n• Return to Femitte.\n• Optional: revisit Michea for an extra scene.' }, { title = 'Notes', note = '• Rouva (Southern San d\'Oria) repeats a hint during the quest.\n• Michea won\'t proceed until you zone after the trade.' }, { title = 'Reward', note = '• White Cape\n• San d\'Oria fame 40' } } },
    { name = 'Eco-Warrior (San d\'Oria)', group = 'San d\'Oria', desc = 'Norejaie in Southern San d\'Oria sends you to Ordelle\'s Caves to beat a Necroplasm while level-restricted. Source: https://vanadreams.org/wiki/#quest-764', steps = { { title = 'Requirements', note = '• San d\'Oria fame 1.\n• No Eco-Warrior from another nation active.' }, { title = 'Walkthrough', note = '• Accept from Norejaie (K-6), Southern San d\'Oria.\n• In Ordelle\'s Caves, take Rojaireaut\'s level-lowering ointment.\n• While affected, check the ??? and kill the Necroplasm.\n• Check the ??? again for the Indigested Stalagmite.\n• Report to Norejaie (K-6).' }, { title = 'Notes', note = '• Rojaireaut can remove the ointment.\n• Repeatable after the next conquest tally; one nation\'s version at a time.' }, { title = 'Reward', note = '• 5,000 gil, Dragon Chronicles, title Vermillion Venturer, San d\'Oria fame 20.' } } },
    { name = 'Exit the Gambler', group = 'San d\'Oria', desc = 'Beat Varchet at dice to settle Aurege\'s problem. Source: https://vanadreams.org/wiki/#quest-766', steps = { { title = 'Walkthrough', note = '• Starter San d\'Oria quest; talk to Aurege (F-3) or Guilberdrier, Northern San d\'Oria.\n• Trade 5 gil to Varchet (L-6), Southern San d\'Oria, and roll until you win.\n• Report back to Aurege or Guilberdrier.' }, { title = 'Reward', note = '• 2,000 EXP, key item map of King Ranperre\'s Tomb, title Daybreak Gambler, San d\'Oria fame 20.' } } },
    { name = 'Father and Son', group = 'San d\'Oria', desc = 'Carry a message between Ailbeche and his father Exoroche. Source: https://vanadreams.org/wiki/#quest-767', steps = { { title = 'Walkthrough', note = '• No requirements; accept from Ailbeche (J-9), Northern San d\'Oria.\n• Speak with Exoroche (K-7), Southern San d\'Oria.\n• Return to Ailbeche.' }, { title = 'Reward', note = '• Willow Fish. Rod, title Lost Child Officer, San d\'Oria fame 20.\n• Trading a Willow Fish. Rod back to Ailbeche later gives title Family Counselor.' } } },
    { name = 'Fear of the Dark', group = 'San d\'Oria', desc = 'Repeatable delivery of 2 Bat Wings to Secodiand. Source: https://vanadreams.org/wiki/#quest-768', steps = { { title = 'Walkthrough', note = '• Accept from Secodiand (E-6), Northern San d\'Oria.\n• Trade him 2 Bat Wings; repeatable.' }, { title = 'Reward', note = '• 200 gil, San d\'Oria fame 10.' } } },
    { name = 'Grave Concerns', group = 'San d\'Oria', desc = 'Swap Andecia\'s well water for tomb water at King Ranperre\'s Tomb. Source: https://vanadreams.org/wiki/#quest-769', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 1.\n• Speak to Andecia (M-7), Southern San d\'Oria, twice to get Well Water.\n• Trade it to the Tombstone in King Ranperre\'s Tomb for a Tomb Waterskin.\n• Trade the Tomb Waterskin to Andecia.\n• Lost it? Refill the Tomb Waterskin at the Southern San d\'Oria Well.' }, { title = 'Reward', note = '• 560 gil, title Royal Grave Keeper, San d\'Oria fame 20.' } } },
    { name = 'Grimy Signposts', group = 'San d\'Oria', desc = 'Clean four signposts in Jugner Forest for Maugie. Source: https://vanadreams.org/wiki/#quest-770', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 2; accept from Maugie (L-9), Southern San d\'Oria.\n• Examine and clean all 4 Signposts in Jugner Forest.\n• Report to Maugie.' }, { title = 'Reward', note = '• 1,500 gil, San d\'Oria fame 20.' } } },
    { name = 'Growing Flowers', group = 'San d\'Oria', desc = 'Give Kuu Mohzolhi the flower he wants to unlock a Mog House feature. Source: https://vanadreams.org/wiki/#quest-771', steps = { { title = 'Walkthrough', note = '• Talk to or trade any flower to Kuu Mohzolhi (F-8), Northern San d\'Oria.\n• Trade him a Marguerite to finish.\n• Wrong flowers are consumed; after completion, flowers traded are no longer used up.' }, { title = 'Reward', note = '• San d\'Oria fame 0.' } } },
    { name = 'Her Majestys Garden', group = 'San d\'Oria', desc = 'Deliver Derfland Humus to Chalvatot. Source: https://vanadreams.org/wiki/#quest-772', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 4+.\n• Accept from Chalvatot (F-7), Chateau d\'Oraguille.\n• Trade him a Derfland Humus.' }, { title = 'Reward', note = '• Key item map of the Northlands area, San d\'Oria fame 40.' } } },
    { name = 'Intermediate Teamwork', group = 'San d\'Oria', desc = 'Bring a same-race party to Vilatroire. Source: https://vanadreams.org/wiki/#quest-773', steps = { { title = 'Requirements', note = '• Introduction to Teamwork done, San d\'Oria fame 3, level 10+.' }, { title = 'Walkthrough', note = '• Accept from Vilatroire (H-5), West Ronfaure.\n• Party with at least one player of your race (Hume male/female count as one; so do Elvaan and Tarutaru).\n• With all members in West Ronfaure near him, talk to Vilatroire.' }, { title = 'Reward', note = '• Mage\'s Ballad, title Second Rate Organizer, San d\'Oria fame 30.' } } },
    { name = 'Introduction to Teamwork', group = 'San d\'Oria', desc = 'Show Vilatroire a party from your nation. Source: https://vanadreams.org/wiki/#quest-774', steps = { { title = 'Requirements', note = '• San d\'Oria fame 2, level 10+.\n• Party of 2+ from your nation, same zone, within 15 yalms.' }, { title = 'Walkthrough', note = '• Accept from Vilatroire (H-5), West Ronfaure.\n• Gather the party nearby in West Ronfaure and talk to him.' }, { title = 'Reward', note = '• Shell Ring, title Third Rate Organizer, San d\'Oria fame 20.' } } },
    { name = 'Lizard Skins', group = 'San d\'Oria', desc = 'Repeatable: 3 Lizard Skins for Hanaa Punaa. Source: https://vanadreams.org/wiki/#quest-775', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 2 and The Seamstress.\n• Accept from Hanaa Punaa (E-8), Southern San d\'Oria (talk again if you declined).\n• Trade her 3 Lizard Skins; repeatable.' }, { title = 'Reward', note = '• Lizard Gloves, title Lizard Skinner, San d\'Oria fame 10.' } } },
    { name = 'Lufets Lake Salt', group = 'San d\'Oria', desc = 'Bring Nogelle 3 Lufet Salt from Lufaise Meadows. Source: https://vanadreams.org/wiki/#quest-776', steps = { { title = 'Walkthrough', note = '• Accept from Nogelle (G-7), Port San d\'Oria.\n• Gather 3 Lufet Salt in Lufaise Meadows and trade them to him.' }, { title = 'Reward', note = '• 600 gil, title Bean Cuisine Salter, San d\'Oria fame 10.' } } },
    { name = 'Lure of the Wildcat (San d\'Oria)', group = 'San d\'Oria', desc = 'Speak to 20 San d\'Orians for Amutiyaal, the Red Sentinel recruiter. Source: https://vanadreams.org/wiki/#quest-777', steps = { { title = 'Walkthrough', note = '• Get the red sentinel badge from Amutiyaal (L-6), Southern San d\'Oria.\n• Southern: Daggao (K-5), Authere (J-9), Rouva, Femitte (I-8), Deraquien (G-8).\n• Northern: Giaunne (I-9), Anilla (J-8), Maloquedil, Phairupegiont (H-8), Bertenont (E-4).\n• Port: Perdiouvilet (G-7), Pomilla (H-8), Cherlodeau, Parcarin (H-10), Rugiette (J-8).\n• Chateau: Curilla, Halver (I-9), Rahal (H-9), Perfaumand (H-7), Chalvatot (F-7).\n• Any order; then report to Amutiyaal (badge is taken).' }, { title = 'Reward', note = '• Key item red invitation card, San d\'Oria fame 0.' } } },
    { name = 'Messenger From Beyond', group = 'San d\'Oria', desc = 'WHM artifact quest 1: take a Tavnazia Pass from Marchelute. Source: https://vanadreams.org/wiki/#quest-778', steps = { { title = 'Walkthrough', note = '• Main job WHM at first-AF level.\n• Accept from Narcheral (M-6), Northern San d\'Oria.\n• Examine the ??? (B-8) in Valkurm Dunes, defeat Marchelute for the Tavnazia Pass.\n• Trade the pass to Narcheral.' }, { title = 'Reward', note = '• Blessed Hammer, San d\'Oria fame 20.' } } },
    { name = 'Methods Create Madness', group = 'San d\'Oria', desc = 'Polearm trial with Balasiel that teaches Impulse Drive. Source: https://vanadreams.org/wiki/#quest-779', steps = { { title = 'Requirements', note = '• Polearm skill 240+, able to equip the Spear of Trials.' }, { title = 'Walkthrough', note = '• Talk to Balasiel, Southern San d\'Oria, for the Spear of Trials and weapon training guide.\n• Earn 300 weapon skill points with the spear.\n• Trade the spear to Balasiel for the map to the Annals of Truth.\n• In Sea Serpent Grotto, examine the ??? and defeat Water Leaper (needs the map).\n• Examine the ??? again for the Annals of Truth.\n• Return to Balasiel to learn Impulse Drive.' }, { title = 'Notes', note = '• Balasiel replaces a lost spear and lets you restart.' }, { title = 'Reward', note = '• Impulse Drive, San d\'Oria fame 20.' } } },
    { name = 'Old Wounds', group = 'San d\'Oria', desc = 'Sword trial with Curilla that teaches Savage Blade. Source: https://vanadreams.org/wiki/#quest-780', steps = { { title = 'Requirements', note = '• Sword skill 240+, able to equip the Sapara of Trials.' }, { title = 'Walkthrough', note = '• Get the Sapara of Trials from Curilla (I-9), Chateau d\'Oraguille.\n• Earn 300 weapon skill points with it, then trade it to Curilla.\n• Enter Quicksand Caves from Western Altepa Desert (I-6); examine the ??? and defeat Girtablulu.\n• Examine the ??? again for the Annals of Truth.\n• Return to Curilla to learn Savage Blade.' }, { title = 'Notes', note = '• Curilla replaces a lost Sapara and allows a restart.' }, { title = 'Reward', note = '• Savage Blade, San d\'Oria fame 20.' } } },
    { name = 'Prelude of Black and White', group = 'San d\'Oria', desc = 'WHM artifact quest 2: bring Narcheral holy water and moccasins. Source: https://vanadreams.org/wiki/#quest-781', steps = { { title = 'Walkthrough', note = '• Main job WHM 50+, Messenger from Beyond done.\n• Examine the door in Chateau d\'Oraguille to start (cutscene).\n• Get a Canteen of Yagudo Holy Water and Moccasins.\n• Trade both at once to Narcheral (M-6), Northern San d\'Oria.' }, { title = 'Reward', note = '• Healer\'s Duckbills, San d\'Oria fame 20.' } } },
    { name = 'The Crimson Trial', group = 'San d\'Oria', desc = 'RDM artifact quest 1: fetch Orcish dried food from Davoi for Sharzalion. Source: https://vanadreams.org/wiki/#quest-782', steps = { { title = 'Walkthrough', note = '• Main job RDM 40+.\n• Accept from Sharzalion (K-6), Southern San d\'Oria.\n• Enter Davoi from Jugner Forest (G-12); Purpleflash Bruktok spawns on entry; kill it for the Davoi Storage Key.\n• Trade the key to the Storage Hole (G-9) in Davoi for the Orcish dried food.\n• Give the food to Sharzalion.' }, { title = 'Notes', note = '• Bruktok reappears each entry until you have the food.\n• Valderotaux in Southern San d\'Oria gives hints.' }, { title = 'Reward', note = '• Fencing Degen, San d\'Oria fame 20.' } } },
    { name = 'Enveloped in Darkness (RDM AF2)', group = 'San d\'Oria', desc = 'RDM artifact quest 2: bury old boots and crawler blood in Crawlers\' Nest. Source: https://vanadreams.org/wiki/#quest-783', steps = { { title = 'Walkthrough', note = '• Main job RDM 50+, The Crimson Trial done.\n• Accept from Curilla (I-9), Chateau d\'Oraguille, for the old pocket watch.\n• Trade a Velvet Cloth to Pagisalis (M-6), Northern San d\'Oria, for the old boots.\n• Enter Crawlers\' Nest from Rolanberry Fields (D-11); open its Treasure Chest for crawler blood.\n• At the ??? choose to bury both items, wait ~30 seconds, examine it again.' }, { title = 'Reward', note = '• Warlock\'s Boots, San d\'Oria fame 20.' } } },
    { name = 'Rosel the Armorer', group = 'San d\'Oria', desc = 'Carry Rosel\'s receipt to Guilerme; naming the right prince pays more. Source: https://vanadreams.org/wiki/#quest-784', steps = { { title = 'Walkthrough', note = '• Get the receipt from Rosel (K-7), Southern San d\'Oria.\n• Give it to Guilerme (I-7), Northern San d\'Oria, choosing the prince Rosel mentioned.\n• Return to Rosel for payment; the correct prince gives more gil and fame.' }, { title = 'Reward', note = '• Title Entrance Denied.' } } },
    { name = 'Sharpening the Sword', group = 'San d\'Oria', desc = 'PLD artifact quest 1: get the Ordelle Whetstone for Ailbeche. Source: https://vanadreams.org/wiki/#quest-785', steps = { { title = 'Requirements', note = '• Main job PLD 40+, A Knight\'s Test done, title Family Counselor.' }, { title = 'Walkthrough', note = '• Accept from Ailbeche (J-9), Northern San d\'Oria.\n• Enter Ordelle\'s Caves from La Theine Plateau (H-10); check the Stalagmite (Map 2, H-10) and defeat Polevik.\n• Check it again for the Ordelle Whetstone.\n• Return to Ailbeche.' }, { title = 'Reward', note = '• Honor Sword, San d\'Oria fame 20.' } } },
    { name = 'Signed in  Blood', group = 'San d\'Oria', desc = 'Recover a cathedral tapestry and missing pages for Sobane. Source: https://vanadreams.org/wiki/#quest-786', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 3; talk to Sobane (D-6), Southern San d\'Oria.\n• Trade her a Cathedral Tapestry.\n• Talk to Abelard (G-9) in Selbina.\n• Get the torn-out pages from an Ordelle\'s Caves Treasure Chest (key or thief\'s tools).\n• Show them to Abelard, then return to Sobane.' }, { title = 'Reward', note = '• 3,500 gil, Cunning Earring, San d\'Oria fame 30.' } } },
    { name = 'Sleepless Nights', group = 'San d\'Oria', desc = 'Bring Paouala a Jug of Mary\'s Milk. Source: https://vanadreams.org/wiki/#quest-787', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 2.\n• Accept from Paouala (M-8), Southern San d\'Oria, then trade her the Jug of Mary\'s Milk.' }, { title = 'Reward', note = '• 5,000 gil, title Sheeps Milk Deliverer, San d\'Oria fame 20.' } } },
    { name = 'Souls in Shadow', group = 'San d\'Oria', desc = 'Scythe trial with Novalmauge that teaches Spiral Hell. Source: https://vanadreams.org/wiki/#quest-788', steps = { { title = 'Requirements', note = '• Can equip the Scythe of Trials, scythe skill 240+, no weapon training guide held.' }, { title = 'Walkthrough', note = '• Enter Bostaunieux Oubliette from Chateau d\'Oraguille (I-8); talk to Novalmauge (Map 1, F-8) for the Scythe of Trials and guide.\n• Earn 300 weapon skill points with it, then trade it to him for the map to the Annals of Truth.\n• Enter Den of Rancor from Temple of Uggalepih (E-7); examine the ??? and defeat Mokumokuren.\n• Examine the ??? again for the Annals of Truth.\n• Return to Novalmauge to learn Spiral Hell.' }, { title = 'Notes', note = '• He replaces a lost scythe or lets you restart.' }, { title = 'Reward', note = '• Spiral Hell, San d\'Oria fame 20.' } } },
    { name = 'Spice Gals', group = 'San d\'Oria', desc = 'Gather Rivernewort in Riverne for Rouva, once per conquest tally. Source: https://vanadreams.org/wiki/#quest-789', steps = { { title = 'Walkthrough', note = '• Needs CoP mission Ancient Vows.\n• Accept from Rouva (I-8), Southern San d\'Oria.\n• Examine the ??? in Riverne - Site A01 or Site B01 for Rivernewort (hold max 1).\n• Bring it to Rouva.' }, { title = 'Reward', note = '• Miratete\'s Mem.' } } },
    { name = 'Starting a Flame', group = 'San d\'Oria', desc = 'Repeatable: 4 Flint Stones for Legata. Source: https://vanadreams.org/wiki/#quest-790', steps = { { title = 'Walkthrough', note = '• Accept from Legata (K-6), Southern San d\'Oria.\n• Trade her 4 Flint Stones; repeatable for gil and fame.' } } },
    { name = 'Tea with a Tonberry?', group = 'San d\'Oria', desc = 'Help Sobane via a Tonberry contact and a Hematic Cyst fight in Davoi. Source: https://vanadreams.org/wiki/#quest-791', steps = { { title = 'Requirements', note = '• Signed in Blood done, San d\'Oria fame 4+.' }, { title = 'Walkthrough', note = '• Accept from Sobane (D-6), Southern San d\'Oria.\n• Trade an Attohwa Ginseng to Anguenet (Map 1, J-10), Carpenters\' Landing, for the Tonberry blackboard.\n• Show it to Riche (H-8), Phanauet Channel.\n• Enter Davoi from Jugner Forest (G-12); trade Treasury Gold to the ??? (J-11) and defeat the Hematic Cyst (wait if it is already up; gold is consumed).\n• Examine the ??? again, then report to Sobane.' }, { title = 'Reward', note = '• Willpower Torque, title Talks with Tonberries, San d\'Oria fame 40.' } } },
    { name = 'The Brugaire Consortium', group = 'San d\'Oria', desc = 'Deliver three parcels in Port San d\'Oria for Fontoumant. Source: https://vanadreams.org/wiki/#quest-792', steps = { { title = 'Walkthrough', note = '• Get the Magic Shop Parcel from Fontoumant (H-10), deliver to Regine (J-8).\n• Get the Auction Parcel, deliver to Apstaule.\n• Get the Pub Parcel, deliver to Thierride (G-7).\n• Talk to Fontoumant to finish.\n• Trading him 100 gil while holding a parcel counts it as delivered.' }, { title = 'Reward', note = '• Lauan Shield, title Courier Extraordinaire, San d\'Oria fame 20.' } } },
    { name = 'The Competition', group = 'San d\'Oria', desc = 'Sell carp to Joulet until your total reaches 10,000 for Lu Shang\'s rod. Source: https://vanadreams.org/wiki/#quest-793', steps = { { title = 'Walkthrough', note = '• Not available if The Rivalry is active or done.\n• Accept from Joulet (H-8), Port San d\'Oria.\n• Trade Moat Carp (10 gil each) and Forest Carp (15 gil each); total carries over and he reports it.\n• Finish at 10,000; trading may continue afterward.' }, { title = 'Reward', note = '• Lu Shang\'s F. Rod, key item testimonial, title Carp Diem, San d\'Oria fame 10.' } } },
    { name = 'The Dismayed Customer', group = 'San d\'Oria', desc = 'Find Gulemont\'s lost document in West Ronfaure. Source: https://vanadreams.org/wiki/#quest-794', steps = { { title = 'Walkthrough', note = '• Needs A Taste for Meat.\n• Accept from Gulemont (G-7), Port San d\'Oria.\n• Check the three ??? in West Ronfaure; one (set at acceptance) holds the document.\n• Return to Gulemont.' }, { title = 'Reward', note = '• 560 gil, title Lost Found Officer, San d\'Oria fame 20.' } } },
    { name = 'A Sentry\'s Peril', group = 'San d\'Oria', desc = 'Fill Curilla\'s bottle at the Horlais Peak hot springs. Source: https://vanadreams.org/wiki/#quest-795', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 2.\n• Get an empty bottle from Curilla (I-9), Chateau d\'Oraguille.\n• Fill it at the Hot Springs (K-8) in Horlais Peak and return.' }, { title = 'Reward', note = '• Lynx Baghnakhs, San d\'Oria fame 20.' } } },
    { name = 'The Medicine Woman', group = 'San d\'Oria', desc = 'Get Amaura to brew cold medicine for Abeaule. Source: https://vanadreams.org/wiki/#quest-796', steps = { { title = 'Walkthrough', note = '• Needs The Trader in the Forest and San d\'Oria fame 3+.\n• Accept from Abeaule (F-8), Northern San d\'Oria.\n• Get Amaura\'s formula from Amaura (G-6), Southern San d\'Oria.\n• Trade her a Malboro Vine, Zinc Ore and Insect Wing together for the cold medicine.\n• Deliver it to Abeaule.' }, { title = 'Reward', note = '• 2,100 gil, title Traveling Medicine Man, San d\'Oria fame 30.' } } },
    { name = 'The Merchants Bidding', group = 'San d\'Oria', desc = 'Repeatable: 3 Rabbit Hides for Parvipon. Source: https://vanadreams.org/wiki/#quest-797', steps = { { title = 'Walkthrough', note = '• Accept from Parvipon (E-8), Southern San d\'Oria.\n• Trade him 3 Rabbit Hides; repeatable for gil and fame.' } } },
    { name = 'The Pickpocket', group = 'San d\'Oria', desc = 'Track down the thief who took Altiret\'s glasses. Source: https://vanadreams.org/wiki/#quest-798', steps = { { title = 'Walkthrough', note = '• Starter quest; talk to Miene (I-9), Port San d\'Oria, to witness the theft from Altiret (I-8).\n• Optional clues from guards/townsfolk in Port and Northern San d\'Oria and West Ronfaure.\n• Accept Altiret\'s request, then get the Eagle Button from Miene (she replaces it if lost).\n• Trade the button to Esca (F-6), West Ronfaure, for the Gilt Glasses.\n• Trade the glasses to Altiret.' }, { title = 'Reward', note = '• Light Axe, title Pickpocket Pincher, San d\'Oria fame 20.' } } },
    { name = 'The Rivalry', group = 'San d\'Oria', desc = 'Sell carp to Gallijaux until you reach 10,000 for Lu Shang\'s rod. Source: https://vanadreams.org/wiki/#quest-799', steps = { { title = 'Walkthrough', note = '• Needs fishing; not available while The Competition is active.\n• Accept from Gallijaux (H-8), Port San d\'Oria.\n• Trade Moat Carp (10 gil) and Forest Carp (15 gil); he reports your running total.\n• Finish at 10,000 carp; trading may continue.' }, { title = 'Reward', note = '• Lu Shang\'s F. Rod, key item testimonial, title Carp Diem, San d\'Oria fame 10.' } } },
    { name = 'The Rumor', group = 'San d\'Oria', desc = 'Bring Beastman Blood to Novalmauge. Source: https://vanadreams.org/wiki/#quest-800', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 3, level 5+.\n• Enter Bostaunieux Oubliette from Chateau d\'Oraguille (I-8); accept from Novalmauge (Map 1, F-8).\n• Trade him a Beastman Blood.' }, { title = 'Reward', note = '• Drain, San d\'Oria fame 30.' } } },
    { name = 'The Seamstress', group = 'San d\'Oria', desc = 'Repeatable: 3 Sheepskins for Hanaa Punaa. Source: https://vanadreams.org/wiki/#quest-801', steps = { { title = 'Walkthrough', note = '• Accept from Hanaa Punaa (E-8), Southern San d\'Oria (talk again if you declined).\n• Trade her 3 Sheepskins; repeatable.' }, { title = 'Reward', note = '• Leather Gloves, title Silencer of the Lambs, San d\'Oria fame 10.' } } },
    { name = 'The Setting Sun', group = 'San d\'Oria', desc = 'Bring an Engraved Key to Vamorcote. Source: https://vanadreams.org/wiki/#quest-802', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 5+ and Blackmail.\n• Accept from Vamorcote (F-6), Northern San d\'Oria, then trade him an Engraved Key.\n• Zone before speaking to him again afterward.' }, { title = 'Reward', note = '• 10,000 gil, San d\'Oria fame 50.' } } },
    { name = 'The Sweetest Things', group = 'San d\'Oria', desc = 'Sell 5 Honey to Raimbroy; repeatable. Source: https://vanadreams.org/wiki/#quest-803', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 2.\n• Talk to Raimbroy (F-8), Southern San d\'Oria, three times; accept on the third.\n• Trade him 5 Honey; repeatable for gil, fame and title.' }, { title = 'Reward', note = '• Title Apiarist, San d\'Oria fame 10.' } } },
    { name = 'The Trader in the Forest', group = 'San d\'Oria', desc = 'Fetch Batagreens from Phairet for Abeaule. Source: https://vanadreams.org/wiki/#quest-804', steps = { { title = 'Walkthrough', note = '• Get the supplies order from Abeaule (F-8), Northern San d\'Oria (he replaces it if lost).\n• Trade it to Phairet (I-11), West Ronfaure, for Batagreens (he also sells them for 50 gil).\n• Trade the Batagreens to Abeaule.' }, { title = 'Reward', note = '• Robe, title Green Grocer, San d\'Oria fame 20.' } } },
    { name = 'The Vicasque\'s Sermon', group = 'San d\'Oria', desc = 'Take Blue Peas from Abioleget to Andelain. Source: https://vanadreams.org/wiki/#quest-805', steps = { { title = 'Walkthrough', note = '• Needs Waters of the Cheval.\n• Accept from Abioleget (M-7), Northern San d\'Oria; trade him 70 gil for Blue Peas (70 gil again if lost).\n• Trade the peas to Andelain (J-11), East Ronfaure.\n• Return to Abioleget.' }, { title = 'Reward', note = '• Brass Ring, title The Benevolent One, San d\'Oria fame 20.' } } },
    { name = 'Tigers Teeth', group = 'San d\'Oria', desc = 'Repeatable: 3 Black Tiger Fangs for Taumila. Source: https://vanadreams.org/wiki/#quest-806', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 3.\n• Accept from Taumila (F-9), Southern San d\'Oria.\n• Trade her 3 Black Tiger Fangs from tigers; repeatable.' }, { title = 'Reward', note = '• 2,100 gil, title Fang Finder, fame 16.' } } },
    { name = 'Trouble at the Sluice', group = 'San d\'Oria', desc = 'Get a neutralizer from Novalmauge for Belgidiveau. Source: https://vanadreams.org/wiki/#quest-807', steps = { { title = 'Walkthrough', note = '• Needs The Rumor and San d\'Oria fame 3.\n• Accept from Belgidiveau (G-8), Northern San d\'Oria.\n• Enter Bostaunieux Oubliette from Chateau d\'Oraguille (I-8); talk to Novalmauge (Map 1, F-8), then trade him a Dahlia for the neutralizer.\n• Bring it to Belgidiveau.' }, { title = 'Reward', note = '• Heavy Axe, San d\'Oria fame 30.' } } },
    { name = 'Unexpected Treasure', group = 'San d\'Oria', desc = 'Return a teacup found in your Mog House cupboard to the Cathedral. Source: https://vanadreams.org/wiki/#quest-808', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 4+.\n• Place a Cupboard in your San d\'Oria Mog House; the Moogle gives you the small teacup.\n• Show it to Morunaude (G-9), Northern San d\'Oria, and accept.\n• Talk to Calovour (M-6), then trade him a Mistletoe.' }, { title = 'Reward', note = '• 12,000 gil.' } } },
    { name = 'Warding Vampires', group = 'San d\'Oria', desc = 'Repeatable: 2 Shaman Garlics for Maloquedil. Source: https://vanadreams.org/wiki/#quest-809', steps = { { title = 'Walkthrough', note = '• Needs San d\'Oria fame 3+.\n• Accept from Maloquedil (J-8), Northern San d\'Oria, then trade him 2 Shaman Garlics; repeatable.' }, { title = 'Reward', note = '• Title Vampire Hunter D Minus, San d\'Oria fame 16.' } } },
    { name = 'Waters of the Cheval', group = 'San d\'Oria', desc = 'Fill a Blessed Waterskin at the Cheval River for Miageau. Source: https://vanadreams.org/wiki/#quest-810', steps = { { title = 'Walkthrough', note = '• Accept from Miageau (L-7), Northern San d\'Oria.\n• Trade 10 gil to Nouveil (M-7), next to her, for a Blessed Waterskin.\n• Trade it to the Cheval River (H-5), East Ronfaure, for Cheval Water.\n• Trade the water to Miageau.' }, { title = 'Reward', note = '• Wing Pendant, title The Pure One, San d\'Oria fame 20.' } } },
    { name = 'A Greeting Cardian', group = 'Windurst', desc = 'Pass a chosen greeting along the Cardian brothers for Kororo. Source: https://vanadreams.org/wiki/#quest-811', steps = { { title = 'Walkthrough', note = '• Needs The All-New C-2000 and Windurst fame 3.\n• Pick one of three greetings from Spare One (H-9), Windurst Woods.\n• Zone, wait a minute, then accept from Kororo (H-9).\n• Talk to Five of Spades (E-7), Buburimu Peninsula.\n• Optional: Five of Clubs (Port Windurst), Five of Diamonds (Windurst Walls), Five of Hearts (Windurst Waters), Boizo-Naizo (Windurst Woods).\n• Return to Kororo.' }, { title = 'Reward', note = '• Tml. Earring, Windurst fame 30.' } } },
    { name = 'A Pose By Any Other Name', group = 'Windurst', desc = 'Wear the body armor Angelica names for your job within one real hour. Source: https://vanadreams.org/wiki/#quest-812', steps = { { title = 'Walkthrough', note = '• Accept from Angelica, Windurst Waters; talk again to get your armor and start the 1-hour timer.\n• Equip it and talk to her before time runs out (she says what is missing if wrong).\n• Timeout cancels; retry after zoning.' }, { title = 'Armor by job', note = '• Bronze Harness: WAR, PLD, DRK, DRG, COR, RUN.\n• Robe: MNK, BRD, BLU.\n• Tunic: WHM, BLM, RDM, SMN, PUP, SCH, GEO.\n• Leather Vest: THF, BST, RNG, DNC.\n• Kenpogi: SAM, NIN.' }, { title = 'Reward', note = '• Ancient Blood, key item Angelica\'s autograph, title Super Model, Windurst fame 20.' } } },
    { name = 'A Smudge on One\'s Record', group = 'Windurst', desc = 'Bring Hariga-Origa Slime Oil and a Frost Turnip. Source: https://vanadreams.org/wiki/#quest-813', steps = { { title = 'Walkthrough', note = '• Needs Chasing Tales and Windurst fame 4+.\n• Accept from Hariga-Origa, Windurst Waters (zone first if required after a prior quest).\n• Trade her a Vial of Slime Oil and a Frost Turnip.\n• Serukoko, Windurst Waters, repeats the shopping list.' }, { title = 'Reward', note = '• 5,000 gil, 2,000 EXP, key item map of Fei\'Yin, Windurst fame 40.' } } },
    { name = 'Acting in Good Faith', group = 'Windurst', desc = 'Burn Gantineux\'s spirit incense in The Eldieme Necropolis and carry his letter to Eperdur. Source: https://vanadreams.org/wiki/#quest-814', steps = { { title = 'Walkthrough', note = '• Needs Windurst fame 4+, main job level 10+.\n• Get spirit incense from Gantineux, Windurst Waters.\n• Enter The Eldieme Necropolis from Batallia Downs (H-8); examine the ??? (location varies), using up the incense.\n• Return to Gantineux for his letter.\n• Deliver it to Eperdur (M-7), Northern San d\'Oria.' }, { title = 'Reward', note = '• Teleport-Mea, title Pilgrim to Mea, Windurst fame 40.' } } },
    { name = 'All at Sea', group = 'Windurst', desc = 'Repair Paytah\'s lost cap with a Ripped Cap and Dhalmel Hides. Source: https://vanadreams.org/wiki/#quest-815', steps = { { title = 'Requirements', note = '• Windurst fame 3+.' }, { title = 'Walkthrough', note = '• Get a Ripped Cap and trade it to Paytah (I-7), Port Windurst, to start.\n• Trade the Ripped Cap to Baren-Moren, Windurst Waters.\n• Trade him 4 Dhalmel Hides for a Sailor\'s Cap.\n• Trade the Sailor\'s Cap to Paytah (I-7).' }, { title = 'Notes', note = '• Lost Sailor\'s Cap: 4 more Dhalmel Hides to Baren-Moren.\n• Odilia (Port Windurst) has quest dialogue.' }, { title = 'Reward', note = '• Leather Ring, Sailor\'s Cap, Dhalmel Mantle\n• Windurst fame 30' } } },
    { name = 'Blast from the Past', group = 'Windurst', desc = 'Koru-Moru (Windurst Walls) wants a Burnite Shell from a fossil in the Maze of Shakhrami. Source: https://vanadreams.org/wiki/#quest-816', steps = { { title = 'Requirements', note = '• Star Struck done; Windurst fame 3.\n• Class Reunion must not be active.' }, { title = 'Walkthrough', note = '• Accept from Koru-Moru (E-7), Windurst Walls.\n• Speak to Tokaka (C-8), Port Windurst.\n• Speak to Yoran-Oran (E-5), Windurst Walls.\n• Check the right Fossil Rock in Maze of Shakhrami; kill Ichorous Ire.\n• Trade the Burnite Shell to Koru-Moru (E-7).' }, { title = 'Notes', note = '• Holding a Burnite Shell stops the rock spawning the NM.\n• Zone before starting Nothing Matters.' }, { title = 'Reward', note = '• Great Club\n• Title: Fossilized Sea Farer\n• Windurst fame 30' } } },
    { name = 'Blood and Glory', group = 'Windurst', desc = 'Staff weapon skill trial that ends with learning Retribution after beating Cailleach Bheur. Source: https://vanadreams.org/wiki/#quest-817', steps = { { title = 'Requirements', note = '• Staff skill 230+; job able to equip Pole of Trials.\n• No weapon training guide already held.' }, { title = 'Walkthrough', note = '• Get Pole of Trials and training guide from Shantotto (K-7), Windurst Walls.\n• Earn 300 weapon skill points with the pole equipped.\n• Trade the pole to Shantotto for the map to the Annals of Truth.\n• Enter Ifrit\'s Cauldron (Yhoator Jungle I-6); check the ??? for Cailleach Bheur.\n• Kill it, recheck the ??? for the Annals of Truth.\n• Report to Shantotto (K-7) to learn Retribution.' }, { title = 'Notes', note = '• Shantotto replaces a lost pole or lets you quit and restart.' }, { title = 'Reward', note = '• Pole of Trials\n• Windurst fame 20' } } },
    { name = 'Blue Ribbon Blues', group = 'Windurst', desc = 'Take Kerutoto\'s Purple Ribbon to Eldieme Necropolis, defeat Lich C Magnus and bring back a Blue Ribbon. Source: https://vanadreams.org/wiki/#quest-818', steps = { { title = 'Requirements', note = '• Water Way to Go done; Windurst fame 5+.' }, { title = 'Walkthrough', note = '• Speak to Kerutoto (Windurst Waters); get a Purple Ribbon from Roberta (I-13), Windurst Woods.\n• Trade it to Kerutoto to start, then speak to him for a second Purple Ribbon.\n• Enter Eldieme Necropolis (Batallia Downs I-10); trade the ribbon to the Hume Bones.\n• Kill Lich C Magnus, then check the Hume Bones for the Blue Ribbon.\n• Hand the Blue Ribbon to Kerutoto.' }, { title = 'Notes', note = '• Roberta replaces a lost Purple Ribbon.' }, { title = 'Reward', note = '• Blue Ribbon, Purple Ribbon\n• Title: Ghostie Buster\n• Windurst fame 50' } } },
    { name = 'Chasing Tales', group = 'Windurst', desc = 'Recover the overdue book A Song of Love from Southern San d\'Oria for the Windurst library. Source: https://vanadreams.org/wiki/#quest-819', steps = { { title = 'Requirements', note = '• Early Bird Catches the Bookworm done; Windurst fame 3.\n• Windurst citizens: not on The Jester Who\'d Be King.' }, { title = 'Walkthrough', note = '• Accept from Tosuka-Porika, Windurst Waters.\n• Get the Overdue Book Notification from Furakku-Norakku, Windurst Waters.\n• Speak to Hae Jakkya (I-13), Windurst Woods.\n• Speak to Hae Jakhya (G-9), Southern San d\'Oria, for A Song of Love.\n• Return the book to Furakku-Norakku.' }, { title = 'Notes', note = '• An Polaali and An Shanaa (Windurst Woods) have extra lines.' }, { title = 'Reward', note = '• 2,800 gil\n• Title: Savior of Knowledge\n• Windurst fame 30' } } },
    { name = 'Curses, Foiled A-Golem!?', group = 'Windurst', desc = 'Bring Shantotto\'s new spell from Beaucedine Glacier to the Feiyin door intact. Source: https://vanadreams.org/wiki/#quest-820', steps = { { title = 'Requirements', note = '• Curses, Foiled Again!? (2) done, then zone once.\n• Windurst fame 4; level 10+.' }, { title = 'Walkthrough', note = '• Accept from Shantotto (K-7), Windurst Walls.\n• Get the spell from Torino-Samarino (I-7), Beaucedine Glacier.\n• Check the door in Feiyin while carrying it.\n• Report to Shantotto (K-7).' }, { title = 'Notes', note = '• Killing Feiyin mobs can turn it into Shantotto\'s ex-spell; return it to Torino-Samarino, wait one Vana\'diel day, ask again.\n• Declining once is fine; she re-offers.' }, { title = 'Reward', note = '• Warp II\n• Title: Doctor Shantottos Flavor of the Month\n• Windurst fame 40' } } },
    { name = 'Curses, Foiled Again! (1)', group = 'Windurst', desc = 'Give Shantotto one Bomb Ash and two Bone Chips. Source: https://vanadreams.org/wiki/#quest-821', steps = { { title = 'Walkthrough', note = '• Accept from Shantotto (K-7), Windurst Walls.\n• Trade her 1 Bomb Ash + 2 Bone Chips.' }, { title = 'Notes', note = '• Zone and wait one Vana\'diel day before the sequel unlocks.' }, { title = 'Reward', note = '• Brass Rod\n• Windurst fame 20' } } },
    { name = 'Curses, Foiled Again!? (2)', group = 'Windurst', desc = 'Gather curse ingredients for Shantotto, including Hiwon-Biwon\'s hair. Source: https://vanadreams.org/wiki/#quest-822', steps = { { title = 'Requirements', note = '• Part (1) done; Windurst fame 2.\n• Zone and wait a Vana\'diel day between steps.' }, { title = 'Walkthrough', note = '• Speak to Hiwon-Biwon (K-8), then Shantotto (K-7), Windurst Walls.\n• Zone, speak to Shantotto again and accept.\n• Collect 2 Bomb Arms and 1 Revival Root.\n• Get Hiwon\'s Hair from Hiwon-Biwon (K-8).\n• Trade all four items at once to Shantotto.' }, { title = 'Reward', note = '• Misery Staff, Hiwon\'s Hair\n• Title: Hexer Vexer\n• Windurst fame 20' } } },
    { name = 'Early Bird Catches the Bookworm', group = 'Windurst', desc = 'Chase an overdue library book to Quu Bokye in Giddeus. Source: https://vanadreams.org/wiki/#quest-823', steps = { { title = 'Requirements', note = '• Glyph Hanger done; Windurst fame 2+.\n• Windurst citizens: not on missions Lost for Words or The Sixth Ministry.' }, { title = 'Walkthrough', note = '• Accept from Tosuka-Porika, Windurst Waters.\n• Get the notification from Furakku-Norakku, then speak to Orn (both Windurst Waters).\n• Trade a Silver Beastcoin to Quu Bokye (Map 2 F-6), Giddeus, for key item "Art For Everyone".\n• Speak to Orn again, then Furakku-Norakku to finish.' }, { title = 'Reward', note = '• 1,500 gil\n• Title: Savior of Knowledge\n• Windurst fame 20' } } },
    { name = 'Eco-Warrior (Windurst)', group = 'Windurst', desc = 'Level-capped hunt for three Wyrmflies in Maze of Shakhrami for Lumomo. Source: https://vanadreams.org/wiki/#quest-824', steps = { { title = 'Requirements', note = '• Windurst fame 1.\n• No other nation\'s Eco-Warrior active or finished since last conquest tally.' }, { title = 'Walkthrough', note = '• Accept from Lumomo, Windurst Waters.\n• Enter Maze of Shakhrami (Tahrongi Canyon K-5); accept the ointment from Ahko Mhalijikhari (Map 1 C-9) - this caps your level.\n• Check the ??? to pop 3 Wyrmflies and kill them all.\n• Recheck the ??? for the indigested meat.\n• Return to Lumomo.' }, { title = 'Notes', note = '• Ahko Mhalijikhari removes the cap on request.\n• Repeatable after each conquest tally.' }, { title = 'Reward', note = '• 5,000 gil, Dragon Chronicles\n• Title: Emerald Exterminator\n• Windurst fame 20' } } },
    { name = 'Flower Child', group = 'Windurst', desc = 'Give Ojha Rhawash a Lilac to unlock a Mog House feature. Source: https://vanadreams.org/wiki/#quest-826', steps = { { title = 'Walkthrough', note = '• Speak to Ojha Rhawash (C-13), Windurst Walls.\n• Trade any flower to start, then a Lilac to finish.' }, { title = 'Notes', note = '• Non-Lilac flowers are consumed; after completion, flowers are no longer consumed.' }, { title = 'Reward', note = '• Windurst fame 0' } } },
    { name = 'Food for Thought', group = 'Windurst', desc = 'Feed three researchers in Windurst Waters for gil. Source: https://vanadreams.org/wiki/#quest-827', steps = { { title = 'Requirements', note = '• Say It with Flowers not active.' }, { title = 'Walkthrough', note = '• Speak to Ohbiru-Dohbiru, then agree with Kerutoto (Windurst Waters).\n• Speak to Kenapa-Keppa 3 times; trade a Hard-boiled Egg.\n• Get Kerutoto\'s order; trade a Slice of Grilled Hare.\n• Get Ohbiru-Dohbiru\'s order; trade Windurstian Tea + Tortilla + Pamtam Kelp together.\n• Finish all three deliveries.' }, { title = 'Notes', note = '• Pay: 120 gil for the egg, 440 gil each for the other two.\n• Taking the order first is the reliable path.\n• Zone afterwards for normal dialogue.' }, { title = 'Reward', note = '• Title: Fast Food Deliverer\n• Windurst fame 20' } } },
    { name = 'From Saplings Grow', group = 'Windurst', desc = 'Archery trial: charge the Bow of Trials, beat Stolas and learn Empyreal Arrow. Source: https://vanadreams.org/wiki/#quest-828', steps = { { title = 'Requirements', note = '• Archery skill 250+; can equip Bow of Trials; no training guide held.' }, { title = 'Walkthrough', note = '• Get Bow of Trials and guide from Perih Vashai (K-7), Windurst Woods.\n• Earn 300 weapon skill points with it.\n• Trade the bow to Perih Vashai for the map to the Annals of Truth.\n• In Cape Terrigan, check the ??? (G-7) to pop Stolas; kill it.\n• Recheck the ??? for the Annals of Truth.\n• Return to Perih Vashai to learn Empyreal Arrow.' }, { title = 'Notes', note = '• Perih Vashai replaces a lost bow or cancels the quest.' }, { title = 'Reward', note = '• Bow of Trials\n• Windurst fame 20' } } },
    { name = 'Glyph Hanger', group = 'Windurst', desc = 'Courier a note between Hariga-Origa and Ipupu. Source: https://vanadreams.org/wiki/#quest-829', steps = { { title = 'Walkthrough', note = '• Accept from Hariga-Origa, Windurst Waters, and take the note.\n• Give it to Ipupu (J-8), West Sarutabaruta, for a reply.\n• Bring the reply to Hariga-Origa.' }, { title = 'Notes', note = '• Serukoko and Sohdede (Windurst Waters) give hints.' }, { title = 'Reward', note = '• 2,000 EXP\n• Key item: map of the Horutoto Ruins\n• Windurst fame 20' } } },
    { name = 'In a Stew', group = 'Windurst', desc = 'Get Woozyshrooms cooked by Ranpi-Monpi and deliver the stew to Kuoh Rhel. Source: https://vanadreams.org/wiki/#quest-831', steps = { { title = 'Requirements', note = '• Windurst fame 2; Chocobilious done.\n• A Crisis in the Making not active.' }, { title = 'Walkthrough', note = '• Accept from Kuoh Rhel (K-12), Windurst Woods; Matata (K-12) gives a hint.\n• Trade 3 Woozyshrooms to Ranpi-Monpi, Windurst Waters, for the stew.\n• Deliver it to Kuoh Rhel.' }, { title = 'Notes', note = '• Repeatable each conquest tally; zone for closing dialogue.' }, { title = 'Reward', note = '• 900 gil\n• Windurst fame 10' } } },
    { name = 'Let Sleeping Dogs Lie', group = 'Windurst', desc = 'Join a Windurst Waters prank using Blazing Peppers or a Remedy, then spill the secret. Source: https://vanadreams.org/wiki/#quest-832', steps = { { title = 'Requirements', note = '• Windurst fame 4.' }, { title = 'Walkthrough', note = '• Accept from Paku-Nakku, Windurst Waters.\n• Ask Maabu-Sonbu (E-7), Port Windurst, what is needed.\n• Trade Blazing Peppers or a Remedy to Paku-Nakku.\n• Speak to Pechiru-Mashiru.\n• Speak to Paku-Nakku and pick spoiling the surprise.\n• Return to Pechiru-Mashiru.' }, { title = 'Reward', note = '• Hypno Staff\n• Windurst fame 40' } } },
    { name = 'Lure of the Wildcat (Windurst)', group = 'Windurst', desc = 'Talk to 20 Windurst residents for Ibwam. Source: https://vanadreams.org/wiki/#quest-833', steps = { { title = 'Requirements', note = '• Treasures of Aht Urhgan enabled.' }, { title = 'Walkthrough', note = '• Accept from Ibwam (G-11), Windurst Woods; get a green Sentinel badge.\n• Woods: Soni-Muni (H-11), Etsa Rhuyuli (J-13), Cayu Pensharhumi (I-10), Umumu (I-6), Nanaa Mihgo.\n• Walls: Yoriri (J-11), Shantotto (K-7), Moan-Maon (J-6), Chomomo (H-3), Naih Arihmepp (F-5).\n• Waters: Npopo, Lago-Charago, Amagusa-Chigurusa, Funpo-Shipo, Kyume-Romeh.\n• Port: Kunchichi (E-7), Yaman-Hachuman, Choyi Totlihpa (F-6), Three of Clubs (G-7), Yujuju (M-6).\n• Report back to Ibwam.' }, { title = 'Notes', note = '• The badge is removed on completion.' }, { title = 'Reward', note = '• Key item: green invitation card\n• Windurst fame 0' } } },
    { name = 'Making Amends', group = 'Windurst', desc = 'Give Hakkuru-Rinkuru a Block of Animal Glue. Source: https://vanadreams.org/wiki/#quest-834', steps = { { title = 'Requirements', note = '• Windurst fame 2.' }, { title = 'Walkthrough', note = '• Accept from Hakkuru-Rinkuru, Port Windurst.\n• Trade him a Block of Animal Glue.' }, { title = 'Notes', note = '• Hints from Kuroido-Moido, Port Windurst.' }, { title = 'Reward', note = '• Title: Quick Fixer\n• Windurst fame 30' } } },
    { name = 'Making the Grade', group = 'Windurst', desc = 'Run test answers and a test sheet around Windurst for Fuepepe. Source: https://vanadreams.org/wiki/#quest-835', steps = { { title = 'Requirements', note = '• Teacher\'s Pet done; Windurst fame 3; level 10+.\n• Let Sleeping Dogs Lie not active.' }, { title = 'Walkthrough', note = '• Accept from Fuepepe, Windurst Waters.\n• Get the Test Answers and trade them to Fuepepe.\n• Trade them to Koru-Moru (E-7), Windurst Walls, for the tattered test sheet.\n• Give the sheet to Chomoro-Kyotoro, Windurst Waters.\n• Speak to Fuepepe to finish.' }, { title = 'Notes', note = '• Answers are only consumed by Koru-Moru.\n• Zone before talking to Fuepepe again.' }, { title = 'Reward', note = '• Aspir\n• Windurst fame 30' } } },
    { name = 'Mihgo\'s Amigo', group = 'Windurst', desc = 'Repeatable turn-in of Yagudo Necklaces to Nanaa Mihgo. Source: https://vanadreams.org/wiki/#quest-836', steps = { { title = 'Requirements', note = '• The Tenshodo Showdown and As Thick as Thieves not active.' }, { title = 'Walkthrough', note = '• Accept from Nanaa Mihgo, Windurst Woods.\n• Collect 4 Yagudo Necklaces and trade them to her.' }, { title = 'Notes', note = '• Zone between repeats.\n• Bopa Greso and Cha Lebagta give hints.' }, { title = 'Reward', note = '• Title: Cat Burglar Groupie' } } },
    { name = 'One Good Deed?', group = 'Windurst', desc = 'Beat six Peerifool in Bibiki Bay for a deed, then claim the Attohwa Chasm map. Source: https://vanadreams.org/wiki/#quest-838', steps = { { title = 'Requirements', note = '• Windurst fame 5.' }, { title = 'Walkthrough', note = '• Accept from Chipmy-Popmy (C-8), Port Windurst.\n• Click the ??? (Map 2 H-9), Bibiki Bay; kill all 6 Peerifool.\n• Click it again for the Deed to Purgonorgo Isle.\n• Give the deed to Chipmy-Popmy.\n• Zone into Boneyard Gully for the Map of the Attohwa Chasm.\n• Report to Chipmy-Popmy.' }, { title = 'Notes', note = '• Zoning resets the kill count.' }, { title = 'Reward', note = '• 3,200 gil, 2,000 EXP\n• Key item: map of the Attohwa Chasm\n• Title: Deed Verifier\n• Windurst fame 50' } } },
    { name = 'Orastery Woes', group = 'Windurst', desc = 'Club trial: charge the Club of Trials, beat Eldhrimnir in Ro\'Maeve and learn Black Halo. Source: https://vanadreams.org/wiki/#quest-839', steps = { { title = 'Requirements', note = '• Club skill 230+; can equip Club of Trials.' }, { title = 'Walkthrough', note = '• Get the Club of Trials and Weapon Training Guide from Kuroido-Moido, Port Windurst.\n• Earn 300 weapon skill points with it.\n• Trade it back for the Map to the Annals of Truth.\n• In Ro\'Maeve, check the ??? (M-8) to pop Eldhrimnir; kill it.\n• Recheck the ??? for the Annals of Truth.\n• Report to Kuroido-Moido.' }, { title = 'Notes', note = '• Kuroido-Moido replaces a lost club or cancels the quest.' }, { title = 'Reward', note = '• Club of Trials\n• Windurst fame 20' } } },
    { name = 'Overnight Delivery', group = 'Windurst', desc = 'Timed run: fetch a small bag from Mhaura for Kenapa-Keppa. Source: https://vanadreams.org/wiki/#quest-840', steps = { { title = 'Requirements', note = '• Food for Thought done, then zone once; Windurst fame 2.' }, { title = 'Walkthrough', note = '• Talk to Kenapa-Keppa (Windurst Waters) 4 times between 07:00 and 00:00, then accept.\n• In Mhaura, get the small bag from Kotan-Purutan between 18:00 and 06:00.\n• Deliver it to Kenapa-Keppa before 06:00 that day.' }, { title = 'Notes', note = '• Arriving late cancels the quest; plan the boat trip.' }, { title = 'Reward', note = '• Power Gi\n• Windurst fame 20' } } },
    { name = 'Sin Hunting', group = 'Windurst', desc = 'Ranger artifact errand via Ranguemont Pass and Jugner Forest. Source: https://vanadreams.org/wiki/#quest-841', steps = { { title = 'Requirements', note = '• Ranger main job, level 40+; The Fanged One done.' }, { title = 'Walkthrough', note = '• Accept from Perih Vashai (K-7), Windurst Woods; get the chieftainness\'s twinstone earring.\n• Enter Ranguemont Pass (East Ronfaure K-4); speak to Perchond (F-10).\n• Get Glittersand from Evil Weapons near the Waters of Oblivion (D-5); trade it to Perchond for his envelope.\n• Give the envelope to Alexius (I-6), Jugner Forest.\n• Check the ??? (H-6) in Jugner Forest.\n• Report to Perih Vashai.' }, { title = 'Notes', note = '• Earring and envelope are removed at the end.' }, { title = 'Reward', note = '• Sniping Bow\n• Windurst fame 20' } } },
    { name = 'Rock Racketeer', group = 'Windurst', desc = 'Nanaa Mihgo\'s stone errand to Bastok Markets and Palborough Mines. Source: https://vanadreams.org/wiki/#quest-842', steps = { { title = 'Requirements', note = '• Mihgo\'s Amigo done; Windurst fame 3+.' }, { title = 'Walkthrough', note = '• Accept from Nanaa Mihgo, Windurst Woods; get the sharp gray stone.\n• Sell it to Ardea (H-8), Bastok Markets.\n• Speak to Nanaa Mihgo again.\n• Mine a Sharp Stone from a Mythril Seam in Palborough Mines.\n• Trade it to Varun (H-9), Windurst Woods.' }, { title = 'Notes', note = '• Varun has an optional cutscene before the trade.' }, { title = 'Reward', note = '• Windurst fame 30' } } },
    { name = 'The Puppet Master', group = 'Windurst', desc = 'Summoner artifact quest: get an Earth Pendulum from Juroro, win in Cloister of Tremors and report to Koru-Moru. Source: https://vanadreams.org/wiki/#quest-843', steps = { { title = 'Requirements', note = '• Summoner main at first-AF level; I Can Hear a Rainbow done.\n• Blocked while Trial by Earth is active.' }, { title = 'Walkthrough', note = '• Check the House of the Hero (G-3), Windurst Walls, and accept.\n• Get the Earth Pendulum from Juroro (I-8), Port Bastok.\n• Win the Puppet Master battlefield in Cloister of Tremors.\n• Return to Juroro (I-8).\n• Speak to Koru-Moru (E-7), Windurst Walls.' }, { title = 'Notes', note = '• Juroro replaces a lost pendulum.\n• Zone before Class Reunion.' }, { title = 'Reward', note = '• Kukulcan\'s Staff, Earth Pendulum\n• Windurst fame 20' } } },
    { name = 'I Can Hear a Rainbow', group = 'Windurst', desc = 'Summoner unlock: expose Carbuncle\'s Ruby to seven weather types, then offer it in La Theine Plateau. Source: https://vanadreams.org/wiki/#quest-844', steps = { { title = 'Requirements', note = '• Carbuncle\'s Ruby in main inventory (not bags/satchel).' }, { title = 'Walkthrough', note = '• Check the door in Windurst Walls with the ruby and accept after the cutscene.\n• Zone into open-field areas of the three nations or Outlands (e.g. West Ronfaure, North Gustaberg, Sauromugue Champaign).\n• A light appears on entry if that weather element is still uncollected.\n• Collect clear, fire, water, earth, wind, ice and thunder.\n• Trade the ruby to the ??? (G-6), La Theine Plateau.' }, { title = 'Notes', note = '• Each element counts once; check weather before zoning.' }, { title = 'Reward', note = '• Key item: job gesture: summoner\n• Title: Rainbow Weaver\n• Windurst fame 20' } } },
    { name = 'Truth, Justice, and the Onion Way', group = 'Windurst', desc = 'Give Kohlo-Lakolo a Rarab Tail. Source: https://vanadreams.org/wiki/#quest-845', steps = { { title = 'Walkthrough', note = '• Accept from Kohlo-Lakolo (G-5), Port Windurst.\n• Trade him a Rarab Tail.' }, { title = 'Notes', note = '• Optional lines: Gomada-Vulmada, Papo-Hopo, Pichichi, Pyo Nzon, Shanruru, Yafa Yaa.\n• Zone before the next quest in the series.' }, { title = 'Reward', note = '• Justice Badge\n• Title: Star Onion Brigade Member\n• Windurst fame 20' } } },
    { name = 'Know One\'s Onions', group = 'Windurst', desc = 'Bring Kohlo-Lakolo four Wild Onions; Windurst rank 3+ shortens it. Source: https://vanadreams.org/wiki/#quest-846', steps = { { title = 'Requirements', note = '• Level 5+; Truth, Justice, and the Onion Way done.' }, { title = 'Walkthrough', note = '• Accept from Kohlo-Lakolo (G-5), Port Windurst.\n• Trade him 4 Wild Onions (rank 3+: done here).\n• Below rank 3: check the House of the Hero door (G-3), Windurst Walls, then speak to Kohlo-Lakolo.' }, { title = 'Notes', note = '• Zone afterwards for normal NPC dialogue.' }, { title = 'Reward', note = '• Blaze Spikes\n• Title: Sob Super Hero\n• Windurst fame 20' } } },
    { name = 'Inspector\'s Gadget!', group = 'Windurst', desc = 'Have Chamama make a fake moustache from Saruta Cotton for Kohlo-Lakolo. Source: https://vanadreams.org/wiki/#quest-847', steps = { { title = 'Requirements', note = '• Know One\'s Onions done; level 5+; Windurst fame 2.' }, { title = 'Walkthrough', note = '• Accept from Kohlo-Lakolo (G-5), Port Windurst; Pichichi (G-5) gives a hint.\n• Speak to Chamama, Windurst Waters.\n• Trade her 4 Saruta Cotton for the fake moustache.\n• Return to Kohlo-Lakolo.' }, { title = 'Notes', note = '• Zone before Onion Rings.' }, { title = 'Reward', note = '• Heko Obi\n• Title: Fake Moustached Investigator\n• Windurst fame 20' } } },
    { name = 'Onion Rings', group = 'Windurst', desc = 'Timed fetch of an old ring from Castle Oztroja for Kohlo-Lakolo. Source: https://vanadreams.org/wiki/#quest-848', steps = { { title = 'Requirements', note = '• Inspector\'s Gadget done; level 5+; Windurst fame 3.' }, { title = 'Walkthrough', note = '• Speak to Kohlo-Lakolo (G-5), Port Windurst; the timer starts.\n• Check the trap door in Castle Oztroja for the old ring.\n• Return within one Vana\'diel day.\n• Speak to other Port Windurst NPCs, then check Door: House of the Hero (G-3), Windurst Walls.' }, { title = 'Notes', note = '• Late return: he still completes it for you.\n• Zone before the next quest.' }, { title = 'Reward', note = '• Title: Star Onion Brigadier\n• Windurst fame 30' } } },
    { name = 'Crying Over Onions', group = 'Windurst', desc = 'Swap a Star Spinel for a Star Necklace and take it to Kohlo-Lakolo. Source: https://vanadreams.org/wiki/#quest-849', steps = { { title = 'Requirements', note = '• Onion Rings done, then zone; level 5+; Windurst fame 5.' }, { title = 'Walkthrough', note = '• Collect the Onion Rings reward from Kohlo-Lakolo (G-5), zone, then speak again to start.\n• Speak to Honoi-Gomoi, Windurst Waters (Nanaa Mihgo optional).\n• Trade Honoi-Gomoi a Star Spinel for a Star Necklace.\n• Bring it to Kohlo-Lakolo for a cutscene.\n• Return to Honoi-Gomoi.' }, { title = 'Reward', note = '• Star Necklace, Bouncer Club\n• Windurst fame 50' } } },
    { name = 'Wild Card', group = 'Windurst', desc = 'Get a Joker Card from a Toraimarai Canal coffer for Honoi-Gomoi. Source: https://vanadreams.org/wiki/#quest-850', steps = { { title = 'Requirements', note = '• Crying Over Onions done; level 5+; Windurst fame 5.' }, { title = 'Walkthrough', note = '• Start with Honoi-Gomoi, Windurst Waters.\n• Speak to Kohlo-Lakolo (G-5), Port Windurst.\n• Check the House of the Hero door (G-3), Windurst Walls.\n• Open the Toraimarai Canal Treasure Coffer (Tor. Coffer Key or lockpick) for the Joker Card.\n• Go back to the House of the Hero (rank 9+: meet Apururu in Windurst Woods).\n• Return to Honoi-Gomoi.' }, { title = 'Notes', note = '• Coffer gives the card only at this step.\n• Handing over the card pays 8,000 gil.' }, { title = 'Reward', note = '• Title: Dream Dweller\n• Windurst fame 60' } } },
    { name = 'The Promise', group = 'Windurst', desc = 'Get an invisible man sticker from Chamama for Kohlo-Lakolo. Source: https://vanadreams.org/wiki/#quest-851', steps = { { title = 'Requirements', note = '• Wild Card done; level 5+; Windurst fame 5.' }, { title = 'Walkthrough', note = '• Accept from Kohlo-Lakolo (G-5), Port Windurst.\n• Speak to Chamama, Windurst Waters.\n• Trade her a Shoalweed for the sticker.\n• Return to Kohlo-Lakolo.' }, { title = 'Notes', note = '• Ending differs at Windurst rank 9.' }, { title = 'Reward', note = '• Promise Badge\n• Windurst fame 60' } } },
    { name = 'Say it with Flowers', group = 'Windurst', desc = 'Repeatable: give Moari-Kaaori a Tahrongi Cactus or a flower. Source: https://vanadreams.org/wiki/#quest-852', steps = { { title = 'Requirements', note = '• Windurst fame 2.' }, { title = 'Walkthrough', note = '• Accept from Moari-Kaaori, Windurst Waters.\n• Take a Tahrongi Cactus from the Tahrongi Cacti (F-6), Tahrongi Canyon.\n• Trade it to Moari-Kaaori.' }, { title = 'Notes', note = '• First cactus: Iron Sword; later cacti: 400 gil.\n• Ohbiru-Dohbiru sells Carnation, Red Rose, Rain Lily, Lilac, Amaryllis, Marguerite (100-300 gil); flowers also work but pay less.\n• Zone before repeating.' }, { title = 'Reward', note = '• Red Rose, Carnation, Rain Lily, Tahrongi Cactus, Lilac, Amaryllis, Marguerite, Iron Sword\n• Title: Cupids Florist' } } },
    { name = 'Scooped!', group = 'Windurst', desc = 'Give Naiko-Paneiko a Bronze Box. Source: https://vanadreams.org/wiki/#quest-853', steps = { { title = 'Requirements', note = '• Making Headlines done.' }, { title = 'Walkthrough', note = '• Accept from Naiko-Paneiko, Windurst Waters.\n• Trade him a Bronze Box.' }, { title = 'Notes', note = '• Hint from Chyuk-Kochak.' }, { title = 'Reward', note = '• 1,500 gil\n• Windurst fame 20' } } },
    { name = 'Star Struck', group = 'Windurst', desc = 'Bring Koru-Moru a Meteorite; starts by carrying a Torn Epistle. Source: https://vanadreams.org/wiki/#quest-854', steps = { { title = 'Requirements', note = '• Torn Epistle in inventory.' }, { title = 'Walkthrough', note = '• Speak to Koru-Moru (E-7), Windurst Walls, with the epistle and accept.\n• Trade him a Meteorite.' }, { title = 'Notes', note = '• Torn Epistles traded during the quest pay a little gil.\n• Luuh Koplehn comments while active.' }, { title = 'Reward', note = '• Cmp. Eye Circlet\n• Windurst fame 20' } } },
    { name = 'The Tenshodo Showdown', group = 'Windurst', desc = 'Thief AF1: carry a Tenshodo envelope between Lower Jeuno and Selbina. Source: https://vanadreams.org/wiki/#quest-855', steps = { { title = 'Requirements', note = '• Thief main job at first-AF level.' }, { title = 'Walkthrough', note = '• Get the Letter from the Tenshodo from Nanaa Mihgo, Windurst Woods.\n• Give it to Harnek (J-7), Lower Jeuno, for the Tenshodo Envelope.\n• Speak to Elfriede (J-9), Selbina; trade her a Bowl of Quadav Stew for the Signed Envelope.\n• Bring it to Harnek (J-7).' }, { title = 'Reward', note = '• Marauder\'s Knife\n• Windurst fame 20' } } },
    { name = 'As Thick as Thieves', group = 'Windurst', desc = 'Thief AF2: win goblin dice games in Dangruf Wadi and climb a Sauromugue tower to sign two forged envelopes. Source: https://vanadreams.org/wiki/#quest-856', steps = { { title = 'Requirements', note = '• Thief main at second-AF level; The Tenshodo Showdown done.\n• Bring Grapnel, Rock Salt, Gausebit Grass, Lizard Egg.' }, { title = 'Walkthrough', note = '• Accept from Nanaa Mihgo, Windurst Woods; get the gang whereabouts note and two forged envelopes.\n• Agree to help Sniggnix (H-10), Lower Jeuno.\n• In Dangruf Wadi (South Gustaberg D-9), trade Rock Salt, Gausebit Grass, then Lizard Egg to the three ??? and beat each goblin.\n• Check the ??? (F-7), North Gustaberg; kill Gambilox\' Wanderling; recheck for the Regal Die.\n• Trade the Regal Die to Sniggnix for the second signed envelope.\n• Remove all gear; trade the Grapnel to the ??? in Sauromugue Champaign for the first.\n• Bring both to Nanaa Mihgo.' }, { title = 'Notes', note = '• Lost dice games can be retried; each ??? takes only its item.\n• The other tower ??? may pop a Climbpix Highrise.\n• Hints: Cha Lebagta, Bopa Greso.' }, { title = 'Reward', note = '• Rogue\'s Bonnet, Regal Die\n• Windurst fame 20' } } },
    { name = 'Hitting the Marquisate', group = 'Windurst', desc = 'Thief AF3: Chandelier Coal from Garlaige Citadel, Quake Grenades for Yatniel, and a Pickaxe dig. Source: https://vanadreams.org/wiki/#quest-857', steps = { { title = 'Requirements', note = '• Thief main at third-AF level; As Thick as Thieves done.\n• Bring 4 Quake Grenades and a Pickaxe.' }, { title = 'Walkthrough', note = '• Accept from Nanaa Mihgo, Windurst Woods; get the Cat Burglar\'s note.\n• Get bomb incense from Hagain (H-8), Mhaura.\n• In Garlaige Citadel (Sauromugue J-10), check the seven ??? following the presence\'s hinted direction; pop and kill the Chandelier.\n• Trade the Chandelier Coal to Hagain.\n• Speak to Yatniel (G-10), Lower Jeuno; trade 4 Quake Grenades.\n• Speak to Nanaa Mihgo.\n• Trade a Pickaxe to the ??? (H-11), La Theine Plateau.' }, { title = 'Notes', note = '• Bomb incense is consumed with the coal turn-in.' }, { title = 'Reward', note = '• Rogue\'s Poulaines\n• Title: Paragon of Thief Excellence' } } },
    { name = 'Teacher\'s Pet', group = 'Windurst', desc = 'Give Moreno-Toeno a Bird Feather and a 2Leaf Mandra Bud. Source: https://vanadreams.org/wiki/#quest-858', steps = { { title = 'Walkthrough', note = '• Speak to Moreno-Toeno, Windurst Waters, twice and agree.\n• Trade him a Bird Feather + 2Leaf Mandra Bud.' }, { title = 'Notes', note = '• Zone before Making the Grade.' }, { title = 'Reward', note = '• Windurst fame 10' } } },
    { name = 'The Fanged One', group = 'Windurst', desc = 'Ranger unlock: kill Old Sabertooth in Sauromugue Champaign. Source: https://vanadreams.org/wiki/#quest-859', steps = { { title = 'Requirements', note = '• Level 30+ (advanced jobs unlocked).' }, { title = 'Walkthrough', note = '• Accept from Perih Vashai (K-7), Windurst Woods.\n• Check the Tiger Bones (L-10), Sauromugue Champaign, to pop Old Sabertooth.\n• Kill it, recheck the bones for the old tiger\'s fang.\n• Report to Perih Vashai.' }, { title = 'Notes', note = '• Failing the time limit means retrying after a short wait.\n• Unlocks Ranger.' }, { title = 'Reward', note = '• Ranger\'s Necklace\n• Title: The Fanged One\n• Windurst fame 20' } } },
    { name = 'The Moonlit Path', group = 'Windurst', desc = 'Collect all six elemental whispers, then win the Moonlit Path fight at the Full Moon Fountain. Given by Leepe-Hoppe, Windurst Waters. Source: https://vanadreams.org/wiki/#quest-860', steps = { { title = 'Requirements', note = '• Windurst fame 6\n• Whispers of flames, tremors, tides, gales, frost and storms' }, { title = 'Walkthrough', note = '• Accept from Leepe-Hoppe (Windurst Waters).\n• Clear Trial by Fire, Earth, Water, Wind, Ice and Lightning for the six whispers.\n• Hand the whispers to Leepe-Hoppe; get a moon bauble.\n• Win Moonlit Path at the Full Moon Fountain for the whisper of the moon.\n• Return to Leepe-Hoppe and pick a reward.' }, { title = 'Notes', note = '• Choices: Fenrir\'s Stone, Cape, Torque, Earring, Ancients\' Key, 15,000 gil, Fenrir spell (SMN) or Fenrir whistle (needs trainer\'s whistle).\n• Repeatable once per Japanese day.' }, { title = 'Reward', note = '• Title: Heir of the New Moon\n• Windurst fame +60' } } },
    { name = 'Toraimarai Turmoil', group = 'Windurst', desc = 'Repeatable Starmite Shell delivery for Ohbiru-Dohbiru, Windurst Waters. Source: https://vanadreams.org/wiki/#quest-861', steps = { { title = 'Requirements', note = '• Blue Ribbon Blues done\n• Windurst fame 6' }, { title = 'Walkthrough', note = '• Accept from Ohbiru-Dohbiru (Windurst Waters); get the Rhinostery certificate.\n• Gather 3 Starmite Shells.\n• Trade all 3 to Ohbiru-Dohbiru.' }, { title = 'Notes', note = '• Repeat by speaking to him again and accepting.' }, { title = 'Reward', note = '• 4,500 gil\n• Title: Certified Rhinostery Venturer\n• Windurst fame +16' } } },
    { name = 'Waking Dreams', group = 'Windurst', desc = 'Kerutoto supplies dream incense for the Diabolos fight, Waking Dreams, at The Shrouded Maw. Given in Windurst Waters. Source: https://vanadreams.org/wiki/#quest-862', steps = { { title = 'Requirements', note = '• CoP mission \'Darkness Named\' done' }, { title = 'Walkthrough', note = '• Get the vial of dream incense from Kerutoto (Windurst Waters); talk again for details if wanted.\n• At The Shrouded Maw, use the Memento Circle to enter Waking Dreams and beat Diabolos (6 players max, 30 min).\n• Bring the whisper of dreams to Kerutoto and choose a reward.' }, { title = 'Notes', note = '• Choices: Diabolos\'s Pole, Earring, Ring, Torque, 15,000 gil, or Diabolos spell (SMN).\n• Repeatable after one Japanese day; Kerutoto hands out a new vial.' } } },
    { name = 'Water Way to Go', group = 'Windurst', desc = 'Fetch Giddeus Water in a canteen for Ohbiru-Dohbiru, Windurst Waters. Source: https://vanadreams.org/wiki/#quest-863', steps = { { title = 'Requirements', note = '• Overnight Delivery done\n• Windurst fame 3' }, { title = 'Walkthrough', note = '• Accept from Ohbiru-Dohbiru; receive a Rhinost. Canteen.\n• Trade the canteen to Giddeus Spring (Giddeus) for Giddeus Water.\n• Trade the water to Ohbiru-Dohbiru.' }, { title = 'Notes', note = '• Lost canteen: ask him for a replacement.\n• Repeatable until Windurst fame reaches 5.' }, { title = 'Reward', note = '• Windurst fame +16' } } },
    { name = 'Wondering Minstrel', group = 'Windurst', desc = 'Get Rosewood Lumber via Ruslan in Lower Jeuno for the minstrel Jatan-Paratan, Windurst Waters. Source: https://vanadreams.org/wiki/#quest-864', steps = { { title = 'Requirements', note = '• Windurst fame 5' }, { title = 'Walkthrough', note = '• Speak to Jatan-Paratan (Windurst Waters), answer that you don\'t remember his playing, then speak again to accept.\n• Speak to Ruslan (I-8, Lower Jeuno) and agree to help.\n• Obtain a Piece of Rosewood Lumber.\n• Trade it to Jatan-Paratan.' }, { title = 'Notes', note = '• Ruslan and the Windurst Waters tavern NPCs have unique lines until you zone.' }, { title = 'Reward', note = '• Faerie Piccolo\n• Title: Down Piper Pipe Upperer\n• Windurst fame +50' } } },
    { name = 'Smash the Orcish Scouts', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 1-1: hunt orcs for an Orcish Axe as proof. Source: https://vanadreams.org/wiki/#mission-0', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10) or Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Kill nearby orcs until an Orcish Axe drops.\n• Trade the axe to any of those three officers.' }, { title = 'Notes', note = '• Repeatable for rank points.' } } },
    { name = 'Bat Hunt', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 1-2: inspect the tomb in King Ranperre\'s Tomb and return with proof. Source: https://vanadreams.org/wiki/#mission-1', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; 1-1 done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• In King Ranperre\'s Tomb, examine the Tombstone in the upper chamber.\n• Get Orcish Mail Scales from orcs (first time) or a Bat Fang (repeats).\n• Trade it to one of the officers.' }, { title = 'Notes', note = '• Repeatable; repeats need the Bat Fang.' } } },
    { name = 'Save the Children', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 1-3: free the children held by orcs in Ghelsba Outpost. Source: https://vanadreams.org/wiki/#mission-2', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; Bat Hunt done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10), Endracion (F-9) or Grilau (C-8).\n• See Arnau\'s (M-6, Northern San d\'Oria) cutscene.\n• Enter Ghelsba Outpost from West Ronfaure (E-4) and win Save the Children.\n• Use the Orcish hut key on the Hut Door (F-10), Ghelsba Outpost.\n• Report to an officer.' }, { title = 'Notes', note = '• First clear: rank 2 plus 1,000 gil; repeats give rank points.\n• Arnau\'s scene can be skipped on repeats; he has one more scene after completion.' }, { title = 'Reward', note = '• 1,000 gil' } } },
    { name = 'The Rescue Drill', group = 'Mission: San d\'Oria', desc = 'San d\'Oria rank 2 mission: visit the knights training on La Theine Plateau, deliver a sword to Ruillont in Ordelles Caves, and turn in a certificate. Source: https://vanadreams.org/wiki/#mission-3', steps = { { title = 'Requirements', note = '• San d\'Oria citizen at the right rank; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Endracion (F-9)/Ambrotien (K-10), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• La Theine Plateau: speak to Galaihaurat (E-6), Equesobillot (F-6), Deaufrain (F-6), Vicorpasse, Laurisse (F-7), Narvecaint, in that order.\n• Speak to Ruillont in Ordelles Caves.\n• Back on the plateau, get a Bronze Sword from Galaihaurat, Equesobillot or Deaufrain.\n• Trade the sword to Ruillont.\n• Get the Rescue Training Certificate from Vicorpasse (F-6).\n• Hand the certificate to an officer.' }, { title = 'Notes', note = '• The sword-giver is random among the three; check each.\n• Augevinne and Yaucevouchat only chat.' } } },
    { name = 'The Davoi Report', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 2-2: find a missing document in Davoi and carry the Temple Knight\'s report home. Source: https://vanadreams.org/wiki/#mission-4', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; 2-1 done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Enter Davoi from Jugner Forest (G-12); speak to Zantaviat (J-7).\n• Search the ??? spots (try the east one near x 211) for the lost document.\n• Give it to Zantaviat for the Temple Knight\'s Davoi report.\n• Deliver the report to an officer.' }, { title = 'Notes', note = '• On the first clear the Chateau d\'Oraguille door in Northern San d\'Oria also accepts the report.\n• If the first ??? is empty, try the others.' } } },
    { name = 'Journey Abroad', group = 'Mission: San d\'Oria', desc = 'San d\'Oria rank 2 mission: take Halver\'s letter to the Bastok and Windurst consuls, then report back. Source: https://vanadreams.org/wiki/#mission-5', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 2; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Get the letter to the consuls from Halver (I-9), Chateau d\'Oraguille.\n• Give it to Savae E Paleade (I-9, Metalworks) or Mourices (G-10, Windurst Woods) to start that nation\'s Journey mission.\n• Finish both the Bastok and Windurst Journey missions, earning a Kindred report.\n• Give the Kindred report to Halver.' }, { title = 'Notes', note = '• Either nation first.\n• Halver may hand over Cipher: Halver if you lack that Trust.\n• Rank 3 on completion.' }, { title = 'Reward', note = '• 3,000 gil\n• Key item: Adventurer\'s Certificate\n• Title: Certified Adventurer' } } },
    { name = 'Journey to Bastok', group = 'Mission: San d\'Oria', desc = 'Mine Mythril Sand in the Bastok region and bring it to Savae E Paleade in Metalworks. Source: https://vanadreams.org/wiki/#mission-6', steps = { { title = 'Requirements', note = '• San d\'Oria citizen on Journey to Bastok (rank 2)' }, { title = 'Walkthrough', note = '• Speak to Pius (K-8), Metalworks.\n• Get 3 Pickaxes from Grohm (H-9), Metalworks.\n• Mine Mythril Sand at a Bastok-region mining point.\n• Trade it to Savae E Paleade (I-9), Metalworks.' }, { title = 'Notes', note = '• Full bag: return to Grohm with space for the Pickaxes.\n• Grohm repeats the instructions if needed.' } } },
    { name = 'Journey to Windurst', group = 'Mission: San d\'Oria', desc = 'First Windurst leg: deliver the shield offering from Heaven\'s Tower to Giddeus, then bring two Parana Shields to Mourices. Source: https://vanadreams.org/wiki/#mission-7', steps = { { title = 'Requirements', note = '• San d\'Oria citizen on Journey to Windurst (rank 2)' }, { title = 'Walkthrough', note = '• Zone into Heaven\'s Tower for a cutscene.\n• Get the shield offering from Kupipi (Map 2, H-6).\n• Present it to Uu Zhoumo (Map 2, F-6), Giddeus.\n• Obtain 2 Parana Shields.\n• Trade both to Mourices (G-10), Windurst Woods.' }, { title = 'Notes', note = '• Mourices, Catalia, Erpolant and Forine remind you of the next step.\n• A second part follows.' }, { title = 'Reward', note = '• Cipher: Semih' } } },
    { name = 'Journey to Bastok', group = 'Mission: San d\'Oria', desc = 'Second Bastok leg of 2-3: win the rank 2 fight at Waughroon Shrine and report in Metalworks. Source: https://vanadreams.org/wiki/#mission-8', steps = { { title = 'Requirements', note = '• Journey Abroad (2-3) active, sent to Bastok a second time' }, { title = 'Walkthrough', note = '• Get the briefing from Pius (K-8), Metalworks.\n• Speak to Grohm (H-9) to be sent to the shrine.\n• Win the Rank 2 Mission fight at Waughroon Shrine for the Kindred Crest.\n• Give the crest to Savae E Paleade (I-9) for the Kindred Report.' }, { title = 'Notes', note = '• Chantain, Lutia and Riault only chat.\n• Bring the Kindred Report to Halver (Chateau d\'Oraguille) to finish Journey Abroad.' }, { title = 'Reward', note = '• Key items: Kindred crest, Kindred report, dark key' } } },
    { name = 'Journey to Windurst', group = 'Mission: San d\'Oria', desc = 'Second Windurst leg: use the dark key to fight at Balga\'s Dais, then report to Kupipi and Mourices. Source: https://vanadreams.org/wiki/#mission-9', steps = { { title = 'Requirements', note = '• San d\'Oria citizen on Journey to Windurst, part two' }, { title = 'Walkthrough', note = '• Get the dark key from Kupipi (Map 2, H-6), Heaven\'s Tower.\n• Enter the Rank 2 fight at the Burning Circle, Balga\'s Dais.\n• Kill the Black Dragon for the Kindred crest.\n• Talk to Kupipi again.\n• Report to Mourices (G-10), Windurst Woods.' }, { title = 'Notes', note = '• Mourices restates the next step after the fight.\n• Party size is limited; check entry rules at the Burning Circle.' }, { title = 'Reward', note = '• Key items: Kindred crest, dark key, Kindred report' } } },
    { name = 'Infiltrate Davoi', group = 'Mission: San d\'Oria', desc = 'San d\'Oria rank 3 mission: scout Davoi, bring Quemaricond\'s report to the Prince Royal\'s room, and on repeats gather three block codes. Source: https://vanadreams.org/wiki/#mission-10', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Endracion (F-9)/Ambrotien (K-10), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Click the Prince Royal\'s room door, Chateau d\'Oraguille.\n• Enter Davoi from Jugner Forest (G-12) and watch the arrival scene.\n• Get the Royal Knights\' Davoi Report from Quemaricond (G-7).\n• Take it to the Prince Royal\'s room door.' }, { title = 'Repeat version', note = '• Later runs use new objectives: speak to Zantaviat in Davoi.\n• Check the three ! map spots for the East, South and North Block Codes.\n• Give them to Zantaviat, then report to an officer.' } } },
    { name = 'The Crystal Spring', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 3-2: hand over a Crystal Bass, then speak to Chalvatot in Chateau d\'Oraguille. Source: https://vanadreams.org/wiki/#mission-11', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; 3-1 done; no other nation mission active\n• 1 Crystal Bass (fished)' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Trade the Crystal Bass to an officer.\n• Zone from Northern San d\'Oria into Chateau d\'Oraguille for the scene.\n• Speak to Chalvatot (F-7).' }, { title = 'Notes', note = '• Repeats only need another Crystal Bass traded to an officer.' } } },
    { name = 'Appointment to Jeuno', group = 'Mission: San d\'Oria', desc = 'Carry the king\'s letter to the ambassador in Ru\'Lude Gardens and unlock the Cermet Door in Lower Delkfutt\'s Tower. Source: https://vanadreams.org/wiki/#mission-12', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; 3-2 done; enough rank; no other mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Speak to Halver (I-9), Chateau d\'Oraguille.\n• Open the Great Hall (throne room) door for the letter to the ambassador.\n• Give it to Nelcabrit (G-9), Ru\'Lude Gardens.\n• Trade a Delkfutt Key to the Cermet Door, Lower Delkfutt\'s Tower.\n• Examine the San d\'Orian Embassy door in Ru\'Lude Gardens.' }, { title = 'Notes', note = '• The Delkfutt Key turns into a key item once used.\n• Arsha and Chupaile only chat.' }, { title = 'Reward', note = '• 5,000 gil' } } },
    { name = 'Magicite', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 4-1: gather three Magicite for the Archduke in Ru\'Lude Gardens and earn an airship pass. Source: https://vanadreams.org/wiki/#mission-13', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 4 with enough rank points' }, { title = 'Walkthrough', note = '• Speak to Nelcabrit (G-9), Ru\'Lude Gardens, then examine the Archduke\'s door for the archducal audience permit.\n• Examine the Archduke\'s inner door for the letter to Aldo.\n• Give it to Aldo (J-8), Lower Jeuno; get the silver bell.\n• Speak to Paya-Sabya (I-8), Upper Jeuno, then Muckvix (H-10), Lower Jeuno, for the Yagudo torch.\n• Collect Magicite: Orastone (Altar Room), Optistone (Monastic Cavern) and Aurastone (Qulun Dome), any order.\n• Examine the Archduke\'s door with all three for the airship pass.\n• Speak to Nelcabrit to finish.' }, { title = 'Notes', note = '• Already own an airship pass: extra gil instead.\n• The Magicite are removed on turn-in.' }, { title = 'Reward', note = '• 10,000 gil\n• Key item: message to Jeuno' } } },
    { name = 'The Ruins of Fei\'Yin', group = 'Mission: San d\'Oria', desc = 'San d\'Oria rank 5 mission: carry the New Fei\'Yin Seal to Fei\'Yin, win at Qu\'Bia Arena, and give the Burnt Seal to Halver. Source: https://vanadreams.org/wiki/#mission-14', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 5; no other nation mission active\n• Message to Jeuno delivered' }, { title = 'Walkthrough', note = '• Accept from Endracion (F-9)/Ambrotien (K-10), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Get the New Fei\'Yin Seal from Halver (I-9), Chateau d\'Oraguille.\n• Enter Fei\'Yin for a cutscene.\n• Win the Rank 5 Mission fight at Qu\'Bia Arena\'s Burning Circle for the Burnt Seal.\n• Give the Burnt Seal to Halver.' }, { title = 'Notes', note = '• The fight consumes the New Fei\'Yin Seal.' } } },
    { name = 'The Shadow Lord', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 5-2: beat the Shadow Lord in the Throne Room and bring Halver the Shadow Fragment. Source: https://vanadreams.org/wiki/#mission-15', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 5; no other mission active' }, { title = 'Walkthrough', note = '• Accept from a San d\'Oria mission officer.\n• Speak to Halver (I-9), Chateau d\'Oraguille.\n• Examine Door: Prince Royal\'s Rm (H-7) for a scene.\n• Examine the Throne Room (G-8) entrance to start the fight.\n• Win and watch the scene for the Shadow Fragment.\n• Give it to Halver.' }, { title = 'Notes', note = '• Raises you to rank 6.\n• Optional scene afterward at Door: Great Hall.\n• Also starts the Zilart mission The New Frontier if not yet done.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Leaute\'s Last Wishes', group = 'Mission: San d\'Oria', desc = 'Fetch a dreamrose from Western Altepa Desert and carry it into Chateau d\'Oraguille. Source: https://vanadreams.org/wiki/#mission-16', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; 5-2 done; enough rank; no other mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Speak to Halver (I-9), then open the Great Hall door.\n• Examine the Dreamrose (G-7), Western Altepa Desert, and kill the Sabotender Enamorado.\n• Examine the Dreamrose again for the dreamrose.\n• Return to Halver.\n• Holding the dreamrose, step into the trigger area by the throne room.' }, { title = 'Notes', note = '• The dreamrose is removed at the end.\n• Arsha and Chupaile only chat.' }, { title = 'Reward', note = '• Key item: piece of paper' } } },
    { name = 'Ranperre\'s Final Rest', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 6-2: defeat three corrupted knights in King Ranperre\'s Tomb and recover an old book. Source: https://vanadreams.org/wiki/#mission-17', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 6; no other mission active' }, { title = 'Walkthrough', note = '• Accept from a San d\'Oria mission officer.\n• Examine Door: Prince Royal\'s Rm (H-7), Chateau d\'Oraguille.\n• In King Ranperre\'s Tomb, examine the Heavy Stone Door and kill Corrupted Yorgos, Corrupted Soffeil and Corrupted Ulbrig.\n• Examine the door again, agree, and go on to the Tombstone.\n• Examine the Tombstone for the Ancient San d\'Orian Book.\n• Give the book to Endracion (F-9)/Ambrotien (K-10) or Grilau (C-8); zone and speak to them again.\n• Examine Door: Prince Royal\'s Rm again.\n• Examine the Heavy Stone Door in the tomb again.\n• Report to an officer.' }, { title = 'Notes', note = '• Raises you to rank 7.\n• Perfaumand has extra lines.' }, { title = 'Reward', note = '• 40,000 gil' } } },
    { name = 'Prestige of the Papsque', group = 'Mission: San d\'Oria', desc = 'San d\'Oria rank 7 mission: take an Ancient San d\'Orian Tablet from a marauder in West Ronfaure to the Papal Chambers. Source: https://vanadreams.org/wiki/#mission-18', steps = { { title = 'Requirements', note = '• San d\'Oria citizen at the right rank; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Endracion (F-9)/Ambrotien (K-10), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Click the Papal Chambers door (M-7), Northern San d\'Oria.\n• Click the ??? (E-8), West Ronfaure, and kill Marauder Dvogzog.\n• Click the ??? again for the tablet.\n• Take it to the Papal Chambers door.' }, { title = 'Notes', note = '• Lost the fight: click the ??? to respawn him.' } } },
    { name = 'The Secret Weapon', group = 'Mission: San d\'Oria', desc = 'San d\'Oria rank 7 mission: win The Secret Weapon at Horlais Peak and return with the crystal dowser. Source: https://vanadreams.org/wiki/#mission-19', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 7, enough rank points; no other nation mission active\n• Prestige of the Papsque done' }, { title = 'Walkthrough', note = '• Accept from Grilau (C-8), Northern San d\'Oria, or Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria.\n• Step into the trigger area in Chateau d\'Oraguille for a scene.\n• Win The Secret Weapon at Horlais Peak for the crystal dowser.\n• Turn the dowser in to an officer.' }, { title = 'Notes', note = '• Raises you to rank 8.' }, { title = 'Reward', note = '• 60,000 gil' } } },
    { name = 'Coming of Age', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 8-1: collect Drops of Amnio at the Fountain of Kings in Quicksand Caves for Halver. Source: https://vanadreams.org/wiki/#mission-20', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; previous mission and rank met; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from a gate guard in Southern or Northern San d\'Oria.\n• Speak to Halver (I-9), Chateau d\'Oraguille.\n• Check the Fountain of Kings (Map 2, G-14), Quicksand Caves; Honor and Valor spawn.\n• Kill one; the other must be dead or despawned.\n• Check the fountain again for the Drops of Amnio.\n• Show them to Halver.' }, { title = 'Notes', note = '• Afterward wait ~1 minute, then zone into Northern San d\'Oria for the last scene; gate guards ignore you until then.\n• Honor and Valor fight together; bring a party.' } } },
    { name = 'Lightbringer', group = 'Mission: San d\'Oria', desc = 'Use the crystal dowser to find broken key pieces in the Temple of Uggalepih, then beat the Granite Door guardians. Gives rank 9. Source: https://vanadreams.org/wiki/#mission-21', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 8; Coming of Age done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien, Endracion or Grilau.\n• Talk to the Great Hall door, Chateau d\'Oraguille, for a scene.\n• Get the crystal dowser from Rahal (H-9).\n• Check the three ??? (qm_key) spots in the Temple of Uggalepih for one broken key piece each.\n• With all three, examine the Granite Door; kill Nio-A and Nio-Hum.\n• Examine the Granite Door again.\n• Return to the Great Hall (I-9) for the final scene.' }, { title = 'Notes', note = '• The door stays shut without all three pieces.\n• Curilla adds optional scenes at certain stages.\n• Afterward, the Prince Royal\'s and Prince Regent\'s doors each give a one-time scene.' }, { title = 'Reward', note = '• 80,000 gil' } } },
    { name = 'Breaking Barriers', group = 'Mission: San d\'Oria', desc = 'Gather three figures from ??? spots in Valley of Sorrows, Xarcabard and Batallia Downs for the Great Hall. Source: https://vanadreams.org/wiki/#mission-22', steps = { { title = 'Requirements', note = '• San d\'Oria citizen; 8-2 done; enough rank; no other mission active' }, { title = 'Walkthrough', note = '• Accept from Ambrotien (K-10)/Endracion (F-9), Southern San d\'Oria, or Grilau (C-8), Northern San d\'Oria.\n• Open the Great Hall door, Chateau d\'Oraguille.\n• Valley of Sorrows ??? (I-8): figure of Titan.\n• Xarcabard ??? (H-7): figure of Garuda.\n• Batallia Downs ??? (J-11): kill Suparna and Suparna Fledgling, then check again for the figure of Leviathan.\n• Bring all three to the Great Hall door.' }, { title = 'Notes', note = '• Figures are removed at turn-in.\n• Halver has extra lines meanwhile.' } } },
    { name = 'The Heir to the Light', group = 'Mission: San d\'Oria', desc = 'San d\'Oria 9-2, the last nation mission: win at Qubia Arena and receive royal recognition. Source: https://vanadreams.org/wiki/#mission-23', steps = { { title = 'Requirements', note = '• San d\'Oria citizen, rank 9; previous mission done' }, { title = 'Walkthrough', note = '• Accept from a San d\'Oria mission officer.\n• Zone into Northern San d\'Oria, then Chateau d\'Oraguille, for scenes.\n• Enter Feiyin for a scene.\n• Win The Heir to the Light at Qubia Arena.\n• Zone into Northern San d\'Oria for a scene.\n• Examine the marked door in Chateau d\'Oraguille.\n• Enter King Ranperre\'s Tomb from East Ronfaure (J-11) and examine the marked door.\n• Speak to Halver (I-9), Chateau d\'Oraguille.' }, { title = 'Notes', note = '• Halver gives the San d\'Orian Flag; with a full bag, come back later.\n• Aramaviont, Curilla and Rahal have extra scenes afterward.' }, { title = 'Reward', note = '• 100,000 gil\n• Title: San Dorian Royal Heir' } } },
    { name = 'The Zeruhn Report', group = 'Mission: Bastok', desc = 'Bastok rank 1 mission: pick up a report in Zeruhn Mines for Naji in Metalworks. Source: https://vanadreams.org/wiki/#mission-24', steps = { { title = 'Requirements', note = '• Bastok citizen; no other nation mission active; not yet completed' }, { title = 'Walkthrough', note = '• Accept from Cleades (Bastok Markets), Rashid (Bastok Mines), Malduc (Metalworks) or Argus (Port Bastok).\n• Enter Zeruhn Mines from Bastok Mines (D-7); get the Zeruhn report from Makarim (H-11). Rasmus (I-6) gives optional background.\n• Give the report to Naji (J-8), Metalworks.' }, { title = 'Notes', note = '• Lost the report: ask Makarim again.' } } },
    { name = 'A Geological Survey', group = 'Mission: Bastok', desc = 'Bastok 1-2: take Cid\'s blue acidity tester to a Dangruf Wadi geyser and bring it back. Source: https://vanadreams.org/wiki/#mission-25', steps = { { title = 'Requirements', note = '• Bastok citizen; 1-1 done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Rashid (H-10, Bastok Mines), Cleades (D-11, Bastok Markets), Argus (L-7, Port Bastok) or Malduc (J-8, Metalworks).\n• Get the blue acidity tester from Cid (H-8), Metalworks.\n• Stand on any geyser in Dangruf Wadi (about I-8, H-8 or J-3); it becomes the red acidity tester.\n• Give the red tester to Cid.' }, { title = 'Notes', note = '• Lost the blue tester: ask Cid for another.' } } },
    { name = 'Fetichism', group = 'Mission: Bastok', desc = 'Bastok 1-3: turn in all four Quadav fetich parts for rank 2 and a first-time bonus. Source: https://vanadreams.org/wiki/#mission-26', steps = { { title = 'Requirements', note = '• Bastok citizen; 1-2 done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Argus (L-7, Port Bastok), Cleades (D-11, Bastok Markets), Rashid (H-10, Bastok Mines) or Malduc (J-8, Metalworks).\n• Get a Fetich Head, Fetich Torso, Fetich Arms and Fetich Legs from Quadav.\n• Trade all four at once to one of those NPCs.' }, { title = 'Notes', note = '• Repeatable for rank points; rank-up and gil only on the first clear.' } } },
    { name = 'The Crystal Line', group = 'Mission: Bastok', desc = 'Run Cid\'s crystal test in Metalworks and bring his report to Ayame. Source: https://vanadreams.org/wiki/#mission-27', steps = { { title = 'Requirements', note = '• Bastok citizen, rank 2; Fetichism done; no other nation mission active' }, { title = 'Walkthrough', note = '• Accept from Argus (L-7), Cleades (D-11), Rashid (H-10) or Malduc (J-8).\n• Accept Cid\'s (H-8, Metalworks) request; he gives a random crystal.\n• Trade a Faded Crystal to Cid for the C. L. report.\n• Give the report to Ayame (K-7), Metalworks.' }, { title = 'Notes', note = '• Naji comments on the report, but only Ayame completes it.\n• Repeatable for rank points.' } } },
    { name = 'Wading Beasts', group = 'Mission: Bastok', desc = 'Bastok rank 2 mission: deliver a Lizard Egg to Alois in Metalworks. Source: https://vanadreams.org/wiki/#mission-28', steps = { { title = 'Requirements', note = '• Bastok citizen; previous Bastok mission done; no other nation mission active\n• 1 Lizard Egg' }, { title = 'Walkthrough', note = '• Accept from Cleades (D-11, Bastok Markets), Rashid (H-10, Bastok Mines), Argus (L-7, Port Bastok) or Malduc (J-8, Metalworks).\n• Obtain a Lizard Egg.\n• Trade it to Alois (K-8), Metalworks.' }, { title = 'Notes', note = '• Repeatable.' } } },
    { name = 'The Emissary', group = 'Mission: Bastok', desc = 'Bastok 2-3: bring Naji\'s letter to the San d\'Oria and Windurst consuls, then report to Naji. Source: https://vanadreams.org/wiki/#mission-29', steps = { { title = 'Requirements', note = '• Bastok citizen; 2-2 done; no other mission active' }, { title = 'Walkthrough', note = '• Accept from Argus (L-7, Port Bastok), Cleades (D-11, Bastok Markets), Rashid (H-10, Bastok Mines) or Malduc (J-8, Metalworks).\n• Get the letter to the consuls from Naji (J-8), Metalworks.\n• Start the first route with Melek (F-6, Port Windurst) or Baraka (J-10, Northern San d\'Oria).\n• After it, start the second route with the other nation\'s contact (Helaku (K-10), Northern San d\'Oria, or Melek (F-6), Port Windurst).\n• Bring the second nation\'s Kindred report to Naji.' }, { title = 'Notes', note = '• Either order; both routes required.\n• The letter is removed when the second route starts.' }, { title = 'Reward', note = '• 3,000 gil\n• Key item: Adventurer\'s Certificate\n• Title: Certified Adventurer' } } },
    { name = 'The Emissary San d\'Oria', group = 'Mission: Bastok', desc = 'San d\'Oria route of Bastok 2-3: deliver the message, defeat Warchief Vatgit, and report. Source: https://vanadreams.org/wiki/#mission-30', steps = { { title = 'Requirements', note = '• The Emissary (2-3) active on the San d\'Oria route' }, { title = 'Walkthrough', note = '• Speak to Helaku (K-10), Northern San d\'Oria.\n• Speak to Halver (I-9), Chateau d\'Oraguille.\n• Enter Ghelsba Outpost from West Ronfaure (E-4) and kill Warchief Vatgit (H-7).\n• Speak to Helaku again.' }, { title = 'Notes', note = '• Baraka and Shakir only chat.\n• Halver may give Cipher: Halver if you lack that Trust.' }, { title = 'Reward', note = '• Cipher: Halver' } } },
    { name = 'The Emissary Windurst', group = 'Mission: Bastok', desc = 'Windurst route of Bastok 2-3: carry the sword offering, sort out the fake sword, and report to Melek. Source: https://vanadreams.org/wiki/#mission-31', steps = { { title = 'Requirements', note = '• The Emissary (2-3) active, sent to Windurst' }, { title = 'Walkthrough', note = '• Enter Heaven\'s Tower for a scene; get the Sword Offering from Kupipi (Map 2, H-6).\n• In Port Windurst, Gold Skull (F-6) swaps it for a Dull Sword.\n• In Giddeus, Uu Zhoumo (Map 2, F-6) refuses it and wants an Aspir Knife.\n• Trade an Aspir Knife to Uu Zhoumo.\n• Report to Melek (F-6), Port Windurst.' }, { title = 'Notes', note = '• Ada, Josef and Gold Skull only chat.\n• Leads straight back into The Emissary.' }, { title = 'Reward', note = '• Cipher: Semih\n• Key items: dull sword, sword offering, San d\'Oria/Bastok/Windurst Trust permits' } } },
    { name = 'The Emissary San d\'Oria', group = 'Mission: Bastok', desc = 'Bastok Rank 2, San d\'Oria leg of The Emissary: win at Horlais Peak and bring the crest to Helaku. Source: https://vanadreams.org/wiki/#mission-32', steps = { { title = 'Requirements', note = '• The Emissary active, San d\'Oria part underway.' }, { title = 'Step 1', note = '• Speak to Halver (I-9), Chateau d\'Oraguille.' }, { title = 'Step 2', note = '• Clear the Rank 2 battle at Horlais Peak; you get a Kindred crest.' }, { title = 'Step 3', note = '• Give the crest to Helaku (K-10), Northern San d\'Oria.' }, { title = 'Notes', note = '• Helaku hands you a Kindred report and points you back to Bastok.\n• Halver gives Cipher: Halver if you lack that Trust.' }, { title = 'Reward', note = '• Items: Cipher: Halver\n• Key items: Kindred crest, Kindred report' } } },
    { name = 'The Emissary Windurst', group = 'Mission: Bastok', desc = 'Bastok Rank 2, Windurst leg of The Emissary: win at Balga\'s Dais and deliver the crest in Windurst. Source: https://vanadreams.org/wiki/#mission-33', steps = { { title = 'Requirements', note = '• Bastok Rank 2; Windurst route of The Emissary active, first part finished.' }, { title = 'Step 1', note = '• In Port Windurst, speak to Ada (F-5), Josef (E-5), Melek (F-6) and Gold Skull.' }, { title = 'Step 2', note = '• Get the dark key from Kupipi (Map 2, H-6), Heaven\'s Tower.' }, { title = 'Step 3', note = '• Use the dark key at Balga\'s Dais and win the Rank 2 battle.' }, { title = 'Step 4', note = '• Show the Kindred crest to Kupipi (Map 2, H-6).' }, { title = 'Step 5', note = '• Hand the crest to Melek (F-6), Port Windurst.' }, { title = 'Notes', note = '• You get the Kindred report for Bastok and the return leg begins.' }, { title = 'Reward', note = '• Key items: dark key, Kindred crest, Kindred report' } } },
    { name = 'The Four Musketeers', group = 'Mission: Bastok', desc = 'Bastok Rank 3: clear Copper Quadavs in Beadeaux for Iron Eater. Source: https://vanadreams.org/wiki/#mission-34', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 3, prior mission done, no mission active.' }, { title = 'Step 1', note = '• Take the mission from Cleades (D-11), Rashid (H-10), Argus (L-7) or Malduc (J-8).' }, { title = 'Step 2', note = '• Agree to Iron Eater\'s plan (J-8, Metalworks).' }, { title = 'Step 3', note = '• Zone into Beadeaux for a cutscene.' }, { title = 'Step 4', note = '• Kill 20 Copper Quadavs (no other monster counts).' }, { title = 'Step 5', note = '• Leave to Pashhow Marshlands for the closing cutscene.' }, { title = 'Notes', note = '• Ayame and Naji (Metalworks) gain new lines mid-mission.' } } },
    { name = 'To the Forsaken Mines', group = 'Mission: Bastok', desc = 'Bastok 3-2: defeat Blind Moby in Gusgen Mines for a Glocolite. Source: https://vanadreams.org/wiki/#mission-35', steps = { { title = 'Requirements', note = '• Bastok citizen, 3-1 done, enough rank, no mission active.' }, { title = 'Step 1', note = '• Accept from a Bastok mission giver.' }, { title = 'Step 2', note = '• Optional hint: Davyad (K-6), Bastok Mines.' }, { title = 'Step 3', note = '• In Gusgen Mines trade a Slice of Hare Meat to the ??? (Map 1, J-7); kill Blind Moby for a Glocolite.' }, { title = 'Step 4', note = '• Trade the Glocolite to Argus (L-7), Cleades (D-11), Rashid (H-10) or Malduc (J-8).' }, { title = 'Notes', note = '• No spawn while holding a Glocolite or while Blind Moby is already out.' } } },
    { name = 'Jeuno', group = 'Mission: Bastok', desc = 'Bastok Rank 3: deliver a letter in Ru\'Lude Gardens and open the Cermet Door in Lower Delkfutt\'s Tower. Source: https://vanadreams.org/wiki/#mission-36', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 3, no mission active.' }, { title = 'Step 1', note = '• Accept from Cleades (D-11), Rashid (H-10), Malduc (J-8) or Argus (L-7).' }, { title = 'Step 2', note = '• Get the letter from Lucius (J-9), Metalworks.' }, { title = 'Step 3', note = '• Give it to Goggehn (H-10), Ru\'Lude Gardens.' }, { title = 'Step 4', note = '• In Lower Delkfutt\'s Tower, trade a Delkfutt Key to the Cermet Door (or just examine it with the key item).' }, { title = 'Step 5', note = '• Examine Door:Bastokan Emb. (H-10), Ru\'Lude Gardens.' }, { title = 'Notes', note = '• Delkfutt Keys drop from tower monsters.\n• Goggehn restates your next task if asked.' }, { title = 'Reward', note = '• 5,000 gil' } } },
    { name = 'Magicite', group = 'Mission: Bastok', desc = 'Bastok 4-1: gather three Magicite and report in Ru\'Lude Gardens for Rank 5. Source: https://vanadreams.org/wiki/#mission-37', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 4, enough rank points, no mission active.' }, { title = 'Step 1', note = '• Accept at the Bastok consulate door, Ru\'Lude Gardens; get the archducal audience permit.' }, { title = 'Step 2', note = '• Examine the audience chamber door; get the letter to Aldo (J-8).' }, { title = 'Step 3', note = '• Give it to Aldo (J-8), Lower Jeuno, for the silver bell.' }, { title = 'Step 4', note = '• Speak to Paya-Sabya (I-8), Upper Jeuno, then Muckvix (H-10), Lower Jeuno, for the Yagudo torch.' }, { title = 'Step 5', note = '• Altar Room Magicite (G-8): Magicite: Orastone.' }, { title = 'Step 6', note = '• Monastic Cavern Magicite (E-6): Magicite: Optistone.' }, { title = 'Step 7', note = '• Qulun Dome Magicite (F-9): Magicite: Aurastone.' }, { title = 'Step 8', note = '• Examine the audience chamber door with all three.' }, { title = 'Step 9', note = '• Speak to Goggehn (H-10) to finish.' }, { title = 'Notes', note = '• Magicite order is free.\n• Yagudo torch is needed for the Altar Room; a scene plays on your next entry after obtaining it.\n• Existing airship pass holders get gil instead.' }, { title = 'Reward', note = '• 10,000 gil\n• Key items: message to Jeuno' } } },
    { name = 'Darkness Rising', group = 'Mission: Bastok', desc = 'Bastok Rank 5: visit Fei\'Yin, then win at Qubia Arena with the new seal. Source: https://vanadreams.org/wiki/#mission-38', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 5, message to Jeuno key item.' }, { title = 'Step 1', note = '• Accept from Cleades (D-11), Rashid (H-10), Malduc or Argus (L-7), or from Naji (J-8).' }, { title = 'Step 2', note = '• Get the new Fei\'Yin seal from Naji (J-8), Metalworks.' }, { title = 'Step 3', note = '• Zone into Fei\'Yin for a cutscene.' }, { title = 'Step 4', note = '• Win the Rank 5 fight at Qubia Arena; get the burnt seal.' }, { title = 'Step 5', note = '• Hand the burnt seal to Naji (J-8).' }, { title = 'Notes', note = '• Turning Naji down first still allows accepting later from the recruiters.' } } },
    { name = 'Xarcabard, Land of Truths', group = 'Mission: Bastok', desc = 'Bastok 5-2: beat the Shadow Lord and return with the Shadow Fragment. Source: https://vanadreams.org/wiki/#mission-39', steps = { { title = 'Requirements', note = '• Bastok nationality, Rank 5 missions reached, no mission active.' }, { title = 'Step 1', note = '• Accept from a Bastok mission officer.' }, { title = 'Step 2', note = '• Get briefed by Karst (K-8), Metalworks.' }, { title = 'Step 3', note = '• In the Throne Room (G-8), examine the entrance to start the fight.' }, { title = 'Step 4', note = '• Defeat the Shadow Lord; obtain the Shadow Fragment after the scene.' }, { title = 'Step 5', note = '• Examine Door: President\'s Office (J-8), Metalworks.' }, { title = 'Notes', note = '• Promotes you to Rank 6.\n• Also opens the Zilart mission The New Frontier if not done.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Return of the Talekeeper', group = 'Mission: Bastok', desc = 'Bastok 6-1: beat two sphinxes in Western Altepa Desert for the Altepa moonpebble. Source: https://vanadreams.org/wiki/#mission-40', steps = { { title = 'Requirements', note = '• Bastok citizen; previous mission done; accept from Cleades, Rashid, Malduc or Argus.' }, { title = 'Step 1', note = '• Speak to Medicine Eagle (H-5), Bastok Mines.' }, { title = 'Step 2', note = '• Enter Zeruhn Mines at (D-7); speak to Drake Fang (H-6).' }, { title = 'Step 3', note = '• Examine the ??? (G-8) in Western Altepa Desert to spawn Eastern Sphinx and Western Sphinx.' }, { title = 'Step 4', note = '• Kill both, re-examine the ??? for the Altepa moonpebble.' }, { title = 'Step 5', note = '• Speak to Tall Mountain (J-7), Bastok Mines.' }, { title = 'Notes', note = '• Spawns only when neither sphinx is up.\n• Moonpebble is removed at the end.' } } },
    { name = 'The Pirate\'s Cove', group = 'Mission: Bastok', desc = 'Bastok 6-2: kill Magma in Ifrit\'s Cauldron and give its Frag Rock to Gilgamesh. Source: https://vanadreams.org/wiki/#mission-41', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 6, 6-1 done.\n• One Adaman Ore.' }, { title = 'Step 1', note = '• Accept from Rashid (H-10), Cleades (D-11), Argus (L-7) or Malduc (J-8).' }, { title = 'Step 2', note = '• Speak to Naji (J-8), Metalworks.' }, { title = 'Step 3', note = '• Speak to Gilgamesh (L-8), Norg.' }, { title = 'Step 4', note = '• Enter Ifrit\'s Cauldron from Yhoator Jungle (I-6); trade Adaman Ore to the ??? (Map 1, H-7) to spawn Salamander and Magma.' }, { title = 'Step 5', note = '• Defeat Magma; take its Frag Rock.' }, { title = 'Step 6', note = '• Trade the Frag Rock to Gilgamesh (L-8).' }, { title = 'Step 7', note = '• Report to Naji (J-8).' }, { title = 'Notes', note = '• Salamander fights alongside Magma.\n• The ??? may need time to reset after use.' }, { title = 'Reward', note = '• 40,000 gil' } } },
    { name = 'The Final Image', group = 'Mission: Bastok', desc = 'Bastok Rank 7: fetch Reinforced cermet from Ro\'Maeve for Cid. Source: https://vanadreams.org/wiki/#mission-42', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 7, prior mission done, no mission active.' }, { title = 'Step 1', note = '• Accept from Cleades (D-11), Rashid (H-10), Argus (L-7) or Malduc (J-8).' }, { title = 'Step 2', note = '• Speak to Cid (H-8), Metalworks.' }, { title = 'Step 3', note = '• Examine the ??? (E-11) in Ro\'Maeve to spawn Mokkurkalfi.' }, { title = 'Step 4', note = '• Kill Mokkurkalfi and its partner.' }, { title = 'Step 5', note = '• Re-examine the ??? for Reinforced cermet.' }, { title = 'Step 6', note = '• Give it to Cid (H-8).' }, { title = 'Notes', note = '• The key item is only given after the kills.' } } },
    { name = 'On My Way', group = 'Mission: Bastok', desc = 'Bastok 7-2: win at Waughroon Shrine for the Letter from Werei; promotes to Rank 8. Source: https://vanadreams.org/wiki/#mission-43', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 7, previous mission done, no mission active.' }, { title = 'Step 1', note = '• Accept from any Bastok mission official.' }, { title = 'Step 2', note = '• Speak to Karst (K-8), Metalworks.' }, { title = 'Step 3', note = '• Speak to Hilda (E-6), Port Bastok.' }, { title = 'Step 4', note = '• Win the On My Way battle, Waughroon Shrine; get the Letter from Werei.' }, { title = 'Step 5', note = '• Return to Karst (K-8) to finish.' }, { title = 'Step 6', note = '• Optional: talk to Gumbah (J-7), Bastok Mines, twice to deliver the letter.' }, { title = 'Notes', note = '• Before delivery, Argus, Cleades, Rashid and Malduc show an extra scene.\n• Afterwards Cornelia\'s door (Metalworks) has an optional scene that changes if Beauty and the Galka, Fallen Comrades and Rivals are done.' }, { title = 'Reward', note = '• 60,000 gil' } } },
    { name = 'The Chains That Bind Us', group = 'Mission: Bastok', desc = 'Bastok 8-1: defeat three Quadav officers in Quicksand Caves and check two ??? spots. Source: https://vanadreams.org/wiki/#mission-44', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 8, previous mission done, no mission active.' }, { title = 'Step 1', note = '• Accept from any Bastok mission official.' }, { title = 'Step 2', note = '• Accept Iron Eater\'s request (J-8, Metalworks).' }, { title = 'Step 3', note = '• Examine the ??? in Quicksand Caves to spawn the guards.' }, { title = 'Step 4', note = '• Kill Centurio IV-VII, Triarius IV-XIV and Princeps IV-XLV.' }, { title = 'Step 5', note = '• Re-examine the ??? for a scene.' }, { title = 'Step 6', note = '• Examine the second ??? in the caves.' }, { title = 'Step 7', note = '• Report to Iron Eater (J-8).' }, { title = 'Notes', note = '• All three spawn at once; bring a party. Recheck the ??? if none appear.' } } },
    { name = 'Enter the Talekeeper', group = 'Mission: Bastok', desc = 'Bastok Rank 9 mission: defeat three ghosts in Kuftal Tunnel for an old piece of wood. Source: https://vanadreams.org/wiki/#mission-45', steps = { { title = 'Requirements', note = '• Bastok citizen, earlier missions done; taken from the Rank 8 list.' }, { title = 'Step 1', note = '• Accept from a Bastok mission official.' }, { title = 'Step 2', note = '• Enter Zeruhn Mines at (D-7); speak to Drake Fang (H-6).' }, { title = 'Step 3', note = '• Enter Kuftal Tunnel from Western Altepa Desert (I-5); examine the first ??? (Map 1, H-8).' }, { title = 'Step 4', note = '• Examine the second ??? (Map 1, H-8) to spawn the ghosts.' }, { title = 'Step 5', note = '• Kill Dervo\'s Ghost, Gizerl\'s Ghost and Gordov\'s Ghost.' }, { title = 'Step 6', note = '• Re-examine the ??? for the old piece of wood.' }, { title = 'Step 7', note = '• Return to Drake Fang (H-6); the final scene follows in Bastok Mines.' }, { title = 'Notes', note = '• All three ghosts must die before the ??? works again.\n• The wood is removed at the end.' }, { title = 'Reward', note = '• 80,000 gil' } } },
    { name = 'The Salt of the Earth', group = 'Mission: Bastok', desc = 'Bastok 9-1: retrieve miraclesalt from Gustav Tunnel for the Rabao nomads. Source: https://vanadreams.org/wiki/#mission-46', steps = { { title = 'Requirements', note = '• Bastok citizen; previous mission done; accept from a Bastok mission giver.' }, { title = 'Step 1', note = '• Speak to Alois (K-8), Metalworks.' }, { title = 'Step 2', note = '• Speak to Dancing Wolf (G-7), Rabao.' }, { title = 'Step 3', note = '• Enter Gustav Tunnel from Cape Teriggan (J-5); examine the ??? (Map 2, G-6) to spawn Gigaplasm and its plasms.' }, { title = 'Step 4', note = '• Kill every plasm, re-examine the ??? for miraclesalt.' }, { title = 'Step 5', note = '• Report to Dancing Wolf (G-7).' }, { title = 'Step 6', note = '• Report to Alois (K-8) to finish.' }, { title = 'Notes', note = '• Franziska (Metalworks) has a follow-up scene afterwards.' } } },
    { name = 'Where Two Paths Converge', group = 'Mission: Bastok', desc = 'Bastok 9-2: win the Throne Room battle to reach Rank 10. Source: https://vanadreams.org/wiki/#mission-47', steps = { { title = 'Requirements', note = '• Bastok citizen, Rank 9, previous mission done, no mission active.' }, { title = 'Step 1', note = '• Accept from any Bastok mission official.' }, { title = 'Step 2', note = '• Speak to Iron Eater (J-8), Metalworks.' }, { title = 'Step 3', note = '• Win the Where Two Paths Converge battle, Throne Room (G-8).' }, { title = 'Step 4', note = '• Report to Iron Eater for the Bastokan Flag.' }, { title = 'Notes', note = '• Full inventory: return later with a free slot to collect the flag.' }, { title = 'Reward', note = '• 100,000 gil\n• Title: Hero Among Heroes' } } },
    { name = 'The Horutoto Ruins Experiment', group = 'Mission: Windurst', desc = 'Windurst 1-1: find the broken gizmo in Inner Horutoto Ruins and bring its cracked Mana Orb to Hakkuru-Rinkuru. Source: https://vanadreams.org/wiki/#mission-48', steps = { { title = 'Requirements', note = '• Windurst citizen, no mission active, not yet completed.' }, { title = 'Step 1', note = '• Accept from Rakoh Buuma (K-10), Mokyokyo, Zokima-Rokima (H-7) or Janshura-Rashura (B-5).' }, { title = 'Step 2', note = '• Speak to Hakkuru-Rinkuru, Orastery (D-7), Port Windurst.' }, { title = 'Step 3', note = '• Enter Inner Horutoto Ruins via the Lily Tower (J-7), East Sarutabaruta.' }, { title = 'Step 4', note = '• Pass the cracked wall at (H-9), Map 1 south wall; examine Gate: Magical Gizmo.' }, { title = 'Step 5', note = '• Check the six Ancient Magical Gizmos until one yields the cracked Mana Orb.' }, { title = 'Step 6', note = '• Bring the orb to Hakkuru-Rinkuru.' }, { title = 'Notes', note = '• The broken gizmo is random per attempt; checked ones are remembered.\n• Sama Gohjima (East Sarutabaruta) has optional lines.' } } },
    { name = 'The Heart of the Matter', group = 'Mission: Windurst', desc = 'Windurst 1-2: seed six gizmos in Outer Horutoto Ruins with dark orbs, then collect them glowing for Apururu. Source: https://vanadreams.org/wiki/#mission-49', steps = { { title = 'Requirements', note = '• Windurst citizen, previous mission done, no mission active.' }, { title = 'Step 1', note = '• Accept from a Windurst gate guard.' }, { title = 'Step 2', note = '• Get six dark Mana Orbs from Apururu, Manustery (H-10), Windurst Woods (H-9).' }, { title = 'Step 3', note = '• Get the southeastern star charm from Pore-Ohre, Marguerite Tower (J-11), East Sarutabaruta.' }, { title = 'Step 4', note = '• Enter Outer Horutoto Ruins through that tower; other entrances lead elsewhere.' }, { title = 'Step 5', note = '• Place one dark orb in each of the six Ancient Magical Gizmos.' }, { title = 'Step 6', note = '• Go east to the cracked wall; examine Gate: Magical Gizmo (charm is consumed).' }, { title = 'Step 7', note = '• Revisit all six gizmos to collect the glowing Mana Orbs.' }, { title = 'Step 8', note = '• Return to Apururu (H-9).' }, { title = 'Notes', note = '• Zoning into East Sarutabaruta with glowing orbs lets Cardians steal them; the mission still finishes with another scene.\n• Warps and home points keep the orbs.\n• One orb per gizmo.' } } },
    { name = 'The Price of Peace', group = 'Mission: Windurst', desc = 'Windurst 1-3: bring food and drink offerings to two allies in Giddeus. Source: https://vanadreams.org/wiki/#mission-50', steps = { { title = 'Requirements', note = '• Windurst citizen, previous mission done.' }, { title = 'Step 1', note = '• Accept from a Windurst mission giver.' }, { title = 'Step 2', note = '• Get the food offering and drink offering from Leepe-Hoppe, Windurst Waters.' }, { title = 'Step 3', note = '• In Giddeus give food to Laa Mozi (Map 1, H-7) and drink to Ghoo Pakya (Map 1, G-7).' }, { title = 'Step 4', note = '• Step into the marked spot in Windurst Waters for a scene.' }, { title = 'Step 5', note = '• Report to Janshura-Rashura (B-5), Zokima-Rokima (H-7), Mokyokyo or Rakoh Buuma (K-10).' }, { title = 'Notes', note = '• Both offerings are required.' }, { title = 'Reward', note = '• 1,000 gil' } } },
    { name = 'Lost for Words', group = 'Mission: Windurst', desc = 'Windurst Rank 2: find lapis coral in the Maze of Shakhrami for Tosuka-Porika. Source: https://vanadreams.org/wiki/#mission-51', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 2, prior mission done, no mission active.' }, { title = 'Step 1', note = '• Accept from a Windurst mission NPC.' }, { title = 'Step 2', note = '• Speak to Tosuka-Porika, Windurst Waters.' }, { title = 'Step 3', note = '• Get the lapis monocle from Nanaa Mihgo, Windurst Woods.' }, { title = 'Step 4', note = '• Search Fossil Rocks in Maze of Shakhrami for the lapis coral.' }, { title = 'Step 5', note = '• Return coral and monocle to Nanaa Mihgo for the hideout key.' }, { title = 'Step 6', note = '• Enter Inner Horutoto Ruins via the Lily Tower (J-7), East Sarutabaruta.' }, { title = 'Step 7', note = '• From the southwest gizmo room on Map 1, pass the cracked wall at (G-9) into Beetle\'s Burrow (Map 2).' }, { title = 'Step 8', note = '• Examine the Mahogany Door (G-8), Map 2 (key consumed).' }, { title = 'Step 9', note = '• Examine Door: House of the Hero (G-3), Windurst Walls.' }, { title = 'Step 10', note = '• Report to Tosuka-Porika.' }, { title = 'Notes', note = '• One of 8 Fossil Rocks has the coral; it varies per player.\n• The Rose Tower entrance does not reach the Mahogany Door.' } } },
    { name = 'A Testing Time', group = 'Mission: Windurst', desc = 'Windurst Rank 2: kill enough monsters in Tahrongi Canyon within one Vana\'diel day for Moreno-Toeno. Source: https://vanadreams.org/wiki/#mission-52', steps = { { title = 'Step 1', note = '• Accept from a Windurst gate guard.' }, { title = 'Step 2', note = '• Agree to the test with Moreno-Toeno, Aurastery, Windurst Waters; get the Creature Counter Magic Doll.' }, { title = 'Step 3', note = '• Kill 30+ listed monsters in Tahrongi Canyon (35+ recommended).' }, { title = 'Step 4', note = '• Report to Moreno-Toeno during the final Vana\'diel hour of the day.' }, { title = 'Notes', note = '• Too early: told how long to wait. Too late or under 30 kills: fail, zone before retrying.\n• Repeats use Buburimu Peninsula with two Vana\'diel days.' } } },
    { name = 'The Three Kingdoms', group = 'Mission: Windurst', desc = 'Windurst 2-3: take a letter to the San d\'Oria and Bastok consuls, then report to Kupipi for Rank 3. Source: https://vanadreams.org/wiki/#mission-53', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 2, no mission active.' }, { title = 'Step 1', note = '• Accept from Janshura-Rashura (B-5), Zokima-Rokima (H-7), Mokyokyo or Rakoh Buuma (K-10).' }, { title = 'Step 2', note = '• Get the letter to the consuls from Kupipi (Map 2, H-6), Heavens Tower.' }, { title = 'Step 3', note = '• San d\'Oria: Heruze-Moruze, then Kasaroro (H-9), Northern San d\'Oria.' }, { title = 'Step 4', note = '• Bastok: Patt-Pott (I-7), Metalworks.' }, { title = 'Step 5', note = '• Deliver the letter to the other consul, then return to Kupipi.' }, { title = 'Notes', note = '• Nation order is free.' }, { title = 'Reward', note = '• 3,000 gil\n• Key items: Adventurer\'s Certificate\n• Title: Certified Adventurer' } } },
    { name = 'The Three Kingdoms San d\'Oria', group = 'Mission: Windurst', desc = 'Windurst Rank 2, San d\'Oria leg: kill Warchief Vatgit at Ghelsba Outpost and report to Kasaroro. Source: https://vanadreams.org/wiki/#mission-54', steps = { { title = 'Requirements', note = '• On The Three Kingdoms, San d\'Oria leg.' }, { title = 'Step 1', note = '• Speak to Halver (I-9), Chateau d\'Oraguille.' }, { title = 'Step 2', note = '• Enter Ghelsba Outpost from West Ronfaure (E-4); kill Warchief Vatgit (H-7).' }, { title = 'Step 3', note = '• Speak to Kasaroro (H-9), Northern San d\'Oria, twice.' }, { title = 'Notes', note = '• With Trust quests on, Halver gives his cipher if you lack it.\n• Leads on to The Three Kingdoms.' }, { title = 'Reward', note = '• Items: Cipher: Halver' } } },
    { name = 'The Three Kingdoms (Bastok)', group = 'Mission: Windurst', desc = 'Windurst 2-3, Bastok leg: dig up Mythril Sand for Patt-Pott. Source: https://vanadreams.org/wiki/#mission-55', steps = { { title = 'Requirements', note = '• Windurst citizen; earlier parts of The Three Kingdoms done.' }, { title = 'Step 1', note = '• Speak to Pius (K-8), Metalworks.' }, { title = 'Step 2', note = '• Get 5 Pickaxes from Grohm (H-9).' }, { title = 'Step 3', note = '• Get Mythril Sand in Palborough Mines.' }, { title = 'Step 4', note = '• Trade it to Patt-Pott (I-7).' }, { title = 'Notes', note = '• Grohm reissues the Pickaxes if your bag was full.\n• Mih Ketto, Moyoyo and Topuru-Kuperu have lines.' }, { title = 'Reward', note = '• Items: Mythril Sand, Pickaxe' } } },
    { name = 'The Three Kingdoms San d\'Oria', group = 'Mission: Windurst', desc = 'Windurst Rank 2, San d\'Oria leg part 2: beat the dragon at Horlais Peak and bring the crest to Kasaroro. Source: https://vanadreams.org/wiki/#mission-56', steps = { { title = 'Requirements', note = '• On The Three Kingdoms, San d\'Oria part 2.\n• Dark Key.' }, { title = 'Step 1', note = '• Speak to Halver (I-9) for a scene.' }, { title = 'Step 2', note = '• Enter the Burning Circle, Horlais Peak; fight the Dread Dragon (F-8).' }, { title = 'Step 3', note = '• Win to get the Kindred Crest.' }, { title = 'Step 4', note = '• Give it to Kasaroro (H-9), Northern San d\'Oria.' }, { title = 'Notes', note = '• 6 players max, 15 minutes, Trusts allowed.\n• Halver gives his cipher if you lack the Trust.\n• Kasaroro only chats before the win.' }, { title = 'Reward', note = '• Items: Cipher: Halver\n• Key items: dark key, Kindred crest, Kindred report' } } },
    { name = 'The Three Kingdoms Bastok', group = 'Mission: Windurst', desc = 'Windurst 2-3, Bastok leg part 2: win at Waughroon Shrine and bring the crest to Patt-Pott. Source: https://vanadreams.org/wiki/#mission-57', steps = { { title = 'Requirements', note = '• Second half of the Bastok leg reached.\n• Dark key.' }, { title = 'Step 1', note = '• Speak to Pius (K-8), Metalworks.' }, { title = 'Step 2', note = '• Speak to Grohm (H-9).' }, { title = 'Step 3', note = '• Win the Rank 2 fight at Waughroon Shrine for the Kindred crest.' }, { title = 'Step 4', note = '• Give it to Patt-Pott (I-7) for the Kindred report.' }, { title = 'Notes', note = '• The dark key is consumed by the battle.' }, { title = 'Reward', note = '• Key items: dark key, Kindred crest, Kindred report' } } },
    { name = 'To Each His Own Right', group = 'Mission: Windurst', desc = 'Windurst Rank 3: carry the Starway Stairway bauble and open a trap door in Castle Oztroja. Source: https://vanadreams.org/wiki/#mission-58', steps = { { title = 'Step 1', note = '• Accept from a Windurst gate guard.' }, { title = 'Step 2', note = '• Get the Starway Stairway bauble from Kupipi (Map 2, H-6), Heaven\'s Tower.' }, { title = 'Step 3', note = '• Speak to Rhy Epocan (Map 4, H-7), Heaven\'s Tower.' }, { title = 'Step 4', note = '• Speak to Hakkuru-Rinkuru, Port Windurst.' }, { title = 'Step 5', note = '• Open any trap door in Castle Oztroja for a scene.' }, { title = 'Step 6', note = '• Report to Rhy Epocan.' }, { title = 'Notes', note = '• Kupipi and the Sibyl Guards repeat hints.' } } },
    { name = 'Written in the Stars', group = 'Mission: Windurst', desc = 'Windurst Rank 3: take the charm of light to the Gate of Light in Inner Horutoto Ruins. Source: https://vanadreams.org/wiki/#mission-59', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 3, no mission active.' }, { title = 'Step 1', note = '• Accept from a Windurst recruiter.' }, { title = 'Step 2', note = '• Get the charm of light from Zubaba (Map 3, I-7), Heaven\'s Tower.' }, { title = 'Step 3', note = '• Enter Inner Horutoto Ruins via the Lily Tower (J-7), East Sarutabaruta.' }, { title = 'Step 4', note = '• Go west through Beetle\'s Burrow (Map 2) to the Rose Tower (Map 3); pass the Magic Gate (H-9) with a Portal Charm or WHM, BLM and RDM on its three circles.' }, { title = 'Step 5', note = '• On Map 4 (second floor) examine the Gate of Light (G-7).' }, { title = 'Step 6', note = '• Report to Zubaba.' }, { title = 'Notes', note = '• Repeat runs (after this or \'A New Journey\'): trade 3 Rusty Daggers to Zubaba.\n• The West Sarutabaruta Rose Tower entrance is blocked by a ledge.' } } },
    { name = 'A New Journey', group = 'Mission: Windurst', desc = 'Windurst 3-3: deliver a letter in Ru\'Lude Gardens and open the door in Lower Delkfutt\'s Tower. Source: https://vanadreams.org/wiki/#mission-60', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 3, previous mission done.\n• Delkfutt Key.' }, { title = 'Step 1', note = '• Accept from a Windurst mission giver; get the star crested summons.' }, { title = 'Step 2', note = '• Examine the Heaven\'s Tower door for the letter to the ambassador.' }, { title = 'Step 3', note = '• Give it to Pakh Jatalfih (I-9), Ru\'Lude Gardens.' }, { title = 'Step 4', note = '• Unlock the marked door in Lower Delkfutt\'s Tower.' }, { title = 'Step 5', note = '• Speak to Pakh Jatalfih again.' }, { title = 'Step 6', note = '• Examine the Ru\'Lude Gardens door to finish.' }, { title = 'Notes', note = '• Trade the Delkfutt Key or hold the key item.\n• The key comes from other quests if you lack it.' }, { title = 'Reward', note = '• 5,000 gil' } } },
    { name = 'Magicite', group = 'Mission: Windurst', desc = 'Windurst 4-1: gain an audience in Ru\'Lude Gardens and gather three magicite; promotes to Rank 5. Source: https://vanadreams.org/wiki/#mission-61', steps = { { title = 'Requirements', note = '• Windurst nationality, Rank 4, enough rank points, no mission active.' }, { title = 'Step 1', note = '• Accept at Door: Windurstian Emb. or from Pakh Jatalfih (I-9); get the Archducal Audience Permit.' }, { title = 'Step 2', note = '• Examine Door: Audience Chamber (H-6) for a Letter to Aldo (J-8).' }, { title = 'Step 3', note = '• Give it to Aldo, Lower Jeuno, for the Silver Bell.' }, { title = 'Step 4', note = '• Speak to Paya-Sabya (I-8), Upper Jeuno, then Muckvix (H-10), Lower Jeuno, for the Yagudo Torch.' }, { title = 'Step 5', note = '• Collect Orastone, Optistone and Aurastone in the Altar Room, Monastic Cavern and Qulun Dome.' }, { title = 'Step 6', note = '• Examine Door: Audience Chamber (H-6) with all three.' }, { title = 'Step 7', note = '• Speak to Pakh Jatalfih to finish.' }, { title = 'Notes', note = '• Airship Pass given; gil instead if you have one.\n• Extra scene on next Altar Room entry after getting the torch.' }, { title = 'Reward', note = '• 10,000 gil\n• Key items: message to Jeuno' } } },
    { name = 'The Final Seal', group = 'Mission: Windurst', desc = 'Windurst 5-1: visit Fei\'Yin, win at Qu\'Bia Arena and return the burnt seal. Source: https://vanadreams.org/wiki/#mission-62', steps = { { title = 'Requirements', note = '• Windurst nationality, Rank 5, no mission active.' }, { title = 'Step 1', note = '• Examine Door: Vestal Chamber (Map 4, H-5), Heaven\'s Tower, for the New Fei\'Yin Seal.' }, { title = 'Step 2', note = '• Zone into Fei\'Yin for a scene.' }, { title = 'Step 3', note = '• Win the Rank 5 fight at Qu\'Bia Arena for the Burnt Seal.' }, { title = 'Step 4', note = '• Bring it to Door: Vestal Chamber.' }, { title = 'Notes', note = '• Mokyokyo, Janshura-Rashura, Rakoh Buuma and Zokima-Rokima can also brief it.\n• Worth 600 rank points.' } } },
    { name = 'The Shadow Awaits', group = 'Mission: Windurst', desc = 'Windurst 5-2: defeat the Shadow Lord and return a shadow fragment to Heaven\'s Tower. Source: https://vanadreams.org/wiki/#mission-63', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 5, 5-1 done, no mission active.' }, { title = 'Step 1', note = '• Accept from a Windurst mission officer; get the star crested summons.' }, { title = 'Step 2', note = '• Turn it in at the Vestal Chamber door, Heaven\'s Tower.' }, { title = 'Step 3', note = '• In the Throne Room zone, examine the Throne Room door to begin.' }, { title = 'Step 4', note = '• Defeat the Shadow Lord; take the shadow fragment after the scene.' }, { title = 'Step 5', note = '• Return to Heaven\'s Tower and examine the Vestal Chamber door.' }, { title = 'Notes', note = '• Zubaba repeats instructions.\n• Fragment is removed on completion.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Full Moon Fountain', group = 'Mission: Windurst', desc = 'Windurst 6-1: beat four Jacks at the Outer Horutoto gate and enter Full Moon Fountain. Source: https://vanadreams.org/wiki/#mission-64', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 6, 5-2 done, no mission active.' }, { title = 'Step 1', note = '• Accept from a Windurst mission officer.' }, { title = 'Step 2', note = '• Get the southwestern star charm from Hakkuru-Rinkuru, Port Windurst.' }, { title = 'Step 3', note = '• Enter Outer Horutoto Ruins via the Dahlia Tower (F-11), West Sarutabaruta.' }, { title = 'Step 4', note = '• Examine Gate: Magical Gizmo (J-8) to spawn the guards.' }, { title = 'Step 5', note = '• Kill Jack of Batons, Jack of Coins, Jack of Cups and Jack of Swords.' }, { title = 'Step 6', note = '• Re-examine the gate (J-8).' }, { title = 'Step 7', note = '• Enter Full Moon Fountain to finish.' }, { title = 'Notes', note = '• Gate stays closed until all four die; the charm is consumed.\n• Hakkuru-Rinkuru and Kuroido-Moido repeat hints.' } } },
    { name = 'Saintly Invitation', group = 'Mission: Windurst', desc = 'Windurst Rank 6: win at Balga\'s Dais, see Kaa Toru the Just in Castle Oztroja and return his oath; promotes to Rank 7. Source: https://vanadreams.org/wiki/#mission-65', steps = { { title = 'Requirements', note = '• Windurst citizen, Rank 6, prior mission done, no mission active.\n• Free slot for the Ashura Necklace.' }, { title = 'Step 1', note = '• Accept from a Windurst mission NPC.' }, { title = 'Step 2', note = '• Examine Door: Vestal Chamber (Map 4, H-5), Heavens Tower, for the Holy One\'s invitation.' }, { title = 'Step 3', note = '• Win at Balga\'s Dais for the Balga champion certificate.' }, { title = 'Step 4', note = '• Enter Castle Oztroja from Meriphataud Mountains (L-8); give the certificate to Kaa Toru the Just for an Ashura Necklace and the Holy One\'s oath.' }, { title = 'Step 5', note = '• Examine Door: Vestal Chamber again.' }, { title = 'Notes', note = '• Kupipi and others in Heavens Tower gain lines.' }, { title = 'Reward', note = '• 40,000 gil' } } },
    { name = 'The Sixth Ministry', group = 'Mission: Windurst', desc = 'Windurst mission: use the Optistery ring in Toraimarai Canal to locate the Book of the Gods. Source: https://vanadreams.org/wiki/#mission-66', steps = { { title = 'Step 1', note = '• Accept from a Windurst gate guard.' }, { title = 'Step 2', note = '• Get the Optistery ring from Tosuka-Porika, Windurst Waters.' }, { title = 'Step 3', note = '• Enter Toraimarai Canal from Windurst Walls (H-4); kill the four Hinge Oils to open the sealed door.' }, { title = 'Step 4', note = '• Examine the correct Tome of Magic (Map 2, H-8) for a scene.' }, { title = 'Step 5', note = '• Report to Tosuka-Porika.' }, { title = 'Notes', note = '• Door stays open only while all four Hinge Oils are dead.\n• The ring is removed at the end.' }, { title = 'Reward', note = '• Key items: blank Book of the Gods' } } },
    { name = 'Awakening of the Gods', group = 'Mission: Windurst', desc = 'Windurst Rank 7 mission: have the blank Book of the Gods filled via Kazham and the Temple of Uggalepih. Source: https://vanadreams.org/wiki/#mission-67', steps = { { title = 'Before you start', note = '• Windurst Rank 7, no other national mission active.\n• The Sixth Ministry done (blank Book of the Gods held).\n• Bring one Cursed Key.' }, { title = 'Walkthrough', note = '• Accept from Leepe-Hoppe in Windurst Waters, then speak to Kerutoto there.\n• In Kazham, speak to Romaa Mihgo (H-11), then Vanono (G-7).\n• In Temple of Uggalepih, trade the Cursed Key to the Granite Door from its south side.\n• Report to Leepe-Hoppe with the Book of the Gods.' }, { title = 'Notes & reward', note = '• Cursed Key is consumed; the book becomes the Book of the Gods.\n• Promotes you to Rank 8.\n• 60,000 gil.' } } },
    { name = 'Vain', group = 'Mission: Windurst', desc = 'Windurst Rank 8 mission: track Qu\'Hau Spring in Ro\'Maeve with the Star Seeker, drain it in Davoi, then report to Moreno-Toeno. Source: https://vanadreams.org/wiki/#mission-68', steps = { { title = 'Before you start', note = '• Windurst Rank 8, no active mission.\n• Bring a Curse Wand.' }, { title = 'Walkthrough', note = '• Accept at any Windurst mission recruiter (Port Windurst, Walls, Waters or Woods).\n• Get the Star Seeker from Moreno-Toeno in Windurst Waters.\n• Zone between areas; the Star Seeker hints at the next direction on each zone-in.\n• Examine Qu\'Hau Spring (H-6) in Ro\'Maeve.\n• In Davoi, speak to Sedal-Godjal (J-8) and trade him the Curse Wand.\n• Report to Moreno-Toeno.' }, { title = 'Good to know', note = '• Fuepepe, Pechiru-Mashiru and Tauwawa in Windurst Waters have extra lines once you hold the Star Seeker.\n• Hints vary by zone and entry point.\n• No wand means Sedal-Godjal just repeats his request.' } } },
    { name = 'The Jester Who\'d be King', group = 'Mission: Windurst', desc = 'Windurst 8-2: collect the five -stery rings for Apururu, defeat the Outer Horutoto guardians and open the Gate of Darkness in Inner Horutoto; rewards Rank 9. Source: https://vanadreams.org/wiki/#mission-69', steps = { { title = 'Before you start', note = '• Windurst Rank 8 with 8-1 done; no other national mission.' }, { title = 'Collect rings', note = '• Accept at a Windurst mission counter.\n• Manustery ring: Apururu (H-9), Windurst Woods.\n• Optistery ring: Tosuka-Porika, Windurst Waters.\n• Aurastery ring: Sedal-Godjal (J-8), Davoi.\n• Rhinostery ring: ??? gate in Fei\'Yin.\n• Rings in any order; then see Apururu, then Kupipi (Map 2, H-6) in Heaven\'s Tower.' }, { title = 'Outer Horutoto Ruins', note = '• Enter via Amaryllis Tower (F-4), West Sarutabaruta; route runs Map 1 → Map 5 → Map 6.\n• Examine the Cermet Door at (E-6) on Map 6 and defeat Queen of Coins and Queen of Swords.\n• Examine the door again for the Orastery ring, then report to Apururu.' }, { title = 'Inner Horutoto Ruins', note = '• Get the glove of perpetual twilight from Shantotto (K-7), Windurst Walls; give it to Apururu.\n• Enter via Lily Tower (J-7), East Sarutabaruta (Map 1).\n• Go west through Beetle\'s Burrow (Map 2) to Rose Tower (Map 3), past the Magic Gate (H-9), up to Map 4.\n• Examine the Gate of Darkness (I-7), then report to Apururu.' }, { title = 'Notes & reward', note = '• Shantotto takes the rings; the Book of the Gods is taken at the gate.\n• Extra Shantotto/Apururu scene afterwards.\n• 80,000 gil.' } } },
    { name = 'Doll of the Dead', group = 'Mission: Windurst', desc = 'Windurst 9-1: bring Goobbue Humus to the Mandragora Warden in The Boyahda Tree and return Zonpa-Zippa\'s letter. Source: https://vanadreams.org/wiki/#mission-70', steps = { { title = 'Before you start', note = '• Windurst citizen of the required rank; no other nation mission.' }, { title = 'Walkthrough', note = '• Accept from Janshura-Rashura (B-5, Port Windurst), Zokima-Rokima (H-7, Windurst Walls), Mokyokyo (Windurst Waters) or Rakoh Buuma (K-10, Windurst Woods).\n• Speak to Apururu (H-9), Windurst Woods.\n• In Heavens Tower, watch the scene and examine the Star Sybil\'s chamber door; return to Apururu.\n• Ask Yoran-Oran (E-5), Windurst Walls, about Goobbue Humus.\n• Trade one Goobbue Humus to the Mandragora Warden (The Boyahda Tree) for Zonpa-Zippa\'s letter.\n• Give the letter to Apururu, then zone into Full Moon Fountain.' }, { title = 'Notes & reward', note = '• Goobbue Humus is crafted from Humus (Yoran-Oran explains).\n• Speak to the Warden first to get his speech translated.\n• Title: Guiding Star.' } } },
    { name = 'Moon Reading', group = 'Mission: Windurst', desc = 'Windurst 9-2: gather three Ancient Verses, win Moon Reading at Full Moon Fountain, and earn Rank 10. Source: https://vanadreams.org/wiki/#mission-71', steps = { { title = 'Before you start', note = '• Rank 9 with 9-1 done; no other national mission.\n• One free inventory slot (Windurstian Flag).' }, { title = 'Walkthrough', note = '• Accept, then examine the Vestal Chamber door in Heaven\'s Tower.\n• Altepa verse: enter Chamber of Oracles from Quicksand Caves (only that way).\n• Ro\'Maeve verse: examine QuHau Spring.\n• Uggalepih verse: ??? (Map 3, E-8), Temple of Uggalepih.\n• With all three, examine the Vestal Chamber door again.\n• Win Moon Reading at Full Moon Fountain (30 min, 6 players, Trusts OK).\n• Examine the Vestal Chamber door for the Orastery ring, then again to warp to Windurst Walls and watch the final scene.' }, { title = 'Notes & reward', note = '• Verses in any order; consumed on victory.\n• Kupipi has new lines afterwards.\n• 100,000 gil, Windurstian Flag, title Vestal Chamberlain.' } } },
    { name = 'The New Frontier', group = 'Mission: Rise of the Zilart', desc = 'First Zilart mission: arrive in Norg and hear the story; grants the Norg map. Source: https://vanadreams.org/wiki/#mission-72', steps = { { title = 'Walkthrough', note = '• Needs nation rank 6+ with this mission active.\n• Zone into Norg for the arrival scene.\n• Speak to Tales Beginning and pick the story option; finish the scene.' }, { title = 'Notes & reward', note = '• Oaken Door and Comitiolus get new dialogue afterwards.\n• Key item: map of Norg.' } } },
    { name = 'Welcome t\'Norg', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 2: pass the Oaken Door in Norg to meet the town\'s leaders. Source: https://vanadreams.org/wiki/#mission-73', steps = { { title = 'Walkthrough', note = '• With this mission active, go to Norg.\n• Examine the Oaken Door (K-8) and watch the scene.' } } },
    { name = 'Kazham\'s Chieftainess', group = 'Mission: Rise of the Zilart', desc = 'Get the Sacrificial Chamber key from Kazham\'s chieftainess. Source: https://vanadreams.org/wiki/#mission-74', steps = { { title = 'Walkthrough', note = '• Optional: Gilgamesh (L-8), Norg, for background.\n• Speak to Jakoh Wahcondalo (J-10) in Kazham.\n• Key item: Sacrificial Chamber key.' } } },
    { name = 'The Temple of Uggalepih', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 4: win the Sacrificial Chamber battle for the dark fragment. Source: https://vanadreams.org/wiki/#mission-75', steps = { { title = 'Walkthrough', note = '• Requires the Sacrificial Chamber key.\n• Optional background: Gilgamesh (L-8, Norg), Jakoh Wahcondalo (J-10, Kazham).\n• Win The Temple of Uggalepih in the Sacrificial Chamber and watch the scene.\n• Re-enter the Sacrificial Chamber if needed for the closing scene.' }, { title = 'Notes & reward', note = '• The key is removed at completion.\n• Replays still award the title.\n• Key item: dark fragment; title Bearer of the Wisewomans Hope.' } } },
    { name = 'Headstone Pilgrimage', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 5: gather seven elemental fragments from Cermet Headstones. Source: https://vanadreams.org/wiki/#mission-76', steps = { { title = 'Headstones', note = '• Ice: Cloister of Frost (L-4).\n• Water: La Theine Plateau (G-11).\n• Earth: Western Altepa Desert (H-9).\n• Lightning: Behemoth\'s Dominion (G-9); defeat Ancient Weapon and Legendary Weapon.\n• Wind: Cape Teriggan (G-5); defeat Axesarion the Wanderer.\n• Light: Sanctuary of Zi\'Tah; defeat the Doomed Pilgrims.\n• Fire: Yuhtunga Jungle (L-7); defeat Tipha and Carthi.\n• Where a fight occurs, re-examine the headstone afterwards for the fragment.' }, { title = 'Notes & reward', note = '• Stand next to the headstone and accept the prompt.\n• Wind, Light and Fire headstones also start Wandering Souls, Soul Searching and Wrath of the Opo-opos.\n• Short delay after the guardians die before the fragment can be taken.\n• Gilgamesh in Norg has extra lines.\n• Title: Bearer of the Eight Prayers.' } } },
    { name = 'Through the Quicksand Caves', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 6: win the Chamber of Oracles battle of the same name. Source: https://vanadreams.org/wiki/#mission-77', steps = { { title = 'Walkthrough', note = '• Optional: Gilgamesh (L-8), Norg.\n• Win Through the Quicksand Caves in the Chamber of Oracles.' } } },
    { name = 'The Chamber of Oracles', group = 'Mission: Rise of the Zilart', desc = 'Set all eight elemental fragments on the Chamber of Oracles pedestals to earn the prismatic fragment. Source: https://vanadreams.org/wiki/#mission-78', steps = { { title = 'Walkthrough', note = '• Hold Fire, Ice, Wind, Earth, Lightning, Water, Light and Dark Fragments.\n• In the Chamber of Oracles, examine each pedestal to place its fragment.\n• Watch the scene after the last one.' }, { title = 'Notes & reward', note = '• Any order; you may leave and come back.\n• Fragments consumed.\n• Key item: prismatic fragment; title Lightweaver.' } } },
    { name = 'Return to Delkfutt\'s Tower', group = 'Mission: Rise of the Zilart', desc = 'Climb Delkfutt\'s Tower to the Stellar Fulcrum and win the battle there. Source: https://vanadreams.org/wiki/#mission-79', steps = { { title = 'Walkthrough', note = '• Optional scenes: Aldo (J-8, Lower Jeuno), Gilgamesh (L-8, Norg).\n• Ascend Lower, Middle and Upper Delkfutt\'s Tower to the Stellar Fulcrum.\n• Watch the scene, then win Return to Delkfutt\'s Tower at the Qe\'Lov Gate.\n• Watch the closing scene.\n• Lower Delkfutt\'s Tower has a one-time optional arrival scene.' } } },
    { name = 'Ro\'Maeve', group = 'Mission: Rise of the Zilart', desc = 'See Aldo in Lower Jeuno, then use Norg\'s Oaken Door to seal Ro\'Maeve. Source: https://vanadreams.org/wiki/#mission-80', steps = { { title = 'Walkthrough', note = '• Speak to Aldo (J-8), Lower Jeuno.\n• Examine the Oaken Door in Norg and agree to proceed.\n• Title: Sealer of the Portal of the Gods.' } } },
    { name = 'The Temple of Desolation', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 10: examine the Hall of the Gods door to reveal the Temple of Desolation. Source: https://vanadreams.org/wiki/#mission-81', steps = { { title = 'Walkthrough', note = '• Optional lines: Aldo (J-8, Lower Jeuno), Gilgamesh (L-8) and Kamui in Norg.\n• Examine the door in Hall of the Gods and watch the scene.\n• The Norg door also has a scene during this mission.' } } },
    { name = 'The Hall of the Gods', group = 'Mission: Rise of the Zilart', desc = 'Investigate the Hall of the Gods, then report in Norg. Source: https://vanadreams.org/wiki/#mission-82', steps = { { title = 'Walkthrough', note = '• Examine the Cermet Grate (H-6) in Hall of the Gods.\n• Optional: Aldo (J-8), Lower Jeuno.\n• Examine the Oaken Door in Norg and agree to proceed.\n• Unlocks The Mithra and the Crystal.' } } },
    { name = 'The Mithra and the Crystal', group = 'Mission: Rise of the Zilart', desc = 'Fetch a scrap of papyrus from Quicksand Caves for Maryoh Comyujah, then take the cerulean crystal to the Hall of the Gods. Source: https://vanadreams.org/wiki/#mission-83', steps = { { title = 'Walkthrough', note = '• Speak to Aldo (J-8), Lower Jeuno.\n• Accept Maryoh Comyujah\'s (G-7) request in Rabao.\n• Enter Quicksand Caves from Western Altepa Desert (C-11) and examine the ??? to spawn the Ancient Vessel; defeat it.\n• Examine the ??? again for the scrap of papyrus.\n• Hand it to Maryoh Comyujah for the cerulean crystal.\n• Examine the Shimmering Circle in Hall of the Gods.' }, { title = 'Good to know', note = '• Stand within ~1.5 yalms of the ???.\n• Ancient Vessel needs ~5 minutes to respawn after a kill.\n• Declined the request? Speak to her again.' } } },
    { name = 'The Gate of the Gods', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 13: zone into Ru\'Aun Gardens for the scene. Source: https://vanadreams.org/wiki/#mission-84', steps = { { title = 'Walkthrough', note = '• Enter Ru\'Aun Gardens and watch the scene.' } } },
    { name = 'Ark Angels', group = 'Mission: Rise of the Zilart', desc = 'Beat the five Ark Angels at LaLoff Amphitheater for their shards. Source: https://vanadreams.org/wiki/#mission-85', steps = { { title = 'Walkthrough', note = '• Speak to Gilgamesh (L-8), Norg.\n• Examine the Divine Might door in The Shrine of Ru\'Avitau.\n• In LaLoff Amphitheater, use the ??? entrances to fight each Ark Angel.\n• Collect Shard of Apathy, Cowardice, Envy, Arrogance and Rage.' }, { title = 'Good to know', note = '• Divine Might fights all five at once and grants every shard.\n• Shards already earned are kept between attempts.' } } },
    { name = 'The Sealed Shrine', group = 'Mission: Rise of the Zilart', desc = 'Unseal and enter The Shrine of Ru\'Avitau. Source: https://vanadreams.org/wiki/#mission-86', steps = { { title = 'Walkthrough', note = '• Examine the Oaken Door in Norg.\n• Optional: Aldo (J-8), Lower Jeuno.\n• Enter The Shrine of Ru\'Avitau for the completing scene.' } } },
    { name = 'The Celestial Nexus', group = 'Mission: Rise of the Zilart', desc = 'Zilart mission 16: defeat Eald\'narche in the Celestial Nexus. Source: https://vanadreams.org/wiki/#mission-87', steps = { { title = 'Walkthrough', note = '• Optional: Gilgamesh (L-8), Norg.\n• Enter the Celestial Nexus from Hall of the Gods and win.\n• You return to Hall of the Gods on completion.\n• Bring an alliance-sized group.\n• Title: Burier of the Illusion.' } } },
    { name = 'Awakening', group = 'Mission: Rise of the Zilart', desc = 'View scenes in Norg and Lower Jeuno to close this Zilart chapter. Source: https://vanadreams.org/wiki/#mission-88', steps = { { title = 'Walkthrough', note = '• Speak to Gilgamesh (L-8), Norg.\n• Zone into Norg for its scene.\n• Examine the door in Lower Jeuno for its scene.\n• Return to Norg for the final scene and choice.\n• Both the Norg and Lower Jeuno scenes are required first.' } } },
    { name = 'The Rites of Life', group = 'Mission: Chains of Promathia', desc = 'Opening Promathia mission: scenes in Lower Delkfutt\'s Tower and Upper Jeuno, ending with the Mysterious Amulet from Monberaux. Source: https://vanadreams.org/wiki/#mission-89', steps = { { title = 'Walkthrough', note = '• Chains of Promathia enabled and not yet started.\n• Enter Lower Delkfutt\'s Tower from Qufim Island.\n• Zone into Upper Jeuno for a scene.\n• Speak to Monberaux in the Infirmary (G-9), Upper Jeuno.' }, { title = 'Notes & reward', note = '• Auchefort, Baran, Colti (Ru\'Lude Gardens) and Rosaline (Upper Jeuno) gain new lines.\n• Key item: mysterious amulet.' } } },
    { name = 'Below the Arks', group = 'Mission: Chains of Promathia', desc = 'Enter one Promyvion via a Shattered Telepoint and seal its memory. Source: https://vanadreams.org/wiki/#mission-90', steps = { { title = 'Walkthrough', note = '• Speak to Pherimociel (G-6), Ru\'Lude Gardens.\n• Examine a Shattered Telepoint: Konschtat Highlands (Dem), La Theine Plateau (Holla) or Tahrongi Canyon (Mea).\n• In Hall of Transference, take the matching door and Large Apparatus.\n• Reach the Spire and examine it for the light of Dem, Holla or Mea.\n• Only one Promyvion is needed now; the others come in The Mothercrystals.' } } },
    { name = 'The Mothercrystals', group = 'Mission: Chains of Promathia', desc = 'Promathia 1-3: clear Promyvion-Holla, Dem and Mea for their Lights. Source: https://vanadreams.org/wiki/#mission-91', steps = { { title = 'Walkthrough', note = '• Use a Shattered Telepoint: La Theine Plateau (Holla), Konschtat Highlands (Dem), Tahrongi Canyon (Mea).\n• Take the matching Large Apparatus in Hall of Transference.\n• Touch the Spire at the end for that Light; you are sent out.\n• Repeat for the other two; after the third you go to Lufaise Meadows.' }, { title = 'Notes & reward', note = '• One Promyvion at a time; seal the current memories at its Telepoint or Apparatus to switch.\n• Exit via the Large Apparatus.\n• Afterwards Telepoints lead straight to Hall of Transference.\n• Title: Ancient Flame Follower.' } } },
    { name = 'An Invitation West', group = 'Mission: Chains of Promathia', desc = 'Your amulet is stolen in Lufaise Meadows and you end up in Tavnazian Safehold. Source: https://vanadreams.org/wiki/#mission-92', steps = { { title = 'Walkthrough', note = '• Hold the mysterious amulet.\n• Go to Lufaise Meadows for the theft scene.\n• Zone into Tavnazian Safehold for the closing scene.\n• Unlocks The Lost City. Title: Dead Body.' } } },
    { name = 'The Lost City', group = 'Mission: Chains of Promathia', desc = 'Talk to Despachiaire and check the Sewer Entrance in Tavnazian Safehold. Source: https://vanadreams.org/wiki/#mission-93', steps = { { title = 'Walkthrough', note = '• Speak to Despachiaire (Map 1, K-10).\n• Optional: Arquil (Map 1, J-9), Justinius, Liphatte (Map 3, I-7).\n• Examine the Sewer Entrance (Map 3, I-7).' } } },
    { name = 'Distant Beliefs', group = 'Mission: Chains of Promathia', desc = 'Promathia 2-3: explore Phomiuna Aqueducts and report to Justinius. Source: https://vanadreams.org/wiki/#mission-94', steps = { { title = 'Walkthrough', note = '• Defeat the Minotaur in Phomiuna Aqueducts.\n• Examine the marked door for a scene.\n• Speak to Justinius in Tavnazian Safehold (stock lines until the Aqueducts part is done).' } } },
    { name = 'An Eternal Melody', group = 'Mission: Chains of Promathia', desc = 'Promathia 2-4: from a Safehold door to the Dilapidated Gate on Misareaux Coast. Source: https://vanadreams.org/wiki/#mission-95', steps = { { title = 'Walkthrough', note = '• Examine the Walnut Door, Tavnazian Safehold (Mysterious Amulet).\n• Optional hints: Justinius, Parelbriaux.\n• Examine the Dilapidated Gate, Misareaux Coast.\n• Back in Tavnazian Safehold, walk into the trigger area for the final scene.' } } },
    { name = 'Ancient Vows', group = 'Mission: Chains of Promathia', desc = 'Go through the Dilapidated Gate to Riverne - Site A01 and win Ancient Vows at Monarch Linn. Source: https://vanadreams.org/wiki/#mission-96', steps = { { title = 'Walkthrough', note = '• Speak to Justinius, Tavnazian Safehold.\n• Examine the Dilapidated Gate, Misareaux Coast.\n• Enter Riverne - Site A01 for the arrival scene.\n• At Monarch Linn (6 players, 30 min) defeat the Mammet-19 Epsilon units.\n• Victory sends you to South Gustaberg.' } } },
    { name = 'The Call of the Wyrmking', group = 'Mission: Chains of Promathia', desc = 'Promathia 3-1: scenes around Bastok ending with Cid. Source: https://vanadreams.org/wiki/#mission-97', steps = { { title = 'Walkthrough', note = '• Zone into South Gustaberg.\n• Walk through Port Bastok to trigger a scene.\n• Speak to Cid (H-8), Metalworks.' } } },
    { name = 'A Vessel Without a Captain', group = 'Mission: Chains of Promathia', desc = 'Promathia 3-2: follow Cid\'s lead to Jeuno, ending in Ru\'Lude Gardens. Source: https://vanadreams.org/wiki/#mission-98', steps = { { title = 'Walkthrough', note = '• Optional: Cid (H-8), Metalworks.\n• Click the Neptune\'s Spire (Tenshodo) door in Lower Jeuno; membership not needed.\n• Harnek (J-7) repeats the dialogue if asked.\n• Walk into the event area in Ru\'Lude Gardens.' } } },
    { name = 'The Road Forks', group = 'Mission: Chains of Promathia', desc = 'Promathia 3-3: finish both a San d\'Oria and a Windurst path, then report to Cid. Source: https://vanadreams.org/wiki/#mission-99', steps = { { title = 'San d\'Oria path', note = '• Zone into Northern San d\'Oria; speak to Arnau (M-6), then Chasalvige (L-6).\n• In Carpenters\' Landing, speak to Guilloud (Map 1, H-10), defeat Overgrown Ivy, speak to him again.\n• Speak to Hinaree (B-6), Southern San d\'Oria.' }, { title = 'Windurst path', note = '• Zone into Windurst Waters; speak to Ohbiru-Dohbiru.\n• Yoran-Oran (E-5, Walls) → Kyume-Romeh → Honoi-Gomoi (Waters) for the cracked Mimeo Mirror; give it to Yoran-Oran.\n• Attohwa Chasm: check Loose Sand (K-8) up close, defeat Lioumere, check again for the Mimeo Jewel.\n• Quickly check the Cradle of Rebirth (J-9) for three Mimeo Feathers.\n• Feathers to Yoran-Oran, then Yujuju (M-6, Port Windurst), Tosuka-Porika (Waters), Yoran-Oran.' }, { title = 'Finish', note = '• Speak to Cid (H-8), Metalworks.' }, { title = 'Good to know', note = '• Mimeo Jewel expires after 30 minutes or on leaving Attohwa Chasm.\n• Overgrown Ivy and Lioumere are solo fights.' } } },
    { name = 'Tending Aged Wounds', group = 'Mission: Chains of Promathia', desc = 'See Cid, then follow events in Lower Jeuno. Source: https://vanadreams.org/wiki/#mission-100', steps = { { title = 'Walkthrough', note = '• Speak to Cid (H-8), Metalworks.\n• Zone into Lower Jeuno for a scene.\n• Examine Door:"Neptune\'s Spire" (I-7).\n• Unlocks Darkness Named.' } } },
    { name = 'Darkness Named', group = 'Mission: Chains of Promathia', desc = 'Give Monberaux the amulet, get the Pso\'Xja pass, and win Darkness Named in The Shrouded Maw. Source: https://vanadreams.org/wiki/#mission-101', steps = { { title = 'Walkthrough', note = '• Give the mysterious amulet to Monberaux (G-10), Upper Jeuno.\n• Speak to Ghebi Damomohe (I-7), Lower Jeuno, then trade a Carmine, Cyan or Gray Chip for the Pso\'Xja pass.\n• Enter The Shrouded Maw and win Darkness Named.\n• Report to Monberaux.' }, { title = 'Good to know', note = '• Aldo, Harnek, Sattal-Mansal have optional lines beforehand.\n• Ghebi also pays 500 gil (scaled by server gil rate).' } } },
    { name = 'Sheltering Doubt', group = 'Mission: Chains of Promathia', desc = 'Promathia 4-1: talk to the Safehold leaders, then check the Misareaux Coast gate. Source: https://vanadreams.org/wiki/#mission-102', steps = { { title = 'Walkthrough', note = '• Zone into Tavnazian Safehold.\n• Speak to Despachiaire (Map 1, K-10), then Justinius.\n• Examine the gate in Misareaux Coast.' } } },
    { name = 'The Savage', group = 'Mission: Chains of Promathia', desc = 'Promathia 4-2: win The Savage at Monarch Linn and report to Justinius in Tavnazian Safehold. Source: https://vanadreams.org/wiki/#mission-103', steps = { { title = 'Before you start', note = '• Finish Promathia 4-1, Sheltering Doubt.' }, { title = 'Walkthrough', note = '• Examine the Dilapidated Gate in Misareaux Coast and enter Monarch Linn.\n• Win The Savage (if you lose or leave, use the same gate to retry).\n• Speak to Justinius in Tavnazian Safehold.\n• Title: Nagmoladas Underling.' } } },
    { name = 'The Secrets of Worship', group = 'Mission: Chains of Promathia', desc = 'Promathia 4-3: reach the Sacrarium and take the reliquiarium key from Old Professor Mariselle. Source: https://vanadreams.org/wiki/#mission-104', steps = { { title = 'Walkthrough', note = '• Examine the Walnut Door, Tavnazian Safehold; speak to Parelbriaux.\n• Go through the Iron Gate, Misareaux Coast, to the Sacrarium.\n• Examine the Wooden Gate from its east (far) side.\n• Check the ??? spots until Old Professor Mariselle spawns; defeat her group.\n• Examine that ??? again for the reliquiarium key.\n• Use the key on the Wooden Gate from the east side.' }, { title = 'Good to know', note = '• Only one ??? holds Mariselle; others just close.\n• Re-enter later via the Misareaux Iron Gate.' } } },
    { name = 'Slanderous Utterings', group = 'Mission: Chains of Promathia', desc = 'Promathia 4-4: a Safehold scene leads to Sealion\'s Den. Source: https://vanadreams.org/wiki/#mission-105', steps = { { title = 'Walkthrough', note = '• Walk into the trigger area in Tavnazian Safehold.\n• Examine the Iron Gate (H-6), Sealion\'s Den.\n• Despachiaire and Arquil get new lines.\n• Title: The Lost One.' } } },
    { name = 'The Enduring Tumult of War', group = 'Mission: Chains of Promathia', desc = 'Promathia 5-1: nation scenes, then defeat Nunyunuwi in Pso\'Xja and reach Promyvion - Vahzl. Source: https://vanadreams.org/wiki/#mission-106', steps = { { title = 'Walkthrough', note = '• Optional: Despachiaire (Map 1, K-10, Safehold), Chasalvige (L-6, N. San d\'Oria), Anoki (H-6, Port San d\'Oria, two scenes).\n• Required: zone into Port Bastok, then speak to Cid (H-8), Metalworks.\n• Enter Pso\'Xja from Beaucedine Glacier (F-7) for a scene.\n• Examine the trap door to spawn Nunyunuwi (Map 8, H-8); defeat it.\n• Examine that gate, then the neighbouring one (it offers an exit).\n• Zone into Promyvion - Vahzl for the Light of Vahzl.' } } },
    { name = 'Desires of Emptiness', group = 'Mission: Chains of Promathia', desc = 'Promathia 5-2: seal three Memory Fluxes in Promyvion-Vahzl and win at the Spire of Vahzl. Source: https://vanadreams.org/wiki/#mission-107', steps = { { title = 'Walkthrough', note = '• Enter Pso\'Xja from Beaucedine Glacier (F-7), then Promyvion-Vahzl via its gate.\n• At each Memory Flux, spawn and kill the Propagator, Solicitor and Ponderer; re-examine each flux for a scene (any order).\n• Enter the Spire of Vahzl and win Desires of Emptiness.\n• Zone into Beaucedine Glacier for the amulet scene.\n• Speak to Cid (H-8), Metalworks.' } } },
    { name = 'Three Paths', group = 'Mission: Chains of Promathia', desc = 'CoP 5-3: finish the Louverance, Tenzen and Ulmia story lines for Cid to clear the mission. Source: https://vanadreams.org/wiki/#mission-108', steps = { { title = 'Requirements', note = '• Active mission: CoP 5-3.\n• Fights: Century of Hardship, Head Wind, Flames for the Dead, Disaster Idol.' }, { title = 'Start', note = '• Speak to Cid (H-8), Metalworks; paths may be done in any order, reporting to Cid after each.' }, { title = 'Louverance', note = '• Visit Despachiaire (Map 1, K-10), Tavnazian Safehold, then Perih Vashai (K-7), Windurst Woods.\n• Visit Warmachine (Bibiki Bay), then Yoran-Oran (E-5), Windurst Walls.\n• Go into Oldton Movalpolos via North Gustaberg (K-6) for a scene, clear Century of Hardship, report to Cid.\n• Re-enter Oldton Movalpolos the same way, see Tarnotik (K-10), trade a Gold Key to the Mine Shaft 2716 door, report to Cid.' }, { title = 'Tenzen', note = '• Check the ??? (G-6), La Theine Plateau; check the door in Pso\'Xja; get an envelope from Monberaux (G-10), Upper Jeuno.\n• Hand it to Pherimociel (G-6), Ru\'Lude Gardens.\n• Check the ??? (K-8), Batallia Downs, twice for the Delkfutt recognition device.\n• At the ??? in Lower Delkfutt\'s Tower, spawn and kill Disaster Idol (Map 1, H-5), then check it again.\n• Enter Pso\'Xja for a scene, check the door, report to Cid.' }, { title = 'Ulmia', note = '• See Hinaree (B-6), Southern San d\'Oria; zone into Port San d\'Oria for a scene; see Chasalvige (L-6), Northern San d\'Oria.\n• See Kerutoto (Windurst Waters), then Yoran-Oran (E-5), Windurst Walls.\n• Clear Head Wind (Boneyard Gully) and Flames for the Dead (Bearclaw Pinnacle), report to Cid.' }, { title = 'Notes', note = '• Cid tells you how many paths are left.\n• Reward title: Treader of an Icy Past.' } } },
    { name = 'For Whom the Verse is Sung', group = 'Mission: Chains of Promathia', desc = 'CoP 6-1: a few cutscenes in Ru\'Lude Gardens and Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-109', steps = { { title = 'Steps', note = '• Speak to Pherimociel (G-6), Ru\'Lude Gardens.\n• Check the Marble Bridge door in Upper Jeuno.\n• Zone into Ru\'Lude Gardens for the closing scene.' }, { title = 'Notes', note = '• Pherimociel only repeats himself until the Marble Bridge scene is done.' } } },
    { name = 'A Place to Return', group = 'Mission: Chains of Promathia', desc = 'CoP 6-2: kill three Warders summoned at Misareaux Coast\'s Dilapidated Gate. Source: https://vanadreams.org/wiki/#mission-110', steps = { { title = 'Steps', note = '• Watch the cutscene in the Ru\'Lude Gardens event area; Pherimociel (G-6) and Auchefort (H-7) have extra lines.\n• At Misareaux Coast, check the Dilapidated Gate to spawn the Warders.\n• Kill Warder Aglaia, Warder Euphrosyne and Warder Thalia.\n• Check the gate (I-11) again for the final scene.' }, { title = 'Notes', note = '• Each Warder kill is saved separately; all three are needed.' } } },
    { name = 'More Questions than Answers', group = 'Mission: Chains of Promathia', desc = 'CoP 6-3: talks in Ru\'Lude Gardens, finishing with Mathilde in Selbina. Source: https://vanadreams.org/wiki/#mission-111', steps = { { title = 'Steps', note = '• Speak to Pherimociel (G-6), Ru\'Lude Gardens.\n• Check the door (H-6) there.\n• Speak to Pherimociel again, then Auchefort (H-7).\n• Speak to Mathilde (H-9) in Selbina to finish.' }, { title = 'Notes', note = '• Adolie, Chapi Galepilai, Colti and Neraf-Najiruf have flavor text only.' } } },
    { name = 'One to be Feared', group = 'Mission: Chains of Promathia', desc = 'CoP 6-4: fight Ultima in Sealion\'s Den. Source: https://vanadreams.org/wiki/#mission-112', steps = { { title = 'Steps', note = '• Speak to Cid (H-8), Metalworks, for a scene.\n• Zone into Sealion\'s Den for a scene (Sueleen at H-6 is optional).\n• Use the Iron Gate (H-6) to reach the battlefield.\n• Win One to be Feared (6 players max, 45 min); you end up in Lufaise Meadows.' }, { title = 'Notes', note = '• Trusts allowed.\n• Disconnected after the win? The scene plays next time you enter Sealion\'s Den.\n• Gives EXP and title Ultima Undertaker.' } } },
    { name = 'Chains and Bonds', group = 'Mission: Chains of Promathia', desc = 'CoP 7-1: pick up the Ducal Guard\'s Ring in Lufaise Meadows, then view three scenes. Source: https://vanadreams.org/wiki/#mission-113', steps = { { title = 'Steps', note = '• Zone into Lufaise Meadows for a scene and the Ducal Guard\'s Ring (full bags: get it later from the ??? there).\n• Enter Tavnazian Safehold for an arrival scene.\n• Click the Walnut Door, then the Sewer Entrance (Map 3, I-7), in the Safehold.\n• Zone into Sealion\'s Den for a scene; done when all three scenes are seen.' }, { title = 'Notes', note = '• Walnut Door, Sewer Entrance and Sealion\'s Den scenes can be done in any order.' } } },
    { name = 'Flames in the Darkness', group = 'Mission: Chains of Promathia', desc = 'CoP mission running from Misareaux Coast through Sealion\'s Den and Ru\'Lude Gardens to Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-114', steps = { { title = 'Steps', note = '• Check the Dilapidated Gate, Misareaux Coast.\n• Speak to Sueleen (H-6), Sealion\'s Den.\n• Walk into the event area in Ru\'Lude Gardens.\n• Check Door:"Marble Bridge" (F-7), Upper Jeuno, to finish.' }, { title = 'Notes', note = '• Unlocks Fire in the Eyes of Men.\n• Reward title: Eshantarls Comrade in Arms.' } } },
    { name = 'Fire in the Eyes of Men', group = 'Mission: Chains of Promathia', desc = 'CoP 7-3: check the Mine Shaft entrance, then wait a game day for Cid. Source: https://vanadreams.org/wiki/#mission-115', steps = { { title = 'Steps', note = '• Check the Shaft Entrance, Mine Shaft #2716.\n• Speak to Cid (H-8), Metalworks.\n• After one Vana\'diel day, speak to Cid again to finish.' }, { title = 'Reward', note = '• Title: Prishes Buddy.' } } },
    { name = 'Calm Before the Storm', group = 'Mission: Chains of Promathia', desc = 'CoP 7-4: three fights in Misareaux Coast, Carpenters\' Landing and Bibiki Bay, then report to Cid and Sueleen. Source: https://vanadreams.org/wiki/#mission-116', steps = { { title = 'Steps', note = '• Misareaux Coast: click the ???, kill Boggelmann (E-7), click again for a scene and the Vessel of Light.\n• Carpenters\' Landing: click the ??? (Cryptonberries) to spawn Cryptonberry Executor (Map 1, I-9); kill it and its Cryptonberry Assassins, then click again.\n• Bibiki Bay: click the ??? (Map 1, F-6), kill Dalham, click again.\n• Get the Letters from Ulmia and Prishe from Cid (H-8), Metalworks.\n• Hand them to Sueleen (H-6), Sealion\'s Den, to finish.' }, { title = 'Notes', note = '• Areas in any order.\n• All four Cryptonberries must die before that scene plays.' } } },
    { name = 'The Warrior\'s Path', group = 'Mission: Chains of Promathia', desc = 'Clear the Warrior\'s Path battlefield in Sealion\'s Den and continue to Al\'Taieu. Source: https://vanadreams.org/wiki/#mission-117', steps = { { title = 'Steps', note = '• Check the Iron Gate (H-6) at the corridor\'s end in Sealion\'s Den for a scene.\n• Win the Warrior\'s Path battlefield.\n• Re-enter Sealion\'s Den for a scene that sends you to Al\'Taieu.\n• Watch the Al\'Taieu scene to finish.' }, { title = 'Notes', note = '• The Al\'Taieu scene swaps your drained mysterious amulet and race Light key item for the light of Al\'Taieu.\n• Afterwards Sueleen can return you to the sea.\n• Reward title: Seeker of the Light.' } } },
    { name = 'Garden of Antiquity', group = 'Mission: Chains of Promathia', desc = 'Clear the three Rubious Crystal towers in Al\'Taieu, then head into the Grand Palace of Hu\'Xzoi. Source: https://vanadreams.org/wiki/#mission-118', steps = { { title = 'Requirements', note = '• Previous mission The Warrior\'s Path; a party or alliance for the tower fights.' }, { title = 'Steps', note = '• Check the central door in Al\'Taieu to begin.\n• At each tower, check the Rubious Crystal; kill the three Ruaern it spawns, then check the crystal again.\n• With all towers cleared, revisit the central door for a scene; you can opt to teleport to the Grand Palace of Hu\'Xzoi (entrance also at H-11).\n• In the palace, check the first gate for a Tavnazian Ring, then the second gate to finish.' }, { title = 'Notes', note = '• Towers in any order; each saves when you recheck its crystal.\n• The central door scene can be replayed.' } } },
    { name = 'A Fate Decided', group = 'Mission: Chains of Promathia', desc = 'CoP 8-2: lure out and kill Ix\'ghrah in the Grand Palace of Hu\'Xzoi. Source: https://vanadreams.org/wiki/#mission-119', steps = { { title = 'Steps', note = '• Check the marked door in the Grand Palace of Hu\'Xzoi to spawn Ix\'ghrah.\n• Kill Ix\'ghrah.\n• Check the door again for the scene.' }, { title = 'Notes', note = '• The other door nearby does nothing.' } } },
    { name = 'When Angels Fall', group = 'Mission: Chains of Promathia', desc = 'CoP 8-3: take your race\'s light from the Ebon Panels in The Garden of Ruhmet, then win the battle. Source: https://vanadreams.org/wiki/#mission-120', steps = { { title = 'Steps', note = '• Zone into The Garden of Ruhmet for a scene and the Mysterious Amulet.\n• Check any Ebon Panel for a scene.\n• Stand right next to your race\'s panel (Hume, Elvaan, Tarutaru, Mithra or Galka) and check it for its Light key item.\n• Check the Particle Gate and win When Angels Fall.\n• Check the Luminous Convergence (Map 3, H-7).\n• Zone into Al\'Taieu for the final scene.' }, { title = 'Notes', note = '• Other Particle Gates can award the Brand of Dawn and Brand of Twilight.' } } },
    { name = 'Dawn', group = 'Mission: Chains of Promathia', desc = 'Final CoP mission: beat Promathia, get the Tear of Altana, make farewell visits and end in Norg. Source: https://vanadreams.org/wiki/#mission-121', steps = { { title = 'Battle', note = '• Check the Transcendental Radiance entrance in Empyreal Paradox.\n• Win Dawn (6 players, 30 min) against Promathia.\n• Re-enter Empyreal Paradox for the Tear of Altana; you are moved to Altaieu.' }, { title = 'Farewells (after next Japanese midnight)', note = '• Hinaree (B-6), Southern San d\'Oria, then Uleguerand Range.\n• Chipmy-Popmy (C-8), Port Windurst, then Warmachine in Bibiki Bay.\n• Zone into Mhaura and Oldton Movalpolos; speak to Cid (H-8), Metalworks.' }, { title = 'Ending', note = '• Walk into the Ru\'Lude Gardens trigger area.\n• Check the Marble Bridge door (Upper Jeuno), then the Walnut Door (Tavnazian Safehold).\n• Walk into the Lufaise Meadows trigger, then go to Norg to finish.' }, { title = 'Notes', note = '• Warmachine gives one random colored Drop out of eight.\n• The Marble Bridge door offers a Rajas, Sattva or Tamas Ring; ask it again if lost.' } } },
    { name = 'Land of Sacred Serpents', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 1, the start of the storyline: reach Whitegate and meet Naja Salaheem. Mission 1. Source: https://vanadreams.org/wiki/#mission-122', steps = { { title = 'Steps', note = '• Needs ToAU enabled and the Boarding Permit.\n• Arrive in Aht Urhgan Whitegate and enter the event area near the Imperial Gate.' }, { title = 'Reward', note = '• Key item: supplies package.' } } },
    { name = 'Immortal Sentries', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 2: give the Supplies Package to an Immortal, then report to Naja Salaheem. Mission 2. Source: https://vanadreams.org/wiki/#mission-123', steps = { { title = 'Steps', note = '• Choose an Immortal: Meyaada (Arrapago Reef), Daswil (Map 2, H-10, Bhaflau Thickets), Nahshib (Map 2, I-9) or Nareema (Caedarva Mire), Waudeen (K-6, Mount Zhayolm).\n• Talk to them and hand over the package.\n• Report to Naja Salaheem (I-10), Aht Urhgan Whitegate.' }, { title = 'Notes', note = '• The handover gives Imperial Standing.\n• Joins you to Salaheem\'s Sentinels and unlocks a Mog Locker.\n• Rewards: PSC Wildcat badge; title Private Second Class.' } } },
    { name = 'President Salaheem', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 3: two talks with Naja Salaheem separated by a zone. Mission 3. Source: https://vanadreams.org/wiki/#mission-124', steps = { { title = 'Steps', note = '• Speak to Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Leave the zone and come back.\n• Speak to him again to finish.' } } },
    { name = 'Knight of Gold', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 4: pay Cacaroon and trace the Knight of Gold around Whitegate. Mission 4. Source: https://vanadreams.org/wiki/#mission-125', steps = { { title = 'Steps', note = '• Speak to Cacaroon (G-11), Aht Urhgan Whitegate.\n• Trade him 1,000 gil or one Imp. Brz. Piece.\n• Go to the Walahra Temple area for a scene.\n• Go to the Teahouse area and pick all three topics.' }, { title = 'Notes', note = '• Cacaroon reminds you of the next step.\n• Reward: Raillefal\'s letter.' } } },
    { name = 'Confessions of Royalty', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 5: hand Raillefal\'s letter to Halver inside Chateau d\'Oraguille. Mission 5. Source: https://vanadreams.org/wiki/#mission-126', steps = { { title = 'Requirements', note = '• Prior ToAU mission done; hold key item Raillefal\'s Letter.\n• Chateau entry needs nation Rank 3 (San d\'Oria citizens: Rank 2) or enough mission progress with another nation.\n• No entry yet: Guilerme in Northern San d\'Oria lets you in.' }, { title = 'Steps', note = '• Optional hints in Aht Urhgan Whitegate: Naja Salaheem (I-10), Cacaroon (G-11), Nadeey (K-7).\n• Go to Chateau d\'Oraguille in San d\'Oria.\n• Give Raillefal\'s Letter to Halver (I-9).' } } },
    { name = 'Easterly Winds', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 6: a scene with the Imperial delegation plays in Ru\'Lude Gardens. Mission 6. Source: https://vanadreams.org/wiki/#mission-127', steps = { { title = 'Steps', note = '• Have Easterly Winds as your active mission.\n• Enter the marked spot in Ru\'Lude Gardens to start the scene.\n• Accept or decline 10 Imperial Bronze Pieces.' }, { title = 'Notes', note = '• Optional talk: Naja Salaheem, Cacaroon, Nadeey (Whitegate), Halver (Chateau d\'Oraguille).\n• Taking the pieces with a full bag stalls completion until space is freed.' } } },
    { name = 'Westerly Winds', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 7: pick up Raillefal\'s Note in Whitegate and deliver it to Naja Salaheem. Mission 7. Source: https://vanadreams.org/wiki/#mission-128', steps = { { title = 'Requirements', note = '• Westerly Winds active; one free inventory slot.' }, { title = 'Steps', note = '• Optional chat in Aht Urhgan Whitegate: Cacaroon (G-11), Nadeey (K-7), Naja Salaheem (I-10).\n• Enter the marked spot in Whitegate to get Raillefal\'s Note and an Imperial Silver Piece.\n• Give the note to Naja Salaheem (I-10).' }, { title = 'Notes', note = '• Zone before the next mission.\n• Reward: Imp. Slv. Piece.' } } },
    { name = 'A Mercenary Life', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 8: speak to Naja Salaheem, zone, then finish her briefing in Whitegate. Mission 8. Source: https://vanadreams.org/wiki/#mission-129', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Leave the zone and re-enter Whitegate.\n• Step into the marked spot for the scene with Naja.\n• Pick both topics; the mission only ends once both are chosen.' } } },
    { name = 'Undersea Scouting', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 9: get the plan from Naja Salaheem, then scout Alzadaal Undersea Ruins. Mission 9. Source: https://vanadreams.org/wiki/#mission-130', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Go to Alzadaal Undersea Ruins and enter the marked spot by the entrance.\n• Watch the cutscene.\n• Reward: key item astral compass.' } } },
    { name = 'Astral Waves', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 10: a cutscene with Naja Salaheem in Whitegate. Mission 10. Source: https://vanadreams.org/wiki/#mission-131', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Aht Urhgan Whitegate, and view the cutscene.\n• Then wait one Vana\'diel day and zone before Imperial Schemes.' } } },
    { name = 'Imperial Schemes', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 11: speak with Naja Salaheem, then return later for a scene in Whitegate. Mission 11. Source: https://vanadreams.org/wiki/#mission-132', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Wait one Vana\'diel day and zone.\n• Enter the marked spot in Whitegate to play the scene.' } } },
    { name = 'Royal Puppeteer', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 12: deliver a Vial of Jody\'s Acid to Pyopyoroon in Nashmau. Mission 12. Source: https://vanadreams.org/wiki/#mission-133', steps = { { title = 'Steps', note = '• Talk to Pyopyoroon (H-7), Nashmau.\n• Get one Vial of Jody\'s Acid.\n• Trade it to Pyopyoroon.\n• Reward: key item vial of spectral scent.' }, { title = 'Notes', note = '• Naja Salaheem (Whitegate) reminds you of the task.' } } },
    { name = 'Lost Kingdom', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 13: use the spectral scent at Jazaraat\'s Headstone in Caedarva Mire and beat the ghost. Mission 13. Source: https://vanadreams.org/wiki/#mission-134', steps = { { title = 'Requirements', note = '• Lost Kingdom active; key item vial of spectral scent.' }, { title = 'Steps', note = '• Examine Jazaraat\'s Headstone, Caedarva Mire (Map 1, E-10).\n• Examine it again to spawn Jazaraat; defeat him.\n• Examine it a third time and watch the scene.\n• Reward: key item Ephramadian gold coin.' }, { title = 'Notes', note = '• Optional talk: Pyopyoroon (Nashmau), Naja Salaheem (Whitegate).\n• Lost the coin? Examine the headstone again to get another.' } } },
    { name = 'The Dolphin Crest', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 14: a report to Naja Salaheem in Whitegate. Mission 14. Source: https://vanadreams.org/wiki/#mission-135', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Watch the cutscene to finish.' } } },
    { name = 'The Black Coffin', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 15: take the Ephramadian gold coin to Arrapago Reef, clear The Ashu Talif, and end up in Nashmau. Mission 15. Source: https://vanadreams.org/wiki/#mission-136', steps = { { title = 'Requirements', note = '• The Black Coffin active; hold the Ephramadian gold coin.' }, { title = 'Steps', note = '• Get the briefing from Naja Salaheem (I-10), Whitegate.\n• Enter the marked spot at the Arrapago Reef entrance for a scene.\n• Complete The Ashu Talif, then return to Arrapago Reef for another scene.\n• You are sent to Nashmau; the last scene completes it.' }, { title = 'Notes', note = '• Without the coin after the first scene, re-entering the spot gives a brief reminder.' } } },
    { name = 'Ghosts of the Past', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 16: a scene with Naja Salaheem in Whitegate where your clothing matters. Mission 16. Source: https://vanadreams.org/wiki/#mission-137', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Aht Urhgan Whitegate, ideally in Royal Palace armor.\n• Pick his outfit during the scene and finish it.\n• Your attire affects Naja\'s reaction.' } } },
    { name = 'Guests of the Empire', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 17: dress for the Royal Palace and get past the Imperial Whitegate guard. Mission 17. Source: https://vanadreams.org/wiki/#mission-138', steps = { { title = 'Steps', note = '• Talk to Naja Salaheem (I-10), Whitegate, and proceed; you may choose attire.\n• Wear palace-suitable gear: an allowed body item, plus hands, legs and feet covered.\n• Take off main-hand and sub.\n• Talk to the Imperial Whitegate guard.' }, { title = 'Notes', note = '• Improper dress means refusal; Naja repeats the rules.\n• Afterward wait one day and zone before the next mission.\n• Rewards: Imp. Mtl. Piece; title Ovjangs Errand Runner.' } } },
    { name = 'Passing Glory', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 18: a scene with Naja Salaheem after the usual wait. Mission 18. Source: https://vanadreams.org/wiki/#mission-139', steps = { { title = 'Steps', note = '• After a new Vana\'diel day and a zone, speak to Naja Salaheem (I-10), Whitegate.\n• Small talk only means you need to zone or wait more.\n• Entering the area near him can also start the scene.' } } },
    { name = 'Sweets for the Soul', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 19: a Whitegate tour ending in a scene. Mission 19. Source: https://vanadreams.org/wiki/#mission-140', steps = { { title = 'Steps', note = '• Speak to Abquhbah (I-10), Aht Urhgan Whitegate.\n• Enter the trigger area for the closing scene.' }, { title = 'Reward', note = '• Title: Karababas Tour Guide.' } } },
    { name = 'Teahouse Tumult', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 20: look into Aydeewa Subterrane. Mission 20. Source: https://vanadreams.org/wiki/#mission-141', steps = { { title = 'Steps', note = '• Enter Aydeewa Subterrane from Wajaom Woodlands (D-9) for a scene.\n• Check the ??? there to finish.\n• Naja Salaheem (I-10) gives reminders.' } } },
    { name = 'Finders Keepers', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 21: a single scene in Whitegate. Mission 21. Source: https://vanadreams.org/wiki/#mission-142', steps = { { title = 'Steps', note = '• Enter the event area in Aht Urhgan Whitegate.' } } },
    { name = 'Shield of Diplomacy', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 22: guard Karababa against three Khimaira in Navukgo Execution Chamber. Mission 22. Source: https://vanadreams.org/wiki/#mission-143', steps = { { title = 'Steps', note = '• Enter Navukgo Execution Chamber for a scene.\n• Check the Decorative Bronze Gate (D-9) to start.\n• Kill all three Khimaira with Karababa alive (6 players, Trusts OK, 30 min).' }, { title = 'Notes', note = '• Karababa holds back but fights any Khimaira that gets near.\n• Reward title: Karababas Bodyguard.' } } },
    { name = 'Social Graces', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 23: a gathering scene in Whitegate. Mission 23. Source: https://vanadreams.org/wiki/#mission-144', steps = { { title = 'Steps', note = '• Enter the event spot in Aht Urhgan Whitegate.\n• Next mission waits for the next Vana\'diel day.' } } },
    { name = 'Foiled Ambition', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 24: wait, then trigger a scene in Whitegate. Mission 24. Source: https://vanadreams.org/wiki/#mission-145', steps = { { title = 'Steps', note = '• Wait one Vana\'diel day and zone, then enter the event area in Whitegate.\n• Naja Salaheem (I-10) gives reminders.' }, { title = 'Reward', note = '• Imp. Gold Piece; title Karababas Secret Agent.' } } },
    { name = 'Playing the Part', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 25: talk to Naja Salaheem, wait a day, talk again. Mission 25. Source: https://vanadreams.org/wiki/#mission-146', steps = { { title = 'Steps', note = '• Speak to Naja Salaheem (I-10), Whitegate.\n• Zone and wait for the next Vana\'diel day.\n• Speak to Naja again for the scene.' } } },
    { name = 'Seal of the Serpent', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 26: a ceremony at the Imperial Whitegate. Mission 26. Source: https://vanadreams.org/wiki/#mission-147', steps = { { title = 'Steps', note = '• Unequip main and sub weapons.\n• Speak to the Imperial Whitegate (L-9).\n• Armed players only get a reminder.' } } },
    { name = 'Misplaced Nobility', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 27: check a ??? in Aydeewa Subterrane. Mission 27. Source: https://vanadreams.org/wiki/#mission-148', steps = { { title = 'Steps', note = '• Enter Aydeewa Subterrane from Wajaom Woodlands (D-9).\n• Check the ??? in the far west for the scene.\n• Naja Salaheem (I-10) gives guidance.' } } },
    { name = 'Bastion of Knowledge', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 28: one scene in Whitegate. Mission 28. Source: https://vanadreams.org/wiki/#mission-149', steps = { { title = 'Steps', note = '• Enter the event area in Aht Urhgan Whitegate.\n• Reward title: Aphmaus Mercenary.' } } },
    { name = 'Puppet in Peril', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 29: clear the Puppet in Peril battlefield in Jade Sepulcher. Mission 29. Source: https://vanadreams.org/wiki/#mission-150', steps = { { title = 'Steps', note = '• Get the briefing from Naja Salaheem (I-10).\n• Check the Ornamental Door (H-8), Jade Sepulcher.\n• Win Puppet in Peril (6 players, 30 min).' } } },
    { name = 'Prevalence of Pirates', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 30: investigate pirates at Arrapago Reef. Mission 30. Source: https://vanadreams.org/wiki/#mission-151', steps = { { title = 'Steps', note = '• Zone into Arrapago Reef (any Survival Guide works) for a scene.\n• Enter the event area there for the second scene.' }, { title = 'Reward', note = '• Key item: Periqia Assault area entry permit.' } } },
    { name = 'Shades of Vengeance', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 31: get the Periqia permit from Nahshib and clear the assault. Mission 31. Source: https://vanadreams.org/wiki/#mission-152', steps = { { title = 'Steps', note = '• Get the briefing from Naja Salaheem (I-10).\n• Get the Periqia Assault area entry permit from Nahshib (Map 2, I-9), Caedarva Mire; if refused, retry after a Vana\'diel day.\n• Clear the Periqia assault.\n• Re-enter Caedarva Mire for the scene.' }, { title = 'Reward', note = '• Title: Nashmeiras Mercenary.' } } },
    { name = 'In the Blood', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 32: news from Naja Salaheem, paid with an Imperial Gold Piece. Mission 32. Source: https://vanadreams.org/wiki/#mission-153', steps = { { title = 'Steps', note = '• Speak to Naja Salaheem (I-10), Whitegate.\n• Reward: Imp. Gold Piece.\n• Next mission waits for the next Vana\'diel day.' } } },
    { name = 'Sentinels\' Honor', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 33: two talks with Naja Salaheem a day apart. Mission 33. Source: https://vanadreams.org/wiki/#mission-154', steps = { { title = 'Steps', note = '• Speak to Naja Salaheem (I-10), Whitegate.\n• Wait one Vana\'diel day, zone, and speak to Naja again.' } } },
    { name = 'Testing the Waters', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 34: bring the Ephramadian gold coin to Arrapago Reef. Mission 34. Source: https://vanadreams.org/wiki/#mission-155', steps = { { title = 'Steps', note = '• Speak to Naja Salaheem (I-10), Whitegate.\n• With the coin, enter the event area in Arrapago Reef.\n• Answer the scene\'s question correctly (wrong answer: zone and retry).\n• Watch the Talacca Cove scene.' }, { title = 'Notes', note = '• The coin is taken.\n• Rewards: percipient eye; title Treasure Trove Tender.' } } },
    { name = 'Legacy of the Lost', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 35: beat Gessho in Talacca Cove\'s Legacy of the Lost battlefield. Mission 35. Source: https://vanadreams.org/wiki/#mission-156', steps = { { title = 'Steps', note = '• Enter Legacy of the Lost in Talacca Cove (6 players, no level cap, Trusts OK).\n• Kill Gessho and his clones within 30 minutes.' }, { title = 'Notes', note = '• Mission battlefield: no EXP loss on defeat.\n• Reward title: Gesshos Mercy.' } } },
    { name = 'Gaze of the Saboteur', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 36: visit Hazhalm Testing Grounds for the luminian dagger. Mission 36. Source: https://vanadreams.org/wiki/#mission-157', steps = { { title = 'Steps', note = '• Zone into Hazhalm Testing Grounds for a scene.\n• Check the Entry Gate (K-8).' }, { title = 'Notes', note = '• The percipient eye is removed.\n• Rewards: luminian dagger; title Emissary of the Empress.' } } },
    { name = 'Path of Blood', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 37: two scenes in Whitegate. Mission 37. Source: https://vanadreams.org/wiki/#mission-158', steps = { { title = 'Steps', note = '• Enter the event area in Aht Urhgan Whitegate.\n• After being moved in town, zone for the second scene.\n• Wait one Vana\'diel day and zone before the next mission.' } } },
    { name = 'Stirrings of War', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 38: after the wait, a Whitegate scene gives the Allied Council Summons. Mission 38. Source: https://vanadreams.org/wiki/#mission-159', steps = { { title = 'Steps', note = '• Wait a Vana\'diel day and zone after mission 37.\n• Enter the event area in Aht Urhgan Whitegate.\n• Naja Salaheem only repeats lines until then.' }, { title = 'Reward', note = '• Key item: Allied Council Summons.' } } },
    { name = 'Allied Rumblings', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 39: a single cutscene in Ru\'Lude Gardens. Source: https://vanadreams.org/wiki/#mission-160', steps = { { title = 'Requirements', note = '• Active ToAU mission: Allied Rumblings.' }, { title = 'Walkthrough', note = '• Enter the marked entrance area of Ru\'Lude Gardens.\n• View the cutscene; mission done.' }, { title = 'Notes', note = '• Zone once and let a Vana\'diel day pass before the next mission.\n• Naja Salaheem (Aht Urhgan Whitegate) restates the objective.' } } },
    { name = 'Unraveling Reason', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 40: Pherimociel sends you by ship to Wajaom Woodlands for three cutscenes. Source: https://vanadreams.org/wiki/#mission-161', steps = { { title = 'Requirements', note = '• Active ToAU mission: Unraveling Reason.' }, { title = 'Walkthrough', note = '• Speak with Pherimociel (G-6), Ru\'Lude Gardens; if no ship yet, wait a Vana\'diel day, zone, retry.\n• Accept the ship to travel to Wajaom Woodlands.\n• View the cutscene, then re-enter Wajaom Woodlands.\n• Re-enter once more for the last cutscene.' }, { title = 'Notes', note = '• Declining the ship lets you ask Pherimociel again with no wait.\n• Naja Salaheem (Aht Urhgan Whitegate) repeats the briefing.' }, { title = 'Reward', note = '• Title: Endymion Paratrooper' } } },
    { name = 'Light of Judgement', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 41: a cutscene with Rodin-Comidin in Aht Urhgan Whitegate. Source: https://vanadreams.org/wiki/#mission-162', steps = { { title = 'Requirements', note = '• Active ToAU mission: Light of Judgment.' }, { title = 'Walkthrough', note = '• Speak with Rodin-Comidin (I-7), Aht Urhgan Whitegate, and view the cutscene.' }, { title = 'Notes', note = '• Naja Salaheem only has reminder lines.' }, { title = 'Reward', note = '• Key item: Nyzul Isle route' } } },
    { name = 'Path of Darkness', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 42: a Nyzul Isle instance fought together with Naja Salaheem. Source: https://vanadreams.org/wiki/#mission-163', steps = { { title = 'Requirements', note = '• Active ToAU mission: Path of Darkness.\n• Key item Nyzul Isle route.' }, { title = 'Walkthrough', note = '• Get the Nyzul Isle route from Rodin-Comidin (I-7), Aht Urhgan Whitegate.\n• In Alzadaal Undersea Ruins, examine the blank lamp and proceed.\n• Inside Nyzul Isle (Map 4, H-7), with Naja Salaheem, kill Amnaf Blu, then Amnaf Psycheflayer.\n• Back in Alzadaal Undersea Ruins, rezone if needed for the closing cutscene.' }, { title = 'Notes', note = '• Entry consumes the route; after a loss, ask Rodin-Comidin for a new one.\n• The instance has a time limit.' }, { title = 'Reward', note = '• Title: Najas Comrade in Arms' } } },
    { name = 'Fangs of the Lion', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 43: a scene triggered in Aht Urhgan Whitegate. Source: https://vanadreams.org/wiki/#mission-164', steps = { { title = 'Requirements', note = '• Active ToAU mission: Fangs of the Lion.' }, { title = 'Walkthrough', note = '• Walk into the marked area of Aht Urhgan Whitegate; the scene completes the mission.' }, { title = 'Reward', note = '• Key item: mythril mirror\n• Title: Nashmeiras Loyalist' } } },
    { name = 'Nashmeira\'s Plea', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 44: take the mythril mirror to Alzadaal Undersea Ruins and win the Runic Seal battle. Source: https://vanadreams.org/wiki/#mission-165', steps = { { title = 'Requirements', note = '• Active ToAU mission: Nashmeira\'s Plea.' }, { title = 'Walkthrough', note = '• Get the mythril mirror from Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• In Alzadaal Undersea Ruins, examine the lamp.\n• Enter via the Runic Seal (Map 5, I-9) and win.\n• Rezone into Alzadaal Undersea Ruins for the final cutscene.' }, { title = 'Notes', note = '• Naja only reminds you once you hold the mirror.' }, { title = 'Reward', note = '• Title: Preventer of Ragnarok' } } },
    { name = 'Ragnarok', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 45: a cutscene in Aht Urhgan Whitegate. Source: https://vanadreams.org/wiki/#mission-166', steps = { { title = 'Requirements', note = '• Active ToAU mission: Ragnarok.' }, { title = 'Walkthrough', note = '• Step into the marked area of Aht Urhgan Whitegate; the cutscene finishes the mission.' }, { title = 'Notes', note = '• Unlocks Imperial Coronation.' } } },
    { name = 'Imperial Coronation', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 46: attend the coronation at the palace and pick a ring keepsake. Source: https://vanadreams.org/wiki/#mission-167', steps = { { title = 'Requirements', note = '• Active ToAU mission: Imperial Coronation.\n• Palace-appropriate body armor plus hands, legs and feet equipped.\n• No main or sub weapon.' }, { title = 'Walkthrough', note = '• Unequip both weapons and wear the required armor.\n• Talk to the Imperial Whitegate (L-9), Aht Urhgan Whitegate, to view the coronation.\n• Pick Balrahn\'s Ring, Ulthalam\'s Ring or Jalzahn\'s Ring, or refuse all.\n• Accept the Imperial Standard if offered.' }, { title = 'Notes', note = '• Improper attire means the gate turns you away.\n• Later, dressed the same way, the Imperial Whitegate gives any ring or Imperial Standard you skipped.\n• Naja Salaheem points to the next objective.' } } },
    { name = 'The Empress Crowned', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 47: the Empress\'s crowning cutscene in Aht Urhgan Whitegate. Source: https://vanadreams.org/wiki/#mission-168', steps = { { title = 'Requirements', note = '• Active ToAU mission: The Empress Crowned.' }, { title = 'Walkthrough', note = '• Walk into the marked area of Aht Urhgan Whitegate and view the cutscene.' }, { title = 'Reward', note = '• Item: Glory Crown\n• Title: Eternal Mercenary' } } },
    { name = 'Eternal Mercenary', group = 'Mission: Treasures of Aht Urhgan', desc = 'ToAU mission 48, the end of the storyline; only closing dialogue remains. Source: https://vanadreams.org/wiki/#mission-169', steps = { { title = 'Walkthrough', note = '• With Eternal Mercenary active, speak with Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• No further ToAU missions follow.' } } },
    { name = 'Cavernous Maws', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 1: touch a Cavernous Maw to be sent to the past. Source: https://vanadreams.org/wiki/#mission-170', steps = { { title = 'Requirements', note = '• WotG enabled; active mission Cavernous Maws.' }, { title = 'Walkthrough', note = '• Examine a Cavernous Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign.\n• After the scene you arrive at a random Maw.' }, { title = 'Reward', note = '• Key item: pure white feather' } } },
    { name = 'Back to the Beginning', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 2: finish a first Crystal War quest, then revisit a Maw. Source: https://vanadreams.org/wiki/#mission-171', steps = { { title = 'Requirements', note = '• Cavernous Maws done; active mission Back to the Beginning.' }, { title = 'Walkthrough', note = '• Clear Fires of Discontent, Claws of the Griffon or The Tigress Strikes.\n• Examine a Cavernous Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign (present or [S]).\n• The scene completes the mission and registers that Maw.' }, { title = 'Reward', note = '• Key item: lightsworm' } } },
    { name = 'Cait Sith', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 3: cutscene on entering Southern San d\'Oria (S). Source: https://vanadreams.org/wiki/#mission-172', steps = { { title = 'Walkthrough', note = '• With Cait Sith active, zone from East Ronfaure (S) into Southern San d\'Oria (S) and view the cutscene.' }, { title = 'Notes', note = '• At the matching Rhapsodies of Vana\'diel point you also get the lightsworm.' }, { title = 'Reward', note = '• Title: Cait Siths Assistant' } } },
    { name = 'The Queen of the Dance', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 4: fetch a show ticket in Upper Jeuno and use it at Lion Springs. Source: https://vanadreams.org/wiki/#mission-173', steps = { { title = 'Requirements', note = '• Active WotG mission 4.\n• Finish Burden of Suspicion, Wrath of the Griffon or A Manifest Problem.' }, { title = 'Walkthrough', note = '• Examine the Lion Springs door, Southern San d\'Oria (S), for a scene.\n• Get the Mayakov show ticket from Turlough (G-7), Upper Jeuno.\n• Examine the Lion Springs door again for the scenes inside.\n• Rezone for further scenes until the mission ends.' }, { title = 'Notes', note = '• Without the ticket the door only reminds you.\n• The ticket is removed on completion.' } } },
    { name = 'While the Cat is Away', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 5: cutscene when leaving Southern San d\'Oria (S). Source: https://vanadreams.org/wiki/#mission-174', steps = { { title = 'Walkthrough', note = '• With the mission active, zone from Southern San d\'Oria (S) into East Ronfaure (S) and view the cutscene.' }, { title = 'Notes', note = '• Scene content depends on your completed Crystal War quests.' } } },
    { name = 'A Timeswept Butterfly', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 6: a scene on entering La Vaule [S]. Source: https://vanadreams.org/wiki/#mission-175', steps = { { title = 'Walkthrough', note = '• With the mission active, zone from Jugner Forest [S] into La Vaule [S] and view the scene.' } } },
    { name = 'Purple, The New Black', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 7: battle Galarhigg past the Reinforced Gateway in La Vaule [S]. Source: https://vanadreams.org/wiki/#mission-176', steps = { { title = 'Walkthrough', note = '• Examine the Reinforced Gateway, La Vaule [S], for a cutscene.\n• Examine it again to enter the Purple, the New Black battle.\n• Kill Galarhigg.\n• Rezone into La Vaule [S] for the final cutscene.' } } },
    { name = 'In the Name of the Father', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 8: a Lion Springs scene after the right Crystal War quest. Source: https://vanadreams.org/wiki/#mission-177', steps = { { title = 'Requirements', note = '• Active WotG mission 8.\n• Finish Fire in the Hole, In a Haze of Glory or A Feast for Gnats.' }, { title = 'Walkthrough', note = '• Examine the Lion Springs door, Southern San d\'Oria (S); the scene completes the mission.' } } },
    { name = 'Dancers in Distress', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 9: a quiz at the Elegant Footprints, then a requested item trade. Source: https://vanadreams.org/wiki/#mission-178', steps = { { title = 'Walkthrough', note = '• Speak with Raustigne (I-7), Southern San d\'Oria [S].\n• In Jugner Forest [S], examine the Elegant Footprints (I-6) and answer the quiz.\n• Zone, then check the footprints to learn the item: Lynx Meat, Gold Beastcoin or Nyumomo Doll.\n• Trade that item to the Elegant Footprints (I-6).' }, { title = 'Notes', note = '• The item is random; quiz answers don\'t affect it.\n• The trade only works after zoning.' } } },
    { name = 'Daughter of a Knight', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 10: plant a Cernunnos Bulb in the past, beat Cernunnos in the present and bring resin to Amaura. Source: https://vanadreams.org/wiki/#mission-179', steps = { { title = 'Requirements', note = '• Active mission Daughter of a Knight.\n• Cernunnos Bulb.' }, { title = 'Walkthrough', note = '• Speak with Amaura (G-6), Southern San d\'Oria, then trade her the Cernunnos Bulb.\n• At Maiden\'s Spring in Jugner Forest [S], trade the bulb to the Humus-rich Earth (E-6).\n• In present-day Jugner Forest, examine the Humus-rich Earth (E-6) for a cutscene.\n• Examine it again to spawn Cernunnos and kill it.\n• Examine it once more to get cernunnos resin.\n• Bring the resin to Amaura (G-6) for a cutscene.\n• After one Vana\'diel day and a zone, talk to Amaura for the treant tonic.' }, { title = 'Notes', note = '• Showing the bulb to Amaura keeps it; planting consumes it.\n• Too early at the end? Zone and retry.' }, { title = 'Reward', note = '• Key item: bottle of treant tonic' } } },
    { name = 'A Spoonful of Sugar', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 11: talk to Raustigne. Source: https://vanadreams.org/wiki/#mission-180', steps = { { title = 'Walkthrough', note = '• Speak with Raustigne (I-7), Southern San d\'Oria [S], and view the cutscene.' } } },
    { name = 'Affairs of State', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 12: visit contacts in Windurst Waters [S] and Bastok Markets [S], any order. Source: https://vanadreams.org/wiki/#mission-181', steps = { { title = 'Walkthrough', note = '• Speak with Velda-Galda (Windurst Waters [S]) or Radford (H-6, Bastok Markets [S]).\n• Then speak with the other one.' }, { title = 'Notes', note = '• Completion needs both; the first only gives reminders afterward.' }, { title = 'Reward', note = '• Key item: Count Borel\'s letter' } } },
    { name = 'Borne by the Wind', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 13: Bulwark Gate cutscene in Sauromugue Champaign [S]. Source: https://vanadreams.org/wiki/#mission-182', steps = { { title = 'Walkthrough', note = '• Examine the Bulwark Gate (E-6), Sauromugue Champaign [S], and view the cutscene.' }, { title = 'Notes', note = '• Radford (Bastok Markets [S]) and Velda-Galda (Windurst Waters [S]) give hints.' }, { title = 'Reward', note = '• Key item: underpass hatch key' } } },
    { name = 'A Nation on the Brink', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 14: the Everbloom Hollow battle via the Underpass Hatch in Batallia Downs [S]. Source: https://vanadreams.org/wiki/#mission-183', steps = { { title = 'Requirements', note = '• Previous WotG mission done; Campaign areas accessible.' }, { title = 'Walkthrough', note = '• Get the underpass hatch key at the Bulwark Gate (E-6), Sauromugue Champaign [S].\n• Check the Underpass Hatch (J-9) in Batallia Downs [S] (northeast towers) for a scene.\n• Check it again to enter Everbloom Hollow with your party.\n• Clear the waves and One-eyed Gwajboj.\n• Keep zoning into Batallia Downs [S] for follow-up scenes until done.' }, { title = 'Notes', note = '• All party members must qualify.\n• Full inventory: claim the Jeunoan Flag later from the ??? in Batallia Downs [S].' }, { title = 'Reward', note = '• Item: Jeunoan Flag\n• Title: Battle of Jeuno Veteran' } } },
    { name = 'Crossroads of Time', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 15: a scene in Southern San d\'Oria [S] after a Crystal War quest and a day\'s wait. Source: https://vanadreams.org/wiki/#mission-184', steps = { { title = 'Requirements', note = '• Finish Honor Under Fire, Bonds That Never Die or The Forbidden Path.\n• One Vana\'diel day after first arriving qualified.' }, { title = 'Walkthrough', note = '• Travel via East Ronfaure [S] to Southern San d\'Oria [S].\n• After the day passes, zone from East Ronfaure [S] into Southern San d\'Oria [S] for the cutscene.' }, { title = 'Notes', note = '• No scene on first arrival? Return after Vana\'diel midnight.' } } },
    { name = 'Sandswept Memories', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 16: examine Lion Springs. Source: https://vanadreams.org/wiki/#mission-185', steps = { { title = 'Walkthrough', note = '• Examine Lion Springs, Southern San d\'Oria (S), and view the cutscene.' }, { title = 'Notes', note = '• Unlocks Northland Exposure.' } } },
    { name = 'Northland Exposure', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 17: cutscene on entering Beaucedine Glacier (S). Source: https://vanadreams.org/wiki/#mission-186', steps = { { title = 'Walkthrough', note = '• Zone into Beaucedine Glacier (S) and view the cutscene.' }, { title = 'Notes', note = '• Unlocks Traitor in the Midst.' }, { title = 'Reward', note = '• Key item: shadow bug' } } },
    { name = 'Traitor in the Midst', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 18: follow the Regal Pawprints in Beaucedine Glacier [S]. Source: https://vanadreams.org/wiki/#mission-187', steps = { { title = 'Walkthrough', note = '• In Beaucedine Glacier [S], examine Regal Pawprints (3) to (7) and choose to follow each.\n• At (3), (4) and (5), wait 20+ seconds at the scene before finishing.\n• With all five done, examine Regal Pawprints (1) for the final cutscene.' }, { title = 'Notes', note = '• Any order; breaks between them are fine.' } } },
    { name = 'Betrayal at Beaucedine', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 19: fight Count Halphas at the Regal Pawprints in Beaucedine Glacier [S]. Source: https://vanadreams.org/wiki/#mission-188', steps = { { title = 'Walkthrough', note = '• Check the Regal Pawprints, Beaucedine Glacier [S], for a scene.\n• Check the Regal Pawprints (H-9) again to spawn Count Halphas; kill him.\n• Check (H-9) once more for a scene.\n• View the last scene after the area reloads.' } } },
    { name = 'On Thin Ice', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 20: talk to Raustigne. Source: https://vanadreams.org/wiki/#mission-189', steps = { { title = 'Walkthrough', note = '• Speak with Raustigne (I-7), Southern San d\'Oria (S), and view the cutscene.' }, { title = 'Notes', note = '• Unlocks Proof of Valor.' } } },
    { name = 'Proof of Valor', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 21: gather 20+ citizen signatures on the north-bound petition in Southern San d\'Oria [S] and hand it to Raustigne. Source: https://vanadreams.org/wiki/#mission-190', steps = { { title = 'Walkthrough', note = '• Speak with Raustigne (I-7) to start (20 signatures minimum).\n• One signature each: Aissaville (I-7), Andagge (H-9), Daigraffeaux (I-11), Elnonde (K-8), Illeuse, Loillie (K-9), Louxiard (G-7), Machionage (C-6), Mailleronce (M-6), Remiotte (L-10).\n• Quizzes (more right answers, more signatures): Aurfet (G-9), Corseihaut (F-6), Farouel (K-7), Vichauxdat (I-8).\n• Eumielle (I-8): trade Angler\'s Cassoulet for 12 signatures.\n• Sabiliont (I-11): trade Gysahl Greens; Hauberliond (H-9): trade Crossbow Bolts x99 stacks.\n• Coucheutand (I-8): trade Orcish Axe, Orc Helmet, Orc Pauldron or Gold Orcmask.\n• Rongelouts N Distaud (I-9): trade a Gnole Claw.\n• At 20+, submit the petition to Raustigne (I-7).' }, { title = 'Notes', note = '• One signature per citizen.\n• Talk to Eumielle, Hauberliond, Sabiliont and Coucheutand before trading.\n• More signatures improve the reward: Square of Foulard, Oxblood Orb, Angel Skin Orb, Orichalcum Ingot or Molybdenum Ingot.\n• Raustigne reminds you once per zone.' } } },
    { name = 'A Sanguinary Prelude', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 22: cutscene on entering Beaucedine Glacier [S]. Source: https://vanadreams.org/wiki/#mission-191', steps = { { title = 'Walkthrough', note = '• Zone into Beaucedine Glacier [S] and view the cutscene.' }, { title = 'Reward', note = '• Key item: aroma bug' } } },
    { name = 'Dungeons and Dancers', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 23: an Everbloom Hollow instance against two Goblin Reavers, entered from Beaucedine Glacier (S). Source: https://vanadreams.org/wiki/#mission-192', steps = { { title = 'Requirements', note = '• Active WotG mission 23.\n• Up to 6 players; 30-minute limit.' }, { title = 'Walkthrough', note = '• Examine the Regal Pawprints (G-9), Beaucedine Glacier (S), for a scene.\n• Examine the Regal Pawprints (H-10) for an aroma bug (resets at Vana\'diel midnight).\n• With the bug, examine (G-9) again to enter Everbloom Hollow.\n• Get past the Giddy Bombs and kill both Goblin Reavers.\n• Rezone into Beaucedine Glacier (S) for the final scene.' }, { title = 'Notes', note = '• Entry consumes the aroma bug; after a loss, wait for the next Vana\'diel day.' }, { title = 'Reward', note = '• Key item: umbra bug' } } },
    { name = 'Distorter of Time', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 24: use the umbra bug to reach a Ruhotz Silvermines instance and defeat Ceithir. Source: https://vanadreams.org/wiki/#mission-193', steps = { { title = 'Walkthrough', note = '• Examine the first Regal Pawprints, Beaucedine Glacier (S), for the umbra bug.\n• Examine the second Regal Pawprints to enter Ruhotz Silvermines.\n• Kill Ceithir with Lilisette; Atomos shows up at intervals to hinder you.\n• Back in Beaucedine Glacier (S), view the cutscene.' }, { title = 'Notes', note = '• After a loss, wait for the next Vana\'diel day to get the bug again.\n• Unlocks The Will of the World.' } } },
    { name = 'The Will of the World', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 25: report to Raustigne. Source: https://vanadreams.org/wiki/#mission-194', steps = { { title = 'Walkthrough', note = '• Speak with Raustigne (I-7), Southern San d\'Oria [S], and view the scene.' } } },
    { name = 'Fate in Haze', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 26: three cutscenes in Southern San d\'Oria (S), beginning at Lion Springs. Source: https://vanadreams.org/wiki/#mission-195', steps = { { title = 'Requirements', note = '• Finish What Price Loyalty, Blood of Heroes or Howl from the Heavens.' }, { title = 'Walkthrough', note = '• Talk to Lion Springs, Southern San d\'Oria (S), for a cutscene.\n• Zone out and back for the next one.\n• Zone again for the final cutscene.' }, { title = 'Notes', note = '• Rholont has extra lines for San d\'Orian allegiance.' } } },
    { name = 'The Scent of Battle', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 27: Bulwark Gate scene. Source: https://vanadreams.org/wiki/#mission-196', steps = { { title = 'Walkthrough', note = '• Examine the Bulwark Gate (E-6), Sauromugue Champaign [S], and view the cutscene.' } } },
    { name = 'Another World', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 28: return to present-day San d\'Oria and see Halver. Source: https://vanadreams.org/wiki/#mission-197', steps = { { title = 'Walkthrough', note = '• Zone from East Ronfaure into Southern San d\'Oria for a scene.\n• Speak with Halver (I-9), Chateau d\'Oraguille.' } } },
    { name = 'A Hawk in Repose', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 29: leave a Lilac at a gravestone in Batallia Downs. Source: https://vanadreams.org/wiki/#mission-198', steps = { { title = 'Requirements', note = '• A Lilac.' }, { title = 'Walkthrough', note = '• Examine the Weathered Gravestone (I-10), Batallia Downs, for a cutscene.\n• Trade it the Lilac for the final cutscene.' } } },
    { name = 'The Battle of Xarcabard', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 30: two cutscenes in Xarcabard [S]. Source: https://vanadreams.org/wiki/#mission-199', steps = { { title = 'Walkthrough', note = '• Zone into Xarcabard [S] for a cutscene.\n• Examine Rally Point Red for the second cutscene.' }, { title = 'Notes', note = '• Rally Point Red is inactive until the arrival scene is seen.' } } },
    { name = 'Prelude to a Storm', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 31: get a magelight signal flare in Xarcabard [S] and clear a Ghoyu\'s Reverie fight. Source: https://vanadreams.org/wiki/#mission-200', steps = { { title = 'Walkthrough', note = '• Talk to Rally Point: Green (G-9), Xarcabard [S], for the magelight signal flare.\n• Examine the Spell-worked Snow behind it to enter Ghoyu\'s Reverie.\n• Defeat the enemies.\n• Back in Xarcabard [S], view the scene for your reward.' }, { title = 'Notes', note = '• Clear speed sets the reward: Elixir, Vile Elixir or Vile Elixir +1.\n• All party members need enough mission progress.\n• Lost flare: ask Rally Point: Green again.' } } },
    { name = 'Storm\'s Crescendo', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 32: use the alchemical signal flare to win the Excavated Snow instance. Source: https://vanadreams.org/wiki/#mission-201', steps = { { title = 'Walkthrough', note = '• Talk to Rally Point: Blue (H-8), Xarcabard [S], for a cutscene and the Alchemical Signal Flare.\n• Examine Excavated Snow (H-8) to enter Ghoyu\'s Reverie; win.\n• After the return cutscene, talk to Rally Point: Red (F-8).\n• Rezone into Xarcabard [S] for the final cutscene.' }, { title = 'Notes', note = '• Lost flare: ask Rally Point: Blue after a Vana\'diel day.' } } },
    { name = 'Into the Beast\'s Maw', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 33: enter Castle Zvahl Baileys (S), use the distress signal flare and beat Count Bifrons in Ghoyu\'s Reverie. Source: https://vanadreams.org/wiki/#mission-202', steps = { { title = 'Walkthrough', note = '• Zone into Castle Zvahl Baileys (S) for a cutscene (forces gather at Rally Point: Red (F-8), Xarcabard (S)).\n• Examine the Peculiar Glint (Map 1, G-7) for another cutscene.\n• Rezone for two more cutscenes and the distress signal flare.\n• Examine the Peculiar Glint (Map 1, G-7) to enter Ghoyu\'s Reverie; kill Count Bifrons (Map 13, I-7) and allies.\n• Rezone into Castle Zvahl Baileys (S) for the final cutscene.' }, { title = 'Notes', note = '• After a loss or lost flare, examine the Ornate Block in Castle Zvahl Baileys (S) after the next Vana\'diel day.\n• Whole party needs enough progress.' } } },
    { name = 'The Hunter Ensnared', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 34: Rally Point: Red scene. Source: https://vanadreams.org/wiki/#mission-203', steps = { { title = 'Walkthrough', note = '• Examine Rally Point: Red (F-8), Xarcabard [S], and view the scene.' } } },
    { name = 'Flight of the Lion', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 35: Bulwark Gate scene. Source: https://vanadreams.org/wiki/#mission-204', steps = { { title = 'Walkthrough', note = '• Examine the Bulwark Gate (E-6), Sauromugue Champaign (S), and view the scene.' } } },
    { name = 'Fall of the Hawk', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 36: arrival cutscene in Castle Zvahl Baileys [S]. Source: https://vanadreams.org/wiki/#mission-205', steps = { { title = 'Walkthrough', note = '• Zone into Castle Zvahl Baileys [S] and view the cutscene.' } } },
    { name = 'Darkness Descends', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 37: win the Darkness Descends battle in the Throne Room (S). Source: https://vanadreams.org/wiki/#mission-206', steps = { { title = 'Walkthrough', note = '• Enter the Throne Room (S) for a cutscene.\n• Enter the Darkness Descends battle and win.\n• Rezone if needed for the closing cutscene.' } } },
    { name = 'Adieu, Lilisette', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 38: farewell scene at Lion Springs. Source: https://vanadreams.org/wiki/#mission-207', steps = { { title = 'Requirements', note = '• Finish Bonds of Mythril, Face of the Future or At Journey\'s End.' }, { title = 'Walkthrough', note = '• Talk to Lion Springs, Southern San d\'Oria [S], and view the cutscene.' }, { title = 'Notes', note = '• Scene depends on Campaign allegiance; Rholont has extra lines for San d\'Oria.' } } },
    { name = 'By the Fading Light', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 39: Rally Point Red cutscene in Xarcabard [S]. Source: https://vanadreams.org/wiki/#mission-208', steps = { { title = 'Walkthrough', note = '• Examine Rally Point Red, Xarcabard [S], and view the cutscene.' } } },
    { name = 'Edge of Existence', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 40: touch any Cavernous Maw for a cutscene. Source: https://vanadreams.org/wiki/#mission-209', steps = { { title = 'Walkthrough', note = '• Examine a Cavernous Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign (present or past) and view the cutscene.\n• You end up at the Maw afterward.' } } },
    { name = 'Her Memories', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 41: collect four Large Memory Fragments through the Her Memories quests. Source: https://vanadreams.org/wiki/#mission-210', steps = { { title = 'Walkthrough', note = '• Do the Her Memories quests (Azure Footfalls, Carnelian Footfalls, Homecoming Queen, Of Malign Maladies, Operation Cupid) until you have four Large Memory Fragments.\n• Report to Cait Sith after the fourth.' }, { title = 'Notes', note = '• The mission has no tasks of its own.' } } },
    { name = 'Forget Me Not', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 42: a Maw trip to Grauberg [S] for a scene. Source: https://vanadreams.org/wiki/#mission-211', steps = { { title = 'Walkthrough', note = '• Examine a Cavernous Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign (present or [S]).\n• View the scene in Grauberg [S]; you return to your starting Maw zone.\n• Zone into that area again to finish.' }, { title = 'Notes', note = '• Memory fragments are taken on completion.' } } },
    { name = 'Pillar of Hope', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 43: use the Veridical Conflux in Grauberg [S]. Source: https://vanadreams.org/wiki/#mission-212', steps = { { title = 'Walkthrough', note = '• In Grauberg [S], remove main and sub weapons.\n• Examine the Veridical Conflux (F-5), view the scene and accept to proceed.' }, { title = 'Notes', note = '• Declining lets you retry later.\n• Glimmer of Life needs the next Vana\'diel day plus a zone.' } } },
    { name = 'Glimmer of Life', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 44: Veridical Conflux cutscene in Grauberg [S]. Source: https://vanadreams.org/wiki/#mission-213', steps = { { title = 'Requirements', note = '• Zoned once and a new Vana\'diel day since the last mission.' }, { title = 'Walkthrough', note = '• Examine the Veridical Conflux (F-5), Grauberg [S], and view the cutscene.' }, { title = 'Notes', note = '• No response? Zone or wait a Vana\'diel day and retry.' } } },
    { name = 'Time Slips Away', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 45: trade a Punch Bug to the Veridical Conflux. Source: https://vanadreams.org/wiki/#mission-214', steps = { { title = 'Requirements', note = '• A Punch Bug.' }, { title = 'Walkthrough', note = '• Trade the Punch Bug to the Veridical Conflux (F-5), Grauberg (S).\n• View the cutscene.' }, { title = 'Notes', note = '• Without the bug, the conflux only reminds you.\n• Next mission: When Wills Collide.' }, { title = 'Reward', note = '• Key item: bottled punch bug' } } },
    { name = 'When Wills Collide', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 46: carry a bottled punch bug to the Walk of Echoes and win the battle. Source: https://vanadreams.org/wiki/#mission-215', steps = { { title = 'Walkthrough', note = '• Trade a Punch Bug to the Veridical Conflux (F-5), Grauberg [S], for a bottled punch bug.\n• Examine the conflux again and choose the Walk of Echoes.\n• Examine the Ornate Door (Map 17, H-7) for a scene.\n• Examine it again to enter (up to 6 players, 30 minutes); kill Ragelise, Portia, Larzos and the Fourth Spitewarden.\n• View the scene on return.' }, { title = 'Notes', note = '• Entry consumes the bottled punch bug.\n• All four foes resist sleep.\n• The conflux still links to the Walk of Echoes afterward.' } } },
    { name = 'Whispers of Dawn', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 47: Veridical Conflux scene. Source: https://vanadreams.org/wiki/#mission-216', steps = { { title = 'Walkthrough', note = '• Examine the Veridical Conflux (F-5), Grauberg [S], view the scene and accept to proceed.' }, { title = 'Notes', note = '• Next mission needs a zone and one Vana\'diel day.' } } },
    { name = 'A Dreamy Interlude', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 48: Veridical Conflux cutscene. Source: https://vanadreams.org/wiki/#mission-217', steps = { { title = 'Requirements', note = '• A Vana\'diel day since the previous mission.' }, { title = 'Walkthrough', note = '• Examine the Veridical Conflux (F-5), Grauberg [S], and view the cutscene.' }, { title = 'Notes', note = '• Too early: zone, wait for the next Vana\'diel day, retry.' } } },
    { name = 'Cait in the Woods', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 49: meet Cait Sith in East Ronfaure [S]. Source: https://vanadreams.org/wiki/#mission-218', steps = { { title = 'Walkthrough', note = '• In East Ronfaure [S], talk to the blank Cait Sith and view the cutscene.' }, { title = 'Reward', note = '• Key item: Ronfaure dawndrop' } } },
    { name = 'Fork in the Road', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 50: gather seven dawndrops from ??? markers, which combine into the Primal Glow. Source: https://vanadreams.org/wiki/#mission-219', steps = { { title = 'Requirements', note = '• Active mission: Fork in the Road.\n• Ronfaure dawndrop already held from the prior mission.' }, { title = 'Walkthrough', note = '• Check the ??? in Jugner Forest [S], La Vaule [S], Southern San d\'Oria [S], Beaucedine Glacier [S], Xarcabard [S] and Throne Room [S] for each zone\'s dawndrop.\n• Finish at the ??? in the Walk of Echoes for the last dawndrop.\n• Any order works; all dawndrops become the Primal Glow.' }, { title = 'Reward', note = '• Key item: primal glow' } } },
    { name = 'Maiden of the Dusk', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 51: beat the Maiden of the Dusk battlefield in the Walk of Echoes. Source: https://vanadreams.org/wiki/#mission-220', steps = { { title = 'Walkthrough', note = '• At the Veridical Conflux in Grauberg [S], accept transport to the Walk of Echoes; view the arrival scene.\n• Check the Ornate Door (Map 17, H-7) for a scene.\n• Go back to the Veridical Conflux (F-5) in Grauberg [S] for the Primal Glow.\n• Use the Primal Glow at the Ornate Door (Map 17, H-7) and win the fight.\n• Keep zoning into the Walk of Echoes, one scene per entry, until the mission ends.' }, { title = 'Notes', note = '• Entry consumes the Primal Glow.\n• Lost it? The Veridical Conflux replaces it after one Vana\'diel day.' }, { title = 'Reward', note = '• Key item: moonshade earring' } } },
    { name = 'Where It All Began', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 52: Lion Springs gives you a wedding invitation. Source: https://vanadreams.org/wiki/#mission-221', steps = { { title = 'Walkthrough', note = '• Speak with Lion Springs in Southern San d\'Oria (S) and view the scene.' }, { title = 'Reward', note = '• Key item: wedding invitation' } } },
    { name = 'Token of Troth', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 53: bring the Wedding Invitation to the Bulwark Gate in Sauromugue Champaign [S] with no weapons on. Source: https://vanadreams.org/wiki/#mission-222', steps = { { title = 'Requirements', note = '• Active mission: A Token of Troth.\n• Key item: Wedding Invitation.' }, { title = 'Walkthrough', note = '• Remove main and sub weapons; the gate refuses armed players.\n• Click the Bulwark Gate (E-6) in Sauromugue Champaign [S] for a scene.\n• Click it a second time to finish.' } } },
    { name = 'Lest We Forget', group = 'Mission: Wings of the Goddess', desc = 'WotG mission 54: pick Moonshade Earring augments at Grauberg [S]\'s Veridical Conflux, or rewind the story. Source: https://vanadreams.org/wiki/#mission-223', steps = { { title = 'Walkthrough', note = '• Check the Veridical Conflux (F-5) in Grauberg [S]; keep one inventory slot free.\n• First pick (one): Accuracy+4, Attack+4, Ranged Accuracy+4, Ranged Attack+4, Magic Accuracy+4, Magic Atk. Bonus+4, HP+25 or MP+25.\n• Second pick (one): Regain+10, Refresh+1, Occasionally grants a damage bonus based on TP+5%, TP Bonus+250, Occasionally maximizes magic accuracy+3%, Occasionally quickens spellcasting+3%, Counter+3 or Occasionally increases resistance to all status ailments+5.\n• Receive the augmented Moonshade Earring.' }, { title = 'Notes', note = '• Without a Moonshade Earring, the ??? (F-5) in Grauberg [S] rewinds you to Maiden of the Dusk and grants the primal glow.' } } },
    { name = 'A Crystalline Prophecy', group = 'Mission: A Crystalline Prophecy', desc = 'First ACP mission: an automatic scene in Lower Jeuno opens the Ark Angels story. Source: https://vanadreams.org/wiki/#mission-224', steps = { { title = 'Walkthrough', note = '• Requires level 10+ and the mission active.\n• Zone into Lower Jeuno to see the scene.\n• Cast in the scene varies with your Rise of the Zilart and Windurst mission progress.' } } },
    { name = 'The Echo Awakens', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission: hand three Seedspalls to a ??? on Qufim Island. Source: https://vanadreams.org/wiki/#mission-225', steps = { { title = 'Walkthrough', note = '• Find the ??? (G-6) on Qufim Island.\n• Trade only Seedspall Lux, Seedspall Luna and Seedspall Astrum (one each); they are consumed.\n• The scene that follows ends the mission.' } } },
    { name = 'Gatherer of Light (I)', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission: take three Seedspalls from mandragora NMs, then check the ??? on Qufim Island. Source: https://vanadreams.org/wiki/#mission-226', steps = { { title = 'Walkthrough', note = '• Kill Vegnix Greenthumb (F-5), Batallia Downs: Seedspall Roseum.\n• Kill Chuglix Berrypaws (E-10), Rolanberry Fields: Seedspall Caerulum.\n• Kill Dribblix Greasemaw (J-9), Sauromugue Champaign: Seedspall Viridis.\n• Holding all three, check the ??? (G-6) on Qufim Island.' }, { title = 'Notes', note = '• The Seedspalls stay with you until the next mission\'s Seed Mandragora battle starts.' } } },
    { name = 'Gatherer of Light (II)', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission: spend the three Seedspalls to fight the Seed Mandragora on Qufim Island, then view the ending scene. Source: https://vanadreams.org/wiki/#mission-227', steps = { { title = 'Walkthrough', note = '• With Seedspall Roseum, Caerulum and Viridis, check the ??? (G-6) on Qufim Island; this starts the fight and uses them up.\n• Kill all 30 Seed Mandragora to earn the Amber Key.\n• Check the ??? (G-6) again for the final scene.' }, { title = 'Notes', note = '• Nearby party members join, but only holders of all three Seedspalls get credit.\n• A loss means re-collecting the Seedspalls.\n• Repeatable once per Japanese day for an Amber Key if you lack one.' } } },
    { name = 'Those Who Lurk in Shadows (I)', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission 5: entering Fei\'Yin plays a scene that finishes the mission. Source: https://vanadreams.org/wiki/#mission-228', steps = { { title = 'Walkthrough', note = '• Zone into Fei\'Yin and view the scene; nothing else is needed.' } } },
    { name = 'Those Who Lurk in Shadows (II)', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission: earn the Mark of Seed in Fei\'Yin, then check the Burning Circle in Qu\'Bia Arena. Source: https://vanadreams.org/wiki/#mission-229', steps = { { title = 'Walkthrough', note = '• In Fei\'Yin, touch all nine Seed Afterglows inside 30 minutes for the Mark of Seed; re-enter to retry if time expires.\n• Go to Qu\'Bia Arena and check the Burning Circle for the scene.' } } },
    { name = 'Those Who Lurk in Shadows (III)', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission: win the Qu\'Bia Arena battlefield for an Ivory Key. Source: https://vanadreams.org/wiki/#mission-230', steps = { { title = 'Walkthrough', note = '• Enter the battlefield in Qu\'Bia Arena using the Mark of Seed.\n• Kill the enemies, then leave after the victory scene to get the Ivory Key.' }, { title = 'Notes', note = '• Repeat wins give an Ivory Key once per Japanese day if you have none.' } } },
    { name = 'Remember Me in Your Dreams', group = 'Mission: A Crystalline Prophecy', desc = 'Short mission: go from Ro\'Maeve into the Hall of the Gods to see a scene. Source: https://vanadreams.org/wiki/#mission-231', steps = { { title = 'Walkthrough', note = '• Travel to Ro\'Maeve, then zone into the Hall of the Gods; the scene ends the mission.\n• Unlocks Born of Her Nightmares.' } } },
    { name = 'Born of Her Nightmares', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission 9: a scene plays when you zone into Lower Delkfutt\'s Tower from Qufim Island. Source: https://vanadreams.org/wiki/#mission-232', steps = { { title = 'Walkthrough', note = '• Go to Qufim Island and enter Lower Delkfutt\'s Tower from there; entering from inside the tower does not work.\n• View the scene.' } } },
    { name = 'Banishing the Echo', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission: collect twelve stones from Seed Afterglows in Delkfutt\'s Tower and merge them into the Omnis Stone at the Stellar Fulcrum. Source: https://vanadreams.org/wiki/#mission-233', steps = { { title = 'Walkthrough', note = '• Lower Delkfutt\'s Tower: touch the Seed Fragment (Map 1, H-10) by the entrance for a level 30 cap, then touch the Seed Afterglows on floors 1-3 (stones Amicitia, Veritas, Sapientia).\n• Middle Delkfutt\'s Tower: Seed Fragment (Map 1, G-6), then Afterglows on floors 4-9.\n• Upper Delkfutt\'s Tower: Seed Fragment (Map 1, F-7), then Afterglows on floors 10-12.\n• At the Stellar Fulcrum, touch the Seed Fragment (A-8) with all twelve stones to get the Omnis Stone.' }, { title = 'Notes', note = '• Mission stays open until you hold the Omnis Stone.\n• Touching a Seed Fragment again, or changing tower section, removes the cap; re-cap at that section\'s Fragment.\n• Afterglows give nothing unless capped and the stone is not already held.\n• Applying the cap dismisses Trusts.' } } },
    { name = 'Ode of Life Bestowing', group = 'Mission: A Crystalline Prophecy', desc = 'ACP mission 11: use the Omnis Stone at the Qe\'Iov Gate in the Stellar Fulcrum and win the battlefield. Source: https://vanadreams.org/wiki/#mission-234', steps = { { title = 'Walkthrough', note = '• Check the Qe\'Iov Gate (B-8) in the Stellar Fulcrum with the Omnis Stone for a scene.\n• Check it again to enter; the stone is consumed.\n• Win, then view the scene to finish.' }, { title = 'Notes', note = '• Repeat wins: an Ebon Key once per Japanese day, plus a Prismatic Key if you hold none.' }, { title = 'Reward', note = '• Title: Silencer of the Echo' } } },
    { name = 'A Crystalline Prophecy Fin', group = 'Mission: A Crystalline Prophecy', desc = 'End marker for ACP after all earlier missions; no tasks remain. Source: https://vanadreams.org/wiki/#mission-235', steps = { { title = 'Notes', note = '• Open the Tenshodo Treasure Coffer in Lower Jeuno with the Prismatic Key for the final reward.\n• Squintrox Dryeyes sells replacement keys.' } } },
    { name = 'A Crystalline Prophecy Helpers', group = 'Mission: A Crystalline Prophecy', desc = 'Not a real mission entry; nothing listed yet. Source: https://vanadreams.org/wiki/#mission-236', steps = {  } },
    { name = 'A Moogle Kupo d\'Etat', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'First MKD mission: speak to your Moogle at home to start the story. Source: https://vanadreams.org/wiki/#mission-237', steps = { { title = 'Walkthrough', note = '• Requires level 10+ and the Mog House exposition event already seen.\n• In your home nation\'s Mog House, talk to the Moogle and view the scene.\n• Next: Drenched! It Began with a Raindrop.' } } },
    { name = 'Drenched! It Began with a Raindrop', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: give your Moogle three beastman materials. Source: https://vanadreams.org/wiki/#mission-238', steps = { { title = 'Walkthrough', note = '• Get one each: Orc. Armor Plate, Quadav Backscale, Yagudo Caulk.\n• In your home nation\'s Mog House, trade all three to the Moogle (consumed).' }, { title = 'Reward', note = '• Key item: white coral key' } } },
    { name = 'Hasten! In a Jam in Jeuno?', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: a scene at the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-239', steps = { { title = 'Walkthrough', note = '• Check the Inconspicuous Door (H-8) in Upper Jeuno and view the scene.' } } },
    { name = 'Welcome! To My Decrepit Domicile', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: gather three items and deliver each to the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-240', steps = { { title = 'Walkthrough', note = '• Mine at Mining Points (outlying or nation areas) for a sturdy metal strip; deliver it to the Inconspicuous Door (H-8).\n• Log at a Logging Point for rugged tree bark; deliver it.\n• Harvest at a Harvesting Point for a savory lamb roast; deliver it.' }, { title = 'Notes', note = '• Each item drops roughly 5% per gathering attempt.\n• Visiting the door empty-handed only gives a reminder.' }, { title = 'Reward', note = '• Key item: blue coral key' } } },
    { name = 'Curses! A Horrifically Harrowing Hex', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission 5: Shantotto explains the moogle\'s curse. Source: https://vanadreams.org/wiki/#mission-241', steps = { { title = 'Walkthrough', note = '• Speak with Shantotto (K-7) in Windurst Walls and view the scene.' } } },
    { name = 'An Errand! The Professor\'s Price', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission 6: win a ripe starfruit from Cardians in Outer Horutoto Ruins and pay Shantotto to break the curse. Source: https://vanadreams.org/wiki/#mission-242', steps = { { title = 'Requirements', note = '• At least one of Orb of Swords, Orb of Cups, Orb of Batons, Orb of Coins.\n• 5,000 gil.' }, { title = 'Walkthrough', note = '• Talk to Shantotto (K-7), Windurst Walls.\n• Enter Outer Horutoto Ruins via the Lilac Tower (H-3) in East Sarutabaruta; head downstairs to the ??? at Map 2 (H-6).\n• Choose to fight and defeat the Cardians; receive a ripe starfruit and a peach coral key.\n• Return to Shantotto and pay 5,000 gil; talk again to see the curse lifted.\n• Check the Inconspicuous Door (H-8) in Upper Jeuno to finish.' }, { title = 'Notes', note = '• Cardian count: 15 with one or two orbs, 10 with three, 5 with four.\n• Held orbs are consumed at the start; missing orbs leave the Cardians immune to that damage type.\n• Stay near the ??? or the fight is lost.\n• Declined to pay? Zone and talk to Shantotto again.' } } },
    { name = 'Shock! Arrant Abuse of Authority', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: chocobo-dig a chest in an assigned area and return it to the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-243', steps = { { title = 'Walkthrough', note = '• Check the Inconspicuous Door (H-8) in Upper Jeuno to learn your dig area (check again if forgotten).\n• Dig there with a chocobo until you get the moldy, worm-eaten chest.\n• Check the door again to finish; the chest is removed.' }, { title = 'Reward', note = '• Key item: black coral key' } } },
    { name = 'Lender Beware! Read the Fine Print', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: check two spots in Sea Serpent Grotto, then report to the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-244', steps = { { title = 'Walkthrough', note = '• In Sea Serpent Grotto, check the Shady Sconce and choose to proceed (required).\n• Check the Waterfall Basin.\n• Return to the Inconspicuous Door (H-8) in Upper Jeuno.' } } },
    { name = 'Rescue! A Moogle\'s Labor of Love', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission 9: find nine stones in Quicksand Caves for the Goblin Geologist, then use the talisman in the Chamber of Oracles. Source: https://vanadreams.org/wiki/#mission-245', steps = { { title = 'Walkthrough', note = '• Talk to the Goblin Geologist (Map 5, J-11) in Quicksand Caves; he marks spots on your map.\n• Check the marked ??? for stones: Surya, Chandra, Mangala, Budha, Brihaspati, Shukra, Shani, Rahu, Ketu.\n• Bring all nine back for the Navaratna talisman.\n• Check the Shimmering Circle in the Chamber of Oracles.' }, { title = 'Notes', note = '• Marked spots are random per player and fixed until you turn in; unmarked ??? give nothing.\n• Owning the Quicksand Caves map helps read the markers.' } } },
    { name = 'Roar! A Cat Burglar Bares Her Fangs', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: pursue the cat burglar in Sea Serpent Grotto, then report to the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-246', steps = { { title = 'Walkthrough', note = '• In Sea Serpent Grotto, check the Shady Sconce and accept.\n• Check the Waterfall Basin for the next scene (rechecking the Sconce only repeats a short scene).\n• Check the Inconspicuous Door (H-8) in Upper Jeuno.' }, { title = 'Reward', note = '• Key item: red coral key' } } },
    { name = 'Relief! A Triumphant Return', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'Short MKD mission at the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-247', steps = { { title = 'Walkthrough', note = '• Check the Inconspicuous Door (H-8) in Upper Jeuno and view the scene.' } } },
    { name = 'Joy! Summoned to a Fabulous Fete', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'Short MKD mission: a scene on entering Castle Zvahl Baileys. Source: https://vanadreams.org/wiki/#mission-248', steps = { { title = 'Walkthrough', note = '• Zone into Castle Zvahl Baileys.' } } },
    { name = 'A Challenge! You Could Be a Winner', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission 13: four moogle puzzles across the Northlands, ending in the Throne Room. Source: https://vanadreams.org/wiki/#mission-249', steps = { { title = 'Walkthrough', note = '• Enter Castle Zvahl Baileys from Xarcabard (D-7); check the Shadowy Pillar (Map 1, J-8).\n• Beaucedine Glacier: talk to the Lonely Evergreen (G-7), zone once, find the Goblin Grenadier (H-8), take the Northlands map and check the six Pips for the hidden one.\n• Swap the pocket mogbomb at the Lonely Evergreen for a Trivia Challenge Kupon.\n• Xarcabard: solve the trivia via Option One (H-8), Option Two (G-9) and Option Three for a Gauntlet Challenge Kupon.\n• Back at the Shadowy Pillar, start the timed run and reach the Flame of Fate for a Festival Souvenir Kupon.\n• Castle Zvahl Keep: read the Ominous Pillar (Map 1, H-8), then check the four Craggy Pillars for the right moogle; get the Mega Bonanza Kupon.\n• Check the Throne Room door (G-8) for the final scene.' }, { title = 'Notes', note = '• Goblin Grenadier offers up to two hints; fewer hints gives a longer Flee bonus.\n• Baileys run is about 8 minutes with Invisible, Sneak, Deodorize and a level restriction; the Shadowy Pillar refreshes the buffs.\n• A wrong Beaucedine answer resets that puzzle.' } } },
    { name = 'Smash! A Malevolent Menace', group = 'Mission: A Moogle Kupo d\'Etat', desc = 'MKD mission: a scene at the Inconspicuous Door in Upper Jeuno. Source: https://vanadreams.org/wiki/#mission-250', steps = { { title = 'Walkthrough', note = '• Check the Inconspicuous Door (H-8) in Upper Jeuno and view the scene.' } } },
    { name = 'A Shantotto Ascension', group = 'Mission: A Shantotto Ascension', desc = 'First ASA mission: a scene when you zone into Windurst Walls. Source: https://vanadreams.org/wiki/#mission-252', steps = { { title = 'Walkthrough', note = '• Requires level 10+ with ASA enabled and active.\n• Zone into Windurst Walls from Windurst Waters or Windurst Woods and view the scenes.' } } },
    { name = 'A Shantotto Ascension', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission Burgeoning Dread: leave Windurst on foot to trigger a scene. Source: https://vanadreams.org/wiki/#mission-253', steps = { { title = 'Walkthrough', note = '• Walk (no chocobo) into West Sarutabaruta from Windurst Waters or Port Windurst, or into East Sarutabaruta from Windurst Woods.\n• The scene on entry ends the mission; it differs a little by exit.' } } },
    { name = 'A Shantotto Ascension', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission 3 (That Which Curdles Blood): visit three nation contacts, then give your enfeebling kit to Trodden Snow on Qufim Island. Source: https://vanadreams.org/wiki/#mission-254', steps = { { title = 'Requirements', note = '• Your chosen Enfeeb. Kit (Poison, Blind, Sleep or Silence).' }, { title = 'Walkthrough', note = '• Talk to Kuroido-Moido (Port Windurst), Faulpie (E-8, Southern San d\'Oria) and Abd-al-Raziq (L-7, Bastok Mines); each explains your kit\'s needs.\n• Trade the Enfeeb. Kit to Trodden Snow (H-7) on Qufim Island.' }, { title = 'Reward', note = '• Key items: Moogle key, Domina\'s scarlet seal, Domina\'s cerulean seal, Domina\'s emerald seal, Domina\'s amber seal, Domina\'s violet seal, Domina\'s azure seal' } } },
    { name = 'A Shantotto Ascension', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission 4 (Sugar-Coated Directive): win Cloister battles to turn Domina\'s seals into counterseals, then see Trodden Snow on Qufim Island. Source: https://vanadreams.org/wiki/#mission-255', steps = { { title = 'Walkthrough', note = '• Enter a Cloister with its matching seal and check the entrance.\n• Win the Sugar-Coated Directive fight, then check the entrance again for the counterseal.\n• Get at least three counterseals (up to six).\n• Talk to Trodden Snow (H-7) on Qufim Island.' }, { title = 'Notes', note = '• Seal to Cloister: scarlet-Flames, azure-Frost, emerald-Gales, violet-Storms, cerulean-Tides, amber-Tremors.\n• Gil: 3 counterseals 3,000; 4 = 10,000; 5 = 30,000; 6 = 50,000.\n• Reporting takes all seals and counterseals, so finish first.\n• Cloisters still accept leftover seals after the mission.' }, { title = 'Reward', note = '• Key item: Bird key' } } },
    { name = 'A Shantotto Ascension', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission 5 (Enemy of the Empire (I)): capture souls of three assigned monster types for Andrause in Norg to earn the Black Book. Source: https://vanadreams.org/wiki/#mission-256', steps = { { title = 'Walkthrough', note = '• Talk to Andrause (I-8) in Norg for three random targets (sahagin, pugils, crabs, bats, leeches and similar); he repeats them on request.\n• If needed, buy a Soultrapper plus 12 Blank Soul Plates from him for 800 gil (once per Vana\'diel day).\n• Record a soul plate of each target.\n• Trade the plates to Andrause one at a time; the third completes the mission.' }, { title = 'Notes', note = '• Plates from non-assigned monsters are rejected.\n• Already holding the Black Book means nothing more from him.' }, { title = 'Reward', note = '• Key item: black book' } } },
    { name = 'Enemy Of The Empire II', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: beat three ninjas at the Outcropping in Gustav Tunnel. Source: https://vanadreams.org/wiki/#mission-257', steps = { { title = 'Walkthrough', note = '• Enter Gustav Tunnel from Cape Teriggan (J-5); check the Outcropping (Map 1, F-10) with the black book.\n• Check again to fight Renfred, Gorattz and Bompupu plus copies.\n• Originals are untargetable until enough copies die or a few minutes pass; kill all three.\n• Check the Outcropping once more to finish.' }, { title = 'Notes', note = '• 30-minute limit; stay near the Outcropping.\n• Black book is removed only on completion.\n• Trusts are dismissed at the start.' } } },
    { name = 'Sugar-Coated Subterfuge', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: a scene with Aldo at the Tenshodo. Source: https://vanadreams.org/wiki/#mission-258', steps = { { title = 'Walkthrough', note = '• Talk to Aldo (J-8) at the Tenshodo in Lower Jeuno and view the scene.' } } },
    { name = 'Shantotto In Chains', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: unseal the Ensorcelled Door in Ro\'Maeve with six luminous fragments. Source: https://vanadreams.org/wiki/#mission-259', steps = { { title = 'Walkthrough', note = '• Collect the red, beige, green, yellow, purple and blue luminous fragments.\n• Check the Ensorcelled Door (B-10) in Ro\'Maeve; fragments are consumed.\n• Missing any fragment shows only a hexagonal depression.\n• Unlocks Fountain of Trouble.' }, { title = 'Reward', note = '• Key item: Bomb key' } } },
    { name = 'Fountain Of Trouble', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: get a sap crystal in Toraimarai Canal and take it to the Moon Spiral at Full Moon Fountain. Source: https://vanadreams.org/wiki/#mission-260', steps = { { title = 'Walkthrough', note = '• Check ??? points in Toraimarai Canal for any sap crystal (Fire, Water, Wind, Earth, Lightning, Ice, Light or Dark Sap Crystal).\n• Check the Moon Spiral in Full Moon Fountain for the scene.' }, { title = 'Notes', note = '• Max one of each crystal type.\n• The ??? points keep working during Battaru Royale.' } } },
    { name = 'Battaru Royale', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: win the Battaru Royale battlefield at Full Moon Fountain for a Chocobo Key. Source: https://vanadreams.org/wiki/#mission-261', steps = { { title = 'Walkthrough', note = '• At the Moon Spiral in Full Moon Fountain, enter with at least one sap crystal; all held crystals are consumed.\n• Win, then view the scene to finish.' } } },
    { name = 'Romancing The Clone', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: a short scene with Aldo at the Tenshodo. Source: https://vanadreams.org/wiki/#mission-262', steps = { { title = 'Walkthrough', note = '• Talk to Aldo (J-8) at the Tenshodo in Lower Jeuno; the mission ends with the scene.' } } },
    { name = 'Sisters In Arms', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: get a Tablet of Hexes and take it to the Mahogany Door in the Sacrificial Chamber. Source: https://vanadreams.org/wiki/#mission-263', steps = { { title = 'Walkthrough', note = '• Check the Shining ??? (Temple of Uggalepih) or the Shiny ??? (Den of Rancor) for a Tablet of Hexes.\n• Check the Mahogany Door in the Sacrificial Chamber.' }, { title = 'Notes', note = '• Temple of Uggalepih: Greed, Envy, Malice, Deceit, Pride, Bale; Den of Rancor: the other ten.\n• The ??? points keep working during Project Shantottofication.' } } },
    { name = 'Project Shantottofication', group = 'Mission: A Shantotto Ascension', desc = 'ASA mission: defeat Shantotto and her doppelganger in the Sacrificial Chamber for the Tonberry Key. Source: https://vanadreams.org/wiki/#mission-264', steps = { { title = 'Walkthrough', note = '• With at least one Tablet of Hexes, click the Mahogany Door in the Sacrificial Chamber.\n• Kill Shantotto and Doppelganger Shantotto within 30 minutes (6 players max).\n• Get the Tonberry Key and view the scene.' }, { title = 'Notes', note = '• All tablets are spent on entry; each one weakens the pair.\n• The win grants EXP.\n• Repeatable for a Tonberry Key if you lack one.' } } },
    { name = 'An Uneasy Peace', group = 'Mission: A Shantotto Ascension', desc = 'Final ASA story step: zone into Windurst Walls for the closing scene. Source: https://vanadreams.org/wiki/#mission-265', steps = { { title = 'Walkthrough', note = '• Enter Windurst Walls; no NPC needed.' }, { title = 'Reward', note = '• Key item: Behemoth key\n• Title: Arrester of the Ascension' } } },
    { name = 'A Shantotto Ascension Fin', group = 'Mission: A Shantotto Ascension', desc = 'End marker for ASA; only the key reward remains. Source: https://vanadreams.org/wiki/#mission-266', steps = { { title = 'Walkthrough', note = '• Open the Treasure Coffer in the Lower Jeuno Tenshodo with the Behemoth Key.' } } },
    { name = 'Rumors from the West', group = 'Mission: Seekers of Adoulin', desc = 'SoA 1-1: Darcia in Lower Jeuno gives the Geomagnetron. Source: https://vanadreams.org/wiki/#mission-267', steps = { { title = 'Walkthrough', note = '• Talk to Darcia (H-7) in Lower Jeuno and accept her offer.\n• Option: pay 1,000,000 gil for the Adoulinian Charter Permit and skip ahead.\n• Optional scenes on entering Northern San d\'Oria, Bastok Markets and Windurst Woods.' } } },
    { name = 'The Geomagnetron', group = 'Mission: Seekers of Adoulin', desc = 'SoA 1-2: attune the Geomagnetron at a Geomagnetic Fount, then see Darcia for the charter permit. Source: https://vanadreams.org/wiki/#mission-268', steps = { { title = 'Walkthrough', note = '• Use the Geomagnetron on a Geomagnetic Fount.\n• Talk to Darcia (H-7) in Lower Jeuno for the Adoulinian charter permit.\n• Option: pay her 1,000,000 gil to skip the Fount.' } } },
    { name = 'Onward to Adoulin', group = 'Mission: Seekers of Adoulin', desc = 'SoA 1-3: take the Lower Jeuno Waypoint to Ceizak Battlegrounds. Source: https://vanadreams.org/wiki/#mission-269', steps = { { title = 'Walkthrough', note = '• Check the Waypoint (H-7) in Lower Jeuno and travel.\n• View the arrival scene in Ceizak Battlegrounds.' } } },
    { name = 'Heartwings and the Kindhearted', group = 'Mission: Seekers of Adoulin', desc = 'SoA 1-4: a scene on arrival in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-270', steps = { { title = 'Walkthrough', note = '• Zone into Western Adoulin and view the scene.' } } },
    { name = 'Pioneer Registration', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: sign up with Brenton for the Pioneer\'s Badge and map of Adoulin. Source: https://vanadreams.org/wiki/#mission-271', steps = { { title = 'Walkthrough', note = '• Talk to Brenton (E-8) in Western Adoulin and view the scene.\n• Also grants the Pioneer\'s Badge and starting Coalition Imprimaturs.' }, { title = 'Reward', note = '• Key item: map of Adoulin' } } },
    { name = 'Life on the Frontier', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: Brenton gives you a dinner invitation. Source: https://vanadreams.org/wiki/#mission-272', steps = { { title = 'Walkthrough', note = '• Talk to Brenton (E-8) in Western Adoulin and view the scene.' } } },
    { name = 'Meeting of the Minds', group = 'Mission: Seekers of Adoulin', desc = 'SoA 1-7: an evening dinner with Ploh Trishbahk in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-273', steps = { { title = 'Requirements', note = '• Active mission: Meeting of the Minds\n• Key item: Dinner Invitation\n• Vana\'diel time 15:00–22:59' }, { title = 'Walkthrough', note = '• In Eastern Adoulin, speak with Ploh Trishbahk inside the evening window.\n• Outside that window you get only a brief scene and no progress.\n• Next mission unlocks the following Vana\'diel day.' } } },
    { name = 'Arciela Appears Again', group = 'Mission: Seekers of Adoulin', desc = 'SoA 1-8: accept Levil\'s prompt in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-274', steps = { { title = 'Requirements', note = '• Active mission: SoA 1-8\n• One Vana\'diel day since the prior mission' }, { title = 'Walkthrough', note = '• Speak with Levil (E-8) in Western Adoulin and say yes.\n• If you declined, speak with him again and accept.' } } },
    { name = 'Budding Prospects', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-1: do the Flavors of Our Lives errand, then see Masad in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-275', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin.\n• Finish the quest Flavors of Our Lives, or advance it until its wait timer starts.\n• After the wait, speak with Masad (G-10), Western Adoulin, for the cutscene.\n• If Masad has nothing, retry on the next Vana\'diel day.' } } },
    { name = 'The Light Shining in Your Eyes', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission finished with a Levil cutscene. Source: https://vanadreams.org/wiki/#mission-276', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin, and view the cutscene.' } } },
    { name = 'The Heirloom', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-1-2: cutscene beside Ploh Trishbahk in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-277', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8), Western Adoulin, for dialogue.\n• Approach Ploh Trishbahk (K-9), Eastern Adoulin, at the marked point.\n• The cutscene completes the mission.' } } },
    { name = 'An Aimless Journey', group = 'Mission: Seekers of Adoulin', desc = 'Scene at the Ergon Locus in Cirdas Caverns. Source: https://vanadreams.org/wiki/#mission-278', steps = { { title = 'Walkthrough', note = '• In Cirdas Caverns, walk to the Ergon Locus area; the scene completes the mission.' } } },
    { name = 'Ortharsyne', group = 'Mission: Seekers of Adoulin', desc = 'Arrival scene in Yorcia Weald, following An Aimless Journey. Source: https://vanadreams.org/wiki/#mission-279', steps = { { title = 'Walkthrough', note = '• Zone into Yorcia Weald; the arrival scene completes the mission.' } } },
    { name = 'In the Presence of Royalty', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-2-2: carry Yorcia\'s tear from the Ergon Locus to the Pellucid Afflusion. Source: https://vanadreams.org/wiki/#mission-280', steps = { { title = 'Walkthrough', note = '• In Yorcia Weald, examine the Ergon Locus to get Yorcia\'s tear.\n• Examine the Pellucid Afflusion (G-6) in the same zone and view the scene.\n• Wait one Vana\'diel day before The Twin World Trees.' }, { title = 'Reward', note = '• Key item: Rosulatia\'s pome\n• Title: Queens Confidante' } } },
    { name = 'The Twin World Trees', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-3: scene near Oscairn in Eastern Adoulin after a one-day wait. Source: https://vanadreams.org/wiki/#mission-281', steps = { { title = 'Walkthrough', note = '• Requires one Vana\'diel day since In the Presence of Royalty.\n• In Eastern Adoulin, walk into the marked area by Oscairn to view the scene.\n• Nothing triggers before the wait ends; retry next Vana\'diel day.\n• Levil (Western Adoulin) only gives reminders.' } } },
    { name = 'Honor and Audacity', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-4: arrival cutscene in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-282', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways; the arrival cutscene completes the mission.\n• Levil (Western Adoulin) gives a reminder.' } } },
    { name = 'The Watergarden Coliseum', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-4-1: talk to Yeggha Dolashi in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-283', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways from Eastern Adoulin (F-7).\n• Speak with Yeggha Dolashi (M-6) for the scene.\n• Wait one Vana\'diel day before Friction and Fissures.' } } },
    { name = 'Friction and Fissures', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: a Levil scene in Western Adoulin after a day\'s wait. Source: https://vanadreams.org/wiki/#mission-284', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin, for the scene.\n• A recent talk gets only a short reply; return next Vana\'diel day.\n• Unlocks The Celennia Memorial Library.' } } },
    { name = 'The Celennia Memorial Library', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-5-1: research in the library, then report to Levil. Source: https://vanadreams.org/wiki/#mission-285', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin.\n• In Celennia Memorial Library, speak with Yefafa.\n• Examine History in the library.\n• Return to Levil (E-8) for the cutscene.' } } },
    { name = 'For Whom Do We Toil?', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: operate Sluice Gate 6 in Rala Waterways to foil the plot. Source: https://vanadreams.org/wiki/#mission-286', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways from Western Adoulin (F-5) and view the cutscene.\n• Examine Sluice Gate 6 (C-6) and play the event.\n• After three failures, check the History book in Celennia Memorial Library and wait a Vana\'diel day before retrying.\n• Examine Sluice Gate 6 (C-6) again when prompted to finish.\n• Optional: Wegellion (Eastern Adoulin) dialogue; Levil (Western Adoulin) reminds.' }, { title = 'Reward', note = '• Key item: note detailing seditious plans' } } },
    { name = 'Aiming for Ygnas', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: report on Ygnas to Ploh Trishbahk in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-287', steps = { { title = 'Walkthrough', note = '• Speak with Ploh Trishbahk (K-9), Eastern Adoulin, and view the scene.\n• Levil (Western Adoulin) only comments briefly.' } } },
    { name = 'Calamity in the Kitchen', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-6-1: accept Chalvava\'s tomato request in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-288', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways from Western Adoulin (I-12).\n• Speak with Chalvava (F-11), then speak again and accept.\n• If you refused, talk once more and accept.' }, { title = 'Reward', note = '• Key item: box of Adoulinian tomatoes' } } },
    { name = 'Arciela\'s Promise', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: stop by Rala Waterways, then see Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-289', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways from Western Adoulin (I-12); Chalvava (F-11) has an optional short scene.\n• Speak with Ploh Trishbahk (K-9), Eastern Adoulin, for the cutscene.' } } },
    { name = 'Predators and Prey', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: inspect Sluice Gate 6 in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-290', steps = { { title = 'Walkthrough', note = '• In Rala Waterways, examine Sluice Gate 6 for the cutscene.\n• Levil (Western Adoulin) repeats the goal.' } } },
    { name = 'Behind the Sluices', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-7 part 1: get the crank, open Sluice Gate 6 and fight beside Arciela. Source: https://vanadreams.org/wiki/#mission-291', steps = { { title = 'Walkthrough', note = '• In Rala Waterways, examine the Storage Container (H-6) for the waterway facility crank.\n• Examine Sluice Gate 6 with the crank and view the cutscene.\n• Examine Sluice Gate 6 (C-6) again and enter.\n• With Arciela, defeat The Keeper, Mistdagger and both Briars.\n• Zone back into Rala Waterways for the final cutscene.' }, { title = 'Battle notes', note = '• Entering uses up the crank; take another from the Storage Container to retry.\n• Arciela buffs herself and fights but needs heals.\n• Enemies move to random party members to use weapon skills.\n• Kill The Keeper last; it is the toughest.' } } },
    { name = 'The Leafkin Monarch', group = 'Mission: Seekers of Adoulin', desc = 'SoA 2-7 part 2: a cutscene spot in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-292', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, walk to the marked spot for the cutscene.\n• Yggdrasil opens after one Vana\'diel day.' } } },
    { name = 'Yggdrasil', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: agree with Levil once the daily wait is over. Source: https://vanadreams.org/wiki/#mission-293', steps = { { title = 'Walkthrough', note = '• Requires the previous mission\'s daily wait to end.\n• Speak with Levil (E-8), Western Adoulin, agree, and view the cutscene.\n• Too early or after declining, he repeats himself; talk again later.' } } },
    { name = 'Return of the Exorcist', group = 'Mission: Seekers of Adoulin', desc = 'Trigger a scene by walking through Western Adoulin. Source: https://vanadreams.org/wiki/#mission-294', steps = { { title = 'Walkthrough', note = '• In Western Adoulin, walk into the marked town area to trigger the scene.\n• Levil only comments briefly.' } } },
    { name = 'The Merciless One', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: trigger a cutscene in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-295', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, enter the trigger area for the cutscene.\n• For a reminder, see Levil (E-8), Western Adoulin.' } } },
    { name = 'A Curse from the Past', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-1-2: collect holy water and a stone wall piece to purify the eternal flame. Source: https://vanadreams.org/wiki/#mission-296', steps = { { title = 'Walkthrough', note = '• Speak with Ploh Trishbahk (K-9), Eastern Adoulin.\n• Speak with Rigobertine (J-7), Eastern Adoulin, for the eternal flame.\n• Western Adoulin: Fontis Xanira (H-9) gives the vial of untainted holy water.\n• Western Adoulin: examine the Sunrise Beacon (J-4) for the piece of a stone wall.\n• Back in Eastern Adoulin, speak with Erminold (J-10); both items are required.\n• Optional: Behsa Alehgo has lines once you hold the flame.' }, { title = 'Reward', note = '• Key item: weather vane wings' } } },
    { name = 'The Purgation', group = 'Mission: Seekers of Adoulin', desc = 'Complete the purification rite in Eastern Adoulin with the four gathered key items. Source: https://vanadreams.org/wiki/#mission-297', steps = { { title = 'Requirements', note = '• Key items: eternal flame, vial of untainted holy water, piece of a stone wall, weather vane wings' }, { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Speak with Erminold (J-10), Eastern Adoulin.\n• Step into the marked area by Erminold for the final scene.\n• All four key items are removed; the next mission needs a Vana\'diel day.' } } },
    { name = 'The Key', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-1-4: after a day\'s wait, a Levil cutscene. Source: https://vanadreams.org/wiki/#mission-298', steps = { { title = 'Walkthrough', note = '• Wait one Vana\'diel day after the prior mission.\n• Speak with Levil (E-8), Western Adoulin, and view the cutscene.\n• Too early, he only repeats himself.' } } },
    { name = 'The Princess\'s Dilemma', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-2-0: a choice-driven scene in Celennia Memorial Library. Source: https://vanadreams.org/wiki/#mission-299', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Enter Celennia Memorial Library.\n• Answer the scene\'s prompts; it only completes with the correct second choice.' } } },
    { name = 'Dark Clouds Ahead', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-2-1: a Levil cutscene in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-300', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin, and view the cutscene.\n• Next mission opens the following Vana\'diel day.' } } },
    { name = 'The Smallest of Favors', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: head out to Ceizak Battlegrounds for an arrival scene. Source: https://vanadreams.org/wiki/#mission-301', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8), Western Adoulin, for background.\n• Zone from Western Adoulin into Ceizak Battlegrounds; the arrival cutscene completes it.\n• The scene may wait until the next Vana\'diel day after the prior mission.' } } },
    { name = 'Summoned by Spirits', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: arrival cutscene in Celennia Memorial Library. Source: https://vanadreams.org/wiki/#mission-302', steps = { { title = 'Walkthrough', note = '• Zone into Celennia Memorial Library for the cutscene.\n• Levil repeats the goal.' } } },
    { name = 'Evil Entities', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: find Elmric in Ceizak Battlegrounds. Source: https://vanadreams.org/wiki/#mission-303', steps = { { title = 'Walkthrough', note = '• In Ceizak Battlegrounds, speak with Elmric (J-7) and view the cutscene.\n• Levil (E-8), Western Adoulin, can remind you.' } } },
    { name = 'Adoulin Calling', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-3-2: the boarding house door in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-304', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, examine the Door of the Boarding House for the scene.\n• Levil and Elmric (Ceizak Battlegrounds) only give reminders.' } } },
    { name = 'The Disappearance of Nyline', group = 'Mission: Seekers of Adoulin', desc = 'Check the Eastern Adoulin Boarding House, then follow the lead to Foret de Hennetiel. Source: https://vanadreams.org/wiki/#mission-305', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, examine the Boarding House door and view the scene.\n• In Foret de Hennetiel, walk into the marked area for the next scene.\n• Levil only comments briefly.' } } },
    { name = 'Shared Consciousness', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-3-4: another Boarding House scene in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-306', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, examine the Boarding House door and view the cutscene.\n• Clear Skies opens after one Vana\'diel day.' }, { title = 'Reward', note = '• 1,000 experience points\n• Title: Sunshine Cadet' } } },
    { name = 'The Disappearance of Nyline', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-3-5 (active mission shown as Clear Skies): see Levil after a one-day wait. Source: https://vanadreams.org/wiki/#mission-307', steps = { { title = 'Walkthrough', note = '• Wait one Vana\'diel day after Shared Consciousness.\n• Speak with Levil (E-8), Western Adoulin, and view the cutscene.' } } },
    { name = 'The Man in Black', group = 'Mission: Seekers of Adoulin', desc = 'Beat Masad\'s card game in Western Adoulin to earn Card Jailer Teodor. Source: https://vanadreams.org/wiki/#mission-308', steps = { { title = 'Walkthrough', note = '• Speak with Masad (G-10), Western Adoulin, and play his card game.\n• Repeat until you win the "Card Jailer Teodor" card.\n• Talk to Masad again holding the card.\n• Quitting early is fine; talk to Masad later to retry.\n• Levil only comments briefly.' } } },
    { name = 'To the Victor', group = 'Mission: Seekers of Adoulin', desc = 'Win Masad\'s dice game against Teodor in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-309', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8).\n• Speak with Masad (G-10), Western Adoulin, and play dice against Teodor (shoot, stay or special trick).\n• A win gives the Card Jailer Teodor card, and Masad\'s follow-up scene ends the mission.\n• Attempts are unlimited; a tie or loss just starts a new round.' }, { title = 'Reward', note = '• Title: Boomy and Busty' } } },
    { name = 'An Extraordinary Gentleman', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: a Levil cutscene in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-310', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin, and view the cutscene.' } } },
    { name = 'The Order\'s Treasures', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-4-3: arrival cutscene in Celennia Memorial Library. Source: https://vanadreams.org/wiki/#mission-311', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8) dialogue.\n• Zone into Celennia Memorial Library; the arrival cutscene completes it.' } } },
    { name = 'August\'s Heirloom', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-4-4: talk to Ploh Trishbahk in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-312', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, speak with Ploh Trishbahk (K-9) and view the scene.\n• Levil only gives reminders.' } } },
    { name = 'Beauty and the Beast', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: inspect the Signs of a Struggle in Ceizak Battlegrounds. Source: https://vanadreams.org/wiki/#mission-313', steps = { { title = 'Walkthrough', note = '• In Ceizak Battlegrounds, examine the Signs of a Struggle (I-7) and view the cutscene.\n• Ploh Trishbahk and Levil have extra lines meanwhile.' }, { title = 'Reward', note = '• Key item: pristine hair ribbon' } } },
    { name = 'Wildcat with a Gold Pelt', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-5-1: trigger a scene in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-314', steps = { { title = 'Walkthrough', note = '• In Eastern Adoulin, enter the marked area for the cutscene.\n• Levil has extra lines meanwhile.' } } },
    { name = 'In Search of Arciela', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: optional Ploh Trishbahk visit, then Levil. Source: https://vanadreams.org/wiki/#mission-315', steps = { { title = 'Walkthrough', note = '• Optional: Ploh Trishbahk (K-9), Eastern Adoulin, has a scene.\n• Speak with Levil (E-8), Western Adoulin, and view the cutscene.' } } },
    { name = 'Looking for Leads', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-5-3: a marked spot in Eastern Adoulin yields the tintinnabulum. Source: https://vanadreams.org/wiki/#mission-316', steps = { { title = 'Walkthrough', note = '• Optional hints: Levil (E-8), Western Adoulin.\n• In Eastern Adoulin, walk to the marked spot for the scene.' }, { title = 'Reward', note = '• Key item: tintinnabulum' } } },
    { name = 'Drifting Northwest', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: bring the tintinnabulum into Kamihr Drifts. Source: https://vanadreams.org/wiki/#mission-317', steps = { { title = 'Walkthrough', note = '• Requires the tintinnabulum key item.\n• Zone into Kamihr Drifts; the cutscene completes it and takes the tintinnabulum.\n• Levil repeats the goal.' }, { title = 'Reward', note = '• Title: Weatherer of Brumal Climes' } } },
    { name = 'Kumhau, the Flashfrost Naakual', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-6-1: the Crawling Cave in Kamihr Drifts leads to a Kumhau scene in Ceizak Battlegrounds. Source: https://vanadreams.org/wiki/#mission-318', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin.\n• In Kamihr Drifts, examine the Crawling Cave (F-11).\n• A scene plays in Ceizak Battlegrounds, then you return to Kamihr Drifts.\n• The cutscene on return completes the mission.' }, { title = 'Reward', note = '• Key item: aureate ball of fur' } } },
    { name = 'Soul Siphon', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: through the Hollowed Pathway to Cirdas Caverns and back. Source: https://vanadreams.org/wiki/#mission-319', steps = { { title = 'Walkthrough', note = '• In Kamihr Drifts, check the Hollowed Pathway (G-11) and agree to enter.\n• View the cutscene in Cirdas Caverns.\n• Being sent back to Kamihr Drifts completes it.\n• Levil repeats the goal.' } } },
    { name = 'Stonewalled', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-6-3: get the aureate ball of fur, then enter Cirdas Caverns. Source: https://vanadreams.org/wiki/#mission-320', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin.\n• In Kamihr Drifts, examine the Crawling Cave (F-11) for the aureate ball of fur.\n• Enter Cirdas Caverns, go through the entrance event and view the cutscene.\n• You return to Kamihr Drifts afterward.' }, { title = 'Reward', note = '• Key item: soul siphon' } } },
    { name = 'Salvation', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-6-4: use the Soul Siphon at the Crawling Cave; awards the White Knight title. Source: https://vanadreams.org/wiki/#mission-321', steps = { { title = 'Walkthrough', note = '• Requires the Soul Siphon key item.\n• Optional hints: Levil (E-8), Western Adoulin.\n• In Kamihr Drifts, check the Crawling Cave (F-11) and pick the option to use the Soul Siphon.\n• The Soul Siphon is consumed; the next mission waits until the next Vana\'diel day.' }, { title = 'Reward', note = '• Title: White Knight' } } },
    { name = 'Glimmer of Portent', group = 'Mission: Seekers of Adoulin', desc = 'SoA 3-6-5: see Levil a day after Salvation. Source: https://vanadreams.org/wiki/#mission-322', steps = { { title = 'Walkthrough', note = '• Wait one Vana\'diel day after Salvation (3-6-4).\n• Speak with Levil (E-8), Western Adoulin, and agree to continue.\n• Too early, he repeats old advice.' } } },
    { name = '...Into the Fire', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-1: a Kipligg cutscene in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-323', steps = { { title = 'Walkthrough', note = '• In Western Adoulin, speak with Kipligg (G-7) and view the cutscene.\n• Levil has extra lines meanwhile.' } } },
    { name = 'Melvien de Malecroix', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-1: Kipligg, Levil, then the Port Storage in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-324', steps = { { title = 'Walkthrough', note = '• In Western Adoulin, speak with Kipligg (G-7), then Levil (E-8).\n• Examine the Port Storage (J-3); the cutscene completes it.\n• That scene sets up the item request for Courier Catastrophe.' } } },
    { name = 'Courier Catastrophe', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-1-2: replace Kipligg\'s lost shipment by trading goods to the Port Storage. Source: https://vanadreams.org/wiki/#mission-325', steps = { { title = 'Walkthrough', note = '• Speak with Kipligg (G-7), Western Adoulin, for the list.\n• Gather the requested goods: 5 Eft Skin, 4 Manticore Hair, 1 Buffalo Horn, 1 Manticore Lth. or 1 Buffalo Leather.\n• Trade them to the Port Storage (J-3), Western Adoulin.\n• Examining the Port Storage shows the list again; Levil only reminds.' } } },
    { name = 'Done and Delivered', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: report back to Kipligg in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-326', steps = { { title = 'Walkthrough', note = '• Speak with Kipligg (G-7), Western Adoulin, and view the cutscene.\n• Levil (E-8) can remind you.' } } },
    { name = 'Ministerial Whispers', group = 'Mission: Seekers of Adoulin', desc = 'Hear the ministry rumors from Levil in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-327', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin, and view the cutscene.\n• Kipligg has extra lines.\n• Afterward, zone and wait one Vana\'diel day for the next mission.' } } },
    { name = 'A Day in the Life of a Pioneer', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-1-5: wait a day, then talk to Levil. Source: https://vanadreams.org/wiki/#mission-328', steps = { { title = 'Walkthrough', note = '• Wait for the next Vana\'diel day and zone at least once.\n• Speak with Levil (E-8), Western Adoulin, and view the scene.\n• Before then he gives only a short reminder.' } } },
    { name = 'Lighting the Way', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: up the Alpine Trail to Mount Kamihr and back. Source: https://vanadreams.org/wiki/#mission-329', steps = { { title = 'Walkthrough', note = '• In Kamihr Drifts, examine the Alpine Trail (H-5) and proceed to Mount Kamihr.\n• View the cutscene there; you return to Kamihr Drifts and the mission completes.\n• Levil (E-8) can remind you.' }, { title = 'Reward', note = '• Title: Knower of Untruths' } } },
    { name = 'Sajj\'aka', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: learn about Sajj\'aka in Celennia Memorial Library. Source: https://vanadreams.org/wiki/#mission-330', steps = { { title = 'Walkthrough', note = '• Zone into Celennia Memorial Library and view the cutscene.\n• Levil can remind you.' } } },
    { name = 'Studying Up', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-2-2: a Mount Kamihr trip from Kamihr Drifts. Source: https://vanadreams.org/wiki/#mission-331', steps = { { title = 'Walkthrough', note = '• In Kamihr Drifts, examine the Alpine Trail (H-5) and proceed.\n• View the arrival cutscene at Mount Kamihr.\n• Zone back into Kamihr Drifts to finish.' } } },
    { name = 'A Vow of Truth', group = 'Mission: Seekers of Adoulin', desc = 'Arrival scene in Woh Gates. Source: https://vanadreams.org/wiki/#mission-332', steps = { { title = 'Walkthrough', note = '• Go to Woh Gates; the arrival scene completes it.\n• Levil only comments briefly.' } } },
    { name = 'Darrcuiln', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-2 part 4: the Darkened Crevice in Woh Gates yields a tuft of golden fur. Source: https://vanadreams.org/wiki/#mission-333', steps = { { title = 'Walkthrough', note = '• Enter Woh Gates from Marjami Ravine (B-5).\n• Examine the Darkened Crevice (Map 1, G-7) and view the cutscene.\n• Levil can remind you.' }, { title = 'Reward', note = '• Key item: tuft of golden fur' } } },
    { name = 'The Gates', group = 'Mission: Seekers of Adoulin', desc = 'Follow Darrcuiln to the Darkened Crevice in Woh Gates and clear its Umbril guards. Source: https://vanadreams.org/wiki/#mission-334', steps = { { title = 'Walkthrough', note = '• Enter Woh Gates from Yorcia Weald (E-7); examine the Large Animal Track (Map 1, K-8) for a tuft of golden fur.\n• Holding the tuft, defeat 8 Calcined Umbrils near the Darkened Crevice (Map 1, G-7).\n• Examine the Darkened Crevice to go through, then view the closing scene.' }, { title = 'Notes', note = '• Every party member holding a tuft gets credit per Umbril.\n• The tuft is removed when you pass through.' }, { title = 'Reward', note = '• Title: Ulbukan Understudy' } } },
    { name = 'Morimar', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-3-1: climb Mount Kamihr and receive Sajj\'aka\'s protective ward. Source: https://vanadreams.org/wiki/#mission-335', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8) dialogue.\n• In Kamihr Drifts, click the Alpine Trail (H-5) and agree to climb.\n• The arrival cutscene at Mount Kamihr completes it; you return to Kamihr Drifts.' }, { title = 'Reward', note = '• Key item: Sajj\'aka\'s protective ward' } } },
    { name = 'A New Force Arises', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-3-2: gather three scales in Outer Ra\'Kaznar, then climb Mount Kamihr. Source: https://vanadreams.org/wiki/#mission-336', steps = { { title = 'Walkthrough', note = '• Outer Ra\'Kaznar: the Demonic Architrave (Map 2, C-8) gives the Sunkissed Scale.\n• First Effigy of Sealing: Moontouched Scale.\n• Second Effigy of Sealing: Starblessed Scale.\n• In Kamihr Drifts, click the Alpine Trail (H-5), agree to climb, and view the Mount Kamihr cutscene.' }, { title = 'Notes', note = '• Scales can be gathered in any order and are consumed.\n• Climbing with fewer than three gives only a hint.' }, { title = 'Reward', note = '• Key item: World Tree sapling' } } },
    { name = 'The Sacred Sapling', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-3-3: a Ploh Trishbahk cutscene in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-337', steps = { { title = 'Walkthrough', note = '• Speak with Ploh Trishbahk (K-9), Eastern Adoulin, and view the cutscene.' } } },
    { name = 'Tree Grafting', group = 'Mission: Seekers of Adoulin', desc = 'Levil explains the grafting plan in Western Adoulin. Source: https://vanadreams.org/wiki/#mission-338', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin, and view the scene.\n• Ploh Trishbahk has extra lines.' } } },
    { name = 'A Shrouded Canopy', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-3-5: arrival scene in Leafallia. Source: https://vanadreams.org/wiki/#mission-339', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Enter Leafallia; the scene completes it.' } } },
    { name = 'Leafallia', group = 'Mission: Seekers of Adoulin', desc = 'Examine the Aged Stump in Leafallia to continue the story. Source: https://vanadreams.org/wiki/#mission-340', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin.\n• In Leafallia, examine the Aged Stump (H-8) and view the cutscene.' } } },
    { name = 'Rosulatia\'s Promise', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-3-7: plant the World Tree Sapling at the Heroic Footprints in Leafallia. Source: https://vanadreams.org/wiki/#mission-341', steps = { { title = 'Walkthrough', note = '• Requires the World Tree Sapling key item.\n• Optional: Levil (E-8) has a scene.\n• In Leafallia, examine the Heroic Footprints (H-8) and view the cutscene.\n• The sapling is removed at the end.' }, { title = 'Reward', note = '• Title: Keeper of Ulbuka' } } },
    { name = 'The Lightsland', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission closing the Lightsland arc with a reward choice. Source: https://vanadreams.org/wiki/#mission-342', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin.\n• In Leafallia, examine the Heroic Footprints (H-8) for a scene.\n• In Eastern Adoulin, speak with Ploh Trishbahk (K-9) and pick Adoulin\'s Refuge, Ygnas\'s Resolve or Arciela\'s Grace.' }, { title = 'Notes', note = '• Needs a free inventory slot; if full, return to Ploh later to collect.\n• Unlocks The Light of Dawn Comes after a one-day wait.' } } },
    { name = 'The Light of Dawn Comes from the East', group = 'Mission: Seekers of Adoulin', desc = 'See Levil in Western Adoulin once the wait has passed. Source: https://vanadreams.org/wiki/#mission-343', steps = { { title = 'Walkthrough', note = '• Speak with Levil (E-8), Western Adoulin; an early visit gets a short line.\n• After at least one Vana\'diel day (counted from mission start), talk again for the scene.' }, { title = 'Reward', note = '• 500 experience points' } } },
    { name = 'Cries from the Deep', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-4: look into a disturbance in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-344', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8) dialogue.\n• In Eastern Adoulin, walk into the marked area for a scene; you are moved to the castle gate area.\n• Zone back into Eastern Adoulin; the cutscene completes the mission.' } } },
    { name = 'Seeds of Doubt', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-4-1: a cutscene with Ploh Trishbahk, then a report to Chalvava. Source: https://vanadreams.org/wiki/#mission-345', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8), Western Adoulin, has dialogue.\n• Eastern Adoulin: speak to Ploh Trishbahk (K-9) for a cutscene.\n• Use the Western Adoulin (I-12) entrance to Rala Waterways; speak to Chalvava (F-11) to finish.' } } },
    { name = 'The Tomatoes of Wrath', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-4-2: see Chalvava first, then report back to Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-346', steps = { { title = 'Walkthrough', note = '• Optional: Levil (E-8), Western Adoulin, has dialogue.\n• Enter Rala Waterways via Western Adoulin (I-12); speak to Chalvava (F-11) for a cutscene.\n• Back in Eastern Adoulin, speak to Ploh Trishbahk (K-9) to finish.' } } },
    { name = 'A Grave Mistake', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: investigate in Rala Waterways and deliver a Broken Fuse to Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-347', steps = { { title = 'Walkthrough', note = '• Enter Rala Waterways via Eastern Adoulin (F-7); speak to Sainene (N-7).\n• Examine the Waterways Overlook (J-6).\n• Speak to Stout Weir (D-8) to get the Broken Fuse.\n• Bring it to Ploh Trishbahk (K-9), Eastern Adoulin; cutscene completes it.' }, { title = 'Good to know', note = '• Zone before the next mission will proceed.' } } },
    { name = 'An Emergency Convocation', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: a chain of scenes in Eastern Adoulin, each needing a zone. Source: https://vanadreams.org/wiki/#mission-348', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; watch the cutscene.\n• Zone out and back in for the second scene.\n• Zone once more; the last scene completes the mission.' }, { title = 'Good to know', note = '• Ploh Trishbahk waits until you zone.\n• Next mission unlocks after one Vana\'diel day.' } } },
    { name = 'Balamor, The Deathborne Xol', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: a cutscene with Ploh Trishbahk introducing Balamor. Source: https://vanadreams.org/wiki/#mission-349', steps = { { title = 'Walkthrough', note = '• Requires one Vana\'diel day since An Emergency Convocation.\n• Optional reminder: Levil (E-8), Western Adoulin.\n• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; the cutscene finishes it.\n• Too early and he only gives a brief line.' } } },
    { name = 'Anagnorisis', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-5-1: present your earlier necklace to Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-350', steps = { { title = 'Walkthrough', note = '• Speak to Ploh Trishbahk (K-9), Eastern Adoulin.\n• Trade him Adoulin\'s Refuge, Ygnas\'s Resolve or Arciela\'s Grace if you have one.\n• Without any of them, simply talking still completes it.' } } },
    { name = 'Just the Thing', group = 'Mission: Seekers of Adoulin', desc = 'SoA 4-5-2: visit Andreine for the key item "Suffering Sacchariferous". Source: https://vanadreams.org/wiki/#mission-351', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Speak to Andreine in the Celennia Memorial Library.' }, { title = 'Reward', note = '• Key item: "Suffering Sacchariferous"' } } },
    { name = 'Sugarcoated Salvation', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: hand "Suffering Sacchariferous" to Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-352', steps = { { title = 'Walkthrough', note = '• Needs key item "Suffering Sacchariferous" (it is consumed).\n• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; the cutscene completes it.\n• Levil (Western Adoulin) and Andreine (Celennia Memorial Library) give reminders.' }, { title = 'Reward', note = '• Key item: sepulcher ensign\n• Title: Lifter of Spirits' } } },
    { name = 'Arciela\'s Resolve', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: a scene with Ploh Trishbahk, then the Royal Sepulcher. Source: https://vanadreams.org/wiki/#mission-353', steps = { { title = 'Walkthrough', note = '• Needs key item sepulcher ensign.\n• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; watch the cutscene.\n• In Rala Waterways, examine the Royal Sepulcher (N-10); the cutscene completes it.\n• Reminder: Levil, Western Adoulin.' } } },
    { name = 'Balamor\'s Ruse', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: farm the consummate simulacrum and win the Rala Waterways [U] battlefield. Source: https://vanadreams.org/wiki/#mission-354', steps = { { title = 'Walkthrough', note = '• Speak to Levil (E-8), Western Adoulin.\n• In Rala Waterways, kill Duskbringer Bats, New Moon Bats, Skittering Spiders, Spoutdrenched Toads or Waterway Pugils until the consummate simulacrum drops (random).\n• Enter Rala Waterways [U] and win the battlefield.\n• Back in Rala Waterways, the scene completes it.' }, { title = 'Good to know', note = '• Any party member in the zone on this mission can get the drop.' }, { title = 'Reward', note = '• Title: Shedder of Harlequin Tears' } } },
    { name = 'The Charlatan', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission closing the Balamor arc with a necklace choice from Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-355', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; watch the scene.\n• Pick Adoulin\'s Refuge +1, Ygnas\'s Resolve +1 or Arciela\'s Grace +1.\n• Inventory full? Free a slot and speak to him again.' }, { title = 'Good to know', note = '• Completion requires taking an item; scene EXP is granted regardless.' }, { title = 'Reward', note = '• Title: Hope for the Future' } } },
    { name = 'Royal Blessings', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: a cutscene with Levil. Source: https://vanadreams.org/wiki/#mission-356', steps = { { title = 'Walkthrough', note = '• Speak to Levil (E-8), Western Adoulin; the cutscene completes it.' } } },
    { name = 'Arboreal Rumors', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-1: Ploh Trishbahk gives you a hastily scribbled note. Source: https://vanadreams.org/wiki/#mission-357', steps = { { title = 'Walkthrough', note = '• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; the cutscene completes it.\n• Reminder: Levil, Western Adoulin.' }, { title = 'Reward', note = '• Key item: hastily scribbled note' } } },
    { name = 'Arciela\'s Missive', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: get Arciela\'s note, then use the Sunrise Beacon. Source: https://vanadreams.org/wiki/#mission-358', steps = { { title = 'Walkthrough', note = '• Speak to Ploh Trishbahk (K-9), Eastern Adoulin; receive the hastily scribbled note.\n• Examine the Sunrise Beacon (J-4), Western Adoulin; the scene completes it.\n• Reminder: Levil (E-8), Western Adoulin.\n• The note is removed on completion.' } } },
    { name = 'Heroes, Unite!', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-1-2: climb Mount Kamihr via the Alpine Trail. Source: https://vanadreams.org/wiki/#mission-359', steps = { { title = 'Walkthrough', note = '• Kamihr Drifts: examine the Alpine Trail (H-5) and proceed.\n• After the Mount Kamihr scene you return to Kamihr Drifts; mission complete.\n• Levil (Western Adoulin) only reminds.' } } },
    { name = 'A Portent Most Ominous', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-1-3: visit the Aged Stump in Leafallia. Source: https://vanadreams.org/wiki/#mission-360', steps = { { title = 'Walkthrough', note = '• Optional scene: Levil (E-8), Western Adoulin.\n• In Leafallia, examine the Aged Stump (H-8); the cutscene completes it.' }, { title = 'Reward', note = '• Key items: sky blue pome, sun yellow pome' } } },
    { name = 'Yggdrasil Beckons', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-2: take two pomes and beat Ashrakk and Dhokmak at the Wavering Fluxes. Source: https://vanadreams.org/wiki/#mission-361', steps = { { title = 'Walkthrough', note = '• Leafallia: examine the Aged Stump (H-8) for the sky blue pome and sun yellow pome.\n• Yorcia Weald: examine the Wavering Flux (H-6), kill 10 Snapweed.\n• Examine it again, defeat Ashrakk; get Ashrakk\'s blood sigil after zoning.\n• Cirdas Caverns: examine the Wavering Flux (Map 1, K-11), kill 10 Flatus Acuex.\n• Examine it again, defeat Dhokmak; get Dhokmak\'s blood sigil after zoning.\n• Both sigils complete the mission.' }, { title = 'Good to know', note = '• Bring a capable party.\n• Fights in any order.\n• Lost a pome? Re-check the Aged Stump.\n• Levil only reminds.' } } },
    { name = 'Returning to the Trees', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-2-1: a scene on entering Leafallia. Source: https://vanadreams.org/wiki/#mission-362', steps = { { title = 'Walkthrough', note = '• Zone into Leafallia; the scene completes it.\n• Levil (Western Adoulin) only reminds.' } } },
    { name = 'The Key to the Turris', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-2-2: use the Ominous Postern and finish in Kamihr Drifts. Source: https://vanadreams.org/wiki/#mission-363', steps = { { title = 'Walkthrough', note = '• Optional reminder: Levil (E-8), Western Adoulin.\n• Ra\'Kaznar Turris: examine the Ominous Postern (I-8).\n• You are moved to Kamihr Drifts; the scene finishes it.' }, { title = 'Reward', note = '• Title: Protected by Ulbukan Spirits' } } },
    { name = 'Teodor\'s Summons', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-3: ascend Mount Kamihr and receive the ash runic board. Source: https://vanadreams.org/wiki/#mission-364', steps = { { title = 'Walkthrough', note = '• Kamihr Drifts: examine the Alpine Trail (H-5) and proceed.\n• After the scene you return to Kamihr Drifts holding the ash runic board.\n• Levil only reminds.' }, { title = 'Reward', note = '• Key item: ash runic board' } } },
    { name = 'The Seventh Guardian', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-3-1: meet Yeggha Dolashi in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-365', steps = { { title = 'Walkthrough', note = '• Optional scene: Levil (E-8), Western Adoulin.\n• Enter Rala Waterways via Eastern Adoulin (F-7).\n• Speak to Yeggha Dolashi (M-6); the cutscene completes it.' } } },
    { name = 'Watery Grave', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-3-2: win the Rala Waterways instance and watch the return scene. Source: https://vanadreams.org/wiki/#mission-366', steps = { { title = 'Walkthrough', note = '• Needs a blank ash runic board; get one in Rala Waterways if missing.\n• Clear the Rala Waterways instance.\n• Back in Rala Waterways, the scene grants several key items.\n• On failure, retry the next Vana\'diel day.' }, { title = 'Reward', note = '• Title: Receiver of Sigils' } } },
    { name = 'Blood for Blood', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-3 part 3: a cutscene at the Ominous Postern. Source: https://vanadreams.org/wiki/#mission-367', steps = { { title = 'Walkthrough', note = '• Ra\'Kaznar Turris: examine the Ominous Postern (I-8); the cutscene completes it.' } } },
    { name = 'Reckoning', group = 'Mission: Seekers of Adoulin', desc = 'SoA 5-4: kill ten Vodoriga, then confront Hades. Source: https://vanadreams.org/wiki/#mission-368', steps = { { title = 'Walkthrough', note = '• Enter Ra\'Kaznar Inner Court; the crystallized psyche is given on arrival.\n• Kill 10 Vodoriga (Scowling Vodoriga).\n• After the 10th, you are sent to Ra\'Kaznar Turris.\n• The Hades cutscene completes it.' }, { title = 'Good to know', note = '• Kills count per player: must be in zone, on the mission, holding the psyche.' }, { title = 'Reward', note = '• Key item: awakened crystallized psyche\n• Title: Destroyer of Hades' } } },
    { name = 'Abomination', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: defeat Hades\'s followers, then end in Ceizak Battlegrounds. Source: https://vanadreams.org/wiki/#mission-369', steps = { { title = 'Walkthrough', note = '• Enter Rakaznar Inner Court; receive an awakened crystallized psyche.\n• Kill 10 Apex Umbrils while holding it.\n• Scene in Rakaznar Turris, then you are moved to Ceizak Battlegrounds.\n• Watch the final scene there.' }, { title = 'Good to know', note = '• All party members holding the psyche are moved when the last Umbril dies.' }, { title = 'Reward', note = '• Title: Bringer of the Dawn' } } },
    { name = 'Undying Light', group = 'Mission: Seekers of Adoulin', desc = 'SoA mission: return to Adoulin and see Ploh Trishbahk. Source: https://vanadreams.org/wiki/#mission-370', steps = { { title = 'Walkthrough', note = '• Enter Western Adoulin through the Ceizak Battlegrounds gate (required for the scene).\n• Speak to Ploh Trishbahk (K-9), Eastern Adoulin.\n• Re-zone into Eastern Adoulin when told for the last scene.' }, { title = 'Reward', note = '• Title: The One True Pioneer' } } },
    { name = 'The Light Within', group = 'Mission: Seekers of Adoulin', desc = 'SoA finale: farewell scenes with Arciela and a ring choice. Source: https://vanadreams.org/wiki/#mission-371', steps = { { title = 'Walkthrough', note = '• Wait one Vana\'diel day after Undying Light.\n• Zone into Ceizak Battlegrounds; answer Arciela during the long scene.\n• Zone into Leafallia for the next scene; you return to Ceizak.\n• Go to Eastern Adoulin; speak to Ploh Trishbahk (K-9) and pick one of 12 rings.' }, { title = 'Good to know', note = '• Pristine hair ribbon is exchanged for Arciela\'s skirt.\n• Saying \'No\' roughly 12 times in the Ceizak scene also gives Arciela\'s spare bonnet.\n• You may return later for a different ring.' }, { title = 'Reward', note = '• 1,000 EXP\n• Title: Bringer of Hope' } } },
    { name = 'Seekers of Adoulin Helpers', group = 'Mission: Seekers of Adoulin', desc = 'Internal support code for SoA missions; nothing for players to do. Source: https://vanadreams.org/wiki/#mission-372', steps = {  } },
    { name = 'Rhapsodies of Vana\'diel', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-1: begins the storyline on entering a nation city. Source: https://vanadreams.org/wiki/#mission-373', steps = { { title = 'Walkthrough', note = '• Level 3+.\n• Zone into any San d\'Oria, Bastok or Windurst city zone (not from a Mog House); the cutscene completes it.' } } },
    { name = 'Resonance', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-2: an arrival scene in Selbina or Mhaura. Source: https://vanadreams.org/wiki/#mission-374', steps = { { title = 'Walkthrough', note = '• Zone into Selbina or Mhaura; the automatic scene completes it.\n• Your choice of town decides your Emissary from the Seas route.' } } },
    { name = 'Emissary from the Seas', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-3: scenes in both Selbina and Mhaura. Source: https://vanadreams.org/wiki/#mission-375', steps = { { title = 'Walkthrough', note = '• Selbina: speak to Naillina (F-9); watch the cutscene.\n• Mhaura: speak to Numi Adaligo (F-9) to finish.' } } },
    { name = 'Set Free', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-4: trade gathering materials to the NPC on your route; leads to The Beginning. Source: https://vanadreams.org/wiki/#mission-376', steps = { { title = 'Walkthrough', note = '• Selbina route: trade 3 Bee Pollen to Abelard (G-9).\n• Mhaura route: trade 3 Mandra. Dewdrops to Ekokoko (F-9).\n• The scene gives Gilgamesh\'s introductory letter or a Copper Voucher, depending on progress.' }, { title = 'Good to know', note = '• Keep a free inventory slot for the voucher or it will not complete.' } } },
    { name = 'The Beginning', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-5: travel to Norg and get the Reisenjima Sanctorium orb. Source: https://vanadreams.org/wiki/#mission-377', steps = { { title = 'Walkthrough', note = '• Selbina route: speak to Pacomart (H-10), accept the trip to Norg.\n• Mhaura route: speak to Tonasav (H-9), accept the trip to Norg.\n• Optional extra scene: Heillal (I-8), Norg.\n• Examine the Oaken Door in Norg; the cutscene completes it.' }, { title = 'Reward', note = '• Key item: Reisenjima Sanctorium orb' } } },
    { name = 'Flames of Prayer', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-6: a scene at Norg\'s Oaken Door. Source: https://vanadreams.org/wiki/#mission-378', steps = { { title = 'Walkthrough', note = '• Examine the Oaken Door in Norg; the cutscene completes it.' }, { title = 'Reward', note = '• Key item: "Rhapsody in White"' } } },
    { name = 'The Path Untraveled', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-7: inspect a Shattered Telepoint. Source: https://vanadreams.org/wiki/#mission-379', steps = { { title = 'Walkthrough', note = '• Examine the Shattered Telepoint in Konschtat Highlands, La Theine Plateau or Tahrongi Canyon (any one); the scene completes it.' }, { title = 'Good to know', note = '• Norg\'s door is locked now; Gilgamesh only reminds.' } } },
    { name = 'At Heaven\'s Door', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-8: inspect the Undulating Confluence on Qufim Island. Source: https://vanadreams.org/wiki/#mission-380', steps = { { title = 'Walkthrough', note = '• Qufim Island: examine the Undulating Confluence (G-8); the scene completes it.\n• Norg\'s door remains locked.' } } },
    { name = 'The Lion\'s Roar', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-9: defeat Ophiotaurus on Qufim Island. Source: https://vanadreams.org/wiki/#mission-381', steps = { { title = 'Walkthrough', note = '• Qufim Island: examine the Undulating Confluence (G-8) to spawn Ophiotaurus.\n• Defeat it to complete the mission.\n• If told to wait, try again shortly.' } } },
    { name = 'Eddies of Despair (I)', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-10: the Undulating Confluence sends you to Escha - Zi\'Tah. Source: https://vanadreams.org/wiki/#mission-382', steps = { { title = 'Walkthrough', note = '• Qufim Island: examine the Undulating Confluence (G-8).\n• In Escha - Zi\'Tah, the cutscene completes it.' } } },
    { name = 'A Land After Time', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-11: a Shattered Telepoint scene that grants "Rhapsody in Umber" and a cipher. Source: https://vanadreams.org/wiki/#mission-383', steps = { { title = 'Walkthrough', note = '• Konschtat Highlands, La Theine Plateau or Tahrongi Canyon: examine the Shattered Telepoint, watch the scene.\n• Examine it again for the reward.' }, { title = 'Good to know', note = '• Nation Rank 6 changes the scene.\n• Free inventory space first; the check can be repeated until everything is received.' }, { title = 'Reward', note = '• Item: Cipher: Lion II\n• Key item: "Rhapsody in Umber"' } } },
    { name = 'Fate\'s Call', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-12: a cutscene on entering a starting-nation city. Source: https://vanadreams.org/wiki/#mission-384', steps = { { title = 'Walkthrough', note = '• Needs home-nation Rank 6+, or advanced Shadow Lord mission progress.\n• Zone into any Bastok, San d\'Oria or Windurst city zone; the arrival cutscene completes it.' } } },
    { name = 'What Lies Beyond', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-13: open Norg\'s Oaken Door. Source: https://vanadreams.org/wiki/#mission-385', steps = { { title = 'Walkthrough', note = '• Norg: examine the Oaken Door (K-8); the scene completes it.\n• Comitiolus (Norg) only reminds.' } } },
    { name = 'The Ties that Bind', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-14: a scene from the ??? in Sea Serpent Grotto. Source: https://vanadreams.org/wiki/#mission-386', steps = { { title = 'Walkthrough', note = '• Sea Serpent Grotto: examine the ???; the cutscene completes it.' } } },
    { name = 'Impurity', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-15: inspect a ??? in Yuhtunga Jungle. Source: https://vanadreams.org/wiki/#mission-387', steps = { { title = 'Walkthrough', note = '• Yuhtunga Jungle: examine the ??? (F-11); the cutscene completes it.' } } },
    { name = 'The Lost Avatar', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-16: defeat Siren in Yuhtunga Jungle. Source: https://vanadreams.org/wiki/#mission-388', steps = { { title = 'Walkthrough', note = '• Yuhtunga Jungle: examine the ??? (F-11) to spawn Siren.\n• Defeat Siren.\n• Examine the ??? (F-11) again; the cutscene completes it.' }, { title = 'Reward', note = '• Key item: "Rhapsody in Azure"' } } },
    { name = 'Volto Oscuro', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-17: a Tenzen scene at Norg\'s Oaken Door. Source: https://vanadreams.org/wiki/#mission-389', steps = { { title = 'Walkthrough', note = '• Norg: examine the Oaken Door and watch the scene.\n• Examine the Oaken Door (K-8) again if the mission has not completed.' }, { title = 'Reward', note = '• Item: Cipher: Zeid II' } } },
    { name = 'Ring My Bell', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 1-18: a cutscene at Norg\'s Oaken Door. Source: https://vanadreams.org/wiki/#mission-390', steps = { { title = 'Walkthrough', note = '• Tenzen must be free of your Chains of Promathia story.\n• Norg: examine the Oaken Door; the cutscene completes it.\n• If he is unavailable, the door gives a short message only.' } } },
    { name = 'Spirits Awoken', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-1: enter Lower Delkfutt\'s Tower from Qufim Island. Source: https://vanadreams.org/wiki/#mission-391', steps = { { title = 'Walkthrough', note = '• Tenzen must be free of your Chains of Promathia story.\n• Enter Lower Delkfutt\'s Tower from Qufim Island (only this entry works); the scene completes it.' } } },
    { name = 'Crashing Waves', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-2: meet Tenzen\'s party in Ru\'Lude Gardens and get his cipher. Source: https://vanadreams.org/wiki/#mission-392', steps = { { title = 'Walkthrough', note = '• Needs Promathia mission A Vessel Without a Captain done and Alter Egos available.\n• In Ru\'Lude Gardens, go to the Homepoint area to trigger the scene.\n• Inventory full? Claim Cipher: Tenzen II from the Mystic Retriever (H-7).' } } },
    { name = 'Call to Serve', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-3: meet Prishe in Port Jeuno for her cipher. Source: https://vanadreams.org/wiki/#mission-393', steps = { { title = 'Walkthrough', note = '• Chains of Promathia progress is required for the full scene.\n• Zone into Port Jeuno, watch the cutscene, accept Cipher: Prishe II.\n• Inventory full? Get it later from the Port Jeuno Mystic Retriever.' } } },
    { name = 'Numbering Days', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-4: a Prishe scene at the Marble Bridge Eatery. Source: https://vanadreams.org/wiki/#mission-394', steps = { { title = 'Walkthrough', note = '• Required allies must be available.\n• Upper Jeuno: examine the Marble Bridge Eatery door; the scene completes it.\n• Dialogue varies with Chains of Promathia progress.' } } },
    { name = 'Inescapable Binds', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-5: reach Aht Urhgan Whitegate with a Boarding Permit. Source: https://vanadreams.org/wiki/#mission-395', steps = { { title = 'Walkthrough', note = '• Hold a Boarding Permit (also obtainable via The Road to Aht Urhgan); scene characters must be available.\n• Zone into Aht Urhgan Whitegate; the cutscene completes it.' } } },
    { name = 'Desert Winds', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-6: an arrival scene in Aht Urhgan Whitegate. Source: https://vanadreams.org/wiki/#mission-396', steps = { { title = 'Walkthrough', note = '• Zone into Aht Urhgan Whitegate; the cutscene completes it.' } } },
    { name = 'Ever Forward', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-7: route depends on Treasures of Aht Urhgan progress. Source: https://vanadreams.org/wiki/#mission-397', steps = { { title = 'Walkthrough', note = '• Prishe must be available.\n• ToAU at Royal Puppeteer or later (not Sweets for the Soul or Teahouse Tumult): zone into any nation city for the summons; this also clears the next mission.\n• Or examine the Imperial Whitegate (L-9) in Aht Urhgan Whitegate for the palace scene, skipping ahead to Reunited.\n• ToAU not far enough: the Imperial Whitegate (L-9) says you cannot progress and you move to The Endless Sky.' } } },
    { name = 'The Endless Sky', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-8: wait for ToAU progress, then get the messenger\'s summons. Source: https://vanadreams.org/wiki/#mission-398', steps = { { title = 'Walkthrough', note = '• Reach ToAU Royal Puppeteer or later (not Sweets for the Soul or Teahouse Tumult).\n• Zone into any nation city for the summons to complete it.\n• Or examine the Imperial Whitegate (L-9) for the palace scene, which also skips the next mission.\n• Before that, the gate only says you cannot progress.' } } },
    { name = 'Aphmau\'s Light', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-9: report to the Imperial Whitegate once ToAU is far enough. Source: https://vanadreams.org/wiki/#mission-399', steps = { { title = 'Walkthrough', note = '• Needs ToAU Royal Puppeteer or later.\n• Aht Urhgan Whitegate: speak to the Imperial Whitegate (L-9) and watch the cutscene.\n• Otherwise the gate says you cannot continue yet.' }, { title = 'Reward', note = '• Item: Cipher: Nashmeira II' } } },
    { name = 'Reunited', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-10: a reunion scene via Nadeey. Source: https://vanadreams.org/wiki/#mission-400', steps = { { title = 'Walkthrough', note = '• Story companions must be available.\n• Aht Urhgan Whitegate: speak to Nadeey (K-7); the cutscene completes it.' } } },
    { name = 'Take Wing', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-11: walk into a marked spot in Aht Urhgan Whitegate. Source: https://vanadreams.org/wiki/#mission-401', steps = { { title = 'Walkthrough', note = '• Required allies must be available.\n• Step into the marked area in Aht Urhgan Whitegate; the scene completes it.\n• Dialogue differs if CoP The Warrior\'s Path is complete.' } } },
    { name = 'Prime Number', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-12: a scene on entering Alzadaal Undersea Ruins. Source: https://vanadreams.org/wiki/#mission-402', steps = { { title = 'Walkthrough', note = '• Tenzen and Aphmau must be available.\n• Zone into Alzadaal Undersea Ruins; the scene completes it.\n• Then zone into The Shrouded Maw for a one-time follow-up scene.' } } },
    { name = 'From the Ruins', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-13: an Imperial Whitegate cutscene granting "Rhapsody in Crimson". Source: https://vanadreams.org/wiki/#mission-403', steps = { { title = 'Walkthrough', note = '• Tenzen and Aphmau must be free of your CoP/ToAU stories, or the scene will not play.\n• Aht Urhgan Whitegate: speak to the Imperial Whitegate (gate guard); the cutscene completes it.' }, { title = 'Reward', note = '• Key item: "Rhapsody in Crimson"' } } },
    { name = 'Cauterize', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-14: a Cavernous Maw scene that grants the lightsworm. Source: https://vanadreams.org/wiki/#mission-404', steps = { { title = 'Walkthrough', note = '• Alter Egos must be available.\n• In Batallia Downs, Rolanberry Fields or Sauromugue Champaign (normal or [S]), check the ??? Cavernous Maw and watch the scene.\n• Completion also starts Ganged Up On.' }, { title = 'Reward', note = '• Key item: lightsworm' } } },
    { name = 'Uncertain Destinations', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-15: not yet implemented; no player actions. Source: https://vanadreams.org/wiki/#mission-405', steps = {  } },
    { name = 'Ganged Up On', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-16: a Lilisette scene in Southern San d\'Oria [S] with her cipher. Source: https://vanadreams.org/wiki/#mission-406', steps = { { title = 'Walkthrough', note = '• Companions available; keep one free inventory slot.\n• Zone into Southern San d\'Oria [S]; watch the cutscene.\n• Inventory was full? Free a slot and see the Mystic Retriever (M-5).' }, { title = 'Reward', note = '• Item: Cipher: Lilisette II' } } },
    { name = 'Sacrifice', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-17: through the Ornate Door in the Walk of Echoes to Grauberg [S]. Source: https://vanadreams.org/wiki/#mission-407', steps = { { title = 'Walkthrough', note = '• Must not have Crystal War quests A Forbidden Reunion or Champion of the Dawn active (finish or drop them).\n• Zone into the Walk of Echoes; watch the cutscene.\n• Examine the Ornate Door (Map 17, H-7); you are moved to Grauberg [S].\n• The arrival cutscene completes it.' } } },
    { name = 'Somber Dreams', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-18: defeat Cetus in Grauberg [S], then go to the Walk of Echoes. Source: https://vanadreams.org/wiki/#mission-408', steps = { { title = 'Walkthrough', note = '• Grauberg [S]: examine the ??? (F-5) to spawn Cetus; defeat it.\n• Examine the ??? (F-5) again for a cutscene.\n• Examine the second nearby ??? and choose the Walk of Echoes.\n• The arrival cutscene completes it.' }, { title = 'Good to know', note = '• No final scene means companions are tied up in their own stories; advance those and zone in again.' } } },
    { name = 'Of Light and Darkness', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-19: another scene at Norg\'s Oaken Door. Source: https://vanadreams.org/wiki/#mission-409', steps = { { title = 'Walkthrough', note = '• Required companions must be available.\n• Norg: examine the Oaken Door; the cutscene completes it.' } } },
    { name = 'Temporary Farewells', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-20: a farewell cutscene at a ??? on Misareaux Coast. Source: https://vanadreams.org/wiki/#mission-410', steps = { { title = 'Steps', note = '• Have Temporary Farewells active.\n• Check the ??? by the Undulating Confluence (G-5), Misareaux Coast, and view the scene.' } } },
    { name = 'Brushing Up', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-21: a cutscene with a story choice on Misareaux Coast. Source: https://vanadreams.org/wiki/#mission-411', steps = { { title = 'Steps', note = '• Have Brushing Up active.\n• Check the ??? by the Undulating Confluence (G-5), Misareaux Coast.\n• Pick an option in the scene; the choice affects the next mission.' } } },
    { name = 'Keep On Giving', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-22: hand an offering to a ??? on Misareaux Coast. Source: https://vanadreams.org/wiki/#mission-412', steps = { { title = 'Steps', note = '• Check the ??? (G-5) first; the wanted item varies per player.\n• Options: 1 Beef Stewpot, 1 Zaru Soba or 30 Spicy Crackers.\n• Trade it to the ??? (G-5) and view the scene.' } } },
    { name = 'Past Imperfect', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-23: a cutscene at the Oaken Door in Norg. Source: https://vanadreams.org/wiki/#mission-413', steps = { { title = 'Steps', note = '• Needs the story companions available.\n• Check the Oaken Door in Norg and view the scene.\n• The scene varies with your progress in RoZ The Temple of Uggalepih.' } } },
    { name = 'The Cursed Temple', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-24: two scenes in the Temple of Uggalepih. Source: https://vanadreams.org/wiki/#mission-414', steps = { { title = 'Steps', note = '• Requires RoZ The Temple of Uggalepih completed.\n• Enter the Temple of Uggalepih for a scene.\n• Check the Granite Door for the second scene.' } } },
    { name = 'Wisdom of Our Forefathers', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-25: a cutscene at the Granite Door. Source: https://vanadreams.org/wiki/#mission-415', steps = { { title = 'Steps', note = '• Story companions must be available.\n• Check the Granite Door in the Temple of Uggalepih and view the scene.' } } },
    { name = 'Where Divinities Collide', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-26: travel to the Hall of Transference via a Shattered Telepoint. Source: https://vanadreams.org/wiki/#mission-416', steps = { { title = 'Steps', note = '• Alter Ego characters must be available.\n• Check the Shattered Telepoint in Konschtat Highlands, La Theine Plateau or Tahrongi Canyon and enter (same prompt as CoP The Mothercrystals).\n• View the scenes in the Hall of Transference.' } } },
    { name = 'Visions of Dread', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-27: an arrival cutscene in the Hall of Transference. Source: https://vanadreams.org/wiki/#mission-417', steps = { { title = 'Steps', note = '• Companions must be available.\n• Enter the Hall of Transference; the scene plays on arrival.' } } },
    { name = 'To the Skies', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-28: an Oaken Door scene in Norg leading toward Escha - Ru\'Aun. Source: https://vanadreams.org/wiki/#mission-418', steps = { { title = 'Steps', note = '• Check the Oaken Door in Norg and view the scene.\n• If companions are unavailable you get a can\'t-progress message; retry later.' } } },
    { name = 'Escha - Ru\'Aun', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-29: first trip to Escha - Ru\'Aun from Misareaux Coast. Source: https://vanadreams.org/wiki/#mission-419', steps = { { title = 'Requirements', note = '• Current mission: Escha - Ru\'Aun.\n• Story companions must be free to appear.' }, { title = 'Steps', note = '• Check the Undulating Confluence (G-5), Misareaux Coast, for a scene with Tenzen (D-6).\n• Check the Undulating Confluence (H-11) to enter Escha - Ru\'Aun.\n• View the arrival scene.' } } },
    { name = 'The Decisive Heroine', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-30: a ??? near the Escha - Ru\'Aun entrance. Source: https://vanadreams.org/wiki/#mission-420', steps = { { title = 'Steps', note = '• In Escha - Ru\'Aun, check the ??? on the slope at H-10, before the stairs, and view the scene.' }, { title = 'Reward', note = '• Key items: "Rhapsody in Emerald", Siren\'s plume' } } },
    { name = 'Fall from Grace', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-31: a cutscene at a Shattered Telepoint. Source: https://vanadreams.org/wiki/#mission-421', steps = { { title = 'Steps', note = '• Tenzen must be free of CoP story conflicts.\n• Check any Shattered Telepoint (Konschtat Highlands, La Theine Plateau or Tahrongi Canyon) and view the scene.' } } },
    { name = 'Banishing the Darkness', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-32: a short Oaken Door scene in Norg. Source: https://vanadreams.org/wiki/#mission-422', steps = { { title = 'Steps', note = '• Check the Oaken Door in Norg.' } } },
    { name = 'Over the Rainbow', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-33: a Shantotto scene in Windurst Walls. Source: https://vanadreams.org/wiki/#mission-423', steps = { { title = 'Steps', note = '• Tenzen must be free of CoP story conflicts.\n• Speak to Shantotto (K-7), Windurst Walls.' }, { title = 'Reward', note = '• Key item: most curious curio' } } },
    { name = 'Cacophonous Discord', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-34: an automatic scene with Cid\'s survey team. Source: https://vanadreams.org/wiki/#mission-424', steps = { { title = 'Steps', note = '• Companions must be available.\n• Zone into Escha - Ru\'Aun; no NPC interaction needed.' } } },
    { name = 'Eddies of Despair (II)', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-35: a Balamor scene at the vortex in Escha - Ru\'Aun. Source: https://vanadreams.org/wiki/#mission-425', steps = { { title = 'Steps', note = '• Enter Escha - Ru\'Aun by the Eschan Portal.\n• Check the ??? (H-12) near Eschan Portal #15 (H-11) for the Balamor scene.' } } },
    { name = 'Pretender to the Throne', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-36: fight Balamor in Escha - Ru\'Aun. Source: https://vanadreams.org/wiki/#mission-426', steps = { { title = 'Steps', note = '• Enter Escha - Ru\'Aun to receive the most curious curio.\n• Check the ??? (H-12) to spawn Balamor and defeat him.\n• Check the ??? (H-12) again for the closing scene.' }, { title = 'Notes', note = '• The curio becomes the most confounding curio on spawn and is removed after the kill.\n• Zoning out early: re-enter to get the curio again.\n• The ??? has a short cooldown between tries.' }, { title = 'Reward', note = '• Cipher: Balamor\n• Title: Banisher of the Profane' } } },
    { name = 'Banished', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-37: a short Oaken Door scene in Norg. Source: https://vanadreams.org/wiki/#mission-427', steps = { { title = 'Steps', note = '• Check the Oaken Door in Norg.' } } },
    { name = 'Call of the Void', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-38: go through a Dimensional Portal to Empyreal Paradox. Source: https://vanadreams.org/wiki/#mission-428', steps = { { title = 'Requirements', note = '• Current mission: Call of the Void.\n• Story companion characters must be free to appear.' }, { title = 'Steps', note = '• Check the Dimensional Portal (J-10) in Konschtat Highlands, La Theine Plateau or Tahrongi Canyon (any one works).\n• View the scene, then the arrival scene in Empyreal Paradox.' }, { title = 'Reward', note = '• Cipher: Selh\'teus' } } },
    { name = 'Both Paths Taken', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-39: the Both Paths Taken battle in Empyreal Paradox. Source: https://vanadreams.org/wiki/#mission-429', steps = { { title = 'Battle', note = '• Up to 6 players, 15 min, trusts allowed.' }, { title = 'Steps', note = '• Use the Dimensional Portal in La Theine Plateau, Konschtat Highlands or Tahrongi Canyon.\n• Enter the Transcendental Radiance in Empyreal Paradox.\n• Defeat the Disjoined Ones in time and view the scenes.' }, { title = 'Notes', note = '• Siren\'s plume is given on arrival, turns into a motionless plume at battle start and is consumed on victory.\n• The portal inside Empyreal Paradox returns you to your nation\'s crag zone.' } } },
    { name = 'The Man Behind the Mask', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-40: an Oaken Door scene in Norg. Source: https://vanadreams.org/wiki/#mission-430', steps = { { title = 'Steps', note = '• Check the Oaken Door (K-8) in Norg.' }, { title = 'Reward', note = '• Key item: "Rhapsody in Mauve"' } } },
    { name = 'Uncertain Futures', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 2-41: two scenes upon entering a nation city. Source: https://vanadreams.org/wiki/#mission-431', steps = { { title = 'Steps', note = '• Zone into any San d\'Oria, Bastok or Windurst city area.' }, { title = 'Reward', note = '• Key item: song of hope' } } },
    { name = 'Darkness Beckons', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-1: reach Reisenjima and find Iroha. Source: https://vanadreams.org/wiki/#mission-432', steps = { { title = 'Steps', note = '• Use a crag zone\'s Dimensional Portal (Map 1, F-12) to reach Reisenjima; view the scene.\n• Check the Etched Rock (K-9) for the Iroha scene.' } } },
    { name = 'The Brewing Storm', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-2: kill three Perfervid Naraka in Reisenjima. Source: https://vanadreams.org/wiki/#mission-433', steps = { { title = 'Steps', note = '• Perfervid Naraka roam near the Etched Rock from 20:00 to 04:00 Vana\'diel time.\n• Kill 3; completes on the third.' }, { title = 'Notes', note = '• Progress persists through zoning.\n• Ascended Naraka also count.\n• The Etched Rock has no role here.' } } },
    { name = 'The River Runs Red', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-3: an Etched Rock scene in Reisenjima. Source: https://vanadreams.org/wiki/#mission-434', steps = { { title = 'Steps', note = '• Check the Etched Rock (Map 1, K-9) in Reisenjima.\n• A geomagnetron is given afterward if you lack one.' }, { title = 'Reward', note = '• Key item: "Rhapsody in Fuchsia"' } } },
    { name = 'The Crucible', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-4: a scene on entering a nation city, or Ceizak Battlegrounds if Arciela Appears Again is done. Source: https://vanadreams.org/wiki/#mission-435', steps = { { title = 'Steps', note = '• Zone into any city zone of Bastok, San d\'Oria or Windurst (Markets/Mines/Port Bastok, Northern/Port/Southern San d\'Oria, Port Windurst, Windurst Walls/Waters/Woods).' }, { title = 'Notes', note = '• With SoA Arciela Appears Again done, zone into Ceizak Battlegrounds instead; you get the drained orb and jump to Tears of the Generals.' } } },
    { name = 'Forward Thinking', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-5: a Ceizak Battlegrounds scene gated by SoA progress. Source: https://vanadreams.org/wiki/#mission-436', steps = { { title = 'Steps', note = '• Requires SoA Arciela Appears Again completed.\n• Zone into Ceizak Battlegrounds.' }, { title = 'Reward', note = '• Key item: drained orb' } } },
    { name = 'Tears of the Generals', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-6: speak to Ploh Trishbahk in Eastern Adoulin. Source: https://vanadreams.org/wiki/#mission-437', steps = { { title = 'Steps', note = '• Requires SoA Ortharsyne completed and companions available.\n• Speak to Ploh Trishbahk at the castle gate (K-9), Eastern Adoulin.\n• Blocked while companions are tied up in some later SoA missions.' } } },
    { name = 'What He Left Behind', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-7: check a glowing ??? in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-438', steps = { { title = 'Steps', note = '• Enter Rala Waterways from Western Adoulin (F-5).\n• Check the ??? in the southwest, near the Augural Conveyor (B-6).\n• Free an inventory slot, or you must check it again.' }, { title = 'Reward', note = '• Cipher: Arciela II' } } },
    { name = 'Gone but Not Forgotten', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-8: get the founder king\'s orb from the old hideout in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-439', steps = { { title = 'Steps', note = '• Go through the sluice gate in Rala Waterways to the old hideout.\n• Check the Inconspicuous Barrel (C-6).' }, { title = 'Reward', note = '• Key item: founder king\'s orb' } } },
    { name = 'August Artifacts', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-9: hand over the founder king\'s orb at a ??? in Rala Waterways. Source: https://vanadreams.org/wiki/#mission-440', steps = { { title = 'Steps', note = '• Enter Rala Waterways from Western Adoulin (F-5) with the founder king\'s orb.\n• Check the ??? (C-6); the orb is taken in the scene.\n• Unlocks Solemnity.' } } },
    { name = 'Solemnity', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-10: a scene in the Celennia Memorial Library. Source: https://vanadreams.org/wiki/#mission-441', steps = { { title = 'Steps', note = '• Enter the Celennia Memorial Library from Eastern Adoulin.\n• Ploh Trishbahk (Eastern Adoulin) gives directions.' } } },
    { name = 'Eyes on You', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-11: meet Yve\'noile in the Hall of the Gods. Source: https://vanadreams.org/wiki/#mission-442', steps = { { title = 'Steps', note = '• Zone into the Hall of the Gods from either entrance.\n• The scene ends with you at the Cermet Grate.' } } },
    { name = 'Exploring the Ruins', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-12: check the Cermet Grate in the Hall of the Gods. Source: https://vanadreams.org/wiki/#mission-443', steps = { { title = 'Steps', note = '• Check the Cermet Grate (H-6), Hall of the Gods; no Zilart crystal required.' } } },
    { name = 'Become Something More', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-13: receive the dimensional compass in Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-444', steps = { { title = 'Steps', note = '• Check the Etched Rock in Reisenjima to enter Reisenjima Sanctorium.\n• View the scenes with Selh\'teus.' }, { title = 'Reward', note = '• Key item: dimensional compass' } } },
    { name = 'Unshakable Nightmares', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-14: reach the Walk of Echoes from a Maw. Source: https://vanadreams.org/wiki/#mission-445', steps = { { title = 'Steps', note = '• Check the ??? at the Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign (present or WotG versions).\n• View the scene in the Walk of Echoes.\n• Unlocks What Remains of Hope.' } } },
    { name = 'What Remains of Hope', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-15: Cait Sith takes you to Desuetia. Source: https://vanadreams.org/wiki/#mission-446', steps = { { title = 'Requirements', note = '• Current mission: What Remains of Hope.\n• Needed companion characters must be free to appear.' }, { title = 'Steps', note = '• In the Walk of Echoes, find the one ??? that triggers the event and accept.\n• View the arrival scene in Desuetia Empyreal Paradox.' }, { title = 'Reward', note = '• Key item: Cait Sith\'s whisker' } } },
    { name = 'Death Cares Not', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-16: get the whisker from Cait Sith and use the Transcendental Radiance. Source: https://vanadreams.org/wiki/#mission-447', steps = { { title = 'Steps', note = '• Speak to Cait Sith (K-12), Desuetia - Empyreal Paradox, for Cait Sith\'s Whisker.\n• Check the Transcendental Radiance while holding it and view the scene.\n• No response means no whisker or story characters busy elsewhere.' } } },
    { name = 'No Time like the Future', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-17: fight Sempurne in Desuetia - Empyreal Paradox. Source: https://vanadreams.org/wiki/#mission-448', steps = { { title = 'Steps', note = '• Get Cait Sith\'s Whisker from Cait Sith (K-12).\n• Enter the No Time like the Future battlefield and defeat Sempurne.\n• The whisker is consumed on entry; ask Cait Sith for another after a loss.' } } },
    { name = 'Sin', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-18: a Transcendental Radiance scene. Source: https://vanadreams.org/wiki/#mission-449', steps = { { title = 'Requirements', note = '• Current mission: Sin.\n• Needed companion characters must be free to appear.' }, { title = 'Steps', note = '• Check the Transcendental Radiance in Desuetia Empyreal Paradox.\n• You are moved to Reisenjima afterward.' } } },
    { name = 'Penance', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-19: scenes in Reisenjima and Desuetia - Empyreal Paradox. Source: https://vanadreams.org/wiki/#mission-450', steps = { { title = 'Steps', note = '• Zone into Reisenjima for the first scene; you are sent to Desuetia - Empyreal Paradox.\n• View the second scene there.\n• If interrupted, re-zone into Reisenjima, then take the Resume Point by the entrance.' }, { title = 'Reward', note = '• Key item: "Rhapsody in Puce"\n• Title: The Decider' } } },
    { name = 'Vessel of Light', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-20: a Selh\'teus scene in Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-451', steps = { { title = 'Steps', note = '• Enter Reisenjima Sanctorium via the Etched Rock in Reisenjima.' } } },
    { name = 'The Lifestream of Reisenjima', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-21: meet Gilgamesh, Aldo and Tenzen at a ??? in Reisenjima. Source: https://vanadreams.org/wiki/#mission-452', steps = { { title = 'Requirements', note = '• Current mission: The Lifestream of Reisenjima.\n• Story companions must be free to appear.\n• Open CoP missions such as Dawn can make Tenzen unavailable and block this.' }, { title = 'Steps', note = '• Check the ??? west of Ethereal Ingress #5, Reisenjima, and view the scene.' } } },
    { name = 'From West to East', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-22: kill Panopts in Reisenjima. Source: https://vanadreams.org/wiki/#mission-453', steps = { { title = 'Steps', note = '• Kill 11 Panopts in Reisenjima; Obstreperous and Ascended Panopts both count.' } } },
    { name = 'Good Things Come in Threes', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-23: Etched Rock scene leading into Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-454', steps = { { title = 'Steps', note = '• Alter Ego characters must be available.\n• Check the Etched Rock (Map 1, K-9), Reisenjima; you are moved into the Sanctorium.' } } },
    { name = 'Tackling the Problem', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-24: answer Selh\'teus in Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-455', steps = { { title = 'Requirements', note = '• Current mission: Tackling the Problem.\n• Characters in the scene must be free to appear.' }, { title = 'Steps', note = '• Zone into Reisenjima Sanctorium or check the Reisen Crystal (H-8).\n• Yes: skip Way to Divinity and go to Empyreal Paradox for The Winds of Time.\n• No: continue to Way to Divinity.\n• Both answers grant the Extradimensional Scar.' } } },
    { name = 'Way to Divinity', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-25: touch the Reisen Crystal. Source: https://vanadreams.org/wiki/#mission-456', steps = { { title = 'Steps', note = '• Check the Reisen Crystal (H-8), Reisenjima Sanctorium, and agree; you go to Empyreal Paradox.' }, { title = 'Reward', note = '• Title: The Ascended' } } },
    { name = 'The Winds of Time', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-26: fight Metus in Empyreal Paradox. Source: https://vanadreams.org/wiki/#mission-457', steps = { { title = 'Battle', note = '• Up to 6 players, 15 min, trusts allowed.' }, { title = 'Steps', note = '• Zone into Empyreal Paradox for the scenes.\n• Without the extradimensional scar: take the Dimensional Portal (J-10) to Reisenjima Sanctorium and accept it at the Reisen Crystal (H-8).\n• Enter the Transcendental Radiance and defeat Metus and his allies in time.' }, { title = 'Notes', note = '• The scar is consumed on entry; get another from the Reisen Crystal after a loss.' } } },
    { name = 'Calm After the Storm', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-27: a scene upon entering Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-458', steps = { { title = 'Steps', note = '• Enter Reisenjima Sanctorium; you return to Reisenjima afterward.\n• Unlocks Nary a Cloud in Sight.' } } },
    { name = 'Nary a Cloud in Sight', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-28: an arrival scene in Reisenjima. Source: https://vanadreams.org/wiki/#mission-459', steps = { { title = 'Steps', note = '• Story characters must not be busy elsewhere.\n• Zone into Reisenjima.' }, { title = 'Reward', note = '• Key item: "Rhapsody in Ochre"\n• Title: The Savior of Vanadiel\n• Iroha Alter Ego cipher' } } },
    { name = 'An Unending Song', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-29: a scene upon entering a nation city. Source: https://vanadreams.org/wiki/#mission-460', steps = { { title = 'Steps', note = '• Zone into any San d\'Oria, Bastok or Windurst city area.\n• Ciphers missed earlier are available from the Mystic Retriever.' } } },
    { name = 'A Deep Sleep', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-30: a Selh\'teus scene in Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-461', steps = { { title = 'Steps', note = '• Enter Reisenjima Sanctorium through the Etched Rock (H-9).' } } },
    { name = 'Guardians', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-31: a ??? at La Theine Plateau\'s stone circle. Source: https://vanadreams.org/wiki/#mission-462', steps = { { title = 'Steps', note = '• Check the ??? (E-4) at the stone circle near the Cavernous Maw, La Theine Plateau.' }, { title = 'Reward', note = '• Key item: breath of the avatars\n• Title: Blessed by the Avatars' } } },
    { name = 'Iroha in Distress', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-32: a scene upon entering Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-463', steps = { { title = 'Steps', note = '• Zone into Reisenjima Sanctorium.' } } },
    { name = 'Absolute Trust', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-33: a Reisen Crystal scene. Source: https://vanadreams.org/wiki/#mission-464', steps = { { title = 'Requirements', note = '• Current mission: Absolute Trust (3-33).\n• Needed story characters must not be tied up in other storylines.' }, { title = 'Steps', note = '• In Reisenjima Sanctorium, check the Reisen Crystal (H-8) and view the scene.' } } },
    { name = 'The Orb\'s Radiance', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-34: fight the Cloud of Darkness in Reisenjima Sanctorium. Source: https://vanadreams.org/wiki/#mission-465', steps = { { title = 'Steps', note = '• Get Breath of the Avatars from the ??? (E-4), La Theine Plateau stone circle.\n• Check the Reisen Crystal (H-8) and enter The Orb\'s Radiance.\n• Defeat the Cloud of Darkness and view the scene.' }, { title = 'Notes', note = '• The Breath is consumed on entry; get another after a loss.\n• Full inventory: claim Cipher: Iroha II from the Mystic Retriever.' }, { title = 'Reward', note = '• Key items: "Scintillating Rhapsody", Phoenix\'s blessing\n• Title: Seer of Songs' } } },
    { name = 'A Rhapsody for the Ages', group = 'Mission: Rhapsodies of Vana\'diel', desc = 'RoV 3-35: the ending scenes. Source: https://vanadreams.org/wiki/#mission-466', steps = { { title = 'Steps', note = '• Zone into Reisenjima; you are moved to Reisenjima Sanctorium for the last scene.\n• If interrupted, zoning into either area resumes.' } } },
    { name = 'The Voracious Resurgence', group = 'Mission: The Voracious Resurgence', desc = 'TVR opener, unlocked after RoV A Rhapsody for the Ages. Source: https://vanadreams.org/wiki/#mission-467', steps = { { title = 'Steps', note = '• Speak to Gumbah (J-7), Bastok Mines.' } } },
    { name = 'The Gloom Phantom\'s Approach', group = 'Mission: The Voracious Resurgence', desc = 'TVR 1-2: follow Cornelia into Zeruhn Mines and fight the Gloom Phantom. Source: https://vanadreams.org/wiki/#mission-468', steps = { { title = 'Steps', note = '• Walk (do not warp) from Bastok Mines into Zeruhn Mines for the Cornelia scene.\n• Optional hints: Gumbah (J-7), Foreman Makarim (H-11).\n• Check the Disturbed Dirt (K-9) for a scene.\n• Check the Disturbed Dirt (K-10) and defeat the Gloom Phantom within 15 min.\n• Check the Disturbed Dirt (K-10) once more.' }, { title = 'Notes', note = '• No level cap; trusts allowed; stay near the Disturbed Dirt.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'The Brygid Cup', group = 'Mission: The Voracious Resurgence', desc = 'TVR 1-3: enter Brygid\'s costume show in Bastok. Source: https://vanadreams.org/wiki/#mission-469', steps = { { title = 'Steps', note = '• Speak to Gumbah (J-7), Bastok Mines.\n• Sign up with Brygid (K-9), Bastok Markets, then speak again to pick a famous Bastokan.\n• Wear gear resembling that person.\n• Speak to Ruenda (E-7), Port Bastok, to compete.\n• Return to Brygid (K-9) for your score; any score passes.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'The Destiny Destroyers', group = 'Mission: The Voracious Resurgence', desc = 'TVR 1-4: help Naji\'s group in Korroloka Tunnel. Source: https://vanadreams.org/wiki/#mission-470', steps = { { title = 'Steps', note = '• Speak to Gumbah (J-7), Bastok Mines.\n• Enter Korroloka Tunnel from Eastern Altepa Desert (K-8); check the glowing Stalagmite (Map 1, D-9).\n• Check it again and defeat Gloom Phantom, Magh Bihu and Dazbog within 15 min.\n• Check the Stalagmite again, then report to Gumbah.' }, { title = 'Notes', note = '• No level cap; trusts allowed.\n• If the enemies remain from a failed try, wait for them to reset.' }, { title = 'Reward', note = '• Maat\'s Mix\n• Title: Destiny Destroyer Destroyer' } } },
    { name = 'Kupipi\'s Dilemma', group = 'Mission: The Voracious Resurgence', desc = 'TVR 1-5: gather clues in Heaven\'s Tower and visit Shantotto. Source: https://vanadreams.org/wiki/#mission-471', steps = { { title = 'Steps', note = '• Speak to Kupipi, Heaven\'s Tower.\n• Trades, any order (items consumed): Red Grass Cloth to Sassa-Kotassa, Yagudo Drink to Sheelala, Dream Flower Petal to Habida-Jubida.\n• Speak to Kupipi, then trade her a White Rolanberry or Ripe White Rolanberry.\n• Speak to Shantotto (K-7), Windurst Walls.' }, { title = 'Reward', note = '• 20,000 gil\n• Title: Fully Baked Hero' } } },
    { name = 'The Cardian\'s Duty', group = 'Mission: The Voracious Resurgence', desc = 'TVR: rescue the King of Spades from Yagudo in East Sarutabaruta. Source: https://vanadreams.org/wiki/#mission-472', steps = { { title = 'Steps', note = '• Speak to Shantotto (K-7), Windurst Walls, then Kupipi (Map 2, H-6), Heavens Tower.\n• Check the glowing Disturbed Earth (J-8), East Sarutabaruta.\n• Check it again; within 15 min defeat 2 Yagudo Underlings, a Yagudo Centurion and a Yagudo Vicar while keeping King of Spades alive.\n• Check it once more, then report to Kupipi.' }, { title = 'Notes', note = '• No level cap; trusts allowed.\n• Optional hints: Sassa-Kotassa, Sheelala, Habida-Jubida.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Zhuu Buxu\'s Gambit', group = 'Mission: The Voracious Resurgence', desc = 'TVR 2-3: deliver a summons, fight in Giddeus and recover a strange doll. Source: https://vanadreams.org/wiki/#mission-473', steps = { { title = 'Steps', note = '• Get the star-crested summons from Kupipi (Map 2, H-6), Heavens Tower.\n• Give it to Tosuka-Porika in the Optistery (G-8), Windurst Waters.\n• Check the Worn Chest (Map 2, F-6) in the Giddeus treasure vault; defeat the Yagudo Lookout within 15 min.\n• Check the chest again for the strange doll and bring it to Tosuka-Porika.' }, { title = 'Notes', note = '• No level cap; summon trusts before starting.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Star Onion Fortune', group = 'Mission: The Voracious Resurgence', desc = 'TVR 2-4: find who owns a strange doll, then win a sublime lucky egg in The Boyahda Tree. Source: https://vanadreams.org/wiki/#mission-474', steps = { { title = 'Walkthrough', note = '• Prior TVR mission done.\n• Get the strange doll from Tosuka-Porika, Windurst Waters.\n• Show it to Kohlo-Lakolo (G-5), Port Windurst, for evidence; speak to him a second time.\n• Enter The Boyahda Tree via Sanctuary of Zi\'Tah (J-12); check glowing Muggy Air spots until Templar Crawler spawns.\n• Kill it for the sublime lucky egg; deliver to Kohlo-Lakolo (G-5).' } } },
    { name = 'The Doll Whisperer', group = 'Mission: The Voracious Resurgence', desc = 'TVR 2-5: beat Chepelle and her pets in West Sarutabaruta, then hand Kupipi the magicked doll. Source: https://vanadreams.org/wiki/#mission-475', steps = { { title = 'Walkthrough', note = '• Speak with Kohlo-Lakolo (G-5), Port Windurst.\n• West Sarutabaruta Secluded Spot (J-8): examine for a scene, then again to fight Chepelle + Chepelle\'s Tiger.\n• At 50% Chepelle, Chepelle\'s Sheep and Chepelle\'s Hare join; kill all.\n• Examine the spot once more, then get the magicked doll from Kohlo-Lakolo.\n• Deliver it to Kupipi (Map 2, H-6), Heaven\'s Tower.' }, { title = 'Notes', note = '• Any party size; 15-min limit; keep within ~30 yalms of the spot.\n• Wait if another group holds the fight.\n• Doll is removed on completion.' }, { title = 'Reward', note = '• Maat\'s Mix, Per. Lucky Egg\n• Title: Ghdwk Vshdnhu' } } },
    { name = 'Dancing Prince', group = 'Mission: The Voracious Resurgence', desc = 'Mission 3-1: investigate an orc ritual in Monastic Cavern and report to Rahal. Source: https://vanadreams.org/wiki/#mission-476', steps = { { title = 'Walkthrough', note = '• Chateau d\'Oraguille: Halver (I-9), then Rahal (H-9).\n• Davoi (enter from Jugner Forest G-12): Quemaricond (G-7).\n• Monastic Cavern (from Davoi H-11): examine Ritual Site (H-10), kill Orcish Bewitcher (H-9) inside 15 min.\n• Collect Quemaricond\'s report, then finish with Rahal.' }, { title = 'Notes', note = '• Orcish battle plan and the report are removed at the end.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Claidie\'s Concern', group = 'Mission: The Voracious Resurgence', desc = 'Harvest a solidago flower in Attohwa Chasm for Chalvatot\'s ball preparations. Source: https://vanadreams.org/wiki/#mission-477', steps = { { title = 'Walkthrough', note = '• Bring a Sickle.\n• Chateau d\'Oraguille: Halver (I-9), then Chalvatot (F-7) in Queen Leaute\'s garden.\n• Attohwa Chasm Harvesting Point (H-8): harvest the Solidago Flower.\n• Give it to Chalvatot, then report to Halver.' }, { title = 'Notes', note = '• Zone before taking Curilla Unleashed.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Curilla Unleashed', group = 'Mission: The Voracious Resurgence', desc = 'Carry a missive toward Altennia, fight a Smilodon, then duel Prince Trion and see Curilla. Source: https://vanadreams.org/wiki/#mission-478', steps = { { title = 'Walkthrough', note = '• Zone after the prior mission first.\n• Halver (I-9), Chateau d\'Oraguille: get missive to Altennia.\n• Ranguemont Pass (from Beaucedine Glacier E-10): examine Vicious Claw Marks (J-8), defeat Harnessed Smilodon (15 min); examine again for a scene.\n• Back to Halver, then open the Prince Royal\'s Room door.\n• Bostaunieux Oubliette (from Chateau I-8): examine Frigid Confluence (Map 1, H-9), fight Prince Trion until he is worn down; examine again.\n• Talk to Curilla (I-9), Chateau d\'Oraguille.' }, { title = 'Notes', note = '• Missive is removed in the Ranguemont scene.\n• Next mission needs a new Vana\'diel day.' }, { title = 'Reward', note = '• Twinned Shield\n• Title: Love Is Alive' } } },
    { name = 'Run, Excenmille, Run!', group = 'Mission: The Voracious Resurgence', desc = 'TVR 3-4: trail Excenmille to the Beaucedine Glacier tower, beat the orcs and read their map. Source: https://vanadreams.org/wiki/#mission-479', steps = { { title = 'Walkthrough', note = '• Wait one game day after the previous mission.\n• Chateau d\'Oraguille: Halver (I-9), then Rahal (H-9).\n• Beaucedine Glacier tower: examine Ferric Stench (H-8) and kill Orcish Axeman, Orcish Atlatl, Orcish Praetor, Harnessed Smilodon for Carmine Swallows\' map.\n• Examine Ferric Stench again to read it.\n• Visit the Point of Interest by the Mirror Pool (J-6) for a scene.' }, { title = 'Notes', note = '• 15-min limit; stay near the enemies.\n• If mobs are already up, let them despawn first.' } } },
    { name = 'Of Knights and Orcs', group = 'Mission: The Voracious Resurgence', desc = 'Restore a broken doll in Fei\'Yin, then beat the Slackjawed Mukdrom beside Excenmille. Source: https://vanadreams.org/wiki/#mission-480', steps = { { title = 'Walkthrough', note = '• Bring a Doll Gizmo.\n• Zone into Fei\'Yin from Beaucedine Glacier for a scene.\n• Trade the Doll Gizmo to Talos (Map 2, H-7), Fei\'Yin.\n• Beaucedine Glacier Point of Interest (J-6): examine for scene, again to fight Slackjawed Mukdrom with Excenmille, once more afterward.\n• Chateau d\'Oraguille: examine Door:Prince Royal\'s Rm (H-7).' }, { title = 'Notes', note = '• 15-min limit; Excenmille\'s death ends the fight.' }, { title = 'Reward', note = '• Maat\'s Mix, Twinned Blade\n• Title: The Awakener' } } },
    { name = 'Best Served Cold', group = 'Mission: The Voracious Resurgence', desc = 'Mission 4-1: assist Gumbah and Drangord, then beat the Quadav Vanguard in Zeruhn Mines. Source: https://vanadreams.org/wiki/#mission-481', steps = { { title = 'Walkthrough', note = '• Bastok Mines: Gumbah (J-7), then Drangord (D-7).\n• Zone into Zeruhn Mines for a scene.\n• Speak to Quadav Inquest (I-9); speak again and kill all four Quadav Vanguard inside 15 min.\n• Speak to the Inquest once more to finish.' }, { title = 'Reward', note = '• Naji\'s Loop' } } },
    { name = 'Cornelia\'s Call to Action', group = 'Mission: The Voracious Resurgence', desc = 'Follow Cornelia\'s tracks in Palborough Mines and beat a Mind-warped Scorpion. Source: https://vanadreams.org/wiki/#mission-482', steps = { { title = 'Walkthrough', note = '• Iron Eater (J-8), Metalworks.\n• Enter Palborough Mines from North Gustaberg for a scene.\n• Perversion\'s Refuge (Map 3, H-9): examine for scene, again to fight Mind-warped Scorpion (15 min), again to get Iapetus.\n• Report to Iron Eater.' }, { title = 'Notes', note = '• No duplicate Iapetus if you already own one.' }, { title = 'Reward', note = '• Title: Get Over Here' } } },
    { name = 'Naja the Ambitious', group = 'Mission: The Voracious Resurgence', desc = 'Kill a Returned Soulflayer in Wajaom Woodlands and bring Naja Salaheem the proof. Source: https://vanadreams.org/wiki/#mission-483', steps = { { title = 'Walkthrough', note = '• Needs all Treasures of Aht Urhgan missions done.\n• Naja Salaheem (I-10), Aht Urhgan Whitegate.\n• Wajaom Woodlands Savage Scars (H-13, by the Engraved Tablet): examine for scene, again to fight Returned Soulflayer (15 min; retry if lost).\n• Examine again for the lock of golden hair; give it to Naja.' }, { title = 'Reward', note = '• Ziamet Khud, Ziamet Peti, Ziamet Bazubands, Ziamet Salvars, Ziamet Nails' } } },
    { name = 'Raubahn the Blue', group = 'Mission: The Voracious Resurgence', desc = 'Beat the Arisen Soulflayer and its Winebibbers in Caedarva Mire with Uran-Mafran. Source: https://vanadreams.org/wiki/#mission-484', steps = { { title = 'Walkthrough', note = '• Examine Imperial Whitegate (L-9), Aht Urhgan Whitegate.\n• Caedarva Mire Savage Scars (Map 4, H-6, by Engraved Tablet): scene, then fight Arisen Soulflayer + three Descended Winebibbers with Uran-Mafran.\n• Examine the Scars again, then report at the Imperial Whitegate.' }, { title = 'Notes', note = '• Lost if Uran-Mafran dies or 15 min pass.' }, { title = 'Reward', note = '• Key item: Mnejing\'s receiver\n• Title: Bond Renewer' } } },
    { name = 'Ghatsad\'s Quandary', group = 'Mission: The Voracious Resurgence', desc = 'TVR 5-1: deliver Ghatsad\'s gift, fight in Caedarva Mire and bring back the Pure White Ampoule. Source: https://vanadreams.org/wiki/#mission-485', steps = { { title = 'Walkthrough', note = '• Ghatsad, Automaton Workshop (I-7), Aht Urhgan Whitegate: get Gift for Megomak.\n• Mount Zhayolm: examine Acid-eaten Door at Gates of Halvung (I-9).\n• Caedarva Mire Vexing Sniffles (Map 1, E-10, outside Hazhalm Testing Grounds): scene, then fight Gloom Phantom, Magh Bihu, Dazbog with Mnejing.\n• Win for the Pure White Ampoule; examine again.\n• Bring ampoule to the Acid-eaten Door, then report to Ghatsad.' }, { title = 'Notes', note = '• 15 min, stay close; lost if Mnejing dies; Trusts allowed.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'The Revelation', group = 'Mission: The Voracious Resurgence', desc = 'Survey Olduum ruins in Aydeewa Subterrane, beat Missabikong, report to Abda-Lurabda. Source: https://vanadreams.org/wiki/#mission-486', steps = { { title = 'Walkthrough', note = '• Abda-Lurabda (I-7), Aht Urhgan Whitegate.\n• Enter Aydeewa Subterrane from Wajaom Woodlands (only this entrance gives the scene).\n• Examine three Survey Points in any order.\n• Final Survey Point (Map 3, G-10): scene, then fight Missabikong (15 min), then closing scene.\n• Report to Abda-Lurabda.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Tateeya\'s Worries', group = 'Mission: The Voracious Resurgence', desc = 'Help Ghatsad retrieve the Olduum staff from the Jade Sepulcher. Source: https://vanadreams.org/wiki/#mission-487', steps = { { title = 'Walkthrough', note = '• Aht Urhgan Whitegate: Tateeya (I-7), then Ghatsad (I-7, Automaton Workshop).\n• Jade Sepulcher Ornamental Door (H-8): scene, then win the battle.\n• Talk to Imperial Whitegate (L-9) for the Thunder Hammer.' }, { title = 'Notes', note = '• Max 6 players, 15 min, Trusts OK.\n• Full inventory: return to the Whitegate later.\n• Abda-Lurabda replaces a lost Thunder Hammer.' }, { title = 'Reward', note = '• Thunder Hammer\n• Title: Treasure of Olduum' } } },
    { name = 'The Seagull Phratrie', group = 'Mission: The Voracious Resurgence', desc = 'TVR 5-4 in Arrapago Reef: feed the Apkallu Guide and beat a Mamool Ja group. Source: https://vanadreams.org/wiki/#mission-488', steps = { { title = 'Walkthrough', note = '• Bring one Hamsi.\n• Arrapago Reef: click the ??? for a scene.\n• Talk to the Apkallu Guide, then trade it the Hamsi.\n• Click Camp Remnants; kill all six enemies in 15 min (wait if occupied).\n• Click Camp Remnants again, then the ??? to finish.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'The Sea Sage', group = 'Mission: The Voracious Resurgence', desc = 'TVR 5-5: obtain an apkallu\'s aeropearl and have Ghatsad mend it. Source: https://vanadreams.org/wiki/#mission-489', steps = { { title = 'Walkthrough', note = '• Talk to the Apkallu Guide, Arrapago Reef.\n• Wajaom Woodlands: check Leypoint (G-8); with Thunder Hammer equipped, check Marolith (G-9) for the aeropearl.\n• Return to the Apkallu Guide, then Ghatsad (I-7), Aht Urhgan Whitegate.\n• Alzadaal Undersea Ruins: kill Qiqirn Goldsmiths/Poulterers until Panaiveriyamman pops (chance on your killing blow); kill it for the man-made solution.\n• Ghatsad gives the repaired aeropearl.\n• Check the ??? (H-10), Arrapago Reef, then give the pearl to the Apkallu Guide.' }, { title = 'Reward', note = '• Apkallu Scepter\n• Title: Beloved by the Sea God' } } },
    { name = 'Sky, Moon, Incantrix', group = 'Mission: The Voracious Resurgence', desc = 'TVR 6-1: collect ingredients on Reisenjima for Incantrix. Source: https://vanadreams.org/wiki/#mission-490', steps = { { title = 'Walkthrough', note = '• Reisenjima: Reikuu (K-8), then Incantrix (Map 1, G-14) by the light near Ethereal Ingress #10.\n• Examine Suspicious Overgrowth (H-6).\n• Get 3 Hoptoads (north of island, hippogryph area) and 1 Eastern Ginger Root; trade them to the Overgrowth.\n• Talk to Reikuu again.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Nii\'s Last Stand', group = 'Mission: The Voracious Resurgence', desc = 'Mission 6-2: train under Reikuu on Reisenjima and clear the solo aspirant\'s trial. Source: https://vanadreams.org/wiki/#mission-491', steps = { { title = 'Walkthrough', note = '• Reisenjima: Reikuu (Map 1, K-8), Incantrix (Map 1, G-14), Babbling Brook (Map 1, F-5), Incantrix again.\n• Examine Aspirant\'s Grounds for the aspirant\'s canteen; examine again to start the solo trial (retry if lost).\n• Examine the Grounds afterward to finish.' }, { title = 'Notes', note = '• Canteen removed at the end.' }, { title = 'Reward', note = '• Tokkosho\n• Title: Destiny Master' } } },
    { name = 'Dance of the Tengu', group = 'Mission: The Voracious Resurgence', desc = 'Mission 6-3: two Henge battles at Reisenjima\'s Babbling Brook. Source: https://vanadreams.org/wiki/#mission-492', steps = { { title = 'Walkthrough', note = '• Talk to Reikuu (Map 1, K-8), Reisenjima.\n• Babbling Brook (Map 1, F-5): scene, then fight Zhuu Buxu, then fight Reikuu.\n• View any pending scene (examine the Brook if one is waiting), then talk to Reikuu.' }, { title = 'Reward', note = '• Tengu War Fan, Tengu Shawl\n• Title: Tireless Tracker' } } },
    { name = 'Raebrimm\'s Rebirth', group = 'Mission: The Voracious Resurgence', desc = 'TVR 7-1: look for Raebrimm in Quicksand Caves and beat his sand guardians. Source: https://vanadreams.org/wiki/#mission-493', steps = { { title = 'Walkthrough', note = '• Gumbah (J-7), Bastok Mines; then Dancing Wolf (G-7), Rabao.\n• Quicksand Caves: examine the first ??? for a scene.\n• Examine the fight ???: kill 2 Spelunking Sabotenders, 2 Sand Tarantulas, 2 Sand Lizards.\n• Examine it again to finish.' }, { title = 'Notes', note = '• 15 min; stay within 50 yalms; wait if occupied.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Uran-Mafran of the Maelstrom', group = 'Mission: The Voracious Resurgence', desc = 'TVR 7-2: save Raebrimm from Uran-Mafran in Quicksand Caves. Source: https://vanadreams.org/wiki/#mission-494', steps = { { title = 'Walkthrough', note = '• Dancing Wolf (G-7), Rabao.\n• Enter Quicksand Caves from Western Altepa Desert (I-6) for a scene.\n• Check Journey\'s End; beat Uran-Mafran with Oggbi in 15 min (Oggbi must live).\n• Check Journey\'s End again, then talk to Gumbah (J-7), Bastok Mines.' }, { title = 'Reward', note = '• Rep. Plat. Medal\n• Title: Galkan Hazard' } } },
    { name = 'Koru-Moru\'s Hypothesis', group = 'Mission: The Voracious Resurgence', desc = 'TVR 7-3: supply Shantotto three cloths to finish Koru-Moru\'s doll. Source: https://vanadreams.org/wiki/#mission-495', steps = { { title = 'Walkthrough', note = '• Talk to Shantotto (K-7), Windurst Walls.\n• Trade her 1 Square of Spectral Crimson, 1 Square of Spectral Goldenrod and 1 Luminicloth.' }, { title = 'Reward', note = '• Key item: Memorian, the Magicked Doll' } } },
    { name = 'Altennia Burns Bright', group = 'Mission: The Voracious Resurgence', desc = 'TVR 7-4: mine Ember-Encrusted Orichalcum in Ifrit\'s Cauldron for Rahal. Source: https://vanadreams.org/wiki/#mission-496', steps = { { title = 'Walkthrough', note = '• Bring a Pickaxe.\n• Chateau d\'Oraguille: Halver (I-9) gives Trion\'s Directive; hand it to Rahal (H-9).\n• Ifrit\'s Cauldron (from Yhoator Jungle G-6): mine a Mining Point for Ember-Encrusted Orichalcum.\n• Deliver it to Rahal.' }, { title = 'Reward', note = '• Title: Bearer of Secrets' } } },
    { name = 'Maat on the Rampage', group = 'Mission: The Voracious Resurgence', desc = 'TVR 8-1: find the missing Maat, beat him in Batallia Downs, return his pillow. Source: https://vanadreams.org/wiki/#mission-497', steps = { { title = 'Walkthrough', note = '• Maat (H-5), Ru\'Lude Gardens: Cloth-lined Basket.\n• Lower Jeuno: Muckvix (H-10) for Map to the Woman\'s Home; give basket to Miladi-Nildi (J-5).\n• Batallia Downs at night (18:00-06:00 game time): click Goblin Festival Site (J-7) for scene, again to fight Maat with Mumor (15 min), again for Maat\'s Pillow.\n• Return pillow to Maat.' }, { title = 'Notes', note = '• Wait if another party is fighting.' }, { title = 'Reward', note = '• Beastmen\'s Seal' } } },
    { name = 'Not Just a Pretty Face', group = 'Mission: The Voracious Resurgence', desc = 'Beat the gigas Echion near Delkfutt\'s Tower with Gloom Phantom\'s crew, then see Muckvix. Source: https://vanadreams.org/wiki/#mission-498', steps = { { title = 'Walkthrough', note = '• Muckvix (H-10), Lower Jeuno.\n• Qufim Island Before Delkfutt\'s Tower (G-6): scene, then fight Echion with Gloom Phantom, Dazbog, Magh Bihu; examine again after.\n• Report to Muckvix.' }, { title = 'Notes', note = '• Lost if any ally dies or after 15 min.' }, { title = 'Reward', note = '• 20,000 gil\n• Title: Long Live Mumor' } } },
    { name = 'Delkfutt the Great', group = 'Mission: The Voracious Resurgence', desc = 'Beat Enkelados and allies in The Eldieme Necropolis (S) for Valaineral R. Davilles. Source: https://vanadreams.org/wiki/#mission-499', steps = { { title = 'Walkthrough', note = '• Shami (H-8), Port Jeuno; then Valaineral R. Davilles, Southern San d\'Oria (S).\n• Batallia Downs (S): examine Secret Entrance (G-7) to reach The Eldieme Necropolis (S).\n• Egg Discovery Site: scene, then fight Enkelados, 3 Gigass Stalking Saplings, Sharpshot Luttdrutt, SaJho Shieldbreaker (15 min).\n• Examine the site again, then report to Valaineral.' }, { title = 'Reward', note = '• Hi-Elixir\n• Title: Parter of the Veil' } } },
    { name = 'Oshasha\'s Violation', group = 'Mission: The Voracious Resurgence', desc = 'Take the Liber Daemonium back from the Velkk in Marjami Ravine for Andreine. Source: https://vanadreams.org/wiki/#mission-500', steps = { { title = 'Walkthrough', note = '• Needs all Seekers of Adoulin missions done.\n• Andreine, Celennia Memorial Library.\n• Marjami Ravine Bibliomaniac\'s Lair (I-10): kill Gramk-Droog, Velkk Defiler, Velkk Inquisitor (15 min, Trusts OK).\n• Examine the Lair for the Liber Daemonium; give it to Andreine.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Phantasmic Heroes', group = 'Mission: The Voracious Resurgence', desc = 'Find Oshasha and Valli, then face the Shadow Lord solo with NPC allies. Source: https://vanadreams.org/wiki/#mission-501', steps = { { title = 'Walkthrough', note = '• Marjoirelle (H-12), Western Adoulin.\n• Leafallia: Odyssean Passage (H-8), then Test of Talents (H-8) for a scene.\n• Leave party, examine Test of Talents again to reach Throne Room [V].\n• Beat the Shadow Lord in 15 min with Oshasha, Valli, Volker, Zeid, Romaa Mihgo.\n• Watch the Leafallia scene, then talk to Andreine, Celennia Memorial Library.' }, { title = 'Notes', note = '• Solo, no Trusts; lost if you or all five allies fall; you return to Leafallia either way.' }, { title = 'Reward', note = '• Title: Demonic Dreamer' } } },
    { name = 'Skokkr Undrborn\'s Temptation', group = 'Mission: The Voracious Resurgence', desc = 'TVR 9-3: sneak into the Silver Knife posing as staff in the Esthete\'s outfit. Source: https://vanadreams.org/wiki/#mission-502', steps = { { title = 'Walkthrough', note = '• Need Oshasha\'s invitation and 90,000 bayld.\n• Glowing Hearth (H-6), Eastern Adoulin, to enter the Silver Knife; talk to Oscarnot, Zemerine, Gama-Shama.\n• Runje Desaali (J-10), Eastern Adoulin: buy Esthete\'s Masque, Esthete\'s Coat, Esthete\'s Hose, 30,000 bayld each, one per chat (free inventory first).\n• Wear all three and talk to Zemerine.\n• Remove them, talk to Oscarnot, then Glowing Hearth outside.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'The Prime Weapons', group = 'Mission: The Voracious Resurgence', desc = 'Locate the Prime weapon workroom to earn the Silver Knife membership card. Source: https://vanadreams.org/wiki/#mission-503', steps = { { title = 'Walkthrough', note = '• Optional hint: Andreine, Celennia Memorial Library.\n• Leafallia Odyssean Passage (H-8): examine for scene, trade a Stygian Ash (Pixie drop) for the Bronze-hued Tag.\n• Outer Ra\'Kaznar upper level: examine Shrouded Workroom (Map 1, K-3) with the tag (two Umbril nearby).\n• Examine the Odyssean Passage again.' }, { title = 'Reward', note = '• Key item: Silver Knife membership card\n• Title: Searcher of the Voracious' } } },
    { name = 'To Movalpolos!', group = 'Mission: The Voracious Resurgence', desc = 'TVR 10-1: go from Bastok Mines to Oldton Movalpolos and win in Mine Shaft #2716. Source: https://vanadreams.org/wiki/#mission-504', steps = { { title = 'Walkthrough', note = '• Needs the CoP Dawn \'Newfound Family\' scene seen.\n• Gumbah (J-7), Bastok Mines.\n• Oldton Movalpolos (from North Gustaberg K-6): Tarnotik (K-10).\n• Mine Shaft #2716: click door for scene, again to fight; win and watch the ending.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Magh Bihu on the Prowl', group = 'Mission: The Voracious Resurgence', desc = 'TVR 10-2: bring Acidic Humus and a Watermelon to the Mandragora Warden in The Boyahda Tree. Source: https://vanadreams.org/wiki/#mission-505', steps = { { title = 'Walkthrough', note = '• Enter The Boyahda Tree from Sanctuary of Zi\'Tah (J-12); talk to the Mandragora Warden.\n• Trade 1 Acidic Humus, talk again, then trade 1 Watermelon.\n• Only single items are accepted.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = '101 Dazbogs', group = 'Mission: The Voracious Resurgence', desc = 'TVR 10-3: deliver tribute to the Meeble Hedrov in Gusgen Mines. Source: https://vanadreams.org/wiki/#mission-506', steps = { { title = 'Walkthrough', note = '• Enter Gusgen Mines from Konschtat Highlands (L-7); talk to Hedrov (Map 4, H-7).\n• Kill Boulder Eaters in Gustav Tunnel for 6 Hunks of Fat Worm Meat.\n• Trade exactly 6 to Hedrov.' }, { title = 'Reward', note = '• 20,000 gil\n• Key item: sheet of Destiny Destroyer tunes' } } },
    { name = 'Kipdrix the Faithful', group = 'Mission: The Voracious Resurgence', desc = 'Visit Mine Shaft 2716 and the Throne Room, then win the Kipdrix the Faithful fight. Source: https://vanadreams.org/wiki/#mission-507', steps = { { title = 'Walkthrough', note = '• Oldton Movalpolos (from North Gustaberg K-6): Tarnotik (K-10).\n• Enter Mine Shaft 2716 for a scene; return to Tarnotik.\n• Throne Room door: scene, then fight Orcish Warchief, Topaz Quadav, Yagudo Inquisitor.\n• Winning sends you to Xarcabard and ends the mission.' }, { title = 'Notes', note = '• Dazbog and Magh Bihu must survive; max 6, 15 min, Trusts OK.' }, { title = 'Reward', note = '• 20,000 gil' } } },
    { name = 'Duke Alloces\'s Decision', group = 'Mission: The Voracious Resurgence', desc = 'Go with the Destiny Destroyers to Castle Zvahl Keep and beat Chaos. Source: https://vanadreams.org/wiki/#mission-508', steps = { { title = 'Walkthrough', note = '• Follows TVR 10-4.\n• With a stage 2 Prime Weapon equipped (not Loughnashade or Duban), examine Heroes\' Gambit (J-9), Xarcabard.\n• Castle Zvahl Keep Valhallan Rift (Map 4, G-7, near HP #1): scene, then Gwora Corridor fight vs Chaos with Gloom Phantom, Magh Bihu, Dazbog (15 min; lost if any ally dies).\n• Win: get Psyche of Despair, moved to Xarcabard.\n• Examine Heroes\' Gambit again to finish.' }, { title = 'Notes', note = '• Fight: up to 6, Trusts OK, Prime Weapon not needed inside.\n• Psyche removed at the end.' }, { title = 'Reward', note = '• 20,000 gil\n• Title: Another Psyche' } } },
    { name = 'Odin\'s Eye', group = 'Mission: The Voracious Resurgence', desc = 'Gather five psyches, four of them in Dynamis-Xarcabard, and bring the memento to Gumbah. Source: https://vanadreams.org/wiki/#mission-509', steps = { { title = 'Walkthrough', note = '• Need Hydra Corps Command Scepter, Hydra Corps Eyeglass, Hydra Corps Lantern, Hydra Corps Insignia; zone once first.\n• Heroes\' Gambit (J-9), Xarcabard: despairing psyche.\n• Dynamis-Xarcabard: examine the four Twinkling Presences (suffering, hatred, oath, wish) for four psyches; full clear not required.\n• Examine Before Castle Zvahl to return; scene swaps psyches for Raebrimm\'s memento.\n• Give it to Gumbah (J-7), Bastok Mines.' }, { title = 'Reward', note = '• Title: Sender of Shadow' } } },
    { name = 'Moglesse Oblige', group = 'Mission: The Voracious Resurgence', desc = 'Join Kupofried in La Theine Plateau and win at Everbloom Hollow. Source: https://vanadreams.org/wiki/#mission-510', steps = { { title = 'Walkthrough', note = '• Talk to the Moogle (J-8) in your home-nation Mog House.\n• La Theine Plateau stone circle: examine ??? (E-4).\n• Moogle Meeting (G-10), below the cliff past Ordelle\'s Caves: scene, then enter Everbloom Hollow.\n• Kill Spikehelm Argok, Tethys, Antican Curule Aedilis, Garmatur the Merciless; watch the final scene.' }, { title = 'Notes', note = '• Max 6, 15 min, Trusts OK; all members must be at this mission step.' } } },
    { name = 'The Voracious Beast', group = 'Mission: The Voracious Resurgence', desc = 'TVR 11-2: two fights via the Valhallan Rift (Garazu-Horeizu, then Chaos), then pick a completion ring. Source: https://vanadreams.org/wiki/#mission-511', steps = { { title = 'Walkthrough', note = '• Heroes\' Gambit (J-9), Xarcabard: scene.\n• Castle Zvahl Keep Valhallan Rift (Map 4, G-7): scene, then Gwora Throne Room vs Garazu-Horeizu with Gloom Phantom, Magh Bihu, Dazbog.\n• Back in the Keep, watch the scene.\n• Equip a stage 2+ Prime Weapon (main/ranged; not stage 1, horn or shield); examine the Rift to fight Chaos with Medada and Gurebu-Ogurebu.\n• Get the vial of Chaos\'s blood; choose one of seven rings at Heroes\' Gambit.' }, { title = 'Notes', note = '• Max 6, Trusts OK, 30 min per fight.\n• Below 50% Chaos, more foes and allies join.\n• Lost rings can be re-picked at Heroes\' Gambit.' }, { title = 'Reward', note = '• Title: Astral Aligner' } } },
    { name = 'Your Decision', group = 'Mission: The Voracious Resurgence', desc = 'Final TVR mission: take a ring at the Heroes\' Gambit to close the story. Source: https://vanadreams.org/wiki/#mission-512', steps = { { title = 'Walkthrough', note = '• Xarcabard: examine Heroes\' Gambit (J-9) and pick one of seven items.\n• Ring not obtained earlier? Choose it here.' } } },
    { name = 'Epilogue', group = 'Mission: The Voracious Resurgence', desc = 'Final Voracious Resurgence mission: say goodbye to seven people across Vana\'diel, each giving a small gift. Source: https://vanadreams.org/wiki/#mission-513', steps = { { title = 'Before you start', note = '• Requires: on The Voracious Resurgence Epilogue.' }, { title = 'Farewell visits', note = '• Reach Oldton Movalpolos via North Gustaberg (K-6) and speak with Tarnotik (K-10).\n• Reach The Boyahda Tree via The Sanctuary of Zi\'Tah (J-12) and speak with the Mandragora Warden.\n• Reach Gusgen Mines via Konschtat Highlands (L-7) and speak with Hedrov (Map 4, H-7).\n• Speak with Gumbah in Bastok Mines (J-7).\n• Speak with Halver in Chateau d\'Oraguille (I-9).\n• Speak with Shantotto in Windurst Walls (K-7).\n• Speak with the Dancing Wolf in Rabao (G-7).' }, { title = 'Good to know', note = '• Any order works; the mission completes once all seven are visited.\n• Full inventory: the gift waits, so talk to that person again to claim it.\n• After Your Decision, a Heroes\' Gambit in Xarcabard gives a ring if you lack one.' } } },
}

return S
